// The overlay sheet with the three tabs. Opening it never touches the table:
// it only reads /learn. "Start guided game" is the one button that does.
function LearnSheet({ game, ctx, onClose, onStartLearn }) {
  const [tab, setTab] = useState(LEARN_TABS[0])
  const { data, error } = useLearnData(ctx, game && game.id, true)
  const panel = !data && !error
    ? jsx('div', { style: { fontSize: 13, color: text.tertiary, padding: '18px 0' }, children: 'Opening the tutorial…' })
    : error
      ? jsx('div', { role: 'alert', style: { fontSize: 13, padding: '18px 0' }, children: error })
      : tab === LEARN_TABS[0]
        ? jsx(HowToCard, { howto: data.howto })
        : tab === LEARN_TABS[1]
          ? jsx(DemoPlayer, { demo: data.demo })
          : jsxs('div', { style: { display: 'flex', flexDirection: 'column', gap: 10 }, children: [
              jsx('div', { style: { fontSize: 14, lineHeight: 1.45 }, children: 'Play a real game against the Beginner computer. It explains each of its moves, a guide appears when a rule first matters, and if the computer could win after your move you get a warning and an Undo.' }),
              onStartLearn
                ? button('Start guided game vs Beginner', () => onStartLearn(), { primary: true, title: 'Replaces this board with a fresh guided game against the built-in Beginner player.' })
                : jsxs('div', { children: [
                    jsx('div', { style: { fontSize: 13, fontWeight: 650 }, children: 'Tips for this game' }),
                    ((data.coach || {}).steps || []).map((step, at) => jsx('div', { key: at, style: { fontSize: 13, color: text.secondary, marginTop: 4 }, children: step.say }, at)),
                    !(((data.coach || {}).steps || []).length) ? jsx('div', { style: { fontSize: 13, color: text.tertiary }, children: 'Start the game from this screen and the guide will coach you as you play.' }) : null
                  ] })
            ] })
  return jsx('div', {
    role: 'dialog', 'aria-modal': true, 'aria-label': `How to play ${game.title || game.id}`,
    className: 'games-learn-sheet',
    style: { position: 'fixed', inset: 0, zIndex: 60, background: 'rgba(6, 10, 16, 0.72)', display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 16 },
    children: jsxs('div', {
      style: { width: 'min(880px, 96vw)', maxHeight: '92vh', overflow: 'auto', background: paper, border: `1px solid ${stroke}`, borderRadius: 16, padding: '16px 18px', display: 'flex', flexDirection: 'column', gap: 12 },
      children: [
        jsxs('div', { style: { display: 'flex', justifyContent: 'space-between', gap: 10, alignItems: 'baseline' }, children: [
          jsxs('div', { children: [
            jsx('div', { style: { fontSize: 20, fontWeight: 700 }, children: `Play & Learn · ${data ? data.title || game.title : game.title || game.id}` }),
            jsx('div', { style: { fontSize: 12, color: text.tertiary }, children: 'Built-in notes. Nothing here sends your game to a model.' })
          ] }),
          button('Close', () => onClose(), { primary: true, autoFocus: true, label: 'Close tutorial' })
        ] }),
        jsx('div', { role: 'tablist', 'aria-label': 'Tutorial sections', style: { display: 'flex', gap: 8, flexWrap: 'wrap' }, children:
          LEARN_TABS.map(name => jsx('span', { key: name, style: { display: 'inline-flex' }, children:
            button(name, () => setTab(name), {
              title: name === LEARN_TABS[0] ? 'The rules in short.' : name === LEARN_TABS[1] ? 'The built-in players show you a game.' : 'A first game with a guide beside you.',
              primary: tab === name
            }) })) }),
        panel
      ]
    })
  })
}

// The Learn door on a game screen. Each screen drops one of these in its
// header row; the sheet it opens is the same for every game.
function LearnButton({ game, ctx, onStartLearn, disabled, title, label }) {
  const [open, setOpen] = useState(false)
  const startLearn = onStartLearn ? () => { setOpen(false); onStartLearn() } : undefined
  return jsxs('span', { style: { display: 'inline-flex' }, children: [
    button(label || 'Learn', () => setOpen(true), { disabled, title: title || 'The rules, a demo game, and a guided first game.' }),
    open ? jsx(LearnSheet, { game, ctx, onClose: () => setOpen(false), onStartLearn: startLearn }) : null
  ] })
}

// Beside the board during a guided game: the computer's own words about its
// last move, and a red warning with Undo when the last move throws the game
// away. Both come from the table picture (kit.py), no model involved.
function CoachStrip({ game, pictured, command, lock }) {
  if (!pictured || !pictured.learn) return null
  const tip = String(pictured.coach_tip || '')
  const note = String(pictured.coach_note || '')
  if (!tip && !note) return null
  return jsxs('section', {
    'aria-label': 'Coach', role: 'status',
    style: {
      padding: '10px 12px', borderRadius: 8, fontSize: 13, lineHeight: 1.45,
      border: `1px solid ${tip ? '#d76b65' : accent}`,
      borderLeft: `4px solid ${tip ? '#d76b65' : accent}`,
      background: card, display: 'flex', gap: 10, alignItems: 'center', flexWrap: 'wrap'
    },
    children: [
      tip
        ? jsxs('span', { style: { color: '#e08a85' }, children: [jsx('b', { children: 'Careful. ' }), tip] })
        : jsxs('span', { children: [jsx('b', { children: 'The computer says: ' }), note] })
      // The Undo lives in the table's single action row now ("Undo move"), so it is not
      // drawn twice; only the warning stays beside the board.
    ]
  })
}

// The guide that explains one rule at a time, as long as the guided game runs.
// Steps come from learn.json; the person moves forward with a mouse.
function CoachGuide({ game, pictured, learn, guideStep, setGuideStep }) {
  const steps = ((learn && learn.coach) || {}).steps || []
  if (!pictured || !pictured.learn || !steps.length) return null
  // A hint must point at a cell the person can still play: keep only the
  // highlighted cells the table itself lists as legal right now. A hint that
  // names a taken cell sends the person clicking at nothing, so it stays hidden.
  const legalList = Array.isArray(pictured.legal) ? pictured.legal.map(String) : null
  const seats = Array.isArray(pictured.seats) ? pictured.seats : []
  const humanSeat = seats.find(seat => seat && seat.kind === 'human')
  const whiteSeat = seats.find(seat => seat && seat.side === 'white')
  // Every game here gives White the first move. When White is the machine and
  // a move is already on the board, the computer opened the game.
  const computerOpened = Boolean(
    humanSeat && whiteSeat && whiteSeat.kind !== 'human' && (pictured.moves || []).length
  )
  const hintsGone = step => {
    const hinted = (step && step.highlight || []).map(cell => String(cell))
    return hinted.length > 0 && Boolean(legalList) && !hinted.some(cell => legalList.includes(cell))
  }
  // The last rule must keep the guide and its "Previous rule" button. A step
  // past the end (a click on Next at the last rule) is clamped to that rule.
  let at = Math.min(Math.max(0, guideStep), steps.length - 1)
  // A rule whose hinted cells are all taken has been followed. Show the next
  // rule instead, so the guide never tells the person to click a taken cell.
  while (at < steps.length - 1 && hintsGone(steps[at])) at += 1
  const step = steps[at] || {}
  let tries = (step.highlight || [])
    .map(cell => String(cell))
    .filter(cell => !legalList || legalList.includes(cell))
  if (computerOpened && !tries.length && legalList && legalList.length) {
    // The computer took the opening move: point at a legal move rather than
    // leave the first rule without a hint.
    tries = legalList.slice(0, 2)
  }
  return jsxs('section', {
    'aria-label': 'Guide',
    style: { padding: '10px 12px', borderRadius: 8, border: `1px dashed ${accent}`, background: card, display: 'flex', flexDirection: 'column', gap: 8 },
    children: [
      jsxs('div', { style: { display: 'flex', gap: 8, alignItems: 'baseline', flexWrap: 'wrap' }, children: [
        jsx('b', { style: { fontSize: 13 }, children: `Guide · rule ${at + 1} of ${steps.length}` }),
        tries.length ? jsx('span', { style: { fontSize: 12, color: text.tertiary }, children: `Try: ${tries.join(', ')}` }) : null
      ] }),
      computerOpened ? jsx('div', { style: { fontSize: 12, color: text.tertiary }, children: 'The computer moved first.' }) : null,
      jsx('div', { style: { fontSize: 14, lineHeight: 1.45 }, children: step.say }),
      jsxs('div', { style: { display: 'flex', gap: 8 }, children: [
        at < steps.length - 1 ? button('Next rule', () => setGuideStep(at + 1), { primary: true, title: 'Move on to the next rule.' }) : null,
        at > 0 ? button('Previous rule', () => setGuideStep(at - 1), { title: 'Read the last rule again.' }) : null
      ] })
    ]
  })
}

// Chess Coach is a Labs experiment inside the table.
function coachArrowPairs(picture) {
  if (picture?.view !== 'chess' || !Array.isArray(picture?.coach?.book)) return []
  return picture.coach.book
    .filter(move => typeof move === 'string' && /^[a-h][1-8][a-h][1-8]/.test(move))
    .map(move => ({ from: move.slice(0, 2), to: move.slice(2, 4) }))
}

function coachArrowMarks(view, picture, options, pad, cell) {
  if (view !== 'chess' || !Array.isArray(options?.coachArrows) || options?.picked?.length) return []
  const files = picture?.files
  const ranks = picture?.ranks
  if (typeof files !== 'string' || !Array.isArray(ranks)) return []
  const centre = square => {
    if (typeof square !== 'string' || square.length !== 2) return null
    const col = files.indexOf(square[0])
    const row = ranks.indexOf(Number(square[1]))
    return col < 0 || row < 0 ? null : { x: pad + col * cell + cell / 2, y: pad + row * cell + cell / 2 }
  }
  return options.coachArrows.flatMap((pair, i) => {
    const from = centre(pair?.from)
    const to = centre(pair?.to)
    if (!from || !to) return []
    const dx = to.x - from.x
    const dy = to.y - from.y
    const length = Math.hypot(dx, dy)
    if (!length) return []
    const tip = { x: from.x + dx * 0.8, y: from.y + dy * 0.8 }
    const head = cell * 0.22
    const base = { x: tip.x - dx / length * head, y: tip.y - dy / length * head }
    const px = -dy / length * head * 0.55
    const py = dx / length * head * 0.55
    return [
      jsx('line', { x1: from.x, y1: from.y, x2: tip.x, y2: tip.y, stroke: accent, strokeWidth: 3, strokeLinecap: 'round', opacity: 0.45, style: { pointerEvents: 'none' } }),
      jsx('polygon', { points: `${tip.x},${tip.y} ${base.x + px},${base.y + py} ${base.x - px},${base.y - py}`, fill: accent, opacity: 0.45, style: { pointerEvents: 'none' } })
    ]
  })
}

function CoachPanel({ coach, onWhy }) {
  if (!coach) return null
  return jsxs('section', {
    'aria-label': 'Chess coach', 'data-coach-panel': 'true',
    style: { padding: '12px 14px', border: `1px solid ${stroke}`, borderRadius: 14, background: card, display: 'flex', flexDirection: 'column', gap: 4 },
    children: [
      jsxs('div', { style: { display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }, children: [
        jsx('div', { style: { fontSize: 11, letterSpacing: '0.12em', textTransform: 'uppercase', color: text.tertiary }, children: 'Chess coach' }),
        labsBadge()
      ] }),
      coach.opening ? jsxs('div', { style: { fontSize: 14, fontWeight: 600 }, children: [
        `${coach.opening.eco} · ${coach.opening.name}`,
        coach.alt > 0 ? jsx('span', { style: { fontWeight: 400, color: text.tertiary }, children: ` +${coach.alt} more names` }) : null
      ] }) : null,
      // An opening begins with the first move; before that the card says so instead of
      // picking one of the 3,332 names the empty position technically shares.
      !coach.opening && coach.in_book ? jsx('div', { style: { fontSize: 14, fontWeight: 600 }, children: 'No opening named yet — the first move names it.' }) : null,
      coach.in_book && Array.isArray(coach.book) && coach.book.length ? jsx('div', { style: { fontSize: 12, color: text.secondary }, children: 'Book moves are marked on the board.' }) : null,
      coach.left_ply != null ? jsx('div', { style: { fontSize: 12, color: text.secondary }, children: `You left the book here — move ${Math.ceil(coach.left_ply / 2)}${coach.left_ply % 2 ? ' (White)' : ' (Black)'}.` }) : null,
      !coach.in_book && coach.left_ply == null ? jsx('div', { style: { fontSize: 12, color: text.tertiary }, children: 'Unbooked position.' }) : null
    ]
  })
}

function CoachReview({ coach, onWhy }) {
  if (!Number.isFinite(coach?.ply) || coach.ply < 1 || typeof coach?.played_san !== 'string' || !coach.played_san || typeof coach?.better_san !== 'string' || !coach.better_san || !Number.isFinite(coach?.before) || !Number.isFinite(coach?.after) || typeof coach?.engine !== 'string' || !coach.engine) return null
  if (coach?.opening != null && (typeof coach.opening?.eco !== 'string' || typeof coach.opening?.name !== 'string')) return null
  if (coach?.left_ply != null && (!Number.isFinite(coach.left_ply) || coach.left_ply < 1)) return null
  const opening = coach?.opening ? `${coach.opening.eco} · ${coach.opening.name}` : '—'
  const book = coach?.left_ply != null ? `Left the book at move ${Math.ceil(coach.left_ply / 2)}.` : 'Never in book.'
  const cp = value => String(value).replace('-', '−')
  return jsxs('div', {
    'data-coach-review': 'true',
    style: { display: 'flex', flexDirection: 'column', gap: 4, borderTop: `1px solid ${stroke}`, paddingTop: 6, marginTop: 2 },
    children: [
      jsx('div', { style: { fontSize: 13 }, children: `Opening: ${opening}` }),
      jsx('div', { style: { fontSize: 13 }, children: book }),
      jsx('div', { style: { fontSize: 13 }, children: `Biggest mistake: move ${Math.ceil(coach.ply / 2)}${coach.ply % 2 ? ' (White)' : ' (Black)'} ${coach.played_san} (${cp(coach.before)} → ${cp(coach.after)} cp); ${coach.better_san} was better.` }),
      jsx('div', { style: { fontSize: 11, color: text.tertiary }, children: `evaluated by ${coach.engine}` }),
      typeof onWhy === 'function' ? textLink('Why this move?', onWhy) : null
    ]
  })
}

// ---- 35-talking-table.js: the talking tables: seats, a log, one click per move
// A talking table: seats round a table, a log this person may read, and one click per move.
// Typing is only ever for conversation, and only while that game is in a talking phase.
const TALKING_IDS = ['mafia', 'liars-dice', 'liars-dice-2v2', 'prisoners-dilemma', 'blind-auction']
// Experiments that live on the Labs shelf but still play on this screen.
const LABS_TALKING_IDS = ['liars-dice-2v2']

const TALK_KIND = {
  human: 'You',
  local: 'Built-in player',
  agent: 'Your agent',
  champion: 'Champion'
}

function talkSpot(index, count) {
  const angle = -Math.PI / 2 + (index * 2 * Math.PI) / Math.max(1, count)
  return { left: `${50 + Math.cos(angle) * 39}%`, top: `${50 + Math.sin(angle) * 36}%` }
}

function talkKindWord(place) {
  if (place.you) return 'You'
  return TALK_KIND[place.kind] || 'Built-in player'
}

function talkSeat(place, count, thinking) {
  const mine = Boolean(place.you)
  const speaking = Boolean(place.playing)
  return jsxs('div', {
    className: 'games-talk-seat',
    'data-seat': String(place.seat),
    style: {
      position: 'absolute',
      ...talkSpot(place.seat, count),
      transform: 'translate(-50%, -50%)',
      width: 108,
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      gap: 3,
      opacity: place.out ? 0.42 : 1
    },
    children: [
      jsx('div', {
        'data-role': place.role || '',
        style: {
          width: 46,
          height: 46,
          borderRadius: 23,
          display: 'grid',
          placeItems: 'center',
          fontSize: 22,
          color: place.colour || text.primary,
          border: `2px solid ${speaking ? accent : stroke}`,
          background: mine ? 'var(--ui-fill-secondary, rgba(127,127,127,0.16))' : fill,
          boxShadow: speaking ? `0 0 0 3px ${accent}33` : 'none'
        },
        children: place.avatar || '●'
      }),
      jsx('div', {
        style: { fontSize: 12, fontWeight: 700, color: mine ? text.primary : text.secondary, maxWidth: 108, textAlign: 'center' },
        children: place.name + (mine ? ' (you)' : '')
      }),
      jsx('div', {
        style: { fontSize: 10, color: text.tertiary, textAlign: 'center' },
        children: place.role ? place.role : [talkKindWord(place), place.note].filter(Boolean).join(' · ')
      }),
      speaking && thinking
        ? jsx('div', { style: { fontSize: 10, color: accent }, children: 'thinking…' })
        : null
    ]
  })
}

function talkBidWord(bid) {
  if (!bid || !bid.quantity) return 'No bid yet'
  return `${bid.quantity} × ${bid.face}s`
}

// The middle of the table: just enough to play from, never another seat's secrets.
function talkMiddle(pictured) {
  const mine = pictured.mine || {}
  const rows = []
  if (pictured.game === 'mafia') {
    rows.push(['Your role', mine.role || 'not dealt yet'])
    rows.push(['Alive', String((pictured.places || []).filter(place => !place.out).length)])
  } else if (pictured.game === 'liars-dice') {
    rows.push(['Bid on the table', talkBidWord(pictured.bid)])
    rows.push(['Your dice', (mine.dice || []).join(' · ') || 'none left'])
  } else if (pictured.game === 'blind-auction') {
    rows.push(['Your coins', String(mine.capital == null ? '—' : mine.capital)])
    // Your own valuation of each lot: it is the only thing this seat may see, and
    // without it the talk before the bids has nothing to talk about.
    const lots = mine.items || []
    if (lots.length) {
      lots.forEach(item => rows.push([item.name, `${item.value} to you`]))
    } else {
      rows.push(['Lots on the block', '0'])
    }
  } else if (pictured.game === 'prisoners-dilemma') {
    rows.push(['Your points', String(mine.points == null ? 0 : mine.points)])
    rows.push(['Match', `${(pictured.match && pictured.match.index) || 1} of ${(pictured.match && pictured.match.count) || 1}`])
  }
  return jsxs('div', {
    className: 'games-talk-middle',
    style: {
      position: 'absolute',
      left: '50%',
      top: '50%',
      transform: 'translate(-50%, -50%)',
      width: 210,
      padding: 14,
      borderRadius: 16,
      border: `1px solid ${stroke}`,
      background: card,
      textAlign: 'center'
    },
    children: [
      jsx('div', { style: { fontSize: 11, letterSpacing: '.08em', textTransform: 'uppercase', color: text.tertiary }, children: 'Table' }),
      jsx('div', { style: { fontSize: 15, fontWeight: 700, margin: '4px 0 8px' }, children: pictured.phase }),
      ...rows.map((row, index) =>
        jsxs('div', {
          key: `row-${index}`,
          style: { display: 'flex', justifyContent: 'space-between', gap: 8, fontSize: 12, color: text.secondary, padding: '2px 0' },
          children: [
            jsx('span', { children: row[0] }),
            jsx('span', { style: { color: text.primary, fontWeight: 600 }, children: row[1] })
          ]
        })
      )
    ]
  })
}

// ---- Liar's Dice 2v2: two teams, one shared pool each, talk in the open ----
// Ten pips stand for the team's shared pool: solid while the team still holds the
// die, hollow once it is gone. The count is always written next to them, so the
// picture never relies on colour alone.
function talkPoolPips(pool, out) {
  const pips = []
  for (let index = 0; index < 10; index += 1) {
    const full = index < pool
    pips.push(jsx('span', {
      key: `pip-${index}`,
      'data-pip': full ? 'full' : 'empty',
      style: {
        width: 11,
        height: 11,
        borderRadius: 3,
        boxSizing: 'border-box',
        border: `1px solid ${full ? accent : stroke}`,
        background: full ? accent : 'transparent',
        opacity: out ? 0.35 : full ? 0.92 : 0.7
      }
    }))
  }
  return pips
}

function talkTeamSeat(place) {
  const speaking = Boolean(place.playing)
  return jsxs('div', {
    key: `team-seat-${place.seat}`,
    'data-team-seat': String(place.seat),
    style: {
      display: 'flex',
      alignItems: 'center',
      gap: 6,
      padding: '4px 8px 4px 4px',
      borderRadius: 999,
      border: `1px solid ${speaking ? accent : stroke}`,
      background: place.you ? 'var(--ui-fill-secondary, rgba(127,127,127,0.16))' : 'transparent',
      opacity: place.out ? 0.45 : 1
    },
    children: [
      jsx('span', {
        style: {
          width: 26, height: 26, borderRadius: 13, display: 'grid', placeItems: 'center',
          fontSize: 14, color: place.colour || text.primary, background: fill
        },
        children: place.avatar || '●'
      }),
      jsxs('span', { style: { display: 'flex', flexDirection: 'column', lineHeight: 1.15, minWidth: 0 }, children: [
        jsx('span', { style: { fontSize: 12, fontWeight: 700, whiteSpace: 'nowrap' }, children: place.name + (place.you ? ' (you)' : '') }),
        jsx('span', { style: { fontSize: 10, color: text.tertiary }, children: place.note || '' })
      ] })
    ]
  })
}

function talkTeamRow(team, places, mine, label) {
  if (!team) return null
  const yours = mine && mine.team === team.team
  const seated = places.filter(place => (team.seats || []).includes(place.seat))
  return jsxs('div', {
    'data-team': String(team.team),
    className: 'games-talk-team',
    style: {
      display: 'flex',
      alignItems: 'center',
      gap: 14,
      padding: '10px 14px',
      border: `1px solid ${yours ? accent : stroke}`,
      borderRadius: 14,
      background: card,
      opacity: team.out ? 0.55 : 1,
      flexWrap: 'wrap'
    },
    children: [
      jsxs('div', { style: { minWidth: 104 }, children: [
        jsx('div', { style: { fontSize: 10, letterSpacing: '.09em', textTransform: 'uppercase', color: text.tertiary }, children: yours ? 'Your team' : label || 'Their team' }),
        jsx('div', { 'data-team-dice': String(team.dice), style: { fontSize: 16, fontWeight: 700 }, children: `${team.dice} ${team.dice === 1 ? 'die' : 'dice'}` }),
        jsx('div', { style: { fontSize: 11, color: text.tertiary }, children: team.out ? 'out of dice' : `shared pool · split ${team.spread.join(' + ')}` })
      ] }),
      jsx('div', { 'aria-hidden': 'true', style: { display: 'grid', gridTemplateColumns: 'repeat(5, 11px)', gap: 3 }, children: talkPoolPips(team.dice, team.out) }),
      jsx('div', { style: { display: 'flex', gap: 6, marginLeft: 'auto', flexWrap: 'wrap' }, children: seated.map(talkTeamSeat) })
    ]
  })
}

function talkTeamCenter(pictured) {
  const bid = pictured.bid || {}
  const places = pictured.places || []
  const turn = places.find(place => place.playing) || null
  const mine = pictured.mine || {}
  const rows = [
    ['Bid on the table', talkBidWord(bid)],
    ['Round', String(pictured.round || 1)],
    ['Your cup this round', (mine.dice || []).join(' · ') || 'no dice'],
    ['To act', turn ? turn.name : (pictured.status === 'active' ? '—' : 'game over')]
  ]
  return jsxs('div', {
    className: 'games-talk-center',
    style: {
      display: 'flex', flexDirection: 'column', gap: 6, padding: '10px 16px',
      border: `1px solid ${stroke}`, borderRadius: 14, background: fill, alignSelf: 'center', minWidth: 260
    },
    children: [
      jsx('div', { style: { fontSize: 10, letterSpacing: '.09em', textTransform: 'uppercase', color: text.tertiary, textAlign: 'center' }, children: 'Table' }),
      jsx('div', { 'data-talk-bid': String(bid.quantity || 0), style: { fontSize: 20, fontWeight: 700, textAlign: 'center' }, children: talkBidWord(bid) }),
      ...rows.map((row, index) => jsxs('div', {
        key: `centre-${index}`,
        style: { display: 'flex', justifyContent: 'space-between', gap: 12, fontSize: 12, color: text.secondary },
        children: [
          jsx('span', { children: row[0] }),
          jsx('span', { style: { color: text.primary, fontWeight: 600 }, children: row[1] })
        ]
      }))
    ]
  })
}

// Who won, in the words that fit this table: "You win!" for the person in a seat,
// the winning seats by name for a watcher, and team words for the 2v2 experiment.
function talkWinnerLine(pictured) {
  const reveal = pictured.reveal || {}
  const winners = Array.isArray(reveal.winners) ? reveal.winners : []
  const seat = pictured.your_seat
  if (pictured.game === 'liars-dice-2v2') {
    if (seat != null) return winners.includes(seat) ? 'Your team wins' : 'Your team loses'
    const teams = pictured.teams || []
    const team = teams.find(row => (row.seats || []).some(value => winners.includes(value)))
    return team ? `Team ${Number(team.team) + 1} wins` : (winners.length ? 'A team wins' : 'Game over')
  }
  if (seat != null) return winners.includes(seat) ? 'You win!' : 'You lose.'
  const names = {}
  ;(pictured.places || []).forEach(place => { names[place.seat] = place.name })
  const won = winners.map(value => names[value] || `Player ${value + 1}`).filter(Boolean)
  if (!won.length) return 'Game over'
  return won.length === 1
    ? `${won[0]} wins`
    : `${won.slice(0, -1).join(', ')} and ${won[won.length - 1]} win`
}

// The result sits on the table itself: the same big card the board games use. It
// names the winner, says what decided it, and offers the three ways on. Every
// way on is a button, so the end can be reached with the mouse alone.
function talkResultOverlay(pictured, actions) {
  if (pictured.status === 'active') return null
  const reveal = pictured.reveal || {}
  const winners = Array.isArray(reveal.winners) ? reveal.winners : []
  const seat = pictured.your_seat
  const won = seat != null ? winners.includes(seat) : null
  const permissions = pictured.permissions || {}
  return jsx('div', {
    className: 'games-result',
    'data-outcome': won == null ? 'watched' : won ? 'win' : 'lose',
    role: 'alert',
    'aria-label': 'Game over',
    'aria-live': 'assertive',
    style: {
      position: 'absolute', inset: 0, zIndex: 4, display: 'flex', alignItems: 'center',
      justifyContent: 'center', padding: 12, borderRadius: 18,
      background: 'rgba(8, 12, 18, .58)'
    },
    children: jsxs('section', {
      style: {
        display: 'flex', flexDirection: 'column', gap: 10, alignItems: 'center', textAlign: 'center',
        maxWidth: 470, padding: '18px 20px', borderRadius: 16,
        border: `2px solid ${won ? accent : stroke}`, background: card,
        boxShadow: '0 20px 44px rgba(0, 0, 0, .55)'
      },
      children: [
        jsx('div', { className: 'games-result-title', style: { fontSize: 28, fontWeight: 800, lineHeight: 1.1 }, children: talkWinnerLine(pictured) }),
        reveal.reason
          ? jsx('div', { className: 'games-result-why', style: { fontSize: 13, color: text.secondary }, children: reveal.reason })
          : null,
        jsxs('div', { style: { display: 'flex', gap: 8, flexWrap: 'wrap', justifyContent: 'center', marginTop: 2 }, children: [
          button('Rematch', actions.rematch, { primary: true, disabled: actions.busy || permissions.can_rematch === false }),
          button('New game', actions.newGame, { disabled: actions.busy || permissions.can_manage === false }),
          button('Back', actions.back)
        ] })
      ]
    })
  })
}

function talkTeamsBoard(pictured, actions) {
  const teams = pictured.teams || []
  const mine = pictured.mine || {}
  const myTeam = teams.find(team => team.team === mine.team) || teams[0]
  const otherTeam = teams.find(team => myTeam && team.team !== myTeam.team) || teams[1]
  const places = pictured.places || []
  return jsxs('div', {
    className: 'games-talk-teams',
    style: {
      position: 'relative', display: 'flex', flexDirection: 'column', gap: 10,
      padding: 14, border: `1px solid ${stroke}`, borderRadius: 18, background: fill,
      minHeight: 330
    },
    children: [
      talkTeamRow(otherTeam, places, mine, 'Other team'),
      talkTeamCenter(pictured),
      talkTeamRow(myTeam, places, mine, 'Your team'),
      talkResultOverlay(pictured, actions)
    ]
  })
}

function talkLog(pictured) {
  const rows = pictured.log || []
  return jsxs('div', {
    className: 'games-talk-log',
    style: { display: 'flex', flexDirection: 'column', minHeight: 0, height: '100%', border: `1px solid ${stroke}`, borderRadius: 12, background: card },
    children: [
      jsx('div', {
        style: { padding: '10px 12px', borderBottom: `1px solid ${stroke}`, fontSize: 12, fontWeight: 700, color: text.secondary },
        children: 'What happened'
      }),
      jsx('ol', {
        'aria-label': 'Table log',
        style: { listStyle: 'none', margin: 0, padding: '8px 12px', overflowY: 'auto', flex: 1, minHeight: 0, display: 'flex', flexDirection: 'column', gap: 6 },
        children: rows.length
          ? rows.map((row, index) =>
              jsxs('li', {
                key: `log-${index}`,
                style: {
                  fontSize: 12,
                  lineHeight: 1.4,
                  color: row.kind === 'say' ? text.primary : text.tertiary,
                  fontStyle: row.kind === 'say' ? 'normal' : 'italic'
                },
                children: [
                  row.name ? jsx('span', { style: { fontWeight: 700, marginRight: 6, color: text.secondary }, children: `${row.name}:` }) : null,
                  jsx('span', { children: row.text })
                ]
              })
            )
          : jsx('li', { style: { fontSize: 12, color: text.tertiary }, children: 'Nothing has been said yet.' })
      })
    ]
  })
}

function talkReveal(pictured) {
  const reveal = pictured.reveal || {}
  const names = {}
  ;(pictured.places || []).forEach(place => { names[place.seat] = place.name })
  const rows = []
  if (pictured.game === 'mafia') {
    ;(reveal.roles || []).forEach(row => rows.push([names[row.seat] || `Player ${row.seat + 1}`, row.role]))
  } else if (pictured.game === 'liars-dice') {
    ;(reveal.dice || []).forEach(row => rows.push([names[row.seat] || `Player ${row.seat + 1}`, (row.dice || []).join(' · ') || 'no dice left']))
  } else if (pictured.game === 'blind-auction') {
    ;(reveal.lots || []).forEach(row => rows.push([
      row.name,
      row.winner == null ? 'nobody' : `${names[row.winner] || `Player ${row.winner + 1}`} paid ${row.paid}`
    ]))
  } else if (pictured.game === 'prisoners-dilemma') {
    ;(reveal.points || []).forEach(row => rows.push([names[row.seat] || `Player ${row.seat + 1}`, `${row.points} points in the last match`]))
  }
  return jsxs('section', {
    'aria-label': 'Reveal',
    style: { display: 'flex', flexDirection: 'column', gap: 8, padding: 12, border: `1px solid ${stroke}`, borderRadius: 12, background: fill },
    children: [
      jsx('div', { style: { fontSize: 13, fontWeight: 700 }, children: 'The reveal' }),
      rows.length
        ? jsx('div', { style: { display: 'flex', flexDirection: 'column', gap: 4 }, children: rows.map((row, index) =>
            jsxs('div', { key: `reveal-${index}`, style: { display: 'flex', justifyContent: 'space-between', gap: 10, fontSize: 12 }, children: [
              jsx('span', { style: { color: text.secondary }, children: row[0] }),
              jsx('span', { style: { color: text.primary, fontWeight: 600 }, children: row[1] })
            ] })) })
        : null,
      reveal.reason ? jsx('div', { style: { fontSize: 12, color: text.secondary }, children: reveal.reason }) : null
    ]
  })
}

// ---- Watch it think: the owner's own bot's working, and the corner coach ----
// A bot's Read answers and its scratchpad are private. The backend sends them
// only to the person whose seat shares that bot; this panel renders what it was
// given and never asks for more.
function talkThinkHeading(label) {
  return jsxs('div', {
    style: { display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', gap: 8 },
    children: [
      jsx('div', { style: { fontSize: 12, fontWeight: 700, color: text.secondary }, children: label }),
      jsx('span', { style: { fontSize: 10, letterSpacing: '.08em', textTransform: 'uppercase', color: text.tertiary }, children: 'only you' })
    ]
  })
}

function talkReadRows(entry) {
  const rows = entry.read || []
  if (!rows.length) return null
  return jsx('div', {
    className: 'games-think-read',
    style: { display: 'flex', flexDirection: 'column', gap: 6 },
    children: rows.map((row, index) => jsxs('div', {
      key: `read-${entry.seat}-${index}`,
      style: { display: 'flex', flexDirection: 'column', gap: 1 },
      children: [
        jsx('div', { style: { fontSize: 10, letterSpacing: '.06em', textTransform: 'uppercase', color: text.tertiary }, children: row.label }),
        jsx('div', { style: { fontSize: 11.5, lineHeight: 1.4, color: text.secondary }, children: row.text || '—' })
      ]
    }))
  })
}

function talkThinkEntry(entry) {
  return jsxs('div', {
    key: `think-${entry.seat}`,
    className: 'games-think-entry',
    style: { display: 'flex', flexDirection: 'column', gap: 8, padding: 10, borderRadius: 12, border: `1px solid ${stroke}`, background: card },
    children: [
      jsxs('div', { style: { display: 'flex', alignItems: 'center', gap: 7, minWidth: 0 }, children: [
        jsx('span', {
          style: { width: 24, height: 24, borderRadius: 12, display: 'grid', placeItems: 'center', fontSize: 13, border: `1px solid ${stroke}`, flex: '0 0 auto' },
          children: entry.avatar || '●'
        }),
        jsx('div', { style: { fontSize: 12, fontWeight: 700, minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }, children: entry.name })
      ] }),
      entry.action
        ? jsx('div', {
            className: 'games-think-action',
            title: entry.action,
            style: {
              fontSize: 11, lineHeight: 1.4, color: accent, overflowWrap: 'anywhere',
              border: `1px solid ${accent}`, borderRadius: 8, padding: '3px 7px'
            },
            children: entry.action
          })
        : null,
      entry.fallback
        ? jsx('div', { style: { fontSize: 11.5, color: text.tertiary }, children: 'Its model did not answer, so the built-in player took that turn.' })
        : null,
      talkReadRows(entry),
      entry.scratch
        ? jsx('div', {
            className: 'games-think-scratch',
            style: {
              fontFamily: 'var(--font-mono, ui-monospace, monospace)', fontSize: 11.5, lineHeight: 1.45,
              color: text.secondary, background: fill, border: `1px solid ${stroke}`, borderRadius: 8,
              padding: '8px 9px', maxHeight: 120, overflowY: 'auto', whiteSpace: 'pre-wrap'
            },
            children: entry.scratch
          })
        : null
    ]
  })
}

function talkThinkPanel(pictured) {
  const entries = pictured.think || []
  const owned = (pictured.places || []).filter(place => place.kind === 'agent' || place.kind === 'champion')
  const shell = children => jsxs('section', {
    'aria-label': 'Inside its head',
    className: 'games-think',
    style: { display: 'flex', flexDirection: 'column', gap: 8, padding: 10, borderRadius: 12, border: `1px solid ${stroke}`, background: fill, minHeight: 0, flex: '0 0 auto' },
    children: [talkThinkHeading('Inside its head'), ...children]
  })
  if (!owned.length) {
    return shell([jsx('div', {
      style: { fontSize: 11.5, lineHeight: 1.45, color: text.tertiary },
      children: 'Their thinking stays private at a table you are not sitting at.'
    })])
  }
  if (!entries.length) {
    const names = owned.map(place => place.name).join(' and ')
    return shell([jsx('div', {
      className: 'games-think-waiting',
      style: { fontSize: 11.5, lineHeight: 1.45, color: text.tertiary },
      children: `${names} has not moved yet. Its Read answers and working appear here, and only you see them.`
    })])
  }
  return shell([
    pictured.coach && pictured.coach.used_round && pictured.coach.text
      ? jsxs('div', {
          className: 'games-think-coach',
          style: { fontSize: 11.5, color: text.secondary, borderLeft: `2px solid ${accent}`, paddingLeft: 8 },
          children: [
            jsx('div', { style: { fontSize: 10, letterSpacing: '.06em', textTransform: 'uppercase', color: text.tertiary }, children: 'Your whisper this round' }),
            jsx('div', { children: pictured.coach.text })
          ]
        })
      : null,
    ...entries.map(talkThinkEntry)
  ])
}

// One sentence, 15 seconds, once a round. The clock is the backend's; this only
// draws it down between polls so the window does not look frozen.
function TalkCoachBox({ pictured, whisper, busy }) {
  const coach = pictured.coach || {}
  const [said, setSaid] = useState('')
  const [, setTick] = useState(0)
  const until = Number(coach.until || 0)
  useEffect(() => {
    if (!coach.open) return undefined
    const timer = setInterval(() => setTick(value => value + 1), 500)
    return () => clearInterval(timer)
  }, [coach.open, until])
  if (!coach.available) return null
  const left = until ? Math.max(0, until - Math.floor(Date.now() / 1000)) : 0
  const open = Boolean(coach.open) && left > 0
  const used = Boolean(coach.used_round)
  const name = coach.name || 'your bot'
  const state_ = used
    ? `Whispered${coach.text ? `: “${coach.text}”` : ''}. ${name} reads it before its next move.`
    : open
      ? `${left}s left of this round's whisper window.`
      : `One whisper a round, between rounds. Next window opens when the round turns.`
  return jsxs('section', {
    'aria-label': 'Corner Coach',
    className: 'games-coach',
    style: { display: 'flex', flexDirection: 'column', gap: 7, padding: 10, borderRadius: 12, border: `1px solid ${open ? accent : stroke}`, background: card },
    children: [
      jsxs('div', { style: { display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', gap: 8 }, children: [
        jsx('div', { style: { fontSize: 12, fontWeight: 700, color: text.secondary }, children: 'Corner Coach' }),
        jsx('div', { className: 'games-coach-clock', style: { fontSize: 11, color: open ? accent : text.tertiary }, children: open ? `${left}s` : used ? 'sent' : 'waiting' })
      ] }),
      open
        ? jsx('div', {
            'aria-hidden': 'true',
            style: { height: 3, borderRadius: 2, background: fill, overflow: 'hidden' },
            children: jsx('div', { style: { height: '100%', width: `${Math.min(100, Math.max(0, (left / 15) * 100))}%`, background: accent, transition: 'width .5s linear' } })
          })
        : null,
      open
        ? jsxs('div', { style: { display: 'flex', gap: 6, alignItems: 'center' }, children: [
            jsx('input', {
              value: said,
              'aria-label': 'One sentence for your bot',
              placeholder: `One sentence for ${name}`,
              maxLength: 120,
              disabled: busy,
              onChange: event => setSaid(event.target.value.slice(0, 120)),
              onKeyDown: event => {
                if (event.key === 'Enter' && said.trim() && !busy) { whisper(said.trim()); setSaid('') }
              },
              style: { flex: 1, minWidth: 0, padding: '7px 9px', borderRadius: 8, border: `1px solid ${stroke}`, background: 'transparent', color: 'inherit', fontSize: 12 }
            }),
            button('Whisper', () => { if (said.trim()) { whisper(said.trim()); setSaid('') } },
              { primary: true, disabled: busy || !said.trim(), label: 'Whisper this sentence to your bot' })
          ] })
        : null,
      jsx('div', { className: 'games-coach-state', style: { fontSize: 11, lineHeight: 1.4, color: used ? text.secondary : text.tertiary }, children: state_ }),
      open ? jsx('div', { style: { fontSize: 10.5, color: text.tertiary }, children: `${said.length} of 120 characters` }) : null
    ]
  })
}

function talkSetup({ game, pictured, seats, setSeats, level, setLevel, agent, setAgent, champions, setChampions, busy, start, startLearn, back, watch, openShared, failure, ctx, aiAllowed = true }) {
  const limits = pictured.limits || { min: 2, max: 6, default: 2 }
  const offered = pictured.champions || []
  const levels = pictured.levels || []
  const invitesMax = pictured.max_invites == null ? seats - 1 : Number(pictured.max_invites)
  const picked = invitesMax - champions.length - (agent ? 1 : 0)
  const seatButtons = []
  for (let count = limits.min; count <= limits.max; count += 1) {
    seatButtons.push(button(`${count} seats`, () => setSeats(count), { primary: count === seats }))
  }
  const invites = [
    button(agent ? 'Your agent is in' : 'Seat your agent', () => setAgent(!agent),
      { primary: agent, disabled: !aiAllowed || (picked <= 0 && !agent) })
  ].concat(offered.map(champion =>
    button(
      champions.includes(champion.id) ? `${champion.name} is in` : `Invite ${champion.name}`,
      () => setChampions(champions.includes(champion.id)
        ? champions.filter(id => id !== champion.id)
        : (picked > 0 ? champions.concat([champion.id]) : champions)),
      { primary: champions.includes(champion.id) })
  ))
  return jsxs('div', {
    className: 'games-talk-setup',
    style: { display: 'flex', flexDirection: 'column', gap: 14, padding: 18, overflow: 'auto', height: '100%' },
    children: [
      jsx('div', { style: { fontSize: 20, fontWeight: 700 }, children: pictured.title || game.title }),
      game.subtitle ? jsx('div', { style: { fontSize: 12, fontStyle: 'italic', color: text.secondary }, children: game.subtitle }) : null,
      jsx('div', { style: { fontSize: 13, color: text.secondary, maxWidth: 640, lineHeight: 1.5 }, children: pictured.blurb || game.summary }),
      jsxs('div', { children: [
        jsx('div', { style: { fontSize: 12, fontWeight: 700, color: text.secondary, marginBottom: 6 }, children: 'How many seats' }),
        limits.max > limits.min
          ? jsx('div', { style: { display: 'flex', gap: 6, flexWrap: 'wrap' }, children: seatButtons })
          : jsx('div', { style: { fontSize: 12.5, color: text.secondary }, children: 'Four seats: you and a partner on one team, two computer players on the other. Turns alternate between the teams.' })
      ] }),
      levels.length
        ? jsxs('div', { children: [
            jsx('div', { style: { fontSize: 12, fontWeight: 700, color: text.secondary, marginBottom: 6 }, children: 'Computer strength' }),
            jsx('div', { style: { display: 'flex', gap: 6, flexWrap: 'wrap' }, children: levels.map(entry =>
              button(entry.label, () => setLevel(entry.id), { primary: entry.id === (level || levels[1]?.id || levels[0]?.id) })) })
          ] })
        : null,
      jsxs('div', { children: [
        jsx('div', { style: { fontSize: 12, fontWeight: 700, color: text.secondary, marginBottom: 6 }, children: 'Who sits down' }),
        jsx('div', {
          style: { fontSize: 12, color: text.tertiary, marginBottom: 6 },
          children: pictured.max_invites === 1
            ? 'Seat 1 is you, and your guest sits opposite you on the same team. The other two seats are the computer pair.'
            : 'Seat 1 is you. Every other seat is the built-in player unless you seat your agent or invite a champion.'
        }),
        jsx('div', { style: { display: 'flex', gap: 6, flexWrap: 'wrap' }, children: invites })
      ] }),
      jsx('div', {
        style: { fontSize: 12, color: text.secondary, padding: '10px 12px', border: `1px solid ${stroke}`, borderRadius: 10 },
        children: agent || champions.length
          ? `This table will ask a model about ${pictured.estimate || 0} time(s). Any answer that is late or not allowed is covered by the built-in player, and the table says so.`
          : 'No model is needed for this table: every other seat is the built-in player.'
      }),
      aiAllowed ? null : jsx('div', {
        style: { fontSize: 12, color: text.secondary },
        children: 'AI is off for this profile, so there is nobody to sit at this table with you. Turn it back on in Game Center settings to play a talking table.'
      }),
      failure ? jsx('div', {
        role: 'alert',
        style: { fontSize: 12, color: 'var(--ui-danger, #e06c75)' },
        children: failure
      }) : null,
      jsxs('div', { style: { display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'center' }, children: [
        button('Start the game', start, { primary: true, disabled: busy || !aiAllowed }),
        button('Watch computers play', watch, { disabled: busy || !aiAllowed, title: 'No person in any seat: you only watch, and no secrets are shown.' }),
        button('Back', back),
        jsx(LearnButton, { game, ctx, onStartLearn: startLearn }),
        jsx('label', { style: { fontSize: 12, color: text.secondary, display: 'inline-flex', alignItems: 'center', gap: 6 }, children: [
          'Open a game file',
          jsx('input', { type: 'file', accept: '.json,application/json', onChange: openShared, style: { fontSize: 11 } })
        ] })
      ] })
    ]
  })
}

function TalkingTable({ game, view, board, send, onBack, refresh, ctx }) {
  const [busy, setBusy] = useState(false)
  const [failure, setFailure] = useState('')
  const [notice, setNotice] = useState('')
  const [message, setMessage] = useState('')
  const [seats, setSeats] = useState(0)
  const [agent, setAgent] = useState(false)
  const [champions, setChampions] = useState([])
  const [level, setLevel] = useState('')
  const latest = useRef(null)
  const alive = useRef(true)
  useEffect(() => {
    alive.current = true
    return () => { alive.current = false }
  }, [])
  const pictured = (board && board.picture) || null
  // Guided first game (Learn → Play & Learn): the rules' margin notes ride in the
  // table picture; the guide steps come from the game's learn.json.
  const learnBook = useLearnData(ctx, game.id, Boolean(pictured && pictured.learn))
  const [guideStep, setGuideStep] = useState(0)
  useEffect(() => {
    if (!pictured || !pictured.preview) return
    setSeats(Number((pictured.limits && pictured.limits.default) || 2))
  }, [game.id])
  const run = async line => {
    if (busy || !alive.current) return false
    setBusy(true)
    setFailure('')
    try {
      const answer = await send(line)
      if (answer && answer.ok === false) throw new Error(answer.text || 'The table refused that.')
      if (alive.current) setNotice((answer && answer.text) || '')
      return true
    } catch (error) {
      if (alive.current) setFailure(error.message || 'That did not reach the table.')
      return false
    } finally {
      if (alive.current) setBusy(false)
    }
  }
  const modelName = view && view.opponent && view.opponent.model
  const whisper = async text => {
    if (!text.trim() || busy) return false
    return run(`${game.id} coach ${text.trim()}`)
  }
  // Between rounds the table holds still for one whisper: while the owner's own
  // bot is the next to move and the window is open, the machine seats wait.
  const coached = (pictured && (pictured.places || []).some(place =>
    place.playing && (place.kind === 'agent' || place.kind === 'champion'))) || false
  const holding = Boolean(pictured && pictured.coach && pictured.coach.open && coached)
  const acting = Boolean(pictured && pictured.status === 'active' && pictured.can_step && !holding)
  latest.current = { ready: acting, step: () => send(`${game.id} step`) }
  // Machine seats play themselves while the person watches, one turn at a time.
  useEffect(() => {
    if (!acting) return undefined
    return startTableWatch(
      async () => {
        const answer = await latest.current.step()
        if (answer && answer.ok === false) throw new Error(answer.text || 'A seat could not move.')
        return true
      },
      () => latest.current.ready,
      error => { if (alive.current) setFailure(error.message || 'A seat could not move.') }
    )
  }, [acting, game.id])
  useEffect(() => { setMessage(''); setGuideStep(0) }, [pictured && pictured.table_id, pictured && pictured.phase])
  // A shared file is opened from the same screen that offers it after a game: a person
  // who was sent one has no game of their own to finish first.
  const openShared = async event => {
    const file = event && event.target && event.target.files && event.target.files[0]
    if (!file) return
    try {
      const text = await file.text()
      const answer = await ctx.rest('/talk/import', { method: 'POST', body: { game: game.id, text } })
      if (answer.ok === false) throw new Error(answer.text || 'That file was refused.')
      if (refresh) await refresh()
      setNotice(answer.text || 'Opened the game file.')
    } catch (error) {
      setFailure(error.message || 'That file could not be opened.')
    }
  }
  if (!pictured) {
    return jsx('div', { style: { padding: 18, color: text.tertiary }, children: 'Opening the table…' })
  }
  if (pictured.status === 'idle' || pictured.preview) {
    const start = () => {
      const parts = [`${game.id} new`, `seats=${seats || ((pictured.limits && pictured.limits.default) || 2)}`]
      if (level) parts.push(`level=${level}`)
      else if ((pictured.levels || []).length) parts.push(`level=${pictured.levels[1] ? pictured.levels[1].id : pictured.levels[0].id}`)
      if (agent) parts.push('agent=1')
      if (champions.length) parts.push(`champions=${champions.join(',')}`)
      run(parts.join(' '))
    }
    return jsx('div', {
      style: { height: '100%', minHeight: 0, background: paper },
      children: talkSetup({
        game, pictured,
        seats: seats || (pictured.limits && pictured.limits.default) || 2,
        setSeats,
        level,
        setLevel,
        agent,
        setAgent,
        champions,
        setChampions,
        busy,
        start,
        startLearn: () => run(`${game.id} new seats=2 learn`),
        watch: () => run(`${game.id} new seats=${seats || ((pictured.limits && pictured.limits.default) || 2)} bots=1`),
        back: () => onBack(),
        openShared,
        failure,
        ctx,
        aiAllowed: !(view && view.allow_ai === false)
      })
    })
  }
  const places = pictured.places || []
  const done = pictured.status !== 'active'
  const yourTurn = Boolean(pictured.can_move)
  const say = () => {
    const line = message.trim()
    if (!line) return
    setMessage('')
    run(`${game.id} say ${line}`)
  }
  const act = id => run(`${game.id} act ${id}`)
  const shareReplay = () => {
    if (!pictured.share) return
    const saved = saveFile(`${game.id}-game.json`, JSON.stringify(pictured.share, null, 2))
    setNotice(saved ? 'Saved the game file.' : 'This window cannot save files.')
  }
  const standings = pictured.standings || []
  const groups = []
  ;(pictured.actions || []).forEach(item => {
    const group = item.group || ''
    let bucket = groups.find(entry => entry.group === group)
    if (!bucket) { bucket = { group, items: [] }; groups.push(bucket) }
    bucket.items.push(item)
  })
  const chips = groups.filter(group => group.group)
  const plain = groups.filter(group => !group.group).reduce((all, group) => all.concat(group.items), [])
  const statusLine = done
    ? 'The game is over.'
    : (holding
        ? `Corner Coach is listening — ${Math.max(0, Number((pictured.coach && pictured.coach.seconds_left) || 0))}s to whisper.`
        : (pictured.watching
            ? `You are watching · ${pictured.turn_name || 'a seat'} is playing…`
            : (yourTurn
                ? (pictured.can_say ? 'Your turn: say something.' : 'Your turn.')
                : `${pictured.turn_name || 'A seat'} is thinking…`)))

  const resultActions = {
    rematch: () => run(`${game.id} rematch`),
    newGame: () => run(`${game.id} abandon`),
    back: () => onBack(),
    busy
  }

  return jsxs('div', {
    className: 'games-talk',
    style: {
      display: 'grid',
      gridTemplateColumns: 'minmax(0, 1fr) minmax(240px, 330px)',
      gap: 14,
      padding: 16,
      height: '100%',
      minHeight: 0,
      background: paper
    },
    children: [
      jsxs('div', { style: { display: 'flex', flexDirection: 'column', gap: 12, minWidth: 0, minHeight: 0, overflow: 'auto' }, children: [
        jsxs('div', { style: { display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', gap: 10 }, children: [
          jsxs('div', { children: [
            jsxs('div', { style: { display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }, children: [
              jsx('div', { style: { fontSize: 20, fontWeight: 700 }, children: pictured.title || game.title }),
              LABS_TALKING_IDS.includes(game.id) ? labsBadge() : null
            ] }),
            game.subtitle ? jsx('div', { style: { fontSize: 12, fontStyle: 'italic', color: text.secondary }, children: game.subtitle }) : null,
            jsx('div', { className: 'games-status', style: { fontSize: 12, color: text.secondary }, children: statusLine })
          ] }),
          jsxs('div', { style: { display: 'flex', gap: 6 }, children: [
            button('New table', () => run(`${game.id} abandon`), { disabled: busy, title: 'Close this table and choose the seats again.' }),
            jsx(LearnButton, { game, ctx }),
            button('Back', onBack)
          ] })
        ] }),
        pictured.game === 'liars-dice-2v2'
          ? talkTeamsBoard(pictured, resultActions)
          : jsxs('div', {
              className: 'games-talk-table',
              style: { position: 'relative', width: '100%', minHeight: 330, aspectRatio: '4 / 3', border: `1px solid ${stroke}`, borderRadius: 18, background: fill, overflow: 'hidden' },
              children: [
                jsx('div', { style: { position: 'absolute', left: '22%', top: '24%', width: '56%', height: '52%', borderRadius: '50%', border: `1px solid ${stroke}` } }),
                ...places.map(place => talkSeat(place, places.length, acting)),
                done ? talkResultOverlay(pictured, resultActions) : talkMiddle(pictured)
              ]
            }),
        // Guided game: the rules walk one step at a time, and the machine seat
        // explains its own moves; a risky move gets a warning and Undo.
        pictured.learn ? jsx(CoachGuide, { game, pictured, learn: learnBook.data, guideStep, setGuideStep }) : null,
        jsx(CoachStrip, {
          game, pictured,
          command: line => run(line),
          lock: options => ({ ...options, disabled: busy || Boolean(options && options.disabled) })
        }),
        done
          ? talkReveal(pictured)
          : jsxs('div', { className: 'games-talk-actions', style: { display: 'flex', flexDirection: 'column', gap: 8 }, children: [
              plain.length
                ? jsx('div', { style: { display: 'flex', gap: 6, flexWrap: 'wrap' }, children: plain.map(item =>
                    button(item.label, () => act(item.id),
                      { primary: item.id === 'send' || item.id === 'cooperate', disabled: busy || item.disabled, title: item.hint })) })
                : null,
              ...chips.map(group => jsxs('div', { key: group.group, style: { display: 'flex', gap: 6, alignItems: 'center', flexWrap: 'wrap' }, children: [
                jsx('span', { style: { fontSize: 11, color: text.tertiary, minWidth: 52 }, children: group.group }),
                ...group.items.map(item => button(item.label, () => act(item.id),
                  { primary: item.on, disabled: busy || item.disabled, title: item.hint }))
              ] }))
            ] }),
        jsxs('div', { style: { display: 'flex', gap: 6, alignItems: 'center' }, children: [
          jsx('input', {
            value: message,
            placeholder: pictured.can_say ? 'Say something to the table' : 'You can talk when it is your turn in a talking phase',
            disabled: !pictured.can_say,
            maxLength: 200,
            onChange: event => setMessage(event.target.value),
            onKeyDown: event => { if (event.key === 'Enter' && pictured.can_say) say() },
            style: { flex: 1, minWidth: 0, padding: '8px 10px', borderRadius: 8, border: `1px solid ${stroke}`, background: 'transparent', color: 'inherit', fontSize: 13, opacity: pictured.can_say ? 1 : 0.6 }
          }),
          button('Say it', say, { primary: true, disabled: !pictured.can_say || !message.trim() || busy })
        ] }),
        notice ? jsx('div', { style: { fontSize: 12, color: text.tertiary }, children: notice }) : null,
        failure ? jsx('div', { role: 'alert', style: { fontSize: 12, color: 'var(--ui-danger, #e06c75)' }, children: failure }) : null,
        (pictured.notes || []).length
          ? jsx('div', { style: { fontSize: 12, color: text.tertiary }, children: pictured.notes[pictured.notes.length - 1] })
          : null,
        done
          ? jsxs('div', { style: { display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'center' }, children: [
              button('Play again', () => run(`${game.id} rematch`), { primary: true, disabled: busy }),
              button('Set up a new table', () => run(`${game.id} abandon`), { disabled: busy }),
              button('Save the game file', shareReplay, { disabled: !pictured.share }),
              jsx('label', { style: { fontSize: 12, color: text.secondary, display: 'inline-flex', alignItems: 'center', gap: 6 }, children: [
                'Open a game file',
                jsx('input', { type: 'file', accept: '.json,application/json', onChange: openShared, style: { fontSize: 11 } })
              ] })
            ] })
          : null
      ] }),
      jsxs('div', { style: { display: 'flex', flexDirection: 'column', gap: 10, minHeight: 0, overflowY: 'auto' }, children: [
        done ? null : talkThinkPanel(pictured),
        jsx('div', { style: { display: 'flex', flexDirection: 'column', minHeight: 0, flex: '1 1 auto' }, children: talkLog(pictured) }),
        standings.length > 1
          ? jsxs('div', { style: { border: `1px solid ${stroke}`, borderRadius: 12, padding: 10, background: card }, children: [
              jsx('div', { style: { fontSize: 12, fontWeight: 700, color: text.secondary, marginBottom: 6 }, children: 'Scores' }),
              ...standings.map(row => jsxs('div', { key: `score-${row.seat}`, style: { display: 'flex', justifyContent: 'space-between', fontSize: 12, color: text.secondary }, children: [
                jsx('span', { children: row.name }),
                jsx('span', { style: { color: text.primary, fontWeight: 600 }, children: String(row.score) })
              ] }))
            ] })
          : null,
        jsx('div', {
          style: { fontSize: 11, color: text.tertiary },
          children: `Model calls: ${pictured.calls ? pictured.calls.used : 0} of ${pictured.calls ? pictured.calls.cap : 0}` +
            (pictured.calls && pictured.calls.fallbacks ? ` · ${pictured.calls.fallbacks} covered by the built-in player` : '') +
            (modelName ? ` · ${modelName}` : '')
        }),
        done ? null : jsx(TalkCoachBox, { pictured, whisper, busy })
      ] })
    ]
  })
}

// ---- 40-doctrine.js: Doctrine: the card battle panel
function DoctrinePanel({ game, view, board, send, playMove, importText, refresh, ctx, onBack }) {
  const pictured = (board && board.picture) || startingPicture('doctrine')
  const d = (pictured && pictured.doctrine) || {}
  const frames = d.frames || []
  const watching = d.mode === 'watch' || d.mode === 'shared'
  const [busy, setBusy] = useState(false)
  const [failure, setFailure] = useState('')
  const [notice, setNotice] = useState('')
  const [auto, setAuto] = useState(false)
  const [index, setIndex] = useState(0)
  const [opponent, setOpponent] = useState('stone-bastion')
  const [seed, setSeed] = useState('1')
  const [pasted, setPasted] = useState('')
  const [cardText, setCardText] = useState(d.card_json || '')
  const [profile, setProfile] = useState('')
  const [panel, setPanel] = useState('')
  const [asking, setAsking] = useState(null)
  const alive = useRef(true)
  const pending = useRef(false)

  useEffect(() => {
    alive.current = true
    return () => { alive.current = false }
  }, [])
  useEffect(() => { setIndex(0); setAuto(false) }, [d.id])
  // Refresh the editor when the card really changed, but never overwrite unsaved edits.
  // A different card (new name) always replaces the editor.
  const lastCard = useRef(d.card_json || '')
  const lastName = useRef((d.your_card && d.your_card.name) || '')
  useEffect(() => {
    const next = d.card_json || ''
    const name = (d.your_card && d.your_card.name) || ''
    if (!next) return
    if (name !== lastName.current) {
      setCardText(next)
      lastCard.current = next
      lastName.current = name
      return
    }
    if (next !== lastCard.current) {
      const previous = lastCard.current
      setCardText(current => (current === previous ? next : current))
      lastCard.current = next
    }
  }, [d.card_json, d.your_card && d.your_card.name])
  useEffect(() => {
    if (!auto || !watching || !frames.length) return
    if (index >= frames.length - 1) { setAuto(false); return }
    const timer = setTimeout(() => setIndex(value => Math.min(value + 1, frames.length - 1)), WATCH_MS)
    return () => clearTimeout(timer)
  }, [auto, watching, index, frames.length])

  const run = async action => {
    if (pending.current || !alive.current) return false
    pending.current = true
    setBusy(true)
    setFailure('')
    try {
      const answer = await action()
      if (answer && answer.ok === false) throw new Error(answer.text || 'The table refused that action.')
      if (alive.current) setNotice((answer && answer.text) || '')
      return true
    } catch (error) {
      if (alive.current) setFailure(error.message || 'That did not reach the table.')
      return false
    } finally {
      pending.current = false
      if (alive.current) setBusy(false)
    }
  }
  const command = line => run(() => send(`doctrine ${line}`))
  // Asking the person's own model (Improve my bot) can take a while: say so.
  const askFor = async (what, action) => {
    if (alive.current) setAsking(what)
    try {
      return await run(action)
    } finally {
      if (alive.current) setAsking(null)
    }
  }
  const importValue = text => run(async () => {
    // A replay is far bigger than one /command line, so the backend has a second door.
    const answer = importText ? await importText(text) : await send(`doctrine import ${text}`)
    if (refresh) await refresh()
    return answer
  })

  const at = Math.min(index, Math.max(0, frames.length - 1))
  const frame = watching ? frames[at] || null : frames[frames.length - 1] || null
  const shownPicture = {
    ...pictured,
    view: 'hex',
    game: 'doctrine',
    cells: (frame && frame.board) || pictured.cells || emptyGrid(11, 11),
    legal: watching ? [] : pictured.legal || []
  }
  const interactive = Boolean(!watching && d.can_move && !busy)
  const rows = (d.scoreboard || []).map(row => {
    const units = frame && frame.units && frame.units[row.id]
    const score = frame && frame.scores && frame.scores[row.id] !== undefined ? frame.scores[row.id] : row.score
    const beacons = frame && frame.beacons && frame.beacons[row.id] !== undefined ? frame.beacons[row.id] : row.beacons
    return {
      ...row,
      score,
      beacons,
      units: units ? units.length : row.units,
      hp: units ? units.reduce((total, unit) => total + (unit.hp || 0), 0) : row.hp
    }
  })
  const sentence = frame && frame.events && frame.events.length
    ? frame.events.join(' · ')
    : d.sentence || ''
  const leftToMove = Object.keys(d.legal_units || {}).length
  const houseOptions = (d.house || []).map(card => jsx('option', { value: card.id, children: card.name }, card.id))
  // "Your card" also lists this person's saved, improved and imported cards,
  // not only the four house cards.
  const cardOptions = (d.cards || d.house || []).map(card => jsx('option', {
    value: card.id,
    children: card.origin === 'yours' && !String(card.name).endsWith('(yours)') ? `${card.name} (yours)` : card.name
  }, `${card.id}:${card.name}`))
  const cardChoices = d.cards || d.house || []
  const yourId = cardChoices.find(card => card.current === true)
    || cardChoices.find(card => d.your_card
      && String(card.name).replace(' (yours)', '') === d.your_card.name)
  const download = async kind => {
    const answer = await send(kind ? `doctrine export ${kind}` : 'doctrine export')
    const value = answer && answer.text
    if (!value) { setFailure('Nothing to export yet.'); return }
    try {
      if (typeof document === 'undefined' || typeof Blob === 'undefined' || typeof URL === 'undefined') {
        setNotice(value.slice(0, 400))
        return
      }
      const url = URL.createObjectURL(new Blob([value], { type: 'application/json' }))
      const anchor = document.createElement('a')
      anchor.href = url
      anchor.download = kind ? 'doctrine-replay.json' : 'doctrine-card.json'
      anchor.click()
      setTimeout(() => URL.revokeObjectURL(url), 1000)
      setNotice(`Saved ${anchor.download}.`)
    } catch (error) {
      setFailure('This window cannot save files. Copy the JSON instead.')
    }
  }
  const readFile = async event => {
    const file = event.target.files && event.target.files[0]
    if (!file) return
    try {
      const text = await file.text()
      await importValue(text)
    } catch (error) {
      setFailure('That file could not be read.')
    }
    event.target.value = ''
  }

  return jsxs('div', {
    className: 'games-play-table doctrine-panel',
    style: { display: 'flex', flexDirection: 'column', gap: 12, padding: 18, paddingBottom: 96, minWidth: 0, overflow: 'auto', background: paper, height: '100%' },
    children: [
      jsxs('div', {
        style: { display: 'flex', justifyContent: 'space-between', gap: 12, alignItems: 'center' },
        children: [
          jsx('div', { style: { fontWeight: 700, fontSize: 22 }, children: game.title || 'Doctrine' }),
          jsxs('div', { style: { display: 'flex', gap: 8 } , children: [
            jsx(LearnButton, { game, ctx }),
            button('Back', () => { alive.current = false; onBack() })
          ] })
        ]
      }),
      jsxs('div', {
        style: { display: 'flex', flexWrap: 'wrap', gap: 8, alignItems: 'center', fontSize: 12, color: text.secondary },
        children: [
          badge(d.mode === 'human' ? 'You against a card' : d.mode === 'watch' ? 'Watching bots' : d.mode === 'shared' ? 'Shared replay' : 'Choose a match'),
          badge(frames.length ? `Turn ${frame ? frame.turn : 0} of ${frames.length}` : d.mode === 'human' ? `Turn ${d.turn} of ${d.max_turns}` : 'No battle yet'),

          jsx('span', { style: { color: text.tertiary }, children: `Your card: ${(d.your_card && d.your_card.name) || 'none'}` })
        ]
      }),
      jsxs('section', {
        'aria-label': 'Score panel',
        style: { border: `1px solid ${stroke}`, borderRadius: 12, padding: 10, background: card, display: 'flex', flexDirection: 'column', gap: 6 },
        children: [
          heading('Score panel'),
          ...(rows.length ? rows.map(row => jsxs('div', {
            style: {
              display: 'grid', gridTemplateColumns: 'minmax(0, 1fr) repeat(3, auto)', gap: 10, alignItems: 'baseline',
              fontFamily: 'var(--font-mono, monospace)', fontSize: 12, color: row.units === 0 ? text.tertiary : text.secondary
            },
            children: [
              jsx('span', { style: { color: text.primary, fontWeight: row.you ? 700 : 500, overflowWrap: 'anywhere' }, children: `${row.name}${row.you ? ' (you)' : ''}` }),
              jsx('span', { children: `${row.units} units · ${row.hp} hp` }),
              jsx('span', { children: `${row.beacons} beacons` }),
              jsx('b', { style: { color: text.primary }, children: String(row.score) })
            ]
          }, row.id)) : [jsx('div', { style: { fontSize: 12, color: text.tertiary }, children: 'Start a match to see units, beacons and score.' })])
        ]
      }),
      jsx('div', {
        className: 'doctrine-board-panel',
        style: { display: 'flex', justifyContent: 'center', padding: 8, background: card, border: `1px solid ${stroke}`, borderRadius: 12, overflow: 'hidden' },
        children: jsx(BoardSvg, {
          picture: shownPicture,
          height: 460,
          flat: true,
          interactive,
          onMove: token => { if (interactive) run(() => playMove('doctrine', token)) }
        })
      }),
      jsxs('div', {
        role: 'status', 'aria-live': 'polite',
        style: { display: 'flex', justifyContent: 'space-between', gap: 8, flexWrap: 'wrap', fontSize: 13 },
        children: [
          jsx('b', { children: d.status === 'active' ? (d.can_move ? `Your turn — ${leftToMove} unit${leftToMove === 1 ? '' : 's'} still to move` : 'The bots are taking their turns') : d.status === 'idle' ? 'Pick a match below' : d.status === 'won' || d.status === 'draw' ? 'Battle finished' : d.status }),
          jsx('span', {
            className: 'games-waiting',
            style: { color: text.tertiary },
            children: busy ? (waitingLine(asking, { kind: 'agent', name: 'Your bot' }) || 'Sending…') : notice
          })
        ]
      }),
      sentence ? jsx('div', {
        role: 'status',
        style: { padding: '9px 12px', borderRadius: 8, border: `1px solid ${stroke}`, fontSize: 13, color: text.secondary, background: card },
        children: sentence
      }) : null,
      // Watch it think, Doctrine flavour: the working that led to the card it
      // just wrote. It is the owner's own card, so only this screen has it.
      d.prep ? jsxs('section', {
        'aria-label': 'How it wrote this card',
        className: 'games-doctrine-prep',
        style: { display: 'flex', flexDirection: 'column', gap: 8, padding: 12, border: `1px solid ${stroke}`, borderRadius: 12, background: card },
        children: [
          talkThinkHeading('How it wrote this card'),
          jsx('div', { style: { fontSize: 12, color: text.secondary }, children: `It wrote ${d.prep.name || 'a new card'}.` }),
          talkReadRows(d.prep),
          d.prep.scratch
            ? jsx('div', {
                className: 'games-think-scratch',
                style: {
                  fontFamily: 'var(--font-mono, ui-monospace, monospace)', fontSize: 11.5, lineHeight: 1.45,
                  color: text.secondary, background: fill, border: `1px solid ${stroke}`, borderRadius: 8,
                  padding: '8px 9px', whiteSpace: 'pre-wrap', maxHeight: 160, overflowY: 'auto'
                },
                children: d.prep.scratch
              })
            : null,
          d.prep.action
            ? jsx('div', { className: 'games-think-action', style: { fontSize: 11, color: text.tertiary }, children: d.prep.action })
            : null
        ]
      }) : null,
      watching ? jsxs('div', {
        style: { display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'center' },
        children: [
          button('Restart', () => { setAuto(false); setIndex(0) }, { disabled: !frames.length }),
          button('Step', () => setIndex(value => Math.min(value + 1, Math.max(0, frames.length - 1))), { disabled: !frames.length || at >= frames.length - 1 }),
          auto ? button('Stop', () => setAuto(false), { primary: true }) : button('Auto-play', () => setAuto(true), { primary: true, disabled: !frames.length || at >= frames.length - 1 }),
          jsx('span', { style: { fontSize: 12, color: text.tertiary }, children: `${frames.length} turns at the usual watch speed` })
        ]
      }) : null,
      !watching ? jsxs('div', {
        style: { display: 'flex', gap: 8, flexWrap: 'wrap' },
        children: [
          button('End turn', () => command('end'), { disabled: Boolean(busy) || !d.can_move }),
          jsx('span', { style: { fontSize: 12, color: text.tertiary, alignSelf: 'center' }, children: 'Click a highlighted hex, or End turn to hold the rest.' })
        ]
      }) : null,
      jsxs('div', {
        style: { display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'center' },
        children: [
          button('Play a battle', () => command(`play ${opponent} seed=${seed || '1'}`), { primary: true, disabled: busy }),
          button('Watch four bots', () => command(`watch 4 seed=${seed || '1'}`), { disabled: busy }),
          button('Improve my bot', () => askFor({ kind: 'improve' }, () => send('doctrine improve')), {
            disabled: busy || !d.improve_ready,
            title: d.improve_ready ? 'Ask your own model for a new card. It is kept only if it wins more.' : d.improve_note
          })
        ]
      }),
      cardChoices.length ? jsxs('div', {
        style: { display: 'flex', gap: 6, flexWrap: 'wrap', alignItems: 'center', fontSize: 12, color: text.tertiary },
        children: [
          jsx('span', { children: 'Your card:' }),
          ...cardChoices.map(card => button(
            `${card.name}${card.current ? ' ✓' : ''}`,
            () => command(`pick ${card.id}`),
            { primary: Boolean(card.current), disabled: busy, title: 'Use this card in the next battle.' }
          ))
        ]
      }) : null,
      jsxs('details', {
        className: 'games-advanced',
        style: { border: `1px solid ${stroke}`, borderRadius: 12, background: card, padding: '8px 12px' },
        children: [
          jsx('summary', { style: { cursor: 'pointer', fontSize: 12, color: text.secondary, fontWeight: 650 }, children: 'More options' }),
          jsxs('div', { style: { display: 'flex', flexDirection: 'column', gap: 8, paddingTop: 10 }, children: [
            jsxs('div', {
              style: { display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'center' },
              children: [
                jsx('select', {
                  'aria-label': 'Opponent card', value: opponent, onChange: event => setOpponent(event.target.value),
                  style: { minWidth: 150, padding: '7px 9px', border: `1px solid ${stroke}`, borderRadius: 8, color: text.primary, background: card },
                  children: houseOptions.length ? houseOptions : [jsx('option', { value: 'stone-bastion', children: 'Stone Bastion' })]
                }),
                jsx('input', {
                  'aria-label': 'Seed', value: seed, placeholder: 'Seed', onChange: event => setSeed(event.target.value.replace(/[^0-9]/g, '').slice(0, 9)),
                  style: { width: 88, padding: '7px 9px', border: `1px solid ${stroke}`, borderRadius: 8, color: text.primary, background: 'transparent' }
                }),
                button('Play 1v1', () => command(`play ${opponent} seed=${seed || '1'}`), { disabled: busy }),
                button('Watch 2', () => command(`watch 2 seed=${seed || '1'}`), { disabled: busy }),
                button('Watch 3', () => command(`watch 3 seed=${seed || '1'}`), { disabled: busy }),
                button('Watch 4', () => command(`watch 4 seed=${seed || '1'}`), { disabled: busy }),
                button('Ladder', () => { setPanel('ladder'); command('ladder') }, { disabled: busy })
              ]
            }),
            jsxs('div', {
              style: { display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'center' },
              children: [
                jsx('select', {
                  'aria-label': 'Your card', value: yourId ? yourId.id : '', onChange: event => command(`pick ${event.target.value}`),
                  style: { minWidth: 150, padding: '7px 9px', border: `1px solid ${stroke}`, borderRadius: 8, color: text.primary, background: card },
                  children: [
                    ...(yourId ? [] : [jsx('option', { value: '', children: (d.your_card && d.your_card.name) || 'Your card' })]),
                    ...cardOptions
                  ]
                }),
                button(panel === 'tree' ? 'Hide tree' : 'Family tree', () => setPanel(panel === 'tree' ? '' : 'tree')),
                button(panel === 'card' ? 'Hide card' : 'Card JSON', () => setPanel(panel === 'card' ? '' : 'card')),
                button(panel === 'import' ? 'Hide share' : 'Share', () => setPanel(panel === 'import' ? '' : 'import'))
              ]
            })
          ] })
        ]
      }),
      !d.improve_ready && d.improve_note ? jsx('div', { style: { fontSize: 12, color: text.tertiary }, children: d.improve_note }) : null,
      panel === 'ladder' ? jsxs('section', {
        'aria-label': 'Ladder',
        style: { border: `1px solid ${stroke}`, borderRadius: 12, padding: 12, background: card, fontSize: 12, display: 'flex', flexDirection: 'column', gap: 4 },
        children: [
          heading('House ladder'),
          ...((d.ladder || []).length ? (d.ladder || []).map(row => jsx('div', {
            style: { fontFamily: 'var(--font-mono, monospace)' },
            children: `${row.wins}-${row.losses}-${row.draws} against ${row.name}`
          }, row.id)) : [jsx('div', { style: { color: text.tertiary }, children: 'Press Ladder to play your card against all four house cards.' })])
        ]
      }) : null,
      panel === 'tree' ? jsxs('section', {
        'aria-label': 'Family tree',
        style: { border: `1px solid ${stroke}`, borderRadius: 12, padding: 12, background: card, display: 'flex', flexDirection: 'column', gap: 6 },
        children: [
          heading('Family tree'),
          jsx('pre', { style: { margin: 0, fontSize: 12, fontFamily: 'var(--font-mono, monospace)', color: text.secondary, whiteSpace: 'pre-wrap' }, children: d.tree || 'No family yet.' })
        ]
      }) : null,
      panel === 'card' ? jsxs('section', {
        'aria-label': 'Card JSON',
        style: { border: `1px solid ${stroke}`, borderRadius: 12, padding: 12, background: card, display: 'flex', flexDirection: 'column', gap: 8 },
        children: [
          heading('Your card — data only'),
          jsx('textarea', {
            'aria-label': 'Card JSON', value: cardText, spellCheck: false, rows: 12,
            onChange: event => setCardText(event.target.value),
            style: { width: '100%', boxSizing: 'border-box', fontFamily: 'var(--font-mono, monospace)', fontSize: 12, padding: 10, borderRadius: 8, border: `1px solid ${stroke}`, background: 'transparent', color: text.primary }
          }),
          jsxs('div', { style: { display: 'flex', gap: 8, flexWrap: 'wrap' }, children: [
            button('Save card', () => importValue(cardText), { primary: true, disabled: busy }),
            button('Export card', () => download(''), { disabled: busy }),
            button('Export replay', () => download('replay'), { disabled: busy || !frames.length })
          ] })
        ]
      }) : null,
      panel === 'import' ? jsxs('section', {
        'aria-label': 'Share a card or replay',
        style: { border: `1px solid ${stroke}`, borderRadius: 12, padding: 12, background: card, display: 'flex', flexDirection: 'column', gap: 8 },
        children: [
          heading('Share a card or replay'),
          jsx('div', { style: { fontSize: 12, color: text.tertiary }, children: 'Export writes a small JSON file. Import checks it first and says plainly what is wrong.' }),
          jsx('textarea', {
            'aria-label': 'JSON to import', value: pasted, spellCheck: false, rows: 8, placeholder: 'Paste a card or replay JSON',
            onChange: event => setPasted(event.target.value),
            style: { width: '100%', boxSizing: 'border-box', fontFamily: 'var(--font-mono, monospace)', fontSize: 12, padding: 10, borderRadius: 8, border: `1px solid ${stroke}`, background: 'transparent', color: text.primary }
          }),
          jsxs('div', { style: { display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'center' }, children: [
            button('Import JSON', () => importValue(pasted), { primary: true, disabled: busy || !pasted.trim() }),
            jsx('input', { type: 'file', accept: '.json,application/json', 'aria-label': 'Choose a JSON file', onChange: readFile, style: { fontSize: 12, color: text.secondary } })
          ] }),
          jsxs('div', { style: { display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'center' }, children: [
            field(profile, setProfile, 'Signature name', () => { if (profile.trim()) command(`author ${profile.trim()}`) }),
            button('Author with profile', () => { if (profile.trim()) command(`author ${profile.trim()}`) }, { disabled: busy || !profile.trim(), title: 'Your own model writes one card, signed with that profile name. The private profile is never used.' })
          ] })
        ]
      }) : null,
      failure ? jsx('div', { role: 'alert', style: { padding: 12, border: '1px solid #d76b65', borderRadius: 8, fontSize: 13 }, children: failure }) : null,
      d.result && d.result.length && !watching ? jsxs('section', {
        'aria-label': 'Result',
        style: { border: `1px solid ${stroke}`, borderRadius: 12, padding: 12, background: card, fontSize: 13, color: text.secondary, display: 'flex', flexDirection: 'column', gap: 4 },
        children: d.result.map((line, at2) => jsx('div', { children: line }, at2))
      }) : null
    ]
  })
}

// ---- 45-arena.js: Doctrine Arena arcade renderer and panel
//
// The engine has already run the battle; this file only draws it. Every visual is a pure
// function of the replay clock, so pausing, slow motion and replaying never change a frame.
// Sprites are the embedded CC0 Kenney subset from 46-arena-sprites.js.

const ARENA_COLOURS = ['#7ec8ff', '#ff9f6e', '#9ae66e', '#e579ff']
const ARENA_GLOWS = ['#1b5685', '#8f3f17', '#356e18', '#6c1f82']
// The countdown runs before replay time 0: the tanks hold the first frame while it plays.
const ARENA_INTRO_START = -2.2
const ARENA_INTRO_END = 0.25
// A finished battle is held on the last frame for a moment so the last explosion lands
// before the result card covers the arena.
const ARENA_RESULT_HOLD = 0.4

const arenaClamp = (value, low, high) => Math.max(low, Math.min(high, value))
const arenaWords = (people, seat) =>
  (people[seat] && people[seat].name) ||
  (ARENA_SEATS[seat] && ARENA_SEATS[seat].name) ||
  `Seat ${seat + 1}`

// Degrees, taking the short way round, so a turret never spins backwards through a keyframe.
function arenaLerpAngle(from, to, u) {
  return from + (((((to - from) % 360) + 540) % 360) - 180) * u
}

function arenaStormRadiusAt(t) {
  if (!(t > ARENA_STORM.start)) return null
  const progress = arenaClamp(
    (t - ARENA_STORM.start) / (ARENA_STORM.end - ARENA_STORM.start), 0, 1
  )
  return ARENA_STORM.from + (ARENA_STORM.to - ARENA_STORM.from) * progress
}

// The keyframe at or before t. Frames are a sorted [t, tanks, bullets] list.
function arenaFrameIndex(frames, t) {
  let low = 0
  let high = frames.length - 1
  while (low < high) {
    const mid = Math.ceil((low + high) / 2)
    if ((frames[mid][0] || 0) <= t) low = mid
    else high = mid - 1
  }
  return low
}

// One tank's pose between two keyframes: [x, y, bodyDeg, turretDeg, hp], or null.
function arenaPose(frames, t, seat) {
  if (!frames.length) return null
  const index = arenaFrameIndex(frames, t)
  const next = Math.min(index + 1, frames.length - 1)
  const a = frames[index] && frames[index][1] && frames[index][1][seat]
  const b = (frames[next] && frames[next][1] && frames[next][1][seat]) || a
  if (!a || !b) return null
  const span = frames[next][0] - frames[index][0]
  const u = span > 0 ? arenaClamp((t - frames[index][0]) / span, 0, 1) : 1
  return [
    a[0] + (b[0] - a[0]) * u,
    a[1] + (b[1] - a[1]) * u,
    arenaLerpAngle(a[2] || 0, b[2] || 0, u),
    arenaLerpAngle(a[3] || 0, b[3] || 0, u),
    (a[4] || 0) + ((b[4] || 0) - (a[4] || 0)) * u
  ]
}

// A tank's full health, from the first keyframe: the armour classes differ (88 to 176).
function arenaStartHp(frames, seat) {
  const first = frames[0] && frames[0][1] && frames[0][1][seat]
  const hp = first && first[4]
  return hp > 0 ? hp : 100
}

function arenaRoundRect(ctx, x, y, w, h, r) {
  ctx.beginPath()
  if (typeof ctx.roundRect === 'function') {
    ctx.roundRect(x, y, w, h, r)
    return
  }
  const rad = Math.min(r, w / 2, h / 2)
  ctx.moveTo(x + rad, y)
  ctx.lineTo(x + w - rad, y)
  ctx.quadraticCurveTo(x + w, y, x + w, y + rad)
  ctx.lineTo(x + w, y + h - rad)
  ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h)
  ctx.lineTo(x + rad, y + h)
  ctx.quadraticCurveTo(x, y + h, x, y + h - rad)
  ctx.lineTo(x, y + rad)
  ctx.quadraticCurveTo(x, y, x + rad, y)
  ctx.closePath()
}

function arenaImage(uri) {
  if (typeof Image === 'undefined' || !uri) return null
  const image = new Image()
  image.src = uri
  return image
}

// drawImage only when the sprite has decoded and the context has one (the test harness'
// canvas has neither), so a slow sprite shows the floor instead of throwing.
function arenaDrawImage(ctx, image, x, y, w, h) {
  if (image && image.complete && image.naturalWidth && typeof ctx.drawImage === 'function') {
    ctx.drawImage(image, x, y, w, h)
  }
}

function arenaText(ctx, body, x, y, maxWidth) {
  if (typeof ctx.fillText !== 'function') return
  if (maxWidth == null) ctx.fillText(body, x, y)
  else ctx.fillText(body, x, y, maxWidth)
}

// Every effect is keyed off an event and its own index, so a spark pattern is the same on
// every replay and a reduced-motion run draws the same shapes without the motion.
function arenaPreparedEvents(events, frames) {
  const prepared = []
  for (let index = 0; index < events.length; index += 1) {
    const event = events[index]
    if (!event || typeof event.kind !== 'string') continue
    const seat = event.kind === 'shot' ? event.seat : event.on
    prepared.push({
      event,
      pose: arenaPose(frames, event.t || 0, seat),
      seed: Math.imul(index + 1, 2654435761) >>> 0
    })
  }
  return prepared
}

// Tread stamps, sampled from the keyframes once: [t, x, y, bodyRadians, seat].
function arenaTreadStamps(frames) {
  const stamps = []
  for (let index = 1; index < frames.length; index += 1) {
    const before = (frames[index - 1] && frames[index - 1][1]) || []
    const after = (frames[index] && frames[index][1]) || []
    for (let seat = 0; seat < after.length; seat += 1) {
      const a = before[seat]
      const b = after[seat]
      if (!a || !b || b[4] <= 0) continue
      if (Math.hypot(b[0] - a[0], b[1] - a[1]) < 1.5) continue
      stamps.push([frames[index][0], b[0], b[1], ((b[2] || 0) * Math.PI) / 180, seat])
    }
  }
  return stamps
}

// Tiny, decaying screen shake from recent fire: 1.5 px a shot, 3.5 a hit, 7 a kill.
function arenaShakeAt(prepared, t, reduced) {
  if (reduced) return { x: 0, y: 0 }
  let amplitude = 0
  for (let index = 0; index < prepared.length; index += 1) {
    const event = prepared[index].event
    const age = t - event.t
    const duration = event.kind === 'kill' ? 0.32 : event.kind === 'hit' ? 0.14
      : event.kind === 'shot' ? 0.07 : 0
    if (duration <= 0 || age < 0 || age >= duration) continue
    const start = event.kind === 'kill' ? 7 : event.kind === 'hit' ? 3.5 : 1.5
    const fall = 1 - age / duration
    amplitude += start * fall * fall
  }
  amplitude = Math.min(8, amplitude)
  return { x: Math.sin(t * 115) * amplitude, y: Math.cos(t * 150) * amplitude }
}

// A fixed scatter of chipped concrete: same marks every replay, so a replay looks identical.
const ARENA_DEBRIS = [
  [96, 372, 3, 1.2], [188, 502, 2, 0.9], [252, 268, 2.5, 1.4], [404, 452, 2, 0.7],
  [516, 214, 3, 1.1], [612, 486, 2, 0.8], [708, 320, 2.5, 1.3], [822, 452, 2, 0.9],
  [120, 218, 2, 0.8], [864, 236, 3, 1.2], [332, 372, 2, 0.6], [556, 356, 2.5, 1.0]
]

function arenaDrawFloor(ctx) {
  ctx.fillStyle = '#12161f'
  ctx.fillRect(0, 0, 960, 600)
  ctx.lineWidth = 1
  for (let x = 0; x <= 960; x += 40) {
    ctx.strokeStyle = x % 160 ? '#1a202c' : '#252f42'
    ctx.beginPath()
    ctx.moveTo(x, 0)
    ctx.lineTo(x, 600)
    ctx.stroke()
  }
  for (let y = 0; y <= 600; y += 40) {
    ctx.strokeStyle = y % 160 ? '#1a202c' : '#252f42'
    ctx.beginPath()
    ctx.moveTo(0, y)
    ctx.lineTo(960, y)
    ctx.stroke()
  }
  for (let x = 160; x < 960; x += 160) {
    for (let y = 160; y < 600; y += 160) {
      ctx.beginPath()
      ctx.moveTo(x - 3, y)
      ctx.lineTo(x + 3, y)
      ctx.moveTo(x, y - 3)
      ctx.lineTo(x, y + 3)
      ctx.stroke()
    }
  }

  // the hall: a painted centre ring with four ticks, so every fight has a middle
  ctx.strokeStyle = '#243044'
  ctx.lineWidth = 2
  ctx.beginPath()
  if (typeof ctx.arc === 'function') ctx.arc(480, 320, 132, 0, Math.PI * 2)
  ctx.stroke()
  ctx.strokeStyle = '#1e2838'
  ctx.lineWidth = 1
  ctx.beginPath()
  if (typeof ctx.arc === 'function') ctx.arc(480, 320, 118, 0, Math.PI * 2)
  ctx.stroke()
  for (let tick = 0; tick < 4; tick += 1) {
    const angle = (tick * Math.PI) / 2 + Math.PI / 4
    ctx.beginPath()
    ctx.moveTo(480 + 118 * Math.cos(angle), 320 + 118 * Math.sin(angle))
    ctx.lineTo(480 + 146 * Math.cos(angle), 320 + 146 * Math.sin(angle))
    ctx.stroke()
  }

  // corner chevrons: the room reads as a pit with four walls
  ctx.strokeStyle = 'rgba(242,179,61,0.20)'
  ctx.lineWidth = 3
  const corners = [[26, 84, 1, 1], [934, 84, -1, 1], [26, 578, 1, -1], [934, 578, -1, -1]]
  for (let index = 0; index < corners.length; index += 1) {
    const corner = corners[index]
    for (let bar = 0; bar < 3; bar += 1) {
      ctx.beginPath()
      ctx.moveTo(corner[0] + corner[2] * bar * 12, corner[1] + corner[3] * 26)
      ctx.lineTo(corner[0] + corner[2] * 26, corner[1] + corner[3] * 26)
      ctx.lineTo(corner[0] + corner[2] * 26, corner[1] + corner[3] * bar * 12)
      ctx.stroke()
    }
  }

  // rubble: small dark chips with one bright edge, so the floor has texture without noise
  for (let index = 0; index < ARENA_DEBRIS.length; index += 1) {
    const chip = ARENA_DEBRIS[index]
    ctx.fillStyle = '#232c3d'
    ctx.fillRect(chip[0], chip[1], chip[2] * 2, chip[3] * 2)
    ctx.fillStyle = '#3d4b66'
    ctx.fillRect(chip[0], chip[1], chip[2] * 2, 1)
  }
  if (typeof ctx.createRadialGradient !== 'function') return
  const vignette = ctx.createRadialGradient(480, 300, 300, 480, 300, 560)
  vignette.addColorStop(0, 'rgba(7,9,14,0)')
  vignette.addColorStop(1, 'rgba(7,9,14,0.65)')
  ctx.fillStyle = vignette
  ctx.fillRect(0, 0, 960, 600)
}

// The storm is a closing ring of energy: a tinted danger field outside it, a pulsing glow,
// two counter-rotating dashed arcs and eight nodes riding the perimeter.
function arenaDrawStorm(ctx, t, radius, reduced) {
  if (radius === null) return
  ctx.fillStyle = 'rgba(255,56,100,0.10)'
  ctx.beginPath()
  ctx.moveTo(0, 0)
  ctx.lineTo(960, 0)
  ctx.lineTo(960, 600)
  ctx.lineTo(0, 600)
  ctx.closePath()
  ctx.arc(480, 300, radius, 0, Math.PI * 2, true)
  ctx.fill('evenodd')

  ctx.save()
  ctx.strokeStyle = 'rgba(255,46,99,0.32)'
  ctx.lineWidth = reduced ? 12 : 12 + 3 * Math.sin(t * 6)
  ctx.beginPath()
  ctx.arc(480, 300, radius, 0, Math.PI * 2)
  ctx.stroke()

  if (!reduced && typeof ctx.setLineDash === 'function') {
    ctx.setLineDash([18, 14])
    ctx.lineDashOffset = -t * 50
    ctx.strokeStyle = '#ff2e63'
    ctx.lineWidth = 2
    ctx.beginPath()
    ctx.arc(480, 300, radius + 2.5, 0, Math.PI * 2)
    ctx.stroke()
    ctx.setLineDash([10, 20])
    ctx.lineDashOffset = t * 38
    ctx.strokeStyle = '#ff9eb5'
    ctx.beginPath()
    ctx.arc(480, 300, radius - 2.5, 0, Math.PI * 2)
    ctx.stroke()
    ctx.setLineDash([])
  }

  ctx.strokeStyle = '#ff9eb5'
  ctx.lineWidth = 2.5
  ctx.beginPath()
  ctx.arc(480, 300, radius, 0, Math.PI * 2)
  ctx.stroke()

  if (!reduced) {
    ctx.fillStyle = '#ffffff'
    for (let node = 0; node < 8; node += 1) {
      const angle = (node * Math.PI) / 4 + t * 0.35
      ctx.save()
      ctx.translate(480 + radius * Math.cos(angle), 300 + radius * Math.sin(angle))
      ctx.rotate(Math.PI / 4)
      ctx.fillRect(-2.5, -2.5, 5, 5)
      ctx.restore()
    }
  }
  ctx.restore()
}

// Tanks are drawn 1.65x their sprite size: at 960x600 the sprites read as toys.
const ARENA_TANK_SCALE = 1.65

// One tank: seat underglow, hull, and a turret drawn on its own pivot. The Kenney art faces
// up while the engine counts from east, hence the 90 degrees.
function arenaDrawTank(ctx, sprites, people, seat, pose, wreck) {
  const info = people[seat] || {}
  const armour = (info.card && info.card.armour) || 'medium'
  const group = sprites.hulls[seat] || sprites.hulls[0]
  const hull = group && (group[armour] || group.medium)
  const barrel = sprites.barrels[seat]
  const size = ARENA_SPRITES.hullSize[armour] || ARENA_SPRITES.hullSize.medium
  const width = size[0] * ARENA_TANK_SCALE
  const height = size[1] * ARENA_TANK_SCALE

  ctx.save()
  ctx.translate(pose[0], pose[1])
  if (wreck) {
    ctx.globalAlpha = 0.48
  } else {
    ctx.fillStyle = 'rgba(0,0,0,0.45)'
    ctx.beginPath()
    ctx.arc(2, 3, width * 0.3, 0, Math.PI * 2)
    ctx.fill()
    ctx.globalAlpha = 0.8
    ctx.strokeStyle = ARENA_GLOWS[seat % ARENA_GLOWS.length]
    ctx.lineWidth = 5
    ctx.beginPath()
    ctx.arc(0, 0, width * 0.32, 0, Math.PI * 2)
    ctx.stroke()
    ctx.globalAlpha = 1
  }

  ctx.save()
  ctx.rotate(((pose[2] + 90) * Math.PI) / 180)
  arenaDrawImage(ctx, hull, -width / 2, -height / 2, width, height)
  ctx.restore()

  ctx.save()
  if (wreck) ctx.translate(6, 4)
  ctx.rotate(((pose[3] + 90 + (wreck ? 28 : 0)) * Math.PI) / 180)
  if (barrel) {
    arenaDrawImage(
      ctx, barrel.image, -barrel.w * ARENA_TANK_SCALE / 2,
      -barrel.h * ARENA_TANK_SCALE * ARENA_SPRITES.barrelPivotY,
      barrel.w * ARENA_TANK_SCALE, barrel.h * ARENA_TANK_SCALE
    )
  }
  ctx.restore()
  ctx.restore()
}

// The top bar: four health cards, the clock, the storm state, and the kill feed.
function arenaDrawHud(ctx, view) {
  const { t, frames, people, prepared, pet, radius } = view
  const cards = [12, 216, 548, 752]
  for (let seat = 0; seat < Math.min(4, people.length); seat += 1) {
    const x = cards[seat]
    const pose = arenaPose(frames, t, seat)
    const hp = pose ? Math.max(0, Math.round(pose[4])) : 0
    const startHp = arenaStartHp(frames, seat)
    let kills = 0
    for (let index = 0; index < prepared.length; index += 1) {
      const event = prepared[index].event
      if (event.kind === 'kill' && event.by === seat && event.t <= t) kills += 1
    }

    ctx.fillStyle = 'rgba(13,17,24,0.88)'
    arenaRoundRect(ctx, x, 10, 196, 48, 8)
    ctx.fill()
    ctx.fillStyle = ARENA_COLOURS[seat]
    ctx.fillRect(x, 10, 4, 48)

    const avatar = seat === 0 && pet && pet.image
    if (avatar) arenaDrawImage(ctx, avatar, x + 10, 18, 32, 32)
    const left = x + (avatar ? 48 : 12)

    ctx.textAlign = 'left'
    ctx.font = '700 13px system-ui, sans-serif'
    ctx.fillStyle = '#f0f4f8'
    arenaText(ctx, `${arenaWords(people, seat)}${seat === 0 ? ' (you)' : ''}`, left, 28, avatar ? 100 : 130)

    ctx.textAlign = 'right'
    ctx.fillStyle = ARENA_COLOURS[seat]
    arenaText(ctx, `${kills} kill${kills === 1 ? '' : 's'}`, x + 186, 28)

    const barWidth = avatar ? 100 : 136
    ctx.fillStyle = '#1e2636'
    ctx.fillRect(left, 38, barWidth, 11)
    ctx.fillStyle = hp <= 0 ? '#2b303a' : hp <= startHp * 0.25 ? '#ff3b5c' : ARENA_COLOURS[seat]
    ctx.fillRect(left, 38, barWidth * arenaClamp(hp / startHp, 0, 1), 11)
    ctx.fillStyle = '#f0f4f8'
    ctx.font = '700 12px monospace'
    arenaText(ctx, hp > 0 ? String(hp) : 'KO', x + 188, 48)
  }

  ctx.fillStyle = 'rgba(13,17,24,0.88)'
  arenaRoundRect(ctx, 422, 10, 116, 48, 8)
  ctx.fill()
  ctx.textAlign = 'center'
  ctx.fillStyle = '#f0f4f8'
  ctx.font = '700 16px monospace'
  const clock = `${String(Math.floor(Math.max(0, t) / 60)).padStart(2, '0')}:${Math.max(0, t % 60).toFixed(1).padStart(4, '0')}`
  arenaText(ctx, clock, 480, 28)
  ctx.font = '700 11px system-ui, sans-serif'
  ctx.fillStyle = radius === null ? '#94a3b8' : '#ff9eb5'
  arenaText(ctx, radius === null ? 'STORM INCOMING' : 'STORM', 480, 46)

  let line = 0
  for (let index = prepared.length - 1; index >= 0 && line < 3; index -= 1) {
    const event = prepared[index].event
    if (event.kind !== 'kill' || t - event.t < 0 || t - event.t > 4.5) continue
    const y = 68 + line * 28
    line += 1
    ctx.fillStyle = 'rgba(13,17,24,0.85)'
    arenaRoundRect(ctx, 736, y, 212, 24, 5)
    ctx.fill()
    ctx.fillStyle = event.by == null ? '#ff2e63' : ARENA_COLOURS[event.by % 4]
    ctx.fillRect(736, y, 3, 24)
    ctx.fillStyle = '#f0f4f8'
    ctx.textAlign = 'left'
    ctx.font = '700 12px system-ui, sans-serif'
    const killer = event.by == null ? 'STORM' : arenaWords(people, event.by)
    arenaText(ctx, `${killer} → ${arenaWords(people, event.on)}`, 744, y + 16, 196)
  }
}

// "3 · 2 · 1 · FIGHT!" over the frozen first frame. Reduced motion keeps one plain fade.
function arenaDrawIntro(ctx, t, reduced) {
  if (t >= ARENA_INTRO_END) return
  const marks = [
    { at: ARENA_INTRO_START, span: 0.6, word: '3' },
    { at: -1.6, span: 0.6, word: '2' },
    { at: -1.0, span: 0.6, word: '1' },
    { at: -0.4, span: 0.65, word: 'FIGHT!' }
  ]
  let mark = marks[0]
  for (let index = 0; index < marks.length; index += 1) {
    if (t >= marks[index].at) mark = marks[index]
  }
  const u = arenaClamp((t - mark.at) / mark.span, 0, 1)
  let scale = 1
  let alpha = 1
  if (reduced) {
    alpha = Math.min(1, (u * mark.span) / 0.1, ((1 - u) * mark.span) / 0.1)
  } else if (mark.word === 'FIGHT!') {
    if (u < 0.28) scale = 0.55 + 0.6 * (1 - (1 - u / 0.28) ** 3)
    else if (u < 0.7) scale = 1.15
    else {
      const w = (u - 0.7) / 0.3
      scale = 1.15 + 0.25 * w
      alpha = 1 - w * w
    }
  } else if (u < 0.25) {
    const z = u / 0.25 - 1
    scale = 2.1 - 1.1 * (1 + 2.70158 * z ** 3 + 1.70158 * z ** 2)
    alpha = u / 0.25
  } else if (u > 0.75) {
    const w = (u - 0.75) / 0.25
    scale = 1 - 0.2 * w * w
    alpha = 1 - w * w
  }
  ctx.save()
  ctx.translate(480, 310)
  if (typeof ctx.scale === 'function') ctx.scale(scale, scale)
  ctx.globalAlpha = alpha
  ctx.textAlign = 'center'
  ctx.font = '900 92px system-ui, sans-serif'
  ctx.fillStyle = '#f0f4f8'
  ctx.strokeStyle = 'rgba(7,9,14,0.9)'
  ctx.lineWidth = 6
  if (typeof ctx.strokeText === 'function') ctx.strokeText(mark.word, 0, 0)
  arenaText(ctx, mark.word, 0, 0)
  ctx.restore()
}

function arenaBullets(ctx, frames, t) {
  if (!frames.length) return
  const index = arenaFrameIndex(frames, t)
  const next = Math.min(index + 1, frames.length - 1)
  const before = frames[index][2] || []
  const after = frames[next][2] || []
  const span = frames[next][0] - frames[index][0]
  const u = span > 0 ? arenaClamp((t - frames[index][0]) / span, 0, 1) : 1

  for (let index2 = 0; index2 < before.length; index2 += 1) {
    const bullet = before[index2]
    if (!bullet) continue
    // A bullet vanishes when it hits or leaves; pair it with the nearest same-seat shot in
    // the next frame, or fall back to the shooter's turret angle for the trail direction.
    let match = null
    let best = 64
    for (let other = 0; other < after.length; other += 1) {
      const candidate = after[other]
      if (!candidate || candidate[2] !== bullet[2]) continue
      const distance = Math.hypot(candidate[0] - bullet[0], candidate[1] - bullet[1])
      if (distance < best) {
        best = distance
        match = candidate
      }
    }
    const pose = arenaPose(frames, t, bullet[2])
    const angle = match && best > 0.01
      ? Math.atan2(match[1] - bullet[1], match[0] - bullet[0])
      : ((pose ? pose[3] : 0) * Math.PI) / 180
    const x = bullet[0] + (match ? (match[0] - bullet[0]) * u : 0)
    const y = bullet[1] + (match ? (match[1] - bullet[1]) * u : 0)

    ctx.save()
    ctx.translate(x, y)
    ctx.rotate(angle)
    ctx.fillStyle = '#ffb703'
    ctx.beginPath()
    ctx.moveTo(0, -2)
    ctx.lineTo(-20, 0)
    ctx.lineTo(0, 2)
    ctx.fill()
    ctx.fillStyle = '#fff6d6'
    ctx.fillRect(-3.5, -1.5, 7, 3)
    ctx.restore()
  }
}

// Muzzle flashes, hit sparks, damage popups and explosions, all from the event list.
function arenaDrawEffects(ctx, view) {
  const { t, prepared, compact, reduced, sprites } = view
  for (let index = 0; index < prepared.length; index += 1) {
    const item = prepared[index]
    const event = item.event
    const age = t - event.t
    if (age < 0 || age > 0.75) continue
    const x = event.x != null ? event.x : item.pose && item.pose[0]
    const y = event.y != null ? event.y : item.pose && item.pose[1]
    if (x == null || y == null) continue

    if (event.kind === 'shot' && !compact && age <= 0.09) {
      const u = age / 0.09
      ctx.save()
      ctx.translate(x, y)
      ctx.rotate(((item.pose ? item.pose[3] : 0) * Math.PI) / 180)
      ctx.globalAlpha = reduced ? 0.45 * (1 - u) : (1 - u) ** 2
      ctx.fillStyle = '#ff9e00'
      if (reduced) {
        ctx.beginPath()
        ctx.arc(0, 0, 10, 0, Math.PI * 2)
        ctx.fill()
      } else {
        ctx.beginPath()
        ctx.moveTo(0, -7 * (1 - 0.45 * u))
        ctx.lineTo(22 * (1 - 0.35 * u), 0)
        ctx.lineTo(0, 7 * (1 - 0.45 * u))
        ctx.fill()
        ctx.globalAlpha = 1 - u
        ctx.fillStyle = '#ffffff'
        ctx.fillRect(0, -3 * (1 - u), 13 * (1 - u), 6 * (1 - u))
      }
      ctx.restore()
    }

    if (event.kind === 'hit') {
      if (age <= 0.22) {
        const u = age / 0.22
        const reach = 4 + 24 * (1 - (1 - u) ** 3)
        ctx.save()
        ctx.globalAlpha = 1 - u * u
        ctx.strokeStyle = u < 0.4 ? '#ffe66d' : '#ff595e'
        ctx.lineWidth = 2
        for (let ray = 0; ray < 8; ray += 1) {
          const angle = (ray * Math.PI) / 4 + ((item.seed >>> (ray * 3)) & 7) * 0.06
          ctx.beginPath()
          ctx.moveTo(x + Math.cos(angle) * reach, y + Math.sin(angle) * reach)
          ctx.lineTo(
            x + Math.cos(angle) * (reach + 9 * (1 - u)),
            y + Math.sin(angle) * (reach + 9 * (1 - u))
          )
          ctx.stroke()
        }
        if (age < 0.1) {
          ctx.strokeStyle = '#ffffff'
          ctx.beginPath()
          ctx.arc(x, y, 4 + 14 * (age / 0.1), 0, Math.PI * 2)
          ctx.stroke()
        }
        ctx.restore()
      }
      if (!compact && age <= 0.45) {
        const u = age / 0.45
        ctx.save()
        ctx.globalAlpha = 1 - u ** 3
        ctx.font = '700 12px monospace'
        ctx.fillStyle = '#ffffff'
        ctx.textAlign = 'center'
        arenaText(ctx, `-${event.damage || 0}`, x, y - 10 - 18 * (1 - (1 - u) ** 2))
        ctx.restore()
      }
    }

    if (event.kind === 'kill') {
      ctx.save()
      if (age < 0.26) {
        const u = age / 0.26
        ctx.globalAlpha = 0.9 * (1 - u)
        ctx.strokeStyle = '#ffe66d'
        ctx.lineWidth = 4 * (1 - u)
        ctx.beginPath()
        ctx.arc(x, y, 8 + 46 * (1 - (1 - u) ** 3), 0, Math.PI * 2)
        ctx.stroke()
      }
      if (age < 0.55) {
        const u = age / 0.55
        const size = 42 + 24 * (1 - (1 - u) ** 2)
        const frame = sprites.explosions[
          Math.min(sprites.explosions.length - 1, Math.floor(u * sprites.explosions.length))
        ]
        ctx.globalAlpha = u < 0.7 ? 1 : (1 - u) / 0.3
        arenaDrawImage(ctx, frame, x - size / 2, y - size / 2, size, size)
      }
      if (age >= 0.1) {
        const u = (age - 0.1) / 0.65
        ctx.globalAlpha = 0.65 * (1 - u)
        ctx.fillStyle = '#2b303a'
        for (let puff = 0; puff < 6; puff += 1) {
          const angle = (puff * Math.PI) / 3
          ctx.beginPath()
          ctx.arc(
            x + Math.cos(angle) * (8 + 26 * u),
            y + Math.sin(angle) * (8 + 26 * u),
            7 + 9 * u, 0, Math.PI * 2
          )
          ctx.fill()
        }
      }
      ctx.restore()
    }
  }
}

function ArenaWinnerTank({ sprites, people, seat }) {
  const canvasRef = useRef(null)
  useEffect(() => {
    const canvas = canvasRef.current
    const ctx = canvas && canvas.getContext && canvas.getContext('2d')
    if (!ctx) return
    ctx.clearRect(0, 0, 110, 110)
    ctx.save()
    ctx.translate(55, 55)
    if (typeof ctx.scale === 'function') ctx.scale(1.7, 1.7)
    arenaDrawTank(ctx, sprites, people, seat, [0, 0, -110, -105, 100], false)
    ctx.restore()
  }, [sprites, seat])
  return jsx('canvas', {
    ref: canvasRef,
    width: 110,
    height: 110,
    role: 'img',
    'aria-label': `${arenaWords(people, seat)} winning tank`,
    style: { display: 'block' }
  })
}

// The stage: one canvas, the replay clock, the effects, and the controls.
// `height < 260` marks the small cover-art and champions-replay uses, which draw the arena
// only: no HUD, no countdown, no result card, no controls and no sound.
function ArenaStage({ picture, height, onAnnouncement }) {
  const canvasRef = useRef(null)
  const clockRef = useRef({ t: 0, last: null, playing: true, speed: 1 })
  const audioRef = useRef({ context: null })
  const petRef = useRef({ image: null })
  const spritesRef = useRef({ sprites: null })
  const [playing, setPlaying] = useState(true)
  const [slow, setSlow] = useState(false)
  const [sound, setSound] = useState(false)
  const [done, setDone] = useState(false)
  const [closed, setClosed] = useState(false)
  const [pet, setPet] = useState(null)
  const [replayKey, setReplayKey] = useState(0)

  const frames = picture && Array.isArray(picture.frames) ? picture.frames : []
  const people = picture && Array.isArray(picture.combatants) ? picture.combatants : []
  const events = picture && Array.isArray(picture.events) ? picture.events : []
  const result = (picture && picture.result) || {}
  const compact = height < 260
  const still = frames.length === 0

  if (!spritesRef.current.sprites) {
    spritesRef.current.sprites = {
      hulls: ARENA_SPRITES.hulls.map(group => ({
        light: arenaImage(group.light),
        medium: arenaImage(group.medium),
        heavy: arenaImage(group.heavy)
      })),
      barrels: ARENA_SPRITES.barrels.map(barrel => ({
        w: barrel.w, h: barrel.h, image: arenaImage(barrel.uri)
      })),
      explosions: ARENA_SPRITES.explosions.map(sprite => arenaImage(sprite.uri))
    }
  }
  const sprites = spritesRef.current.sprites

  // The person's own pet is only ever DISPLAYED, through the gateway: never copied, never
  // bundled. No pet, no request available, or a refusal all leave the layout closed up.
  useEffect(() => {
    let alive = true
    if (compact || !host || typeof host.request !== 'function') return undefined
    Promise.resolve()
      .then(() => host.request('pet.info', {}))
      .then(info => {
        if (!alive || !info || !info.enabled || !info.slug) return null
        return host.request('pet.thumb', { slug: info.slug, url: '' }).then(thumb => ({ info, thumb }))
      })
      .then(answer => {
        if (!alive || !answer || !answer.thumb || !answer.thumb.dataUri) return
        const image = arenaImage(answer.thumb.dataUri)
        if (!image) return
        const show = () => {
          if (!alive) return
          petRef.current.image = image
          setPet({ image, name: answer.info.displayName || 'Your pet' })
          if (canvasRef.current && canvasRef.current._arenaRedraw) canvasRef.current._arenaRedraw()
        }
        image.onload = show
        if (image.complete && image.naturalWidth) show()
      })
      .catch(() => {})
    return () => { alive = false }
  }, [])

  useEffect(() => () => {
    const context = audioRef.current && audioRef.current.context
    if (context && typeof context.close === 'function') {
      const closing = context.close()
      if (closing && typeof closing.catch === 'function') closing.catch(() => {})
    }
    audioRef.current.context = null
  }, [])

  useEffect(() => {
    const canvas = canvasRef.current
    const ctx = canvas && canvas.getContext && canvas.getContext('2d')
    if (!ctx) return undefined
    canvas.width = 960
    canvas.height = 600
    const reduced = typeof matchMedia === 'function' &&
      matchMedia('(prefers-reduced-motion: reduce)').matches
    const lastFrame = frames.length ? frames[frames.length - 1][0] : 0
    const total = Math.max(0, Number(picture && picture.duration) || lastFrame || 0)
    const end = total + ARENA_RESULT_HOLD

    const clock = clockRef.current
    clock.t = compact || still ? 0 : ARENA_INTRO_START
    clock.last = null
    clock.playing = true
    clock.speed = slow ? 0.5 : 1
    setPlaying(true)
    setDone(false)
    setClosed(false)

    const prepared = arenaPreparedEvents(events, frames)
    const stamps = arenaTreadStamps(frames)
    const deaths = []
    for (let index = 0; index < prepared.length; index += 1) {
      const item = prepared[index]
      if (item.event.kind === 'kill' && item.pose) deaths[item.event.on] = item
    }

    // The floor is painted once into an offscreen canvas; every frame is one blit.
    let floor = null
    if (typeof document !== 'undefined' && document.createElement) {
      floor = document.createElement('canvas')
      floor.width = 960
      floor.height = 600
      const floorCtx = floor.getContext && floor.getContext('2d')
      if (floorCtx) arenaDrawFloor(floorCtx)
      else floor = null
    }

    const seats = people.length || (frames[0] && frames[0][1] ? frames[0][1].length : 4)

    const paint = time => {
      const t = Math.max(0, time)
      const radius = arenaStormRadiusAt(t)
      ctx.clearRect(0, 0, 960, 600)
      const shake = arenaShakeAt(prepared, t, reduced)
      ctx.save()
      ctx.translate(shake.x, shake.y)
      if (floor && typeof ctx.drawImage === 'function') ctx.drawImage(floor, 0, 0)
      else arenaDrawFloor(ctx)

      arenaDrawStorm(ctx, t, radius, reduced)

      for (let index = 0; index < stamps.length; index += 1) {
        const stamp = stamps[index]
        const age = t - stamp[0]
        if (age < 0 || age > 4) continue
        ctx.save()
        ctx.translate(stamp[1], stamp[2])
        ctx.rotate(stamp[3])
        ctx.globalAlpha = 0.32 * (age <= 2.5 ? 1 : (4 - age) / 1.5)
        ctx.fillStyle = '#090b10'
        ctx.fillRect(-1.25, -11.5, 2.5, 5)
        ctx.fillRect(-1.25, 6.5, 2.5, 5)
        ctx.restore()
      }

      for (let seat = 0; seat < seats; seat += 1) {
        const death = deaths[seat]
        const wreck = death && t >= death.event.t
        let pose = wreck ? death.pose : arenaPose(frames, t, seat)
        if (!pose && still) {
          const angle = (2 * Math.PI * seat) / (people.length || 4)
          pose = [
            480 + 206 * Math.cos(angle), 300 + 196 * Math.sin(angle),
            (angle * 180) / Math.PI + 180, (angle * 180) / Math.PI + 180, 100
          ]
        }
        if (!pose) continue

        if (wreck) {
          ctx.globalAlpha = 0.6
          ctx.fillStyle = '#090b10'
          ctx.beginPath()
          ctx.arc(pose[0], pose[1], 22, 0, Math.PI * 2)
          ctx.fill()
          ctx.globalAlpha = 1
        }
        arenaDrawTank(ctx, sprites, people, seat, pose, Boolean(wreck))

        if (wreck) {
          // Two slow puffs of smoke, on a fixed cycle, so the wreck always looks the same.
          for (let puff = 0; puff < 2; puff += 1) {
            const u = ((t - death.event.t + puff * 0.7) % 1.4) / 1.4
            ctx.globalAlpha = 0.35 * Math.sin(u * Math.PI)
            ctx.fillStyle = '#2b303a'
            ctx.beginPath()
            ctx.arc(pose[0] + 8 * u, pose[1] - 22 * u, 4 + 8 * u, 0, Math.PI * 2)
            ctx.fill()
          }
          ctx.globalAlpha = 1
        } else if (!compact) {
          const startHp = arenaStartHp(frames, seat)
          ctx.fillStyle = '#1e2636'
          ctx.fillRect(pose[0] - 16, pose[1] - 32, 32, 4)
          ctx.fillStyle = pose[4] <= startHp * 0.25 ? '#ff3b5c' : ARENA_COLOURS[seat % 4]
          ctx.fillRect(pose[0] - 16, pose[1] - 32, 32 * arenaClamp(pose[4] / startHp, 0, 1), 4)
        }
      }

      arenaBullets(ctx, frames, t)
      arenaDrawEffects(ctx, { t, prepared, compact, reduced, sprites })
      ctx.restore()

      if (!compact) {
        arenaDrawHud(ctx, { t, frames, people, prepared, pet: petRef.current, radius })
        arenaDrawIntro(ctx, time, reduced)
      }
    }

    let frame = 0
    let alive = true
    let completed = false
    let announced = -1
    const redraw = () => { if (alive) paint(clock.t) }
    canvas._arenaRedraw = redraw
    for (let seat = 0; seat < sprites.hulls.length; seat += 1) {
      const group = sprites.hulls[seat]
      for (const key of ['light', 'medium', 'heavy']) if (group[key]) group[key].onload = redraw
      if (sprites.barrels[seat] && sprites.barrels[seat].image) {
        sprites.barrels[seat].image.onload = redraw
      }
    }
    for (let index = 0; index < sprites.explosions.length; index += 1) {
      if (sprites.explosions[index]) sprites.explosions[index].onload = redraw
    }
    if (petRef.current.image) petRef.current.image.onload = redraw

    const blip = (kind, context) => {
      try {
        const oscillator = context.createOscillator()
        const gain = context.createGain()
        const duration = kind === 'kill' ? 0.2 : 0.06
        oscillator.frequency.value = kind === 'kill' ? 90 : kind === 'hit' ? 480 : 750
        gain.gain.setValueAtTime(0.08, context.currentTime)
        gain.gain.exponentialRampToValueAtTime(0.001, context.currentTime + duration)
        oscillator.connect(gain)
        gain.connect(context.destination)
        oscillator.start()
        oscillator.stop(context.currentTime + duration)
      } catch (error) { /* a closed or refused audio context never breaks a replay */ }
    }

    const step = now => {
      const previous = clock.t
      if (clock.playing && clock.last !== null) {
        const delta = Math.min(0.1, Math.max(0, (now - clock.last) / 1000))
        clock.t = Math.min(end, clock.t + delta * clock.speed)
      }
      clock.last = now
      paint(clock.t)

      if (!compact && onAnnouncement && clock.t >= 0) {
        for (let index = 0; index < prepared.length; index += 1) {
          const event = prepared[index].event
          if (event.kind !== 'kill' || index === announced) continue
          if (event.t > previous && event.t <= clock.t) {
            announced = index
            onAnnouncement(
              `${event.by == null ? 'The storm takes' : arenaWords(people, event.by) + ' knocks out'} ${arenaWords(people, event.on)}`
            )
          }
        }
      }

      const context = audioRef.current && audioRef.current.context
      if (context && context.createOscillator && clock.playing && clock.t > previous) {
        for (let index = 0; index < prepared.length; index += 1) {
          const event = prepared[index].event
          if (event.t > previous && event.t <= clock.t &&
              (event.kind === 'shot' || event.kind === 'hit' || event.kind === 'kill')) {
            blip(event.kind, context)
          }
        }
      }

      if (!still && clock.t >= end && !completed) {
        completed = true
        clock.playing = false
        setDone(true)
        setPlaying(false)
        if (!compact && onAnnouncement) {
          const winner = Number.isInteger(result.winner) && result.winner >= 0 &&
            result.winner < people.length ? result.winner : -1
          const kills = (result.kills || [])[winner] || 0
          const hp = (result.hp || [])[winner] || 0
          onAnnouncement(winner < 0
            ? 'The battle ended without a winner.'
            : `${arenaWords(people, winner)} wins with ${kills} kill${kills === 1 ? '' : 's'} and ${hp} HP left.`)
        }
      }
      if (!still && !completed) frame = requestAnimationFrame(step)
    }

    paint(clock.t)
    if (!still) frame = requestAnimationFrame(step)
    return () => {
      alive = false
      canvas._arenaRedraw = null
      cancelAnimationFrame(frame)
    }
  }, [picture && picture.battle_id, picture && picture.battle_seq, replayKey, compact])

  const restart = () => {
    setClosed(false)
    setReplayKey(replayKey + 1)
  }
  const togglePlay = () => {
    const clock = clockRef.current
    clock.playing = !clock.playing
    clock.last = null
    setPlaying(clock.playing)
  }
  const toggleSlow = () => {
    const next = !slow
    clockRef.current.speed = next ? 0.5 : 1
    setSlow(next)
  }
  const toggleSound = () => {
    if (sound) {
      const context = audioRef.current.context
      if (context && typeof context.suspend === 'function') context.suspend()
      setSound(false)
      return
    }
    try {
      const Audio = typeof window !== 'undefined' && (window.AudioContext || window.webkitAudioContext)
      if (Audio && !audioRef.current.context) audioRef.current.context = new Audio()
      const context = audioRef.current.context
      if (context && typeof context.resume === 'function') context.resume()
    } catch (error) { /* no audio is a quiet replay, not a broken one */ }
    setSound(true)
  }

  const winner = Number.isInteger(result.winner) && result.winner >= 0 && result.winner < people.length
    ? result.winner : -1
  const control = (label, action, options = {}) => jsx('button', {
    type: 'button',
    onClick: action,
    disabled: options.disabled,
    'aria-pressed': options.pressed,
    'aria-label': options.label,
    style: {
      padding: '6px 10px',
      borderRadius: 7,
      border: `1px solid ${stroke}`,
      background: options.pressed ? accent : 'transparent',
      color: options.pressed ? 'var(--ui-text-on-accent, #0b1220)' : text.secondary,
      cursor: options.disabled ? 'default' : 'pointer',
      opacity: options.disabled ? 0.5 : 1,
      fontSize: 12,
      fontWeight: 600
    },
    children: label
  })

  return jsxs('div', { style: { width: '100%', maxWidth: 960, minWidth: 0 } , children: [
    jsxs('div', {
      style: { position: 'relative', width: '100%', aspectRatio: '960 / 600' },
      children: [
        jsx('canvas', {
          ref: canvasRef,
          role: 'img',
          'aria-label': `Doctrine Arena battle, ${people.length || 4} tanks, ${Math.round(Number(picture && picture.duration) || 0)} seconds`,
          style: {
            display: 'block',
            width: '100%',
            height: '100%',
            maxHeight: height || 'none',
            background: '#12161f',
            borderRadius: 12
          }
        }),
        !compact && done && !closed ? jsxs('div', {
          style: {
            position: 'absolute', inset: 0, background: 'rgba(7,9,14,0.74)',
            display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 8
          },
          children: jsxs('div', {
            role: 'dialog',
            'aria-label': 'Battle result',
            style: {
              background: '#0d1118',
              border: `2px solid ${winner < 0 ? '#ff2e63' : ARENA_COLOURS[winner % 4]}`,
              borderRadius: 14,
              padding: '14px 16px',
              color: '#f0f4f8',
              width: '62%',
              maxWidth: 560,
              maxHeight: '94%',
              overflow: 'auto',
              textAlign: 'center'
            },
            children: [
              jsx('div', {
                style: { fontSize: 22, fontWeight: 800 },
                children: winner < 0 ? 'Battle finished' : `${arenaWords(people, winner)} wins`
              }),
              jsx('div', {
                style: { fontSize: 12, color: '#94a3b8', marginTop: 2 },
                children: result.reason === 'timeout' ? 'Survived the storm' : 'Last tank standing'
              }),
              jsxs('div', {
                style: {
                  display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 10,
                  margin: '8px 0'
                },
                children: winner < 0 ? null : [
                  jsx(ArenaWinnerTank, { sprites, people, seat: winner, key: 'tank' }),
                  winner === 0 && pet ? jsxs('div', {
                    style: { display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 2 },
                    children: [
                      jsx('img', {
                        src: pet.image && pet.image.src, alt: pet.name, width: 64, height: 64,
                        style: { imageRendering: 'pixelated' }
                      }),
                      jsx('div', { style: { fontSize: 11, color: '#94a3b8' }, children: pet.name })
                    ]
                  }, 'pet') : null
                ]
              }),
              jsxs('table', {
                style: { width: '100%', fontSize: 12, borderCollapse: 'collapse', marginBottom: 10 },
                children: [
                  jsx('thead', {
                    children: jsxs('tr', {
                      children: ['Tank', 'Kills', 'Damage', 'HP left'].map(heading => jsx('th', {
                        style: { textAlign: 'left', color: '#94a3b8', fontWeight: 600, padding: '2px 4px' },
                        children: heading
                      }, heading))
                    })
                  }),
                  jsx('tbody', {
                    children: people.map((person, seat) => jsxs('tr', {
                      style: { background: seat === winner ? 'rgba(126,200,255,0.12)' : 'transparent' },
                      children: [
                        jsx('td', {
                          style: { padding: '2px 4px', color: ARENA_COLOURS[seat % 4], fontWeight: 700 },
                          children: person.name || arenaWords(people, seat)
                        }),
                        jsx('td', { children: (result.kills || [])[seat] || 0 }),
                        jsx('td', { children: (result.damage || [])[seat] || 0 }),
                        jsx('td', { children: (result.hp || [])[seat] || 0 })
                      ]
                    }, seat))
                  })
                ]
              }),
              jsxs('div', {
                style: { display: 'flex', gap: 8, justifyContent: 'center' },
                children: [
                  control('Watch again', restart, { label: 'Watch the battle again' }),
                  control('Close', () => setClosed(true), { label: 'Close the result' })
                ]
              })
            ]
          })
        }) : null
      ]
    }),
    !compact ? jsxs('div', {
      role: 'toolbar',
      'aria-label': 'Replay controls',
      style: { display: 'flex', gap: 6, flexWrap: 'wrap', paddingTop: 6, alignItems: 'center' },
      children: [
        control(playing ? 'Pause' : 'Play', togglePlay, { disabled: still || done }),
        control(slow ? 'Half speed on' : 'Half speed', toggleSlow, {
          pressed: slow, disabled: still, label: 'Slow motion'
        }),
        control(sound ? 'Sound on' : 'Sound off', toggleSound, {
          pressed: sound, label: 'Sound'
        }),
        control('Replay', restart, { disabled: still, label: 'Watch again' })
      ]
    }) : null,
    !compact && done && winner >= 0
      ? jsx('span', {
          style: { position: 'absolute', width: 1, height: 1, overflow: 'hidden' },
          children: `${arenaWords(people, winner)} wins`
        })
      : null
  ] })
}

// Doctrine Arena has its own screen too: one big arena, two ways to start a fight, and the
// card and seed controls kept out of the way under More options.
function ArenaPanel({ game, view, board, send, ctx, onBack }) {
  const pictured = (board && board.picture) || startingPicture(ARENA_ID)
  const [busy, setBusy] = useState(false)
  const [notice, setNotice] = useState('')
  const [failure, setFailure] = useState('')
  const [announcement, setAnnouncement] = useState('')
  const [seed, setSeed] = useState('')
  const alive = useRef(true)
  useEffect(() => {
    alive.current = true
    return () => { alive.current = false }
  }, [])
  const run = async line => {
    if (busy) return
    setBusy(true)
    setFailure('')
    setAnnouncement('Battle starting')
    try {
      const answer = await send(line)
      if (answer && answer.ok === false) throw new Error(answer.text || 'The arena refused that.')
      if (alive.current) setNotice((answer && answer.text) || '')
      return true
    } catch (error) {
      if (alive.current) setFailure(error.message || 'That did not reach the arena.')
      return false
    } finally {
      if (alive.current) setBusy(false)
    }
  }
  const cardLine = pictured && pictured.card_line ? String(pictured.card_line) : ''
  const winner = (pictured && pictured.result && pictured.result.winner)
  const combatants = (pictured && pictured.combatants) || []
  // The engine's winner is a zero-based seat index; the picture also carries the name.
  const winnerName = (pictured && pictured.winner) ||
    (Number.isInteger(winner) ? ((combatants[winner] || {}).name || '') : '')
  const result = pictured && pictured.result
  // A battle that has a winner (or a stated reason) is over: the arena says so on the
  // arena itself, not only in the caption.
  const finished = Boolean(pictured && !pictured.preview && result && (Number.isInteger(winner) || Boolean(winnerName)))
  const caption = pictured && pictured.preview
    ? 'Ready to fight'
    : winnerName ? `${winnerName} wins` : 'Battle finished'
  return jsxs('div', {
    className: 'games-play-table',
    style: { display: 'flex', flexDirection: 'column', gap: 10, padding: 14, paddingBottom: 96, minHeight: 0, height: '100%', overflow: 'auto', background: paper },
    children: [
      jsxs('div', {
        style: { display: 'flex', justifyContent: 'space-between', gap: 12, alignItems: 'center', flexWrap: 'wrap' },
        children: [
          jsxs('div', { style: { display: 'flex', gap: 12, alignItems: 'center', minWidth: 0 }, children: [
            button('Back', () => { alive.current = false; onBack() }),
            jsx(LearnButton, { game, ctx }),
            jsxs('div', { children: [
              jsx('div', { style: { fontWeight: 700, fontSize: 20 }, children: game.title }),
              game.subtitle ? jsx('div', { style: { fontSize: 12, fontStyle: 'italic', color: text.secondary }, children: game.subtitle }) : null,
              jsx('div', { style: { fontSize: 12, color: text.tertiary }, children: 'Your card against a house card. No model is called while the tanks fight.' })
            ] })
          ] }),
          button(busy ? 'Fighting…' : 'Fight', () => run(`${ARENA_ID} play${seed ? ` ${seed}` : ''}`), { primary: true, disabled: busy })
        ]
      }),
      jsxs('div', {
        role: 'status', 'aria-live': 'polite', className: 'games-status',
        style: { display: 'flex', gap: 10, alignItems: 'center', flexWrap: 'wrap', fontSize: 14, fontWeight: 650 },
        children: [
          jsx('span', { 'aria-hidden': true, className: 'games-turn-dot', style: { display: 'inline-block', width: 12, height: 12, borderRadius: '50%', background: '#7ec8ff' } }),
          jsx('span', { children: announcement || caption }),
          result && result.reason ? jsx('span', { style: { fontSize: 12, color: text.tertiary, fontWeight: 400 }, children: String(result.reason) }) : null
        ]
      }),
      jsx('div', {
        className: 'games-board-hero',
        // Same rule as the table: the arena keeps its height when More options opens, so the
        // arena never draws over the header above it.
        style: { display: 'flex', flex: '0 0 auto', alignItems: 'center', justifyContent: 'center', position: 'relative' },
        children: [jsx(ArenaStage, { picture: pictured, height: 560, onAnnouncement: setAnnouncement }),
          // The battle's own result card, on the arena, so the end is not a line of text
          // at the top of the screen.
          finished ? jsx('div', {
            className: 'games-result',
            style: { position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: 12, background: 'rgba(8, 12, 18, .58)', borderRadius: 12 },
            children: jsxs('section', {
              role: 'alert', 'aria-label': 'Battle over', 'aria-live': 'assertive',
              style: { display: 'flex', flexDirection: 'column', gap: 10, alignItems: 'center', textAlign: 'center', maxWidth: 460, padding: '18px 20px', borderRadius: 16, border: `2px solid ${accent}`, background: card, boxShadow: '0 20px 44px rgba(0, 0, 0, .55)' },
              children: [
                jsx('div', { className: 'games-result-title', style: { fontSize: 28, fontWeight: 800, lineHeight: 1.1 }, children: winnerName ? `${winnerName} wins` : 'The battle is over' }),
                result && result.reason ? jsx('div', { style: { fontSize: 13, color: text.secondary }, children: String(result.reason) }) : null,
                jsxs('div', { style: { display: 'flex', gap: 8, flexWrap: 'wrap', justifyContent: 'center' }, children: [
                  button('Fight again', () => run(`${ARENA_ID} play${seed ? ` ${seed}` : ''}`), { primary: true, disabled: busy }),
                  button('Back to games', () => { alive.current = false; onBack() })
                ] })
              ]
            })
          }) : null]
      }),
      failure ? jsx('div', { role: 'alert', style: { padding: 12, border: '1px solid #d76b65', borderRadius: 8, fontSize: 13 }, children: failure }) : null,
      jsxs('div', { style: { display: 'flex', gap: 8, flexWrap: 'wrap' }, children: [
        button('Four-way', () => run(`${ARENA_ID} ffa`), { disabled: busy, title: 'Your card against three house cards, on one arena.' })
      ] }),
      jsxs('details', {
        className: 'games-advanced',
        style: { border: `1px solid ${stroke}`, borderRadius: 12, background: card, padding: '8px 12px' },
        children: [
          jsx('summary', { style: { cursor: 'pointer', fontSize: 12, color: text.secondary, fontWeight: 650 }, children: 'More options' }),
          jsxs('div', { style: { display: 'flex', flexDirection: 'column', gap: 8, paddingTop: 10 }, children: [
            jsx('div', { style: { fontSize: 12, color: text.secondary }, children: cardLine || 'No card set.' }),
            jsx('input', {
              'aria-label': 'Seed', value: seed, placeholder: 'Seed (optional)',
              onChange: event => setSeed(event.target.value.replace(/[^0-9]/g, '').slice(0, 9)),
              style: { width: 120, padding: '7px 9px', border: `1px solid ${stroke}`, borderRadius: 8, color: text.primary, background: 'transparent' }
            }),
            notice ? pre(notice) : null
          ] })
        ]
      })
    ]
  })
}

// ---- 46-arena-sprites.js: the CC0 Kenney tank sprites, embedded as data URIs
//
// Source: Kenney "Topdown Tanks Remastered" (CC0 1.0 Universal, kenney.nl),
// via the shorepine/kenney mirror. The subset below (three hull shapes, four
// barrels, three explosions) was recoloured to the four seat colours and
// quantised; the shapes are unchanged. See THIRD-PARTY-NOTICES.md.
// The plugin bundle may not read files at runtime, so the images live here as text.
//
// Every sprite is drawn facing UP (north); the renderer adds 90 degrees to the
// engine angle, which counts from east.
const ARENA_SPRITES = {
  // per seat colour, per armour class
  hulls: [
    {
      light: 'data:image/png;base64,',
      medium: 'data:image/png;base64,',
      heavy: 'data:image/png;base64,',
    },
    {
      light: 'data:image/png;base64,',
      medium: 'data:image/png;base64,',
      heavy: 'data:image/png;base64,',
    },
    {
      light: 'data:image/png;base64,',
      medium: 'data:image/png;base64,',
      heavy: 'data:image/png;base64,',
    },
    {
      light: 'data:image/png;base64,',
      medium: 'data:image/png;base64,',
      heavy: 'data:image/png;base64,',
    },
  ],
  barrels: [
    { w: 16, h: 30, uri: 'data:image/png;base64,' },
    { w: 16, h: 30, uri: 'data:image/png;base64,' },
    { w: 16, h: 30, uri: 'data:image/png;base64,' },
    { w: 16, h: 30, uri: 'data:image/png;base64,' },
  ],
  explosions: [
    { w: 60, h: 60, uri: 'data:image/png;base64,' },
    { w: 64, h: 63, uri: 'data:image/png;base64,' },
    { w: 53, h: 52, uri: 'data:image/png;base64,' },
  ],
  // Canvas size of each hull image, so the renderer can scale it to a tank radius.
  hullSize: {
    light: [38, 40],
    medium: [42, 42],
    heavy: [52, 60],
  },
  // The barrel image points up, with its pintle around 80% down the image.
  barrelPivotY: 0.8
}

// ---- 47-petbattles.js: Pet Battles, the Labs turn-based pet battle
//
// The engine has already resolved the whole turn; this file only draws what came back and
// plays the new log lines one at a time, so a hit, a shield and a faint each get their own
// beat. Every control is a button: nothing here is typed, and nothing is a drop-down.
//
// The pets are the person's own Hermes pets and the Petdex gallery, shown through Hermes:
// `pet.gallery` says what exists, `pet.thumb` renders a real sprite. A pet file is never
// copied into this repo. Only when no sprite can be reached does a drawn stand-in appear,
// and the screen says so instead of pretending it is a real pet.
//
// Every beat is one of Hermes's own pet states: run is the attack dash, jump is a hit and
// the win, failed is a hurt pet and a faint, wave is a taunt, review is choosing a move,
// waiting is the other side's turn.

const PETB_ID = 'pet-battles'
const PETB_MOVE_MS = 460
const PETB_WATCH_MS = 950
const PETB_HOWTO_KEY = 'gameshelf.petbattles.howto'
const PETB_STATES = ['idle', 'wave', 'run', 'jump', 'failed', 'review', 'waiting']

const PETB_TYPES = {
  Ember: '#ff7a59',
  Tide: '#4fa8ff',
  Verdant: '#63c76a',
  Data: '#b07bff',
  Shadow: '#8b8fb5',
  Steel: '#8fa3ad'
}

// Colour, health colour and the state a line of the log puts a pet in. These are pure so the
// UI harness can check them without a browser.
function petbColour(type) {
  return PETB_TYPES[type] || 'var(--ui-accent)'
}

function petbHpPercent(slot) {
  const max = Number(slot && slot.maxhp) || 0
  const hp = Number(slot && slot.hp) || 0
  if (max <= 0) return 0
  return Math.max(0, Math.min(100, Math.round((hp / max) * 100)))
}

function petbHpColour(percent) {
  if (percent <= 25) return '#e0574f'
  if (percent <= 55) return '#e0a33f'
  return '#4fb86a'
}

// Which pet a log line moves: the one acting, or the one on the receiving end.
function petbStateSide(event) {
  if (!event) return ''
  if (event.kind === 'hit' || event.kind === 'faint') return event.target || ''
  if (event.kind === 'move' || event.kind === 'shield' || event.kind === 'heal'
    || event.kind === 'buff' || event.kind === 'switch' || event.kind === 'miss') return event.side || ''
  if (event.kind === 'status') return event.target || event.side || ''
  return ''
}

// One Hermes pet state per battle beat. `run` is the dash, `jump` the hit, `failed` the hurt,
// `wave` the taunt around a buff or a switch, `review` the thinking pose.
function petbStateFor(event) {
  if (!event) return 'idle'
  switch (event.kind) {
    case 'move': return 'run'
    case 'hit': return 'jump'
    case 'faint': return 'failed'
    case 'switch': return 'wave'
    case 'shield': return 'wave'
    case 'heal': return 'wave'
    case 'buff': return 'wave'
    case 'status': return 'wave'
    case 'miss': return 'review'
    default: return 'idle'
  }
}

// What a pet does while nobody is acting: the side to move thinks (`review`), the other side
// waits (`waiting`), and a finished battle leaves the winner jumping and the loser failed.
function petbRestState(side, status) {
  const won = status === 'won'
  const lost = status === 'lost'
  const draw = status === 'draw'
  if (status === 'active') return side === 'you' ? 'review' : 'waiting'
  if (status === 'watch') return 'waiting'
  if (won) return side === 'you' ? 'jump' : 'failed'
  if (lost) return side === 'you' ? 'failed' : 'jump'
  if (draw) return 'failed'
  return 'idle'
}

// A pet's line in the log, kept short: the sentence the engine wrote is already plain English.
function petbLogLine(event) {
  if (!event) return ''
  return event.text || ''
}

// The frame a watch mode is playing, clamped: a slider or a late tick can never index out.
function petbFrame(frames, index) {
  const list = Array.isArray(frames) ? frames : []
  if (!list.length) return null
  return list[Math.max(0, Math.min(list.length - 1, Number(index) || 0))]
}

// ---- Petdex ------------------------------------------------------------------
// The gateway answers `pet.gallery` as one flat `pets` list with an `installed` flag; the
// plugin's own fallback route answers with the two lists already split. Both become one shape.

function petbGalleryShape(answer) {
  const empty = { installed: [], gallery: [], source: 'local', reason: '', active: '' }
  if (!answer || typeof answer !== 'object') return { ...empty, reason: 'no-answer' }
  if (Array.isArray(answer.installed) || Array.isArray(answer.gallery)) {
    return {
      installed: Array.isArray(answer.installed) ? answer.installed.filter(pet => pet && pet.slug) : [],
      gallery: Array.isArray(answer.gallery) ? answer.gallery.filter(pet => pet && pet.slug) : [],
      source: answer.source === 'local' ? 'local' : 'petdex',
      reason: String(answer.reason || ''),
      active: String(answer.active || '')
    }
  }
  const pets = Array.isArray(answer.pets) ? answer.pets.filter(pet => pet && pet.slug) : []
  return {
    installed: pets.filter(pet => pet.installed),
    gallery: pets.filter(pet => !pet.installed),
    source: pets.length ? 'petdex' : 'local',
    reason: pets.length ? '' : 'no-pets',
    active: String(answer.active || '')
  }
}

// A seed in, the same order out: the same battle seed always meets the same opponents, so a
// replay and a rematch never disagree about who was on the field.
function petbSeedRandom(seed) {
  let state = (Number(seed) || 1) >>> 0
  return () => {
    state = (state + 0x6d2b79f5) >>> 0
    let step = Math.imul(state ^ (state >>> 15), 1 | state)
    step = (step + Math.imul(step ^ (step >>> 7), 61 | step)) ^ step
    return ((step ^ (step >>> 14)) >>> 0) / 4294967296
  }
}

// The computer's team, drawn from the Petdex gallery: curated pets first, then the rest,
// never one of the person's own installed pets.
function petbPickOpponents(gallery, seed, count = 3) {
  const pool = (gallery || []).filter(pet => pet && pet.slug && !pet.installed)
  const curated = pool.filter(pet => pet.curated)
  const ordered = curated.concat(pool.filter(pet => !pet.curated))
  const random = petbSeedRandom(seed)
  for (let index = ordered.length - 1; index > 0; index -= 1) {
    const swap = Math.floor(random() * (index + 1))
    const held = ordered[index]
    ordered[index] = ordered[swap]
    ordered[swap] = held
  }
  const picked = []
  const seen = new Set()
  for (const pet of ordered) {
    if (seen.has(pet.slug)) continue
    seen.add(pet.slug)
    picked.push({ slug: pet.slug, name: pet.displayName || pet.slug })
    if (picked.length >= count) break
  }
  return picked
}

// The person's three pets: the one they picked leads, then the rest of their installed pets.
function petbTeamIdentities(installed, leadSlug, count = 3) {
  const pets = (installed || []).filter(pet => pet && pet.slug)
  const lead = pets.find(pet => pet.slug === leadSlug) || pets[0]
  const ordered = lead ? [lead, ...pets.filter(pet => pet.slug !== lead.slug)] : []
  return ordered.slice(0, count).map(pet => ({ slug: pet.slug, name: pet.displayName || pet.slug }))
}

// `slug=Name` tokens, one shlex word each: spaces and accents are percent-encoded.
function petbIdentityTokens(list) {
  return (list || [])
    .filter(pet => pet && pet.slug)
    .map(pet => `${pet.slug}=${encodeURIComponent(pet.name || pet.slug)}`)
    .join(' ')
}

// ---- critters ---------------------------------------------------------------
// One shape per type, all from a handful of primitives. This is the stand-in the screen
// draws only when no real sprite could be fetched; `state` changes the eyes and the CSS
// class the wrapper carries, so the same drawing still animates.

function petbEyes(state, x1, x2, y) {
  if (state === 'failed') {
    return [
      jsx('path', { d: `M${x1 - 5} ${y - 4} l10 8 M${x1 + 5} ${y - 4} l-10 8`, stroke: '#1b2030', strokeWidth: 2.4, strokeLinecap: 'round', fill: 'none' }, 'eye-a'),
      jsx('path', { d: `M${x2 - 5} ${y - 4} l10 8 M${x2 + 5} ${y - 4} l-10 8`, stroke: '#1b2030', strokeWidth: 2.4, strokeLinecap: 'round', fill: 'none' }, 'eye-b')
    ]
  }
  if (state === 'jump' || state === 'run') {
    return [
      jsx('circle', { cx: x1, cy: y, r: 4.2, fill: '#1b2030' }, 'eye-a'),
      jsx('circle', { cx: x2, cy: y, r: 4.2, fill: '#1b2030' }, 'eye-b')
    ]
  }
  return [
    jsxs('g', { children: [
      jsx('circle', { cx: x1, cy: y, r: 5.2, fill: '#fdfdff' }),
      jsx('circle', { cx: x1 + 1, cy: y + 0.5, r: 2.6, fill: '#1b2030' })
    ] }, 'eye-a'),
    jsxs('g', { children: [
      jsx('circle', { cx: x2, cy: y, r: 5.2, fill: '#fdfdff' }),
      jsx('circle', { cx: x2 + 1, cy: y + 0.5, r: 2.6, fill: '#1b2030' })
    ] }, 'eye-b'),
    jsx('path', { d: `M${x1 + 4} ${y + 13} q${(x2 - x1) / 2 - 4} 6 ${x2 - x1 - 8} 0`, stroke: '#1b2030', strokeWidth: 2, fill: 'none', strokeLinecap: 'round' }, 'smile')
  ]
}

function petbCritter(type, state, size = 150) {
  const colour = petbColour(type)
  const dark = '#1b2030'
  const common = { width: size, height: size, viewBox: '0 0 100 100', role: 'img', 'aria-label': `${type} pet` }
  if (type === 'Tide') {
    return jsxs('svg', { ...common, children: [
      jsx('path', { d: 'M50 12 C74 30 84 48 84 62 a34 26 0 0 1 -68 0 C16 48 26 30 50 12 Z', fill: colour }),
      jsx('path', { d: 'M50 12 C58 26 60 34 58 42 C52 36 46 34 42 42 C40 32 44 22 50 12 Z', fill: '#dff2ff', opacity: 0.8 }),
      jsx('path', { d: 'M22 58 q10 -8 20 0', stroke: '#dff2ff', strokeWidth: 3, fill: 'none', opacity: 0.6 }),
      ...petbEyes(state, 39, 61, 58),
      jsx('path', { d: 'M28 78 q22 10 44 0', stroke: dark, strokeWidth: 2, fill: 'none', opacity: 0.25 })
    ] })
  }
  if (type === 'Verdant') {
    return jsxs('svg', { ...common, children: [
      jsx('ellipse', { cx: 30, cy: 28, rx: 11, ry: 18, fill: '#3f8f47', transform: 'rotate(-28 30 28)' }),
      jsx('ellipse', { cx: 70, cy: 28, rx: 11, ry: 18, fill: '#3f8f47', transform: 'rotate(28 70 28)' }),
      jsx('circle', { cx: 50, cy: 60, r: 30, fill: colour }),
      jsx('path', { d: 'M50 30 q6 -12 0 -20', stroke: '#3f8f47', strokeWidth: 3, fill: 'none' }),
      ...petbEyes(state, 40, 60, 56),
      jsx('circle', { cx: 34, cy: 72, r: 4, fill: '#3f8f47', opacity: 0.5 }),
      jsx('circle', { cx: 66, cy: 74, r: 3, fill: '#3f8f47', opacity: 0.4 })
    ] })
  }
  if (type === 'Data') {
    return jsxs('svg', { ...common, children: [
      jsx('line', { x1: 50, y1: 16, x2: 50, y2: 30, stroke: colour, strokeWidth: 3 }),
      jsx('circle', { cx: 50, cy: 14, r: 5, fill: '#f0e6ff' }),
      jsx('rect', { x: 20, y: 30, width: 60, height: 52, rx: 10, fill: colour }),
      jsx('rect', { x: 20, y: 30, width: 60, height: 52, rx: 10, fill: 'none', stroke: '#f0e6ff', strokeWidth: 1.5, opacity: 0.45 }),
      ...petbEyes(state, 40, 60, 54),
      jsx('rect', { x: 36, y: 68, width: 28, height: 6, rx: 3, fill: '#f0e6ff', opacity: 0.55 }),
      jsx('rect', { x: 10, y: 46, width: 8, height: 18, rx: 4, fill: colour }),
      jsx('rect', { x: 82, y: 46, width: 8, height: 18, rx: 4, fill: colour })
    ] })
  }
  if (type === 'Shadow') {
    return jsxs('svg', { ...common, children: [
      jsx('path', { d: 'M50 12 C74 12 84 32 84 56 v26 q-8 -8 -16 0 q-8 8 -18 0 q-10 -8 -18 0 q-8 8 -16 0 V56 C16 32 26 12 50 12 Z', fill: colour }),
      jsxs('g', { opacity: 0.85, children: [
        jsx('circle', { cx: 39, cy: 46, r: 7, fill: '#e9e6ff' }),
        jsx('circle', { cx: 61, cy: 46, r: 7, fill: '#e9e6ff' })
      ] }),
      petbEyes(state, 39, 61, 47)[2] || null,
      jsx('path', { d: 'M44 62 q6 5 12 0', stroke: '#e9e6ff', strokeWidth: 2, fill: 'none' })
    ] })
  }
  if (type === 'Steel') {
    return jsxs('svg', { ...common, children: [
      jsx('polygon', { points: '50,12 84,32 84,70 50,88 16,70 16,32', fill: colour }),
      jsx('polygon', { points: '50,20 76,36 76,66 50,80 24,66 24,36', fill: '#dfe9ee', opacity: 0.35 }),
      ...petbEyes(state, 40, 60, 50),
      jsx('circle', { cx: 30, cy: 70, r: 3, fill: '#5b6b73' }),
      jsx('circle', { cx: 70, cy: 70, r: 3, fill: '#5b6b73' }),
      jsx('rect', { x: 42, y: 66, width: 16, height: 4, rx: 2, fill: '#5b6b73', opacity: 0.6 })
    ] })
  }
  // Ember, and the fallback for a type this build does not know yet.
  return jsxs('svg', { ...common, children: [
    jsx('path', { d: 'M50 8 C40 24 32 30 38 42 C42 34 46 32 48 26 C54 38 64 42 60 54 C70 44 66 24 50 8 Z', fill: '#ffb347' }),
    jsx('ellipse', { cx: 50, cy: 64, rx: 31, ry: 26, fill: colour }),
    jsx('path', { d: 'M30 40 l-8 -16 16 8 Z', fill: colour }),
    jsx('path', { d: 'M70 40 l8 -16 -16 8 Z', fill: colour }),
    ...petbEyes(state, 40, 60, 62),
    jsx('ellipse', { cx: 50, cy: 76, rx: 12, ry: 6, fill: '#ffd9a0', opacity: 0.55 })
  ] })
}

// ---- Petdex sprite -----------------------------------------------------------
// A real Hermes pet sprite when `pet.thumb` answered for this slug, else the drawn stand-in
// (labelled on the wrapper so nobody mistakes it for the person's pet).

function PetbSprite({ slot, state, facing, scale, thumbs, onNeedThumb }) {
  const slug = (slot && slot.slug) || ''
  const name = (slot && slot.name) || 'Pet'
  const type = (slot && slot.type) || 'Ember'
  const uri = slug ? ((thumbs && thumbs[slug]) || '') : ''
  const size = scale || 150
  useEffect(() => {
    if (slug && !uri && typeof onNeedThumb === 'function') onNeedThumb(slug)
  }, [slug, uri])
  if (uri) {
    return jsx('img', {
      src: uri,
      alt: `${name}, the Hermes pet`,
      'data-pet-slug': slug,
      draggable: false,
      style: {
        width: size, height: size, objectFit: 'contain', display: 'block',
        imageRendering: 'pixelated', userSelect: 'none'
      }
    })
  }
  return jsx('div', {
    'data-pet-drawn': slug || 'none',
    title: slug ? `The sprite for ${slug} has not arrived, so this is a drawn stand-in.` : '',
    style: { lineHeight: 0 },
    children: petbCritter(type, state, size)
  })
}

// A pet on the field: the real sprite (or the stand-in), the Hermes state class, and the name.
function PetbPet({ slot, state, facing, scale, thumbs, onNeedThumb }) {
  const percent = petbHpPercent(slot)
  const name = (slot && slot.name) || 'Pet'
  return jsxs('div', {
    'data-testid': `petb-pet-${facing}`,
    'data-state': state || 'idle',
    'data-pet-slug': (slot && slot.slug) || '',
    style: {
      position: 'relative',
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      gap: 4,
      filter: percent <= 0 ? 'grayscale(1)' : 'none',
      transition: 'filter 300ms ease'
    },
    children: [
      jsx('div', {
        className: `petb-state-${state || 'idle'}`,
        style: { lineHeight: 0, transform: facing === 'foe' ? 'scaleX(-1)' : 'none' },
        children: jsx(PetbSprite, { slot, state, facing, scale: scale || 150, thumbs, onNeedThumb })
      }),
      jsx('div', {
        style: { fontSize: 12, color: text.tertiary, transform: facing === 'foe' ? 'scaleX(-1)' : 'none' },
        children: name
      })
    ]
  })
}

function PetbHpCard({ side, slot, active, total, hp }) {
  const shown = hp == null ? slot : { ...slot, hp }
  const percent = petbHpPercent(shown)
  const colour = petbHpColour(percent)
  const right = side === 'foe'
  return jsxs('div', {
    'data-testid': `petb-hpcard-${side}`,
    style: {
      position: 'absolute',
      [right ? 'top' : 'bottom']: 12,
      [right ? 'left' : 'right']: 12,
      width: 'min(62%, 300px)',
      padding: '9px 11px',
      borderRadius: 10,
      background: 'var(--ui-bg-elevated, rgba(12,18,26,0.86))',
      minWidth: 0
    },
    children: [
      jsxs('div', { style: { display: 'flex', alignItems: 'center', gap: 6, justifyContent: right ? 'flex-start' : 'flex-end' }, children: [
        jsx('span', {
          style: {
            fontSize: 12, fontWeight: 700, letterSpacing: '0.06em', textTransform: 'uppercase',
            color: '#10141c', background: petbColour(slot && slot.type), borderRadius: 999, padding: '1px 7px'
          },
          children: (slot && slot.type) || '—'
        }),
        jsx('span', { style: { fontSize: 13, fontWeight: 700, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }, children: (slot && slot.name) || '—' })
      ] }),
      jsx('div', {
        style: { height: 9, borderRadius: 999, background: 'rgba(127,127,127,0.22)', marginTop: 6, overflow: 'hidden' },
        children: jsx('div', {
          'data-testid': `petb-hpbar-${side}`,
          style: {
            width: `${percent}%`, height: '100%', borderRadius: 999, background: colour,
            transition: 'width 420ms ease, background 300ms ease'
          }
        })
      }),
      jsxs('div', { style: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: 4 }, children: [
        jsxs('div', { style: { display: 'flex', gap: 4 }, children: (total || []).map((pet, index) =>
          jsx('span', {
            key: `pip-${index}`,
            title: pet.name,
            style: {
              width: 8, height: 8, borderRadius: 999,
              background: pet.fainted ? 'rgba(127,127,127,0.3)' : petbColour(pet.type),
              outline: index === (active || 0) ? `2px solid ${pet.fainted ? 'transparent' : 'var(--ui-text-secondary, #cfd6e4)'}` : 'none',
              outlineOffset: 1
            }
          }, `pip-${index}`)) }),
        jsx('span', { style: { fontSize: 12, color: text.secondary, fontVariantNumeric: 'tabular-nums' }, children: `${Math.max(0, Number(shown.hp) || 0)} / ${Number(shown.maxhp) || 0}` })
      ] })
    ]
  })
}

function PetbMoveButton({ action, index, disabled, onPick }) {
  const colour = petbColour(action.type)
  return jsxs('button', {
    type: 'button',
    'data-testid': `petb-move-${index}`,
    'aria-label': `${action.name}, ${action.type}, ${action.note || ''}`,
    onClick: () => { if (!disabled) onPick(action) },
    disabled,
    style: {
      textAlign: 'left',
      padding: '9px 11px',
      borderRadius: 6,
      border: 0,
      borderLeft: `2px solid ${disabled ? stroke : colour}`,
      background: disabled ? 'transparent' : fill,
      color: text.primary,
      cursor: disabled ? 'default' : 'pointer',
      opacity: disabled ? 0.55 : 1,
      display: 'flex',
      flexDirection: 'column',
      gap: 2,
      minWidth: 0
    },
    children: [
      jsxs('div', { style: { display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', gap: 8 }, children: [
        jsx('span', { style: { fontWeight: 700, fontSize: 13, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }, children: action.name }),
        jsx('span', { style: { fontSize: 12, color: colour, fontWeight: 700 }, children: action.type })
      ] }),
      jsx('span', { style: { fontSize: 12, color: text.tertiary }, children: action.note || `${action.power} power` })
    ]
  })
}

function PetbSwitchButton({ action, disabled, onPick }) {
  return jsxs('button', {
    type: 'button',
    'data-testid': `petb-switch-${action.slot}`,
    onClick: () => { if (!disabled) onPick(action) },
    disabled,
    style: {
      padding: '7px 9px',
      borderRadius: 10,
      border: `1px solid ${stroke}`,
      background: 'transparent',
      color: text.secondary,
      cursor: disabled ? 'default' : 'pointer',
      opacity: disabled ? 0.45 : 1,
      fontSize: 12,
      display: 'flex',
      alignItems: 'center',
      gap: 6,
      minWidth: 0
    },
    children: [
      jsx('span', { style: { width: 8, height: 8, borderRadius: 999, background: petbColour(action.type) } }),
      jsx('span', { style: { whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }, children: `Switch to ${action.name}` }),
      jsx('span', { style: { color: text.tertiary }, children: `${action.hp}/${action.maxhp}` })
    ]
  })
}

// The Labs card on the Game Center home page: one name, one honest line, one way in.
function PetBattlesLabsCard({ onOpen }) {
  return jsxs('div', {
    'data-labs-card': PETB_ID,
    style: {
      display: 'flex', flexDirection: 'column', justifyContent: 'space-between', gap: 8,
      borderRadius: 14, padding: 16, background: card, minWidth: 0
    },
    children: [
      jsxs('div', { children: [
        jsxs('div', { style: { display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }, children: [
          jsx('div', { style: { fontFamily: DISPLAY_FONT, fontSize: 18, letterSpacing: '-.01em', fontWeight: 600 }, children: 'Pet Battles' }),
          labsBadge()
        ] }),
        jsx('div', { style: { fontSize: 12, color: text.tertiary, marginTop: 2 }, children: 'by Game Center · your Hermes pets, three a side' }),
        jsx('div', {
          style: { fontSize: 12, color: text.secondary, marginTop: 4, lineHeight: 1.35 },
          children: 'Fight with the pets installed in Hermes against pets drawn from the Petdex gallery. Pick four moves, then take on the computer at Beginner, Intermediate, Advanced or Expert.'
        })
      ] }),
      jsxs('div', { style: { display: 'flex', gap: 8, alignItems: 'center', marginTop: 6 }, children: [
        button('Open Pet Battles', onOpen, { primary: true }),
        jsx('span', { style: { fontSize: 12, color: text.tertiary }, children: 'Runs offline · no model calls in play' })
      ] })
    ]
  })
}

// ---- the pet gateway ---------------------------------------------------------
// Desktop: `host.request` (the same JSON-RPC the Hermes app uses). Anything else, including
// the browser preview: the plugin's own read-only routes, which render through Hermes too.
function usePetdex(ctx) {
  const [data, setData] = useState({ loading: true, source: '', reason: '', installed: [], gallery: [], active: '' })
  const [thumbs, setThumbs] = useState({})
  const asked = useRef({})
  const alive = useRef(true)

  useEffect(() => {
    alive.current = true
    return () => { alive.current = false }
  }, [])

  const ask = useCallback(async (method, params) => {
    if (typeof host !== 'undefined' && host && typeof host.request === 'function') {
      try {
        return await host.request(method, params)
      } catch (failure) {
        // A host without the pet methods falls through to the plugin route.
      }
    }
    if (ctx && typeof ctx.rest === 'function') {
      if (method === 'pet.gallery') return ctx.rest('/pet/gallery')
      if (method === 'pet.thumb') {
        return ctx.rest(`/pet/thumb?slug=${encodeURIComponent(params.slug || '')}&url=${encodeURIComponent(params.url || '')}`)
      }
    }
    throw new Error(`no pet gateway for ${method}`)
  }, [ctx])

  // A sprite is either in the gateway answer or in the plugin's own route. A host that
  // answers "no" (a preview without pets, an older build) is not the end of the road.
  const askThumb = useCallback(async (slug, url) => {
    if (typeof host !== 'undefined' && host && typeof host.request === 'function') {
      try {
        const answer = await host.request('pet.thumb', { slug, url })
        if (answer && answer.ok && answer.dataUri) return answer
      } catch (failure) {
        // fall through to the plugin route
      }
    }
    if (ctx && typeof ctx.rest === 'function') {
      return ctx.rest(`/pet/thumb?slug=${encodeURIComponent(slug)}&url=${encodeURIComponent(url || '')}`)
    }
    return { ok: false }
  }, [ctx])

  useEffect(() => {
    let live = true
    ask('pet.gallery', {}).then(answer => {
      if (!live) return
      setData({ loading: false, ...petbGalleryShape(answer) })
    }).catch(() => {
      if (live) setData(current => ({ ...current, loading: false, source: 'local', reason: 'no-gateway' }))
    })
    return () => { live = false }
  }, [ask])

  const loadThumb = useCallback(async slug => {
    if (!slug || asked.current[slug]) return
    asked.current[slug] = true
    const entry = (data.installed || []).find(pet => pet.slug === slug)
      || (data.gallery || []).find(pet => pet.slug === slug)
      || {}
    try {
      const answer = await askThumb(slug, entry.spritesheetUrl || '')
      if (answer && answer.ok && answer.dataUri && alive.current) {
        setThumbs(current => ({ ...current, [slug]: answer.dataUri }))
      }
    } catch (failure) {
      // The drawn stand-in stays, and the screen says the sprite is missing.
    }
  }, [askThumb, data])

  return { ...data, thumbs, loadThumb }
}

// A one-line, honest account of where the pets came from; it only appears when something is
// missing, so a working Hermes never sees a caveat it does not need.
function petdexNote(petdex) {
  if (!petdex || petdex.loading) return null
  const installed = petdex.installed || []
  const lines = []
  if (!installed.length) {
    lines.push('No Hermes pet is installed, so drawn stand-ins are playing. Install or hatch one in Hermes ▸ Settings ▸ Appearance ▸ Pet.')
  }
  if (petdex.source !== 'petdex' || petdex.reason === 'no-gateway') {
    lines.push('The Petdex gallery could not be reached, so the computer fields drawn stand-ins.')
  }
  if (!lines.length) return null
  return jsx('div', {
    'data-testid': 'petdex-note',
    style: { fontSize: 11, color: 'var(--ui-warning, #d9a441)', lineHeight: 1.35 },
    children: lines.join(' ')
  })
}

// The whole screen. It reads `board.picture` and sends short command lines; it never judges
// a move and never computes damage itself.
function PetBattlePanel({ game, view, board, send, ctx, onBack }) {
  const picture = (board && board.picture) || null
  const status = (picture && picture.status) || 'idle'
  const log = (picture && picture.log) || []
  const catalogue = (picture && picture.catalogue) || { types: [], moves: [] }
  const petdex = usePetdex(ctx)
  const [type, setType] = useState('Ember')
  const [moves, setMoves] = useState(['cinder-lash', 'guard-up', 'quick-jab', 'scorch'])
  const [petSlug, setPetSlug] = useState('')
  const [watchLevel, setWatchLevel] = useState('intermediate')
  const [busy, setBusy] = useState(false)
  const [notice, setNotice] = useState('')
  const [shownLog, setShownLog] = useState([])
  const [states, setStates] = useState({})
  const [hpNow, setHpNow] = useState({})
  const [activeNow, setActiveNow] = useState({})
  const [frame, setFrame] = useState(0)
  const [auto, setAuto] = useState(true)
  const [speed, setSpeed] = useState(1)
  const [replaying, setReplaying] = useState(false)
  const [howto, setHowto] = useState(false)
  const seen = useRef(0)
  const token = useRef(0)
  const alive = useRef(true)
  const pending = useRef(null)
  const starting = useRef(null)
  const logBox = useRef(null)

  useEffect(() => {
    alive.current = true
    return () => { alive.current = false }
  }, [])

  // The short "How to play" card opens once, the first time this screen is ever opened.
  // Dismissing it is remembered locally; the header button brings it back on demand.
  useEffect(() => {
    try {
      if (window.localStorage.getItem(PETB_HOWTO_KEY) !== 'seen') setHowto(true)
    } catch (failure) {
      // No storage: the card simply does not auto-open, and the header button still works.
    }
  }, [])
  const closeHowto = () => {
    setHowto(false)
    try { window.localStorage.setItem(PETB_HOWTO_KEY, 'seen') } catch (failure) { /* fine */ }
  }

  // The saved enlistment is the one the buttons start from, so a person who picked Shadow
  // yesterday finds Shadow still picked rather than reset to the default.
  useEffect(() => {
    const saved = picture && picture.enlist
    if (!saved || !saved.type) return
    setType(current => (current === 'Ember' ? saved.type : current))
    if (Array.isArray(saved.moves) && saved.moves.length === 4) {
      setMoves(current => (current.join(',') === 'cinder-lash,guard-up,quick-jab,scorch' ? saved.moves : current))
    }
  }, [picture && picture.enlist && picture.enlist.type])

  const battleKey = `${(picture && picture.seed) || ''}:${status}`
  useEffect(() => {
    // A new battle starts with an empty log on screen: the old hits must not replay.
    seen.current = 0
    setShownLog([])
    setStates({})
    setHpNow({})
    setActiveNow({})
    setFrame(0)
    setAuto(true)
    setReplaying(false)
  }, [battleKey])

  const sleeping = ms => new Promise(resolve => setTimeout(resolve, ms))

  // One line of log, one beat: the Hermes state, the health it moved, the pet it brings on.
  const playEvents = async (events, tick) => {
    for (const event of events) {
      if (!alive.current || token.current !== tick) return false
      setShownLog(lines => lines.concat([event]))
      const side = petbStateSide(event)
      if (side) setStates(current => ({ ...current, [side]: petbStateFor(event) }))
      if (event.kind === 'hit') setHpNow(current => ({ ...current, [event.target]: Number(event.hp) }))
      if (event.kind === 'faint') setHpNow(current => ({ ...current, [event.target]: 0 }))
      if (event.kind === 'switch' && typeof event.slot === 'number') {
        setActiveNow(current => ({ ...current, [event.side]: event.slot }))
      }
      await sleeping(PETB_MOVE_MS)
      if (!alive.current || token.current !== tick) return false
      setStates({})
    }
    return true
  }

  useEffect(() => {
    if (status === 'watch' || !picture) return
    if (log.length < seen.current) {
      seen.current = log.length
      setShownLog(log.slice(0, log.length))
      return
    }
    const fresh = log.slice(seen.current)
    seen.current = log.length
    if (!fresh.length) {
      // A rerun with nothing new (a poll, or a superseded animation) must not leave a
      // pet frozen in its hit pose: a stuck state would hide the result.
      setStates(current => (Object.keys(current).length ? {} : current))
      return
    }
    const tick = ++token.current
    ;(async () => {
      try {
        await playEvents(fresh, tick)
      } finally {
        if (alive.current && token.current === tick) {
          setStates({})
          setHpNow({})
          setActiveNow({})
        }
      }
    })()
  }, [log.length, status, picture && picture.seed])

  useEffect(() => {
    if (logBox.current) logBox.current.scrollTop = logBox.current.scrollHeight
  }, [shownLog.length])

  useEffect(() => {
    if (!picture || status !== 'watch') return
    const frames = (picture.watch && picture.watch.frames) || []
    if (!auto || frame >= frames.length - 1) return
    const timer = setTimeout(() => setFrame(value => Math.min(value + 1, frames.length - 1)), PETB_WATCH_MS / speed)
    return () => clearTimeout(timer)
  }, [auto, frame, speed, status, picture && picture.seed, picture && picture.watch && picture.watch.frames.length])

  // A press that lands while the last turn is still resolving is a real turn, not noise:
  // it waits for the one in flight and then goes. Dropping it made a fast click look
  // broken, and the action bar then looked stuck.
  const command = async line => {
    if (pending.current) {
      try { await pending.current } catch (failure) { /* the earlier one already said so */ }
    }
    const work = (async () => {
      setBusy(true)
      setNotice('')
      try {
        const answer = await send(line)
        if (answer && answer.ok === false) setNotice((answer && answer.text) || 'That did not reach the battle.')
        return answer
      } catch (failure) {
        setNotice(failure && failure.message ? failure.message : 'That did not reach the battle.')
        return null
      } finally {
        pending.current = null
        setBusy(false)
      }
    })()
    pending.current = work
    return work
  }

  // The person's three pets and the computer's three, both named through Hermes. The lead is
  // the card they picked; the computer's team comes from the Petdex gallery for this seed.
  const installed = petdex.installed || []
  const savedPets = (picture && picture.enlist && picture.enlist.pets) || []
  const leadSlug = petSlug || (savedPets[0] && savedPets[0].slug) || (installed[0] && installed[0].slug) || ''

  // One press of Rematch is one battle, whenever it lands. A press that arrived while
  // the last turn's command was still travelling used to be dropped on the floor: the
  // player sat under a result curtain that claimed to be replaying a battle that was
  // already over (the bug hunt's dead Rematch). Now it waits its turn behind whatever
  // is in flight, and a second press joins the start already running.
  const start = level => {
    if (moves.length !== 4) {
      setNotice('Pick exactly four moves to start.')
      return Promise.resolve()
    }
    if (starting.current) return starting.current
    const run = (async () => {
      try {
        const seed = Math.floor(Math.random() * 999999) + 1
        const mine = petbTeamIdentities(installed, leadSlug, 3)
        const theirs = petbPickOpponents(petdex.gallery, seed, 3)
        const enlistLine = [`${game.id} enlist ${type} ${moves.join(',')}`, petbIdentityTokens(mine)].filter(Boolean).join(' ')
        const newLine = [`${game.id} new ${level} ${seed}`, petbIdentityTokens(theirs)].filter(Boolean).join(' ')
        await command(enlistLine)
        await command(newLine)
      } finally {
        starting.current = null
      }
    })()
    starting.current = run
    return run
  }

  const watch = async level => {
    if (busy) return
    const chosen = typeof level === 'string' ? level : watchLevel
    setWatchLevel(chosen)
    await command(`${game.id} watch ${chosen}`)
  }

  const newBattle = () => command(`${game.id} reset`)
  const back = () => { if (typeof onBack === 'function') onBack() }

  // Watch replay of the battle just played: the same log, played again from turn one.
  const replayBattle = async () => {
    if (replaying || !log.length) return
    const tick = ++token.current
    setReplaying(true)
    setShownLog([])
    setStates({})
    setHpNow({})
    setActiveNow({})
    setNotice('')
    try {
      await playEvents(log, tick)
    } finally {
      if (alive.current && token.current === tick) {
        setStates({})
        setHpNow({})
        setActiveNow({})
        setShownLog(log)
      }
      if (alive.current) setReplaying(false)
    }
  }

  if (!picture) {
    return jsxs('div', { style: { padding: 18, display: 'flex', flexDirection: 'column', gap: 10 }, children: [
      jsx('div', { style: { fontFamily: DISPLAY_FONT, fontSize: 26, lineHeight: 1.15, fontWeight: 600, letterSpacing: '-.02em' }, children: 'Pet Battles' }),
      jsx('div', { style: { fontSize: 13, color: text.tertiary }, children: 'Waiting for the battle field…' }),
      jsxs('div', { style: { display: 'flex', gap: 8 }, children: [
        jsx(LearnButton, { game, ctx }),
        button('Back to games', back)
      ] })
    ] })
  }

  const you = picture.you || { slots: [], active: 0, name: 'You' }
  const foe = picture.foe || { slots: [], active: 0, name: 'The computer' }
  // Watch mode draws the frame being played, so both the health bars and the pets on the
  // field move with the replay instead of showing the finished result from the first beat.
  const watchFrames = (picture.watch && picture.watch.frames) || []
  const watchFrame = status === 'watch' ? petbFrame(watchFrames, frame) : null
  const youSlots = watchFrame ? watchFrame.you : you.slots || []
  const foeSlots = watchFrame ? watchFrame.foe : foe.slots || []
  const youActive = activeNow.you != null ? activeNow.you : (watchFrame ? watchFrame.active.you : you.active)
  const foeActive = activeNow.foe != null ? activeNow.foe : (watchFrame ? watchFrame.active.foe : foe.active)
  const youSlot = youSlots[youActive] || { name: '—', type: 'Ember', hp: 0, maxhp: 1 }
  const foeSlot = foeSlots[foeActive] || { name: '—', type: 'Ember', hp: 0, maxhp: 1 }
  const legal = picture.legal || []
  const moveActions = legal.filter(action => action.kind === 'move')
  const switchActions = legal.filter(action => action.kind === 'switch')
  // A beat plays for about half a second, but the buttons do not wait for it: the engine
  // decides what is legal, and gating input on a cosmetic flag meant a beat that never
  // finished clearing could lock the whole action bar.
  const youState = states.you || petbRestState('you', status)
  const foeState = states.foe || petbRestState('foe', status)
  // In watch mode the replay runs first and the curtain waits for the last frame; a
  // battle that has just finished has no replay to wait for. `curtain` is the one answer
  // every control uses, so nothing hides behind a card that is not there.
  const watchFramesAll = (picture.watch && picture.watch.frames) || []
  const watchDone = status !== 'watch' || watchFramesAll.length < 2 || frame >= watchFramesAll.length - 1
  const curtain = Boolean(picture.overlay && !replaying && watchDone)

  const header = jsxs('div', {
    style: { display: 'flex', alignItems: 'flex-end', justifyContent: 'space-between', gap: 12, flexWrap: 'wrap', paddingBottom: 8, borderBottom: `1px solid ${stroke}` },
    children: [
      jsxs('div', { children: [
        jsxs('div', { style: { display: 'flex', alignItems: 'baseline', gap: 10, flexWrap: 'wrap' }, children: [
          jsx('div', { style: { fontFamily: DISPLAY_FONT, fontSize: 28, lineHeight: 1.15, letterSpacing: '-.02em', fontWeight: 600 }, children: 'Pet Battles' }),
          labsBadge(),
          status === 'idle' ? null : jsx('span', {
            'data-testid': 'petb-turn',
            children: badge(`${picture.level_label || 'Intermediate'} · turn ${picture.turn || 0}`)
          })
        ] }),
        jsx('div', {
          'data-testid': 'petb-status',
          style: { fontSize: 12, color: text.secondary, marginTop: 2 },
          children: status === 'idle'
            ? 'Pick your pet, a type, four moves and a level. Everything happens with clicks.'
            : status === 'watch'
              ? 'Two computer teams are playing. Nothing you press changes the result.'
              : status === 'active'
                ? 'Your turn: choose a move or switch a pet.'
                : 'The battle is finished.'
        })
      ] }),
      jsxs('div', { style: { display: 'flex', gap: 6, flexWrap: 'wrap' }, children: [
        button('How to play', () => setHowto(true)),
        status === 'idle' ? null : button('Watch bots', watch, { disabled: busy }),
        // A battle left half played must never be a trap: the picks are one press away,
        // and the result curtain carries its own copy of this button.
        status === 'idle' || curtain ? null : button('New battle', newBattle, { disabled: busy }),
        button('Back to games', back),
        jsx(LearnButton, { game, ctx })
      ] })
    ]
  })

  const field = jsxs('div', {
    'data-testid': 'petb-field',
    style: {
      position: 'relative',
      minHeight: 300,
      borderRadius: 12,
      overflow: 'hidden',
      background: 'var(--ui-bg-solid, #0b0a09)'
    },
    children: [
      // The floor is drawn, not lit: a horizon rule, a centre ring with four ticks, and
      // two corner chevrons. The same marks every battle, so a replay still looks identical.
      jsx('div', { style: { position: 'absolute', left: '6%', right: '6%', top: '52%', height: 1, background: `linear-gradient(90deg, transparent, ${stroke}, transparent)` } }),
      jsxs('div', {
        style: {
          position: 'absolute', left: '50%', top: '52%', width: 220, height: 220, marginLeft: -110, marginTop: -110,
          borderRadius: '50%', border: `1px solid ${stroke}`, opacity: 0.5
        },
        children: [0, 90, 180, 270].map(angle => jsx('span', {
          key: `tick-${angle}`,
          style: {
            position: 'absolute', left: '50%', top: '50%', width: 1, height: 10, background: stroke,
            transform: `rotate(${angle}deg) translateY(-110px)`, transformOrigin: '0 0'
          }
        }))
      }),
      jsx('div', { style: { position: 'absolute', left: 14, top: 12, width: 22, height: 1, background: stroke } }),
      jsx('div', { style: { position: 'absolute', left: 14, top: 12, width: 1, height: 22, background: stroke } }),
      jsx('div', { style: { position: 'absolute', right: 14, top: 12, width: 22, height: 1, background: stroke } }),
      jsx('div', { style: { position: 'absolute', right: 14, top: 12, width: 1, height: 22, background: stroke } }),
      jsx('div', { style: { position: 'absolute', left: '7%', bottom: '9%', width: '36%', height: 20, borderRadius: '50%', background: 'rgba(127,127,127,0.10)' } }),
      jsx('div', { style: { position: 'absolute', right: '7%', bottom: '9%', width: '36%', height: 20, borderRadius: '50%', background: 'rgba(127,127,127,0.10)' } }),
      jsx('div', { style: { position: 'absolute', left: '9%', bottom: '18%' }, children:
        jsx(PetbPet, { slot: youSlot, state: youState, facing: 'you', scale: 158, thumbs: petdex.thumbs, onNeedThumb: petdex.loadThumb }) }),
      jsx('div', { style: { position: 'absolute', right: '9%', top: '18%' }, children:
        jsx(PetbPet, { slot: foeSlot, state: foeState, facing: 'foe', scale: 158, thumbs: petdex.thumbs, onNeedThumb: petdex.loadThumb }) }),
      jsx(PetbHpCard, { side: 'foe', slot: foeSlot, active: foeActive, total: foeSlots, hp: hpNow.foe }),
      jsx(PetbHpCard, { side: 'you', slot: youSlot, active: youActive, total: youSlots, hp: hpNow.you })
    ]
  })

  const actionBar = status === 'active'
    ? jsxs('div', { style: { display: 'flex', flexDirection: 'column', gap: 8 }, children: [
        jsx('div', {
          style: { display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(min(100%, 190px), 1fr))', gap: 8 },
          children: moveActions.map(action =>
            jsx(PetbMoveButton, {
              action,
              index: action.index,
              disabled: busy || !picture.can_move,
              onPick: picked => command(`${game.id} move ${picked.index}`)
            }, `move-${action.index}`))
        }),
        switchActions.length
          ? jsxs('div', { style: { display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'center' }, children: [
              jsx('span', { style: { fontSize: 12, color: text.tertiary }, children: 'Or switch:' }),
              ...switchActions.map(action =>
                jsx(PetbSwitchButton, {
                  action,
                  disabled: busy || !picture.can_move,
                  onPick: picked => command(`${game.id} switch ${picked.slot}`)
                }, `switch-${action.slot}`))
            ] })
          : null
      ] })
    : status === 'watch'
      ? jsxs('div', { style: { display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'center' }, children: [
          button(auto ? 'Pause' : 'Play', () => setAuto(value => !value), { primary: !auto, disabled: frame >= ((picture.watch && picture.watch.frames.length) || 1) - 1 && auto }),
          button('1×', () => setSpeed(1), { primary: speed === 1 }),
          button('2×', () => setSpeed(2), { primary: speed === 2 }),
          button('Replay', () => { setFrame(0); setAuto(true) }),
          jsxs('span', { style: { fontSize: 12, color: text.secondary }, children: [
            `Frame ${Math.min(frame + 1, (picture.watch && picture.watch.frames.length) || 1)} of ${(picture.watch && picture.watch.frames.length) || 1}`
          ] })
        ] })
      : status === 'idle'
        ? null
        // The result curtain carries these four buttons, so the action bar keeps out of
        // the way while it is up: two copies of Rematch under one curtain is a mouse
        // target that cannot be reached.
        : curtain
          ? null
          : jsxs('div', { style: { display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'center' }, children: [
          button('Rematch', () => start(picture.level || 'intermediate'), { primary: true }),
          button('New battle', newBattle, { disabled: busy }),
          button('Watch replay', replayBattle, { disabled: busy || replaying }),
          jsx('span', { style: { fontSize: 11, color: text.tertiary }, children: `Seed ${picture.seed || '—'} · same seed replays the same battle` })
        ] })

  const logPanel = jsxs('div', {
    style: { display: 'flex', flexDirection: 'column', gap: 6, minHeight: 0, minWidth: 0 },
    children: [
      jsx('div', { style: { fontSize: 12, letterSpacing: '0.12em', textTransform: 'uppercase', color: text.tertiary }, children: 'Battle log' }),
      jsxs('div', {
        ref: logBox,
        'data-testid': 'petb-log',
        style: {
          flex: '1 1 auto', minHeight: 140, overflowY: 'auto', padding: '10px 12px',
          borderRadius: 10, background: card,
          display: 'flex', flexDirection: 'column', gap: 4, fontSize: 12, lineHeight: 1.35
        },
        children: shownLog.length || log.length
          ? (status === 'watch' ? watchLogLines(picture, frame) : shownLog).map((event, index) =>
              jsx('div', {
                style: {
                  color: event.kind === 'win' ? text.primary : event.kind === 'faint' ? '#e0574f' : text.secondary,
                  fontWeight: event.kind === 'win' || event.kind === 'faint' ? 650 : 400,
                  borderLeft: event.kind === 'hit' ? `2px solid ${petbColour(event.move_type)}` : '2px solid transparent',
                  paddingLeft: 6
                },
                children: petbLogLine(event)
              }, `line-${index}`))
          : jsx('div', { style: { color: text.tertiary }, children: status === 'idle' ? 'No battle yet. The log fills in as the turns play.' : 'The first turn starts when you pick a move.' })
      }),
      petdexNote(petdex),
      notice ? jsx('div', { role: 'status', style: { fontSize: 12, color: text.secondary }, children: notice }) : null
    ]
  })

  const result = curtain
    ? jsx(PetbResult, {
        overlay: picture.overlay,
        picture,
        thumbs: petdex.thumbs,
        onNeedThumb: petdex.loadThumb,
        busy,
        notice: status === 'watch' ? '' : notice,
        mode: status === 'watch' ? 'watch' : 'battle',
        onRematch: status === 'watch' ? () => { setFrame(0); setAuto(true) } : () => start(picture.level || 'intermediate'),
        onNew: status === 'watch' ? () => command(`${game.id} reset`) : newBattle,
        onReplay: status === 'watch' ? () => { setFrame(0); setAuto(true) } : replayBattle,
        onBack: back
      })
    : null

  return jsxs('div', {
    'data-testid': 'petb-screen',
    'data-status': status,
    'data-petdex': petdex.source || 'loading',
    className: 'games-petb',
    style: {
      position: 'relative',
      display: 'grid',
      gridTemplateColumns: 'minmax(0, 1fr) minmax(230px, 300px)',
      gap: 14,
      padding: 16,
      height: '100%',
      minHeight: 0,
      background: paper
    },
    children: [
      jsx('style', { children: `
        @keyframes petb-bob { 0%,100% { transform: translateY(0) } 50% { transform: translateY(-5px) } }
        @keyframes petb-run { 0% { transform: translate(0,0) } 30% { transform: translate(-26px,-6px) } 55% { transform: translate(18px,-12px) } 100% { transform: translate(0,0) } }
        @keyframes petb-jump { 0% { transform: translate(0,0); filter: brightness(1) } 32% { transform: translate(0,-22px) scale(1.06); filter: brightness(2.1) } 100% { transform: translate(0,0) scale(1); filter: brightness(1) } }
        @keyframes petb-failed { 0% { transform: translateY(0) rotate(0); opacity: 1 } 100% { transform: translateY(30px) rotate(-7deg); opacity: 0.35 } }
        @keyframes petb-wave { 0%,100% { transform: rotate(0) } 25% { transform: rotate(-7deg) translateY(-6px) } 60% { transform: rotate(6deg) translateY(-4px) } }
        @keyframes petb-review { 0%,100% { transform: translateY(0) scale(1) } 50% { transform: translateY(-3px) scale(1.02) } }
        @keyframes petb-waiting { 0%,100% { opacity: 0.72 } 50% { opacity: 1 } }
        .petb-state-idle { animation: petb-bob 2.6s ease-in-out infinite }
        .petb-state-run { animation: petb-run 440ms ease-out }
        .petb-state-jump { animation: petb-jump 460ms ease-out }
        .petb-state-failed { animation: petb-failed 520ms ease-in forwards }
        .petb-state-wave { animation: petb-wave 620ms ease-in-out }
        .petb-state-review { animation: petb-review 1.5s ease-in-out infinite }
        .petb-state-waiting { animation: petb-waiting 1.8s ease-in-out infinite }
        @media (prefers-reduced-motion: reduce) {
          [class^="petb-state-"] { animation: none !important }
        }
        @container (max-width: 760px) {
          .games-petb { grid-template-columns: minmax(0, 1fr) !important; overflow: auto; }
        }
      ` }),
      jsxs('div', { style: { display: 'flex', flexDirection: 'column', gap: 10, minWidth: 0, minHeight: 0, overflow: 'auto' }, children: [
        header,
        status === 'idle'
          ? jsx(PetbEnlist, {
              picture, catalogue, type, setType, moves, setMoves, busy, notice,
              petdex, leadSlug, setPetSlug,
              watchLevel, setWatchLevel, onStart: start, onWatch: watch
            })
          : field,
        actionBar
      ] }),
      status === 'idle' ? null : logPanel,
      result,
      howto ? jsx(PetbHowTo, { onClose: closeHowto }) : null
    ]
  })
}

// Watch mode draws the log up to the frame being played, not the whole finished battle.
function watchLogLines(picture, frame) {
  const frames = (picture.watch && picture.watch.frames) || []
  const current = petbFrame(frames, frame)
  const turn = current ? current.turn : 0
  const events = (picture.watch && picture.watch.events) || []
  return events.filter(event => Number(event.turn) <= turn)
}

// The winner, for the result card: the engine names the pet that finished the battle; an
// old saved battle without that key falls back to the winning side's pet on the field.
function petbWinnerPet(picture, overlay) {
  if (overlay && overlay.winner_pet && overlay.winner_pet.name) return overlay.winner_pet
  if (!overlay) return null
  const you = (picture && picture.you) || { slots: [], active: 0 }
  const foe = (picture && picture.foe) || { slots: [], active: 0 }
  if (overlay.result === 'win') return you.slots[you.active] || null
  if (overlay.result === 'lose') return foe.slots[foe.active] || null
  return you.slots[you.active] || foe.slots[foe.active] || null
}

// The end of a battle: the winner and their pet, then every way out. Back is always one of
// them, so a finished battle can never trap the person on the field.
function PetbResult({ overlay, picture, thumbs, onNeedThumb, busy, notice, onRematch, onNew, onReplay, onBack, mode }) {
  if (!overlay) return null
  const win = overlay.result === 'win'
  const draw = overlay.result === 'draw'
  const colour = draw ? text.secondary : win ? '#4fb86a' : '#e0574f'
  const winner = petbWinnerPet(picture, overlay)
  const watching = mode === 'watch'
  const sideLabel = watching
    ? (winner && winner.side === 'foe' ? 'Team Orange' : 'Team Blue')
    : win ? 'Your pet' : draw ? 'Last out' : 'The computer’s pet'
  return jsx('div', {
    'data-testid': 'petb-result',
    style: {
      // Fixed, not absolute: the screen is a grid, and an absolutely placed child is
      // laid out inside a grid cell, which put the card off to one side and under the
      // fold where the buttons could not be reached. Fixed pins it to the window.
      position: 'fixed', inset: 0, zIndex: 60, display: 'flex', alignItems: 'center', justifyContent: 'center',
      background: 'rgba(8,11,16,0.72)', backdropFilter: 'blur(4px)', padding: 16, overflowY: 'auto'
    },
    children: jsxs('div', {
      style: {
        width: 'min(460px, 100%)', maxHeight: 'calc(100vh - 32px)', overflowY: 'auto',
        borderRadius: 18, border: `1px solid ${stroke}`,
        background: 'var(--ui-bg-elevated, #141c26)', padding: 20, textAlign: 'center',
        display: 'flex', flexDirection: 'column', gap: 8, boxShadow: '0 18px 50px rgba(0,0,0,0.4)'
      },
      children: [
        jsx('div', { style: { fontSize: 11, letterSpacing: '0.16em', textTransform: 'uppercase', color: text.tertiary }, children: draw ? 'Draw' : win ? 'Victory' : 'Defeat' }),
        jsxs('div', {
          'data-testid': 'petb-result-pet',
          style: { display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 6, margin: '2px 0 4px' },
          children: [
            jsx('div', { style: { lineHeight: 0 }, children:
              jsx(PetbSprite, { slot: winner || {}, state: win ? 'jump' : 'failed', facing: 'you', scale: 128, thumbs, onNeedThumb }) }),
            jsxs('div', { style: { display: 'flex', alignItems: 'center', gap: 7, flexWrap: 'wrap', justifyContent: 'center' }, children: [
              jsx('span', { style: { fontSize: 15, fontWeight: 700 }, children: (winner && winner.name) || '—' }),
              winner && winner.type ? jsx('span', {
                style: {
                  fontSize: 10, fontWeight: 700, letterSpacing: '0.05em', textTransform: 'uppercase',
                  color: '#10141c', background: petbColour(winner.type), borderRadius: 999, padding: '1px 7px'
                },
                children: winner.type
              }) : null,
              jsx('span', { style: { fontSize: 11, color: text.tertiary }, children: sideLabel })
            ] })
          ]
        }),
        jsx('div', { style: { fontSize: 26, fontWeight: 800, color: colour, letterSpacing: '-0.02em' }, children: overlay.title }),
        jsx('div', { style: { fontSize: 13, color: text.secondary, lineHeight: 1.4 }, children: overlay.line }),
        jsx('div', { style: { fontSize: 11, color: text.tertiary }, children: `${overlay.turns || 0} turns · seed ${(picture && picture.seed) || '—'}` }),
        // A Rematch that the battle refused to start says so here, on the card the
        // person is looking at, instead of as a quiet line behind the curtain.
        notice ? jsx('div', { role: 'status', style: { fontSize: 12, color: '#e0574f', lineHeight: 1.35 }, children: notice }) : null,
        jsxs('div', { style: { display: 'flex', gap: 8, justifyContent: 'center', flexWrap: 'wrap', marginTop: 6 }, children: [
          // Never disabled: the card it sits on is the way out, and a greyed-out way out
          // with no explanation is how the stuck result curtain read as a dead button.
          button(watching ? 'Play again' : 'Rematch', onRematch, { primary: true }),
          button('New battle', onNew, { disabled: busy }),
          button('Watch replay', onReplay, { disabled: busy }),
          button('Back to games', onBack)
        ] })
      ]
    })
  })
}

// The short "How to play" card: the type chart, four moves, switching. TU's full tutorial
// replaces this later; until then this is the whole teaching surface.
function PetbHowTo({ onClose }) {
  const row = (attack, beaten) => jsxs('div', { style: { display: 'flex', alignItems: 'center', gap: 6, flexWrap: 'wrap' }, children: [
    jsx('span', { style: { fontWeight: 700, color: petbColour(attack) }, children: attack }),
    jsx('span', { style: { color: text.tertiary, fontSize: 12 }, children: 'beats' }),
    jsx('span', { style: { fontWeight: 700, color: petbColour(beaten) }, children: beaten }),
    jsx('span', { style: { color: text.tertiary, fontSize: 11 }, children: 'and loses to the next one round the ring' })
  ] })
  return jsx('div', {
    'data-testid': 'petb-howto',
    style: {
      // Fixed for the same reason as the result curtain: a grid child placed absolutely
      // lands in a cell, not over the screen.
      position: 'fixed', inset: 0, zIndex: 70, display: 'flex', alignItems: 'center', justifyContent: 'center',
      background: 'rgba(8,11,16,0.7)', backdropFilter: 'blur(3px)', padding: 16, overflowY: 'auto'
    },
    children: jsxs('div', {
      style: {
        width: 'min(520px, 100%)', maxHeight: '90%', overflow: 'auto', borderRadius: 18,
        border: `1px solid ${stroke}`, background: 'var(--ui-bg-elevated, #141c26)', padding: 20,
        display: 'flex', flexDirection: 'column', gap: 10, boxShadow: '0 18px 50px rgba(0,0,0,0.4)'
      },
      children: [
        jsxs('div', { style: { display: 'flex', alignItems: 'center', gap: 8 }, children: [
          jsx('div', { style: { fontSize: 18, fontWeight: 700 }, children: 'How to play' }),
          labsBadge()
        ] }),
        jsx('div', { style: { fontSize: 13, color: text.secondary, lineHeight: 1.45 },
          children: 'Three pets a side. Each turn you pick one of your four moves, or switch to another pet. Every pet starts at full health.' }),
        jsxs('div', { style: { border: `1px solid ${stroke}`, borderRadius: 12, padding: 12, display: 'flex', flexDirection: 'column', gap: 6 }, children: [
          jsx('div', { style: { fontSize: 11, letterSpacing: '0.12em', textTransform: 'uppercase', color: text.tertiary }, children: 'Types beat types' }),
          row('Ember', 'Verdant'),
          row('Verdant', 'Tide'),
          row('Tide', 'Ember'),
          row('Data', 'Shadow'),
          row('Shadow', 'Steel'),
          row('Steel', 'Data'),
          jsx('div', { style: { fontSize: 11, color: text.tertiary }, children: 'A move that matches your pet’s own type hits 25% harder. A good match-up is worth half as much again.' })
        ] }),
        jsxs('div', { style: { border: `1px solid ${stroke}`, borderRadius: 12, padding: 12, display: 'flex', flexDirection: 'column', gap: 5 }, children: [
          jsx('div', { style: { fontSize: 11, letterSpacing: '0.12em', textTransform: 'uppercase', color: text.tertiary }, children: 'Four moves and a switch' }),
          jsx('div', { style: { fontSize: 12, color: text.secondary, lineHeight: 1.45 },
            children: 'You bring four moves and may use any of them every turn — there are no charges. Some moves shield, heal, raise a stat or leave a status on the other pet.' }),
          jsx('div', { style: { fontSize: 12, color: text.secondary, lineHeight: 1.45 },
            children: 'Switching uses your turn: the pet that comes in takes that turn’s hit. Switch when your pet is nearly out, or when the match-up is wrong.' }),
          jsx('div', { style: { fontSize: 12, color: text.secondary, lineHeight: 1.45 },
            children: 'When a pet faints the next one comes in. Beat all three of theirs to win.' })
        ] }),
        jsxs('div', { style: { display: 'flex', gap: 8, justifyContent: 'flex-end', marginTop: 2 }, children: [
          button('Got it', onClose, { primary: true })
        ] })
      ]
    })
  })
}

// One card per real Hermes pet: the sprite Hermes renders for it, its name, and a ring when
// it leads your team.
function PetbPetCard({ pet, selected, onPick, thumbs, onNeedThumb }) {
  const colour = petbColour(pet.type || 'Data')
  return jsxs('button', {
    type: 'button',
    'data-testid': `petb-petcard-${pet.slug}`,
    'data-selected': selected ? 'true' : 'false',
    'aria-pressed': selected,
    title: selected ? `${pet.displayName || pet.slug} leads your team` : `Lead with ${pet.displayName || pet.slug}`,
    onClick: () => onPick(pet.slug),
    style: {
      display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 3, padding: '8px 6px',
      width: 96, borderRadius: 14, cursor: 'pointer', background: selected ? `${accent}22` : 'transparent',
      border: `2px solid ${selected ? accent : stroke}`, color: text.primary, minWidth: 0
    },
    children: [
      jsx('div', { style: { width: 64, height: 64, display: 'flex', alignItems: 'center', justifyContent: 'center', lineHeight: 0 }, children:
        jsx(PetbSprite, {
          slot: { slug: pet.slug, name: pet.displayName, type: pet.type || 'Data' },
          state: 'idle', facing: 'you', scale: 64, thumbs, onNeedThumb
        }) }),
      jsx('span', {
        style: { fontSize: 11, fontWeight: 650, maxWidth: '100%', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' },
        children: pet.displayName || pet.slug
      }),
      jsx('span', {
        style: { fontSize: 9, letterSpacing: '0.05em', textTransform: 'uppercase', color: colour },
        children: pet.type || 'ready'
      })
    ]
  })
}

// Pre-battle: your pets, a type, four moves, and four levels. Every choice is a button, and a
// choice that cannot start a battle explains itself instead of hiding.
function PetbEnlist({ picture, catalogue, type, setType, moves, setMoves, busy, notice, watchLevel, setWatchLevel, onStart, onWatch, petdex, leadSlug, setPetSlug }) {
  const types = catalogue.types || []
  const allMoves = catalogue.moves || []
  const installed = (petdex && petdex.installed) || []
  const pickup = petdex && petdex.loadThumb
  const thumbs = (petdex && petdex.thumbs) || {}
  const toggle = moveId => {
    setMoves(current => {
      if (current.includes(moveId)) return current.filter(item => item !== moveId)
      if (current.length >= 4) return current
      return current.concat([moveId])
    })
  }
  const ready = moves.length === 4 && Boolean(type)
  const levels = picture.levels || []
  return jsxs('div', {
    'data-testid': 'petb-enlist',
    style: { display: 'flex', flexDirection: 'column', gap: 12, minWidth: 0 },
    children: [
      // Your pets: the ones installed in Hermes, shown with the sprite Hermes itself renders.
      jsxs('div', { style: { border: `1px solid ${stroke}`, borderRadius: 14, padding: 12, background: card }, children: [
        jsxs('div', { style: { display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', gap: 8, flexWrap: 'wrap', marginBottom: 8 }, children: [
          jsx('div', { style: { fontSize: 12, fontWeight: 700 }, children: '1. Pick the pet who leads' }),
          jsx('div', { style: { fontSize: 11, color: text.tertiary }, children: 'your pets in Hermes · shown through Hermes, never copied' })
        ] }),
        installed.length
          ? jsxs('div', { style: { display: 'flex', gap: 8, flexWrap: 'wrap' }, children: [
              ...installed.slice(0, 8).map(pet =>
                jsx(PetbPetCard, {
                  pet, selected: leadSlug === pet.slug, onPick: setPetSlug,
                  thumbs, onNeedThumb: pickup
                }, `pet-${pet.slug}`)),
              jsx('div', {
                'data-testid': 'petdex-gallery-line',
                style: { fontSize: 11, color: text.tertiary, alignSelf: 'center', maxWidth: 200, lineHeight: 1.35 },
                children: `${Math.max(0, (petdex.gallery || []).length)} pets from the Petdex gallery are waiting on the other side.`
              })
            ] })
          : jsxs('div', {
              'data-testid': 'petb-no-pet',
              style: { display: 'flex', gap: 10, alignItems: 'center', flexWrap: 'wrap', border: `1px dashed ${stroke}`, borderRadius: 12, padding: 12 },
              children: [
                jsx('div', { style: { fontSize: 12, color: text.secondary, lineHeight: 1.4, maxWidth: 360 },
                  children: 'No Hermes pet is installed yet. Hermes can hatch one with a model, or install one from the Petdex gallery — that is Hermes’s own flow, in Settings ▸ Appearance ▸ Pet.' }),
                button('Open pet gallery in Hermes', () => {
                  try {
                    if (typeof host !== 'undefined' && host && typeof host.navigate === 'function') host.navigate('/settings')
                  } catch (failure) { /* an older host: the line above already names the screen */ }
                }, { primary: true })
              ]
            }),
        // The other side, drawn from the Petdex gallery and shown by Hermes's own thumbnail.
        (petdex && (petdex.gallery || []).length)
          ? jsxs('div', {
              'data-testid': 'petdex-strip',
              style: { display: 'flex', gap: 10, alignItems: 'flex-end', flexWrap: 'wrap', marginTop: 10, paddingTop: 10, borderTop: `1px solid ${stroke}` },
              children: [
                jsx('span', { style: { fontSize: 11, color: text.tertiary, alignSelf: 'center' }, children: 'On the other side, from Petdex:' }),
                ...(petdex.gallery || []).slice(0, 6).map(pet =>
                  jsxs('div', {
                    key: `gallery-${pet.slug}`,
                    'data-gallery-pet': pet.slug,
                    title: `${pet.displayName || pet.slug} — one of the pets you might face`,
                    style: { display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 2, width: 58 },
                    children: [
                      jsx('div', { style: { width: 46, height: 46, display: 'flex', alignItems: 'center', justifyContent: 'center', lineHeight: 0 }, children:
                        jsx(PetbSprite, {
                          slot: { slug: pet.slug, name: pet.displayName, type: pet.type || 'Data' },
                          state: 'idle', facing: 'you', scale: 46, thumbs, onNeedThumb: pickup
                        }) }),
                      jsx('span', {
                        style: { fontSize: 9, color: text.tertiary, maxWidth: 58, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' },
                        children: pet.displayName || pet.slug
                      })
                    ]
                  }, `gallery-${pet.slug}`))
              ]
            })
          : null
      ] }),
      jsxs('div', {
        style: { display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(min(100%, 300px), 1fr))', gap: 12 },
        children: [
          jsxs('div', { style: { border: `1px solid ${stroke}`, borderRadius: 14, padding: 12, background: card }, children: [
            jsx('div', { style: { fontSize: 12, fontWeight: 700, marginBottom: 8 }, children: '2. Pick your type' }),
            jsxs('div', { style: { display: 'flex', flexWrap: 'wrap', gap: 6 }, children: types.map(item =>
              jsxs('button', {
                type: 'button',
                key: item.name,
                'data-testid': `petb-type-${item.name.toLowerCase()}`,
                onClick: () => setType(item.name),
                'aria-pressed': type === item.name,
                style: {
                  display: 'inline-flex', alignItems: 'center', gap: 6, padding: '6px 10px', borderRadius: 6,
                  border: 0,
                  background: type === item.name ? fill : 'transparent',
                  color: type === item.name ? text.primary : text.secondary,
                  boxShadow: type === item.name ? `inset 2px 0 0 ${item.colour}` : 'none',
                  cursor: 'pointer', fontSize: 12, fontWeight: 600
                },
                children: [
                  jsx('span', { style: { width: 9, height: 9, borderRadius: 999, background: item.colour } }),
                  item.name
                ]
              }, item.name)) }),
            jsx('div', { style: { fontSize: 12, color: text.tertiary, marginTop: 8, lineHeight: 1.4 },
              children: 'Ember ▸ Verdant ▸ Tide ▸ Ember · Data ▸ Shadow ▸ Steel ▸ Data. A move that matches your type hits 25% harder.' })
          ] }),
          jsxs('div', { style: { border: `1px solid ${stroke}`, borderRadius: 14, padding: 12, background: card }, children: [
            jsx('div', { style: { fontSize: 12, fontWeight: 700, marginBottom: 8 }, children: `3. Pick four moves — ${moves.length} of 4` }),
            jsxs('div', { style: { display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(min(100%, 132px), 1fr))', gap: 6 }, children: allMoves.map(move => {
              const picked = moves.includes(move.id)
              const colour = petbColour(move.type)
              return jsxs('button', {
                type: 'button',
                key: move.id,
                'data-testid': `petb-pick-${move.id}`,
                'aria-pressed': picked,
                onClick: () => toggle(move.id),
                disabled: !picked && moves.length >= 4,
                style: {
                  textAlign: 'left', padding: '6px 8px', borderRadius: 6,
                  border: 0,
                  borderLeft: `2px solid ${picked ? colour : stroke}`,
                  background: picked ? fill : 'transparent',
                  color: picked ? text.primary : text.secondary,
                  fontSize: 12, cursor: picked || moves.length < 4 ? 'pointer' : 'default',
                  opacity: !picked && moves.length >= 4 ? 0.45 : 1,
                  display: 'flex', flexDirection: 'column', gap: 1, minWidth: 0
                },
                children: [
                  jsx('span', { style: { fontWeight: 650, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }, children: move.name }),
                  jsxs('span', { style: { color: colour, fontSize: 12 }, children: [
                    move.type,
                    move.power ? ` · ${move.power}` : move.kind === 'heal' ? ' · heal' : move.kind === 'shield' ? ' · shield' : ''
                  ] })
                ]
              }, move.id)
            }) })
          ] })
        ]
      }),
      jsxs('div', { style: { border: `1px solid ${stroke}`, borderRadius: 14, padding: 12, background: card }, children: [
        jsx('div', { style: { fontSize: 12, fontWeight: 700, marginBottom: 8 }, children: '4. Start a battle against the computer' }),
        jsxs('div', { style: { display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'center' }, children: [
          ...levels.map(level =>
            jsx('button', {
              type: 'button',
              key: level.id,
              'data-testid': `petb-level-${level.id}`,
              onClick: () => onStart(level.id),
              disabled: !ready || busy,
              style: {
                padding: '9px 14px', borderRadius: 6,
                border: `1px solid ${ready ? accent : stroke}`,
                background: ready ? `${accent}1f` : 'transparent',
                color: ready ? text.primary : text.tertiary,
                cursor: ready && !busy ? 'pointer' : 'default',
                fontSize: 13, fontWeight: 700, opacity: busy ? 0.6 : 1
              },
              children: level.label
            }, level.id)),
          jsx('span', {
            style: { fontSize: 12, color: ready ? text.tertiary : 'var(--ui-warning, #d9a441)' },
            children: ready ? `Lead pet: ${type}, four moves chosen.` : 'Pick exactly four moves to start.'
          })
        ] }),
        jsxs('div', { style: { display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'center', marginTop: 12, paddingTop: 12, borderTop: `1px solid ${stroke}` }, children: [
          jsx('span', { style: { fontSize: 12, color: text.secondary }, children: 'Or just watch:' }),
          ...levels.map(level =>
            jsx('button', {
              type: 'button',
              key: `watch-${level.id}`,
              'data-testid': `petb-watch-level-${level.id}`,
              onClick: () => { setWatchLevel(level.id); onWatch(level.id) },
              disabled: busy,
              style: {
                padding: '6px 10px', borderRadius: 999,
                border: `1px solid ${watchLevel === level.id ? accent : stroke}`,
                background: watchLevel === level.id ? `${accent}1c` : 'transparent',
                color: text.secondary, cursor: busy ? 'default' : 'pointer', fontSize: 12
              },
              children: level.label
            }, `watch-${level.id}`)),
          button('Watch two computer teams', () => onWatch(watchLevel), { disabled: busy })
        ] })
      ] }),
      petdexNote(petdex),
      notice ? jsx('div', { role: 'status', style: { fontSize: 12, color: text.secondary }, children: notice }) : null
    ]
  })
}

// ---- 48-playbook.js: the champion's playbook, its Hermes pet, and the Bot Passport card
// A champion is a pet's body playing a written brain. The brain is a "playbook": a
// read checklist, tactics, one scout rule and a voice, all in plain words with caps
// the server enforces. The body is the person's own installed Hermes pet, drawn from
// Hermes's own pet cells. We never copy a pet file into this plugin: we ask the
// gateway for its cells and draw the half-blocks it hands back.

// The seven states a Hermes pet animates through, and what each one means at a table.
const PET_GAME_STATES = [
  { id: 'idle', label: 'Idle', use: 'At the table with nothing to answer.' },
  { id: 'wave', label: 'Wave', use: 'A taunt before the match, or after a good move.' },
  { id: 'run', label: 'Run', use: 'Charging a line of play.' },
  { id: 'jump', label: 'Jump', use: 'The attack, and the win.' },
  { id: 'failed', label: 'Failed', use: 'Taking a hit, and the loss.' },
  { id: 'review', label: 'Review', use: 'Thinking about the next move.' },
  { id: 'waiting', label: 'Waiting', use: 'The other side is to move.' }
]

// One place that turns what is happening into a pet state, so the mapping stays honest.

// What a state is called out loud, so a caption never reads like a machine code.
function petStateLabel(state) {
  const named = {
    idle: 'Ready', wave: 'Taunt', run: 'Pressing', jump: 'Won',
    failed: 'Lost', review: 'Thinking', waiting: 'Your turn'
  }
  return named[String(state || '').toLowerCase()] || 'Ready'
}

// The editor counts words the way the server does: runs of non-space characters.
function wordCount(value) {
  const text = String(value == null ? '' : value).trim()
  return text ? text.split(/\s+/).length : 0
}

function playbookWords(draft) {
  const rows = draft || {}
  const read = (Array.isArray(rows.read) ? rows.read : []).reduce((total, line) => total + wordCount(line), 0)
  const tactics = (Array.isArray(rows.tactics) ? rows.tactics : []).reduce((total, line) => total + wordCount(line), 0)
  const scout = wordCount(rows.scout)
  const voice = wordCount(rows.voice)
  return { read, tactics, scout, voice, total: read + tactics + scout + voice }
}

// The server names its caps in Python constants; this is the one place that maps them.
function playbookLimits(limits) {
  const raw = limits || {}
  const pick = (...names) => {
    for (const name of names) {
      const value = Number(raw[name])
      if (Number.isFinite(value) && value > 0) return value
    }
    return 0
  }
  return {
    total: pick('cap_total_words', 'total') || 250,
    readQuestions: pick('cap_read_questions', 'read_questions') || 3,
    minReadQuestions: pick('min_read_questions') || 2,
    readQuestion: pick('cap_read_question_words', 'read_question') || 20,
    tactics: pick('cap_tactics', 'tactics') || 4,
    tactic: pick('cap_tactic_words', 'tactic') || 40,
    scout: pick('cap_scout_words', 'scout') || 40,
    voice: pick('cap_voice_words', 'voice') || 40,
    dossier: pick('max_dossier_words') || 80
  }
}

// A saved version carries its word counts either as a number or as the counted block.
function versionWords(version) {
  const words = version && version.words
  if (typeof words === 'number') return words
  if (words && typeof words.total === 'number') return words.total
  return 0
}

// Hermes hands a pet over as half-block cells: [tr,tg,tb,ta, br,bg,bb,ba]. Two pixels in
// one character cell, so the top half is one colour and the bottom half the other.
function petCellStyle(cell) {
  const [tr, tg, tb, ta, br, bg, bb, ba] = cell
  const alpha = value => Math.max(0, Math.min(255, Number(value) || 0)) / 255
  const top = `rgba(${tr || 0},${tg || 0},${tb || 0},${alpha(ta).toFixed(3)})`
  const bottom = `rgba(${br || 0},${bg || 0},${bb || 0},${alpha(ba).toFixed(3)})`
  return { background: `linear-gradient(to bottom, ${top} 0 50%, ${bottom} 50% 100%)` }
}

// Our own small figure, drawn here rather than downloaded: it stands in when this Hermes
// has no pet support or the person has not adopted a pet yet. Three shapes, theme colours.
function CritterFallback({ state = 'idle', size = 72 }) {
  const body = state === 'failed' || state === 'loss' ? 'var(--ui-text-tertiary)' : accent
  const hop = state === 'jump' || state === 'win' ? -0.06 : 0
  return jsx('svg', {
    width: size, height: Math.round(size * 0.9), viewBox: '0 0 40 36', role: 'img',
    'aria-label': `Placeholder champion figure (${state})`,
    style: { display: 'block', transform: `translateY(${hop * size}px)` },
    children: jsxs('g', { children: [
      jsx('rect', { x: 8, y: 10, width: 24, height: 20, rx: 8, fill: body, opacity: 0.85 }),
      jsx('circle', { cx: 16, cy: 19, r: 2.4, fill: 'var(--ui-bg-solid, #101820)' }),
      jsx('circle', { cx: 24, cy: 19, r: 2.4, fill: 'var(--ui-bg-solid, #101820)' }),
      jsx('rect', { x: 11, y: 6, width: 4, height: 7, rx: 2, fill: body, opacity: 0.6 }),
      jsx('rect', { x: 25, y: 6, width: 4, height: 7, rx: 2, fill: body, opacity: 0.6 })
    ] })
  })
}

// The champion's body: the person's own Hermes pet, in one of the seven game states.
// Frames come from the gateway (GET /pet/cells) and are drawn as a grid of half-block cells.
function PetSprite({ ctx, pet, state = 'idle', size = 72, cols = 24, caption = '' }) {
  const [frames, setFrames] = useState([])
  const [frameMs, setFrameMs] = useState(1100)
  const [frame, setFrame] = useState(0)
  const [missing, setMissing] = useState(!(pet && pet.enabled))
  const cache = useRef({})
  const slug = (pet && pet.slug) || ''
  const shown = PET_GAME_STATES.some(item => item.id === state) ? state : 'idle'

  useEffect(() => {
    setMissing(!(pet && pet.enabled))
  }, [pet && pet.enabled, slug])

  useEffect(() => {
    if (!ctx || !pet || !pet.enabled || !slug) return undefined
    let live = true
    const key = `${slug}:${shown}:${cols}`
    const cached = cache.current[key]
    if (cached) { setFrames(cached.frames); setFrameMs(cached.frameMs); setFrame(0); return undefined }
    const read = async () => {
      try {
        // The sanctioned door first: the desktop host's gateway JSON-RPC, the same
        // pet.cells the Hermes app itself draws with. The plugin route below is the
        // fallback for a host without it (and for the browser preview).
        const request = host && typeof host.request === 'function' ? host.request : null
        let answer = null
        if (request) {
          try {
            answer = await request('pet.cells', { state: shown, cols })
          } catch (failure) {
            answer = null
          }
        }
        if (!answer || !answer.enabled) answer = await ctx.rest(`/pet/cells?state=${encodeURIComponent(shown)}&cols=${cols}`)
        if (!live) return
        if (answer && answer.enabled && Array.isArray(answer.frames) && answer.frames.length) {
          cache.current[key] = { frames: answer.frames, frameMs: Number(answer.frameMs) || 1100 }
          setFrames(answer.frames)
          setFrameMs(Number(answer.frameMs) || 1100)
          setFrame(0)
          setMissing(false)
        } else {
          setMissing(true)
        }
      } catch (failure) {
        if (live) setMissing(true)
      }
    }
    read()
    return () => { live = false }
  }, [ctx, slug, shown, cols, pet && pet.enabled])

  useEffect(() => {
    if (frames.length <= 1) return undefined
    const timer = setInterval(() => setFrame(current => (current + 1) % frames.length), Math.max(90, frameMs))
    return () => clearInterval(timer)
  }, [frames, frameMs])

  const grid = frames.length ? frames[Math.min(frame, frames.length - 1)] : []
  const cell = Math.max(2, Math.round(size / Math.max(1, cols)))
  const height = grid.length ? grid.length * cell : Math.round(size * 0.9)
  return jsxs('div', {
    style: { display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 4 },
    children: [
      grid.length && !missing
        ? jsx('div', {
          role: 'img',
          'aria-label': `${(pet && pet.displayName) || 'Hermes pet'}, ${shown}`,
          style: {
            width: cols * cell, height, display: 'grid',
            gridTemplateColumns: `repeat(${cols}, ${cell}px)`, gridAutoRows: `${cell}px`
          },
          children: grid.flatMap((row, y) => row.map((value, x) => jsx('div', {
            key: `${y}-${x}`, style: { width: cell, height: cell, ...petCellStyle(value) }
          })))
        })
        : jsx(CritterFallback, { state: shown, size }),
      caption ? jsx('div', { style: { fontSize: 12, color: text.tertiary }, children: caption }) : null
    ]
  })
}

// One capped box of plain text with its own word counter.
function PlaybookField({ label, hint, value, onChange, words, cap, rows = 2, placeholder, blockSpace = false }) {
  const over = words > cap
  return jsxs('label', {
    style: { display: 'flex', flexDirection: 'column', gap: 4 },
    children: [
      jsxs('div', { style: { display: 'flex', justifyContent: 'space-between', gap: 8, alignItems: 'baseline' }, children: [
        jsx('span', { style: { fontSize: 12, color: text.secondary, fontWeight: 600 }, children: label }),
        jsx('span', {
          style: { fontSize: 12, color: over ? 'var(--ui-warning, #d9a441)' : text.secondary, whiteSpace: 'nowrap' },
          children: `${words} / ${cap} words`
        })
      ] }),
      jsx('textarea', {
        value,
        rows,
        placeholder,
        'aria-label': label,
        onChange: event => onChange(event.target.value),
        // A new word cannot be started once the field or the whole playbook is at its cap.
        // Text pasted over the cap still lands, and then saving is refused with a sentence.
        onKeyDown: event => {
          if (blockSpace && event.key === ' ') event.preventDefault()
        },
        style: {
          width: '100%', boxSizing: 'border-box', padding: '8px 10px', borderRadius: 8,
          border: `1px solid ${over ? 'var(--ui-warning, #d9a441)' : stroke}`,
          background: 'transparent', color: 'inherit', fontSize: 12.5, fontFamily: 'inherit',
          resize: 'vertical', lineHeight: 1.4
        }
      }),
      hint ? jsx('span', { style: { fontSize: 12, color: text.tertiary }, children: hint }) : null
    ]
  })
}

// The playbook editor: plain text, live counters, hard caps, versions, and a sparring game.
function PlaybookEditor({ ctx, champion, limits, pet, onClose, onChanged }) {
  const caps = playbookLimits(limits)
  const empty = { read: ['', ''], tactics: [''], scout: '', voice: '' }
  const [draft, setDraft] = useState(empty)
  const [name, setName] = useState('')
  const [versions, setVersions] = useState([])
  const [current, setCurrent] = useState(null)
  const [note, setNote] = useState('')
  const [error, setError] = useState('')
  const [busy, setBusy] = useState(false)
  const [spar, setSpar] = useState(null)
  const [sparId, setSparId] = useState('')
  const alive = useRef(true)

  const load = useCallback(async () => {
    try {
      const answer = await ctx.rest(`/playbook?champion=${encodeURIComponent(champion.id)}`)
      if (!alive.current) return
      if (answer && answer.ok) {
        setVersions(answer.versions || [])
        const chosen = answer.current
        setCurrent(chosen || null)
        if (chosen && chosen.playbook) {
          setDraft({
            read: chosen.playbook.read && chosen.playbook.read.length ? chosen.playbook.read : ['', ''],
            tactics: chosen.playbook.tactics && chosen.playbook.tactics.length ? chosen.playbook.tactics : [''],
            scout: chosen.playbook.scout || '',
            voice: chosen.playbook.voice || ''
          })
          setName(chosen.name || '')
        }
      } else {
        setError((answer && answer.text) || 'The playbook could not be read.')
      }
    } catch (failure) {
      if (alive.current) setError(failure.message || 'The playbook could not be read.')
    }
  }, [ctx, champion.id])

  useEffect(() => {
    alive.current = true
    load()
    return () => { alive.current = false }
  }, [load])

  // The sparring game runs on the backend; this asks it how it is going.
  useEffect(() => {
    if (!sparId) return undefined
    let live = true
    const timer = setInterval(async () => {
      try {
        const answer = await ctx.rest(`/playbook/test?id=${encodeURIComponent(sparId)}`)
        if (!live || !alive.current) return
        if (answer && answer.ok) {
          setSpar(answer)
          if (answer.status !== 'running') { setSparId(''); onChanged && onChanged() }
        }
      } catch (failure) {
        if (live && alive.current) setError(failure.message || 'The test game could not be read.')
      }
    }, 1200)
    return () => { live = false; clearInterval(timer) }
  }, [sparId, ctx, onChanged])

  const counts = playbookWords(draft)
  const capTotal = caps.total
  const capRead = caps.readQuestion
  const capTactic = caps.tactic
  const capScout = caps.scout
  const capVoice = caps.voice
  const maxRead = caps.readQuestions
  const maxTactics = caps.tactics
  const readOver = (draft.read || []).some(line => wordCount(line) > capRead)
  const tacticsOver = (draft.tactics || []).some(line => wordCount(line) > capTactic)
  const over = counts.total > capTotal || readOver || tacticsOver
  const emptyPlaybook = counts.total === 0
  const canSave = !over && !busy && !emptyPlaybook
  const state = spar && spar.status === 'running' ? 'review' : spar && spar.winner === 'champion' ? 'jump' : spar && spar.winner === 'house' ? 'failed' : 'idle'

  const setLine = (key, index, value) => setDraft(currentDraft => {
    const rows = [...(currentDraft[key] || [])]
    rows[index] = value
    return { ...currentDraft, [key]: rows }
  })
  const addLine = key => setDraft(currentDraft => {
    const rows = [...(currentDraft[key] || [])]
    if (rows.length >= (key === 'read' ? maxRead : maxTactics)) return currentDraft
    return { ...currentDraft, [key]: [...rows, ''] }
  })
  const dropLine = (key, index) => setDraft(currentDraft => {
    const rows = (currentDraft[key] || []).filter((_row, at) => at !== index)
    const floor = key === 'read' ? 2 : 1
    return { ...currentDraft, [key]: rows.length >= floor ? rows : [...rows, ''] }
  })

  const save = async () => {
    setBusy(true)
    setError('')
    try {
      const answer = await ctx.rest('/playbook/save', {
        method: 'POST',
        body: { champion: champion.id, name: name.trim(), playbook: draft }
      })
      if (answer && answer.ok) {
        setNote(answer.text || 'Version saved.')
        setCurrent(answer.version || null)
        await load()
        onChanged && onChanged()
      } else {
        setError((answer && answer.text) || 'That version could not be saved.')
      }
    } catch (failure) {
      setError(failure.message || 'That version could not be saved.')
    } finally {
      if (alive.current) setBusy(false)
    }
  }

  const openVersion = async version => {
    if (!version || !version.id) return
    try {
      const answer = await ctx.rest('/playbook/select', {
        method: 'POST', body: { champion: champion.id, version: version.id }
      })
      if (answer && answer.ok) {
        setNote(`Now playing ${version.name}.`)
        await load()
        onChanged && onChanged()
      } else {
        setError((answer && answer.text) || 'That version could not be opened.')
      }
    } catch (failure) {
      setError(failure.message || 'That version could not be opened.')
    }
  }

  const test = async () => {
    setError('')
    setSpar(null)
    try {
      const answer = await ctx.rest('/playbook/test', {
        method: 'POST', body: { champion: champion.id, game: 'connect4' }
      })
      if (answer && answer.ok && (answer.id || (answer.test && answer.test.id))) {
        setSparId(answer.id || answer.test.id)
        setSpar({ status: 'running', moves: [], reads: [], game: 'connect4' })
      } else {
        setError((answer && answer.text) || 'The test game could not start.')
      }
    } catch (failure) {
      setError(failure.message || 'The test game could not start.')
    }
  }

  const totalColour = counts.total > capTotal ? 'var(--ui-warning, #d9a441)' : text.tertiary
  const readRows = draft.read || []
  const tacticRows = draft.tactics || []

  return jsxs('div', {
    style: { display: 'flex', flexDirection: 'column', gap: 12 },
    children: [
      jsxs('div', { style: { display: 'flex', gap: 12, alignItems: 'center', paddingBottom: 10, borderBottom: `1px solid ${stroke}`, flexWrap: 'wrap' }, children: [
        jsx(PetSprite, { ctx, pet, state, size: 56, caption: petStateLabel(state) }),
        jsxs('div', { style: { minWidth: 0 }, children: [
          jsx('div', { style: { fontFamily: DISPLAY_FONT, fontSize: 22, lineHeight: 1.15, letterSpacing: '-.015em', fontWeight: 600 }, children: `Playbook · ${champion.name}` }),
          jsx('div', { style: { fontSize: 12, color: text.tertiary }, children: current ? `Playing ${current.name} · ${counts.total} of ${capTotal} words in the box` : 'No version saved yet. The box below is the whole brain.' })
        ] }),
        jsx('div', { style: { marginLeft: 'auto', display: 'flex', gap: 6 }, children: button('Back to champions', onClose) })
      ] }),
      jsxs('div', {
        style: { borderRadius: 14, padding: 16, background: card, display: 'flex', flexDirection: 'column', gap: 12 },
        children: [
          jsxs('div', { style: { display: 'flex', gap: 10, alignItems: 'flex-end', flexWrap: 'wrap' }, children: [
            jsxs('label', { style: { display: 'flex', flexDirection: 'column', gap: 4, flex: 1, minWidth: 200 }, children: [
              jsx('span', { style: { fontSize: 12, color: text.secondary, fontWeight: 600 }, children: 'Version name' }),
              jsx('input', {
                value: name,
                placeholder: 'Patient wall v3',
                'aria-label': 'Version name',
                onChange: event => setName(event.target.value),
                style: { padding: '7px 10px', borderRadius: 8, border: `1px solid ${stroke}`, background: 'transparent', color: 'inherit', fontSize: 12.5 }
              })
            ] }),
            jsxs('div', { style: { fontSize: 12, color: totalColour, textAlign: 'right', minWidth: 170 }, children: [
              jsx('div', { style: { fontSize: 12, color: text.tertiary }, children: 'Playbook total' }),
              jsx('div', { style: { fontWeight: 700, fontSize: 14 }, children: `${counts.total} / ${capTotal} words` }),
              jsx('div', { children: over
                ? `Over the cap by ${counts.total - capTotal}. Shorten a line before saving.`
                : counts.total >= capTotal - 25 ? `Near the word limit (${capTotal - counts.total} words left).`
                  : 'Read, tactics, scout and voice together.' })
            ] })
          ] }),
          jsxs('div', { style: { display: 'flex', flexDirection: 'column', gap: 8 }, children: [
            jsxs('div', { style: { display: 'flex', justifyContent: 'space-between', alignItems: 'baseline', gap: 8 }, children: [
              jsx('div', { style: { fontSize: 12, color: text.secondary, fontWeight: 600 }, children: `Read checklist — ${readRows.length} of ${maxRead} questions` }),
              readRows.length < maxRead ? button('Add a question', () => addLine('read')) : null
            ] }),
            jsx('div', { style: { fontSize: 12, color: text.tertiary }, children: 'The bot answers these privately before every move. Two questions are enough; three is the most.' }),
            ...readRows.map((line, index) => jsxs('div', { key: `read-${index}`, style: { display: 'flex', gap: 6, alignItems: 'flex-start' }, children: [
              jsx('div', { style: { flex: 1 }, children: jsx(PlaybookField, {
                label: `Question ${index + 1}`,
                value: line,
                rows: 2,
                cap: capRead,
                words: wordCount(line),
                blockSpace: wordCount(line) >= capRead || counts.total >= capTotal,
                placeholder: index === 0 ? 'What does their last move leave undefended?' : 'What is the cheapest way to make them answer?',
                onChange: value => setLine('read', index, value)
              }) }),
              readRows.length > 2 ? button('Remove', () => dropLine('read', index)) : null
            ] }))
          ] }),
          jsxs('div', { style: { display: 'flex', flexDirection: 'column', gap: 8, borderTop: `1px solid ${stroke}`, paddingTop: 10 }, children: [
            jsxs('div', { style: { display: 'flex', justifyContent: 'space-between', alignItems: 'baseline', gap: 8 }, children: [
              jsx('div', { style: { fontSize: 12, color: text.secondary, fontWeight: 600 }, children: `Tactics — ${tacticRows.length} of ${maxTactics} rules` }),
              tacticRows.length < maxTactics ? button('Add a rule', () => addLine('tactics')) : null
            ] }),
            jsx('div', { style: { fontSize: 12, color: text.tertiary }, children: 'Write each rule as if this, then that. Four rules is the most; 40 words each.' }),
            ...tacticRows.map((line, index) => jsxs('div', { key: `tactic-${index}`, style: { display: 'flex', gap: 6, alignItems: 'flex-start' }, children: [
              jsx('div', { style: { flex: 1 }, children: jsx(PlaybookField, {
                label: `Rule ${index + 1}`,
                value: line,
                rows: 2,
                cap: capTactic,
                words: wordCount(line),
                blockSpace: wordCount(line) >= capTactic || counts.total >= capTotal,
                placeholder: index === 0 ? 'If they stack one column, then open the other side and keep the trade even.' : 'If a trade is offered, then take it only when it wins a tempo.',
                onChange: value => setLine('tactics', index, value)
              }) }),
              tacticRows.length > 1 ? button('Remove', () => dropLine('tactics', index)) : null
            ] }))
          ] }),
          jsxs('div', { style: { display: 'flex', gap: 10, flexWrap: 'wrap', borderTop: `1px solid ${stroke}`, paddingTop: 10 }, children: [
            jsx('div', { style: { flex: 1, minWidth: 220 }, children: jsx(PlaybookField, {
              label: 'Scout rule',
              hint: 'After each match the bot writes up to 80 words about that rival, from this rule.',
              value: draft.scout,
              cap: capScout,
              words: counts.scout,
              blockSpace: counts.scout >= capScout || counts.total >= capTotal,
              rows: 2,
              placeholder: 'Note what they do when they are behind, and which side they always open.',
              onChange: value => setDraft(currentDraft => ({ ...currentDraft, scout: value }))
            }) }),
            jsx('div', { style: { flex: 1, minWidth: 220 }, children: jsx(PlaybookField, {
              label: 'Voice',
              hint: 'How it talks in public chat: short, plain, no insults.',
              value: draft.voice,
              cap: capVoice,
              words: counts.voice,
              blockSpace: counts.voice >= capVoice || counts.total >= capTotal,
              rows: 2,
              placeholder: 'Dry, brief, gives credit when it loses.',
              onChange: value => setDraft(currentDraft => ({ ...currentDraft, voice: value }))
            }) })
          ] }),
          over ? jsx('div', {
            role: 'alert',
            style: { fontSize: 12, color: 'var(--ui-warning, #d9a441)' },
            children: counts.total > capTotal
              ? `This playbook is ${counts.total} words. The cap is ${capTotal}.`
              : 'One line is over its own cap. Shorten it to save.'
          }) : null,
          error ? jsx('div', { role: 'alert', style: { fontSize: 12, color: 'var(--ui-text-primary, inherit)' }, children: error }) : null,
          note ? jsx('div', { role: 'status', style: { fontSize: 12, color: text.secondary }, children: note }) : null,
          jsxs('div', { style: { display: 'flex', gap: 6, flexWrap: 'wrap', alignItems: 'center' }, children: [
            button('Save as a new version', save, { primary: true, disabled: !canSave }),
            button(sparId ? 'Testing…' : 'Test vs house bot', test, { disabled: Boolean(sparId) || !current }),
            jsx('span', { style: { fontSize: 12, color: text.tertiary }, children: current
              ? 'The test plays the saved version against the built-in computer.'
              : 'Save a version first: the test plays the saved version.' })
          ] })
        ]
      }),
      versions.length ? jsxs('div', { style: { display: 'flex', flexDirection: 'column', gap: 6 }, children: [
        jsx('div', { style: { fontSize: 12, color: text.secondary, fontWeight: 600 }, children: 'Saved versions' }),
        jsxs('div', { style: { display: 'flex', gap: 6, flexWrap: 'wrap' }, children: versions.map(version => button(
          `${current && current.id === version.id ? '● ' : ''}${version.name} · ${versionWords(version)} words`,
          () => openVersion(version),
          { primary: Boolean(current && current.id === version.id) }
        )) })
      ] }) : null,
      spar ? jsxs('div', {
        'data-spar': 'result',
        style: { border: `1px solid ${stroke}`, borderRadius: 16, padding: 14, background: card, display: 'flex', gap: 12, alignItems: 'flex-start' },
        children: [
          jsx(PetSprite, { ctx, pet, state, size: 64, caption: petStateLabel(state) }),
          jsxs('div', { style: { display: 'flex', flexDirection: 'column', gap: 6, minWidth: 0, flex: 1 }, children: [
            jsx('div', { style: { fontSize: 12, letterSpacing: '0.1em', textTransform: 'uppercase', color: text.tertiary }, children: 'Test result' }),
            jsx('div', { style: { fontWeight: 700, fontSize: 14 }, children: spar.status === 'running'
              ? 'Playing the house computer…'
              : spar.winner === 'champion' ? 'The champion won.' : spar.winner === 'house' ? 'The house computer won.' : 'Drawn.' }),
            jsx('div', { style: { fontSize: 12, color: text.secondary }, children: `Moves: ${(spar.moves || []).join(' ') || 'none yet'}` }),
            (spar.reads || []).length ? jsxs('div', { style: { fontSize: 12, color: text.secondary }, children: [
              jsx('div', { style: { color: text.tertiary, fontSize: 12 }, children: 'Its private read, last move' }),
              ...(spar.reads || []).map((line, index) => jsx('div', { key: index, style: { fontStyle: 'italic' }, children: `“${line}”` }))
            ] }) : null,
            spar.text ? jsx('div', { style: { fontSize: 12, color: text.tertiary }, children: spar.text }) : null
          ] })
        ]
      }) : null
    ]
  })
}

// The Bot Passport: one champion's public identity — its pet, the playbook it plays, its record.
function PassportCard({ ctx, champion, avatars, colors, pet, badges: earned, onEdit, onOpenPlaybook, actions }) {
  const [dossiers, setDossiers] = useState(null)
  const [wave, setWave] = useState(false)
  const colour = (colors || []).find(item => item.id === champion.color) || { hex: '#d9a441' }
  const today = champion.playbook || null
  const records = champion.record_by_version || null
  const record = (champion.record || {})
  const rows = champion.dossiers || []
  const scouted = rows.reduce((total, row) => total + (Number(row.matches) || 0), 0)
  const line = today ? `Playbook: ${today.name} · ${versionWords(today)} words` : 'No playbook yet: it plays from its brief.'
  return jsxs('div', {
    'data-passport': champion.id,
    style: { borderRadius: 14, padding: 14, background: card, display: 'flex', flexDirection: 'column', gap: 10, minHeight: 196 },
    children: [
      jsxs('div', { style: { display: 'flex', gap: 12, alignItems: 'center' }, children: [
        jsx('button', {
          type: 'button',
          title: 'Say hello',
          'aria-label': `${champion.name}'s pet`,
          onClick: () => { setWave(true); setTimeout(() => setWave(false), 1300) },
          style: { background: 'transparent', border: 0, padding: 0, cursor: 'pointer', borderRadius: 8 },
          children: jsx(PetSprite, { ctx, pet, state: wave ? 'wave' : 'idle', size: 58 })
        }),
        jsxs('div', { style: { minWidth: 0, flex: 1 }, children: [
          jsx('div', { style: { fontFamily: DISPLAY_FONT, fontSize: 18, lineHeight: 1.2, letterSpacing: '-.01em', fontWeight: 600 }, children: champion.name }),
          jsx('div', { style: { fontSize: 12, color: text.tertiary }, children: champion.motto || 'No motto' })
        ] }),
        jsxs('div', { style: { textAlign: 'right' }, children: [
          jsx('div', { style: { fontSize: 12, letterSpacing: '.09em', textTransform: 'uppercase', color: text.tertiary }, children: 'Elo' }),
          jsx('div', { style: { ...TABULAR, fontSize: 18, fontWeight: 600, lineHeight: 1.1 }, children: Math.round(record.rating || 1500) })
        ] })
      ] }),
      jsxs('div', { style: { display: 'flex', flexDirection: 'column', gap: 3, borderTop: `1px solid ${stroke}`, paddingTop: 8 }, children: [
        jsx('div', { style: { fontSize: 12, color: text.secondary }, children: line }),
        jsx('div', { style: { fontSize: 12, color: text.tertiary }, children: `From ${colour.id}: its colour. W ${record.wins || 0} · L ${record.losses || 0} · D ${record.draws || 0}${records ? ` · this version ${records.wins || 0}-${records.losses || 0}-${records.draws || 0}` : ''}` })
      ] }),
      (earned || []).length ? jsx('div', { style: { display: 'flex', gap: 4, flexWrap: 'wrap' }, children: (earned || []).map(name => badge(String(name).replace('_', ' '))) }) : null,
      jsxs('div', { style: { display: 'flex', gap: 6, flexWrap: 'wrap', alignItems: 'center' }, children: [
        button(today ? 'Open playbook' : 'Write a playbook', onOpenPlaybook, { primary: !today }),
        rows.length ? button(`${rows.length} rival${rows.length === 1 ? '' : 's'} scouted`, () => setDossiers(dossiers ? null : rows)) : jsx('span', { style: { fontSize: 12, color: text.tertiary }, children: 'No rivals scouted yet' })
      ] }),
      dossiers ? jsxs('div', {
        style: { borderTop: `1px solid ${stroke}`, paddingTop: 8, display: 'flex', flexDirection: 'column', gap: 6 },
        children: rows.map((row, index) => jsxs('div', { key: index, style: { fontSize: 12, color: text.secondary }, children: [
          jsx('div', { style: { fontWeight: 600, color: text.primary }, children: `${row.opponent_name || row.opponent} · ${row.matches || 0} match${(row.matches || 0) === 1 ? '' : 'es'}` }),
          jsx('div', { children: row.text || `${row.wins || 0} won, ${row.losses || 0} lost, ${row.draws || 0} drawn.` })
        ] }))
      }) : null,
      scouted ? jsx('div', { style: { fontSize: 12, color: text.tertiary }, children: `Scout notes cover ${scouted} match${scouted === 1 ? '' : 'es'}.` }) : null,
      jsxs('div', { style: { display: 'flex', gap: 6, flexWrap: 'wrap', marginTop: 'auto' }, children: actions })
    ]
  })
}

// ---- 49-mafia-town.js: Mafia Town, the talking-table Mafia drawn as a place ----
//
// A skin, not a second game: the picture and every command are the classic table's
// (`mafia …`), only the drawing changes. The town square darkens at night, dawn names
// who is gone, speech bubbles carry the day's talk, and a vote is one click on a
// portrait. Watching a town of bots is the same scene with the buttons at rest.

// Pure helpers first: the UI harness asserts on these without a browser.

// Which scene to draw. The picture's phase line is English ("Night 2 · the table
// sleeps"), so this reads the words, not a field only the table knows.
function townPhaseOf(label, status) {
  if (status === 'done') return 'done'
  const word = String(label || '')
  if (!word || word === 'Not started') return 'setup'
  if (word.indexOf('Night') === 0) return 'night'
  if (word.indexOf('voting') >= 0) return 'vote'
  if (word.indexOf('talking') >= 0) return 'talk'
  return 'day'
}

// The latest thing each seat said. Only day talk shows bubbles; the map is keyed by
// the name the log row carries, which is the name the seat shows.
function townBubbles(places, log) {
  const said = {}
  ;(Array.isArray(log) ? log : []).forEach(row => {
    if (!row || row.kind !== 'say' || !row.name) return
    const text = String(row.text || '').slice(0, 90)
    if (text) said[row.name] = text
  })
  const bubbles = {}
  ;(Array.isArray(places) ? places : []).forEach(place => {
    if (place && place.name && said[place.name]) bubbles[place.seat] = said[place.name]
  })
  return bubbles
}

// The one action word this phase's buttons share ('vote', 'eliminate', …), or ''.
function townVerbOf(actions) {
  const first = (Array.isArray(actions) && actions[0] && actions[0].id) || ''
  const dash = String(first).indexOf('-')
  return dash > 0 ? String(first).slice(0, dash) : ''
}

// Seats that are gone now but were not a moment ago: the dawn list and the dust.
function townNewlyOut(prevOut, places) {
  const before = new Set(Array.isArray(prevOut) ? prevOut : [])
  const now = []
  ;(Array.isArray(places) ? places : []).forEach(place => {
    if (place && place.out && !before.has(place.seat)) now.push(place.seat)
  })
  return now
}

