function MafiaTown({ game, view, board, send, refresh, ctx, onBack, onClassic }) {
  const [busy, setBusy] = useState(false)
  const [failure, setFailure] = useState('')
  const [notice, setNotice] = useState('')
  const [message, setMessage] = useState('')
  const [seats, setSeats] = useState(0)
  const [agent, setAgent] = useState(false)
  const [champions, setChampions] = useState([])
  const [dawn, setDawn] = useState(null)
  const [puff, setPuff] = useState([])
  const [roles, setRoles] = useState({})
  const latest = useRef(null)
  const seen = useRef({ phase: '', out: [], gone: [] })
  const alive = useRef(true)
  useEffect(() => {
    alive.current = true
    return () => { alive.current = false }
  }, [])
  const pictured = (board && board.picture) || null
  useEffect(() => {
    if (!pictured || !pictured.preview) return
    setSeats(Number((pictured.limits && pictured.limits.default) || 6))
  }, [game.id])
  const run = async line => {
    if (busy || !alive.current) return false
    setBusy(true)
    setFailure('')
    try {
      const answer = await send(line)
      if (answer && answer.ok === false) throw new Error(answer.text || 'The town refused that.')
      if (alive.current) setNotice((answer && answer.text) || '')
      return true
    } catch (error) {
      if (alive.current) setFailure(error.message || 'That did not reach the town.')
      return false
    } finally {
      if (alive.current) setBusy(false)
    }
  }
  const acting = Boolean(pictured && pictured.status === 'active' && pictured.can_step)
  latest.current = { ready: acting, step: () => send(`${game.id} step`) }
  // Machine seats play themselves while the town watches, one turn at a time — the
  // same watcher the classic table uses, so the two skins stay in step.
  useEffect(() => {
    if (!acting) return undefined
    return startTableWatch(
      async () => {
        const answer = await latest.current.step()
        if (answer && answer.ok === false) throw new Error(answer.text || 'A seat could not move.')
        return true
      },
      () => latest.current.ready,
      error => { if (alive.current) setFailure(error.message || 'A seat could not move.') }
    )
  }, [acting, game.id])

  const phaseLabel = (pictured && pictured.phase) || ''
  const phase = townPhaseOf(phaseLabel, pictured && pictured.status)
  const places = (pictured && pictured.places) || []
  const log = (pictured && pictured.log) || []
  const actions = (pictured && pictured.actions) || []
  const myTurn = Boolean(pictured && pictured.can_move)
  const verb = townVerbOf(myTurn ? actions : [])
  const bubbles = phase === 'talk' ? townBubbles(places, log) : {}

  // Night, death and dawn, all read off the diff between this picture and the last.
  useEffect(() => {
    if (!pictured || pictured.preview) return undefined
    const seenBefore = seen.current
    const outNow = places.filter(place => place.out).map(place => place.seat)
    const fresh = townNewlyOut(seenBefore.out, places)
    const nowPhase = phase
    const wasNight = seenBefore.phase === 'night'
    let gone = seenBefore.gone || []
    if (nowPhase === 'night') gone = Array.from(new Set(gone.concat(fresh)))
    let nextDawn = null
    if (wasNight && (nowPhase === 'talk' || nowPhase === 'vote' || nowPhase === 'day') && gone.length) {
      const names = {}
      places.forEach(place => { names[place.seat] = place.name })
      nextDawn = {
        day: (pictured.phase || '').match(/Day (\d+)/) && RegExp.$1,
        gone: gone.map(seat => names[seat] || `Player ${Number(seat) + 1}`).join(', ')
      }
      gone = []
    }
    seen.current = { phase: nowPhase, out: outNow, gone }
    const timers = []
    if (fresh.length) {
      setPuff(fresh)
      timers.push(setTimeout(() => { if (alive.current) setPuff([]) }, 1500))
    }
    if (nextDawn) {
      setDawn(nextDawn)
      timers.push(setTimeout(() => { if (alive.current) setDawn(null) }, 6000))
    }
    return () => timers.forEach(clearTimeout)
  }, [pictured])

  // The reveal puts every role on the table.
  useEffect(() => {
    const reveal = pictured && pictured.reveal
    const map = {}
    ;((reveal && reveal.roles) || []).forEach(row => { map[row.seat] = row.role })
    setRoles(reveal ? map : {})
  }, [pictured && pictured.reveal, pictured && pictured.table_id])

  if (!pictured) {
    return jsx('div', { style: { padding: 18, color: text.tertiary }, children: 'Walking to the square…' })
  }
  if (pictured.status === 'idle' || pictured.preview) {
    const start = () => {
      const parts = [`${game.id} new`, `seats=${seats || ((pictured.limits && pictured.limits.default) || 6)}`]
      if (agent) parts.push('agent=1')
      if (champions.length) parts.push(`champions=${champions.join(',')}`)
      run(parts.join(' '))
    }
    return jsx('div', {
      'data-town': 'mafia-town-setup',
      style: { height: '100%', minHeight: 0, background: paper },
      children: talkSetup({
        game, pictured,
        seats: seats || (pictured.limits && pictured.limits.default) || 6,
        setSeats, agent, setAgent, champions, setChampions, busy, start,
        watch: () => run(`${game.id} new seats=${seats || ((pictured.limits && pictured.limits.default) || 6)} bots=1`),
        back: () => onBack(),
        openShared: async () => true,
        failure,
        aiAllowed: !(view && view.allow_ai === false)
      })
    })
  }

  const done = pictured.status !== 'active'
  const night = phase === 'night'
  const say = () => {
    const line = message.trim()
    if (!line) return
    setMessage('')
    run(`${game.id} say ${line}`)
  }
  const pick = place => {
    if (!myTurn || !verb) return
    const id = `${verb}-${place.env_seat}`
    if (actions.some(item => item.id === id)) run(`${game.id} act ${id}`)
  }
  const targeted = seat => {
    if (!myTurn || !verb) return false
    return actions.some(item => item.id === `${verb}-${seat}`)
  }
  const grave = place => Boolean(place.out)
  const winners = ((pictured.reveal && pictured.reveal.winners) || []).map(Number)
    const mySeat = pictured.your_seat
  const won = mySeat != null && winners.includes(Number(mySeat))
  const verdict = (pictured.reveal && pictured.reveal.reason) || ''
  const statusLine = done
    ? 'The game is over.'
    : night
      ? (myTurn && actions.length
          ? `Your night move: ${String((actions[0] && actions[0].hint) || 'choose').toLowerCase()} — click a portrait.`
          : 'Night. The town sleeps while the roles move.')
      : phase === 'vote' && myTurn
        ? 'Click a portrait to vote them out.'
        : (pictured.watching
            ? `Watching the town · ${pictured.turn_name || 'a seat'} acts…`
            : (myTurn ? 'Your turn.' : `${pictured.turn_name || 'A seat'} is acting…`))

  return jsxs('div', {
    'data-town': 'mafia-town',
    'data-town-phase': phase,
    style: { display: 'flex', flexDirection: 'column', gap: 10, padding: 16, height: '100%', minHeight: 0, background: paper, overflow: 'auto' },
    children: [
      jsxs('div', { style: { display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', gap: 10 }, children: [
        jsxs('div', { children: [
          jsx('div', { style: { fontSize: 20, fontWeight: 700 }, children: 'Mafia Town' }),
          jsx('div', { className: 'games-status', 'data-town-status': 'true', style: { fontSize: 12, color: text.secondary }, children: statusLine })
        ] }),
        jsxs('div', { style: { display: 'flex', gap: 6 }, children: [
          pictured.watching ? jsx('span', { 'data-town-ribbon': 'true', style: {
            fontSize: 11, color: accent, border: `1px solid ${accent}`, borderRadius: 999, padding: '2px 9px'
          }, children: 'Watching' }) : null,
          button('Classic table', () => onClassic && onClassic(), { title: 'The same game on the plain talking table.' }),
          button('New town', () => run(`${game.id} abandon`), { disabled: busy }),
          jsx(LearnButton, { game, ctx }),
          button('Back', onBack)
        ] })
      ] }),
      // The square itself.
      jsxs('div', {
        'data-town-scene': 'true',
        style: {
          position: 'relative', width: '100%', minHeight: 380, aspectRatio: '16 / 9',
          border: `1px solid ${stroke}`, borderRadius: 18, overflow: 'hidden',
          background: night
            ? 'linear-gradient(180deg, rgba(20,32,58,0.9) 0%, rgba(24,34,54,0.7) 40%, var(--ui-fill-tertiary, rgba(127,127,127,0.12)) 100%)'
            : 'linear-gradient(180deg, rgba(255,214,140,0.10) 0%, rgba(255,255,255,0.02) 46%, var(--ui-fill-tertiary, rgba(127,127,127,0.12)) 100%)',
          transition: 'background 1s'
        },
        children: [
          night
            ? TOWN_STARS.map((star, index) => jsx('div', {
                'data-town-star': 'true', 'aria-hidden': 'true',
                style: {
                  position: 'absolute', left: `${star[0]}%`, top: `${star[1]}%`, width: 2, height: 2,
                  borderRadius: 1, background: 'rgba(255,255,255,0.8)'
                }, key: `star-${index}`
              }))
            : null,
          ...TOWN_HOUSES.map((house, index) => jsx(TownHouse, { ...house, night }, `house-${index}`)),
          // The well at the middle of the square.
          jsx('div', { 'data-town-well': 'true', 'aria-hidden': 'true', style: {
            position: 'absolute', left: '50%', top: '52%', transform: 'translate(-50%, -50%)',
            width: '13%', aspectRatio: '2 / 1', borderRadius: '50%',
            border: `3px solid ${stroke}`, background: night ? 'rgba(30,50,80,0.6)' : 'rgba(120,160,200,0.25)'
          } }),
          // Sun or moon.
          jsx('div', { 'data-town-sky': night ? 'moon' : 'sun', 'aria-hidden': 'true', style: {
            position: 'absolute', right: '4%', top: '7%', width: 26, height: 26, borderRadius: 13,
            background: night ? 'rgba(220,228,255,0.85)' : 'rgba(255,206,112,0.9)',
            boxShadow: night ? '0 0 12px rgba(220,228,255,0.6)' : '0 0 12px rgba(255,206,112,0.6)',
            transition: 'background 1s, box-shadow 1s'
          } }),
          phase === 'vote' && myTurn
            ? jsx('div', { 'data-town-hint': 'true', style: {
                position: 'absolute', left: '50%', bottom: 10, transform: 'translateX(-50%)',
                fontSize: 11, color: accent, border: `1px solid ${accent}`, borderRadius: 999,
                padding: '2px 10px', background: card
              }, children: 'Click a player to vote' })
            : null,
          ...places.map(place => jsxs(TownSeat, {
            place, count: places.length, phase, bubble: bubbles[place.seat] || '',
            myTurn, targeted: targeted(place.env_seat), justOut: puff.includes(place.seat),
            grave: grave(place), role: done ? (roles[place.env_seat] || '') : '',
            onPick: pick
          }, `town-seat-${place.seat}`)),
          // Night draws the curtain over everything but the sky's own dark.
          jsx('div', { 'data-town-nightshade': night ? 'true' : 'false', 'aria-hidden': 'true', style: {
            position: 'absolute', inset: 0, pointerEvents: 'none',
            background: 'linear-gradient(180deg, rgba(10,18,38,0.35), rgba(10,18,38,0.55))',
            opacity: night ? 1 : 0, transition: 'opacity 1s'
          } }),
          dawn
            ? jsx('div', { 'data-town-dawn': 'true', role: 'status', style: {
                position: 'absolute', left: 0, right: 0, top: '38%', padding: '10px 16px',
                background: 'linear-gradient(180deg, rgba(255,196,87,0.28), rgba(255,196,87,0.06))',
                borderTop: '1px solid rgba(255,196,87,0.6)', borderBottom: '1px solid rgba(255,196,87,0.6)',
                textAlign: 'center', fontSize: 14, fontWeight: 700, color: text.primary,
                animation: 'townDawn 1s ease-out'
              }, children: `Dawn — ${dawn.gone} is gone` })
            : null,
          // The result, laid over the town so the last frame stays visible behind it.
          done
            ? jsxs('div', { 'data-town-over': 'true', role: 'dialog', 'aria-label': 'Game over', style: {
                position: 'absolute', inset: 0, display: 'grid', placeItems: 'center',
                background: 'rgba(8,12,20,0.72)'
              }, children: [
                jsxs('div', { style: { textAlign: 'center', padding: 22, border: `1px solid ${stroke}`, borderRadius: 16, background: card, minWidth: 280 }, children: [
                  jsx('div', { 'data-town-verdict': 'true', style: { fontSize: 20, fontWeight: 700, marginBottom: 4 }, children:
                    mySeat != null ? (won ? 'You won' : 'You lost') : 'The game is over' }),
                  jsx('div', { style: { fontSize: 13, color: text.secondary, marginBottom: 12 }, children: verdict }),
                  jsx('div', { style: { display: 'flex', gap: 8, justifyContent: 'center', flexWrap: 'wrap' }, children: [
                    button('Play again', () => run(`${game.id} rematch`), { primary: true, disabled: busy }),
                    button('Classic table', () => onClassic && onClassic()),
                    button('Back', onBack)
                  ] })
                ] })
              ] })
            : null
        ]
      }),
      // The day's talk, and the one line this seat may say.
      !done
        ? jsxs('div', { style: { display: 'flex', gap: 6, alignItems: 'center' }, children: [
            jsx('input', {
              value: message,
              placeholder: pictured.can_say ? 'Say something to the town' : 'You can talk when the day talks and it is your turn',
              disabled: !pictured.can_say,
              maxLength: 200,
              onChange: event => setMessage(event.target.value),
              onKeyDown: event => { if (event.key === 'Enter' && pictured.can_say) say() },
              'data-town-say': 'true',
              style: { flex: 1, minWidth: 0, padding: '8px 10px', borderRadius: 8, border: `1px solid ${stroke}`, background: 'transparent', color: 'inherit', fontSize: 13, opacity: pictured.can_say ? 1 : 0.6 }
            }),
            button('Say it', say, { primary: true, disabled: !pictured.can_say || !message.trim() || busy })
          ] })
        : null,
      jsx('div', {
        'data-town-log': 'true',
        style: { maxHeight: 130, overflowY: 'auto', border: `1px solid ${stroke}`, borderRadius: 12, background: card, padding: '8px 12px' },
        children: log.length
          ? log.slice(-40).map((row, index) => jsx('div', {
              key: `town-log-${index}`,
              style: { fontSize: 11.5, lineHeight: 1.45, color: row.kind === 'say' ? text.secondary : text.tertiary, fontStyle: row.kind === 'say' ? 'normal' : 'italic' },
              children: row.name ? `${row.name}: ${row.text}` : row.text
            }, index))
          : jsx('div', { style: { fontSize: 11.5, color: text.tertiary }, children: 'Nothing has happened yet.' })
      }),
      notice ? jsx('div', { style: { fontSize: 12, color: text.tertiary }, children: notice }) : null,
      failure ? jsx('div', { role: 'alert', style: { fontSize: 12, color: 'var(--ui-danger, #e06c75)' }, children: failure }) : null,
      jsx('style', { children: `
        @keyframes townPuff { 0% { transform: scale(0.4); opacity: 0.9; } 100% { transform: scale(1.6); opacity: 0; } }
        @keyframes townDawn { 0% { transform: translateY(-14px); opacity: 0; } 100% { transform: translateY(0); opacity: 1; } }
        @media (prefers-reduced-motion: reduce) { [data-town] * { animation: none !important; transition: none !important; } }
      ` })
    ]
  })
}

// ---- 50-champions.js: champions and tournaments
// A champion's body is the person's own Hermes pet (drawn by PetSprite); there is
// no avatar picker and no chess glyph anywhere on this screen. The server still
// carries an `avatar` field on old files, so it is kept and sent unchanged, but it
// is never shown and never chosen.
const EMPTY_CHAMPION = { id: '', name: '', motto: '', avatar: 'knight', color: 'amber', brief: '', model: '', provider: '', created_at: 0 }


function ChampionsPage({ ctx, view }) {
  const [data, setData] = useState(null)
  const [error, setError] = useState('')
  const [notice, setNotice] = useState('')
  const [form, setForm] = useState(EMPTY_CHAMPION)
  const [division, setDivision] = useState('prompt')
  const [picked, setPicked] = useState([])
  const [bots, setBots] = useState([])
  const [games, setGames] = useState([])
  const [seed, setSeed] = useState('1')
  const [capGames, setCapGames] = useState('40')
  const [capCalls, setCapCalls] = useState('240')
  const [run, setRun] = useState(null)
  const [watching, setWatching] = useState(null)
  const [auto, setAuto] = useState(false)
  const [pasted, setPasted] = useState('')
  const [editing, setEditing] = useState('')
  const [spar, setSpar] = useState(null)
  const [routes, setRoutes] = useState([])
  const [showShare, setShowShare] = useState('')
  const alive = useRef(true)
  const pollGen = useRef(0)

  const refresh = useCallback(async () => {
    const gen = ++pollGen.current
    try {
      const next = await ctx.rest('/champions')
      if (!alive.current || gen !== pollGen.current) return null
      if (next && next.ok === false) { setError(next.text || 'Game Center could not read the champions.'); return null }
      setData(next)
      return next
    } catch (failure) {
      if (alive.current) setError(failure.message || 'Champions are waiting on the Hermes gateway. Stay on this page; it retries.')
      return null
    }
  }, [ctx])

  useEffect(() => {
    alive.current = true
    refresh()
    const timer = setInterval(refresh, 5000)
    return () => { alive.current = false; clearInterval(timer) }
  }, [refresh])

  // The model routes this Hermes may hand a champion. Read once: the list only changes
  // when a person edits their config. A host without the route simply offers one chip.
  useEffect(() => {
    let live = true
    const load = async () => {
      try {
        const answer = await ctx.rest('/models')
        if (live && answer && answer.ok && Array.isArray(answer.routes)) setRoutes(answer.routes)
      } catch (failure) {
        if (live) setRoutes([])
      }
    }
    load()
    return () => { live = false }
  }, [ctx])

  useEffect(() => {
    if (!run || run.status !== 'running' || !run.id) return undefined
    let live = true
    const timer = setInterval(async () => {
      try {
        const next = await ctx.rest(`/tournament/status?id=${encodeURIComponent(run.id)}`)
        if (!live || !alive.current) return
        if (next && next.ok !== false) {
          setRun(next)
          if (next.status !== 'running') refresh()
        }
      } catch (failure) {
        if (live && alive.current) setError(failure.message || 'Could not read the tournament.')
      }
    }, 1500)
    return () => { live = false; clearInterval(timer) }
  }, [run && run.id, run && run.status, ctx, refresh])

  useEffect(() => {
    if (!watching || !auto) return undefined
    const frames = watching.frames || []
    if (watching.index >= frames.length - 1) return undefined
    const timer = setTimeout(() => {
      setWatching(current => current ? { ...current, index: Math.min(current.index + 1, frames.length - 1) } : current)
    }, 1100)
    return () => clearTimeout(timer)
  }, [watching, auto])

  const act = async (path, body) => {
    try {
      const answer = await ctx.rest(path, { method: 'POST', body })
      if (alive.current) {
        if (answer && answer.ok === false) { setError(answer.text || 'That did not work.'); setNotice('') }
        else { setError(''); setNotice((answer && answer.text) || '') }
      }
      await refresh()
      return answer
    } catch (failure) {
      if (alive.current) setError(failure.message || 'That did not reach the Game Center.')
      return { ok: false }
    }
  }

  if (!data) {
    return jsx('div', { style: { padding: 18, color: text.secondary }, children: error || 'Loading champions…' })
  }

  // The body of every champion on this screen is this Hermes's own pet.
  const pet = data.pet || null

  const save = () => {
    const champion = {
      ...(form.id ? { id: form.id } : {}),
      name: form.name, motto: form.motto, avatar: form.avatar, color: form.color,
      brief: form.brief,
      brain: { kind: 'model', model: form.model.trim(), provider: form.provider.trim() }
    }
    if (form.created_at) champion.created_at = form.created_at
    return act('/champions/save', { champion }).then(answer => {
      if (answer && answer.ok) setForm(EMPTY_CHAMPION)
    })
  }
  const remove = champion => {
    const okay = typeof window === 'undefined' || !window.confirm
      ? true
      : window.confirm(`Delete "${champion.name}"? Its record and rating stay until a tournament removes it.`)
    if (okay) act('/champions/delete', { id: champion.id })
  }
  const exportChampion = async champion => {
    const answer = await act('/champions/export', { id: champion.id })
    if (answer && answer.ok) {
      if (!saveFile(answer.filename || `${champion.id}.champion.json`, answer.text)) {
        setShowShare(answer.text); setNotice('Copy this file text to share the champion.')
      } else setNotice(`Saved ${answer.filename}.`)
    }
  }
  const importChampion = async text => {
    if (!String(text || '').trim()) { setError('Paste a champion file first.'); return }
    const answer = await act('/champions/import', { text })
    if (answer && answer.ok) { setPasted(''); setNotice(`Imported ${answer.champion.name}.`) }
  }
  const pickImport = () => {
    if (typeof document === 'undefined') return
    const input = document.createElement('input')
    input.type = 'file'
    input.accept = 'application/json,.json'
    input.onchange = () => {
      const file = input.files && input.files[0]
      if (!file || typeof FileReader === 'undefined') return
      const reader = new FileReader()
      reader.onload = () => importChampion(String(reader.result || ''))
      reader.onerror = () => setError('That file could not be read.')
      reader.readAsText(file)
    }
    input.click()
  }
  const toggle = (list, setList, value) => {
    setList(list.includes(value) ? list.filter(item => item !== value) : [...list, value])
  }

  const champions = data.champions || []
  const boards = Object.fromEntries((data.leaderboard || []).map(row => [row.id, row]))
  const count = picked.length + bots.length
  const pairs = count * (count - 1) / 2
  const estimateGames = pairs * 2 * games.length
  const estimateCalls = picked.length ? estimateGames * 24 : 0
  const estimateMinutes = Math.max(1, Math.round(estimateGames * 0.6))
  const divisionInfo = (data.divisions || []).find(item => item.id === division) || {}
  const canStart = count >= 2 && games.length > 0 && !(division === 'prompt' && (bots.length > 0 || picked.length < 2))
    && estimateGames <= Number(data.caps.games) && estimateCalls <= Number(data.caps.calls)
  const gameTitle = id => ((data.games || []).find(item => item.id === id) || {}).title || id
  const nameOf = id => (run && run.names && run.names[id]) || ((data.champions || []).find(item => item.id === id) || {}).name || (id.startsWith("bot-") ? "Computer (" + id.slice(4).replace(/^./, c => c.toUpperCase()) + ")" : id)

  const start = async () => {
    const answer = await act('/tournament/start', {
      champions: picked, bots, games, division,
      seed: Number(seed) || 0,
      cap_games: Number(capGames) || undefined,
      cap_calls: Number(capCalls) || undefined
    })
    if (answer && answer.ok && answer.id) {
      setRun({ id: answer.id, status: 'running', played: 0, total: answer.estimate.games, results: [], names: {}, estimate: answer.estimate })
    }
  }
  const openSaved = async id => {
    try {
      const status = await ctx.rest(`/tournament/status?id=${encodeURIComponent(id)}`)
      if (status && status.ok !== false) { setRun(status); setError('') }
      else setError((status && status.text) || 'That tournament could not be opened.')
    } catch (failure) {
      setError(failure.message || 'That tournament could not be opened.')
    }
  }
  const importTournament = async text => {
    if (!String(text || '').trim()) { setError('That file was empty.'); return }
    const answer = await act('/tournament/import', { text })
    if (answer && answer.ok) openSaved(answer.id)
  }
  const pickTournamentFile = () => {
    if (typeof document === 'undefined') return
    const input = document.createElement('input')
    input.type = 'file'
    input.accept = 'application/json,.json'
    input.onchange = () => {
      const file = input.files && input.files[0]
      if (!file || typeof FileReader === 'undefined') return
      const reader = new FileReader()
      reader.onload = () => importTournament(String(reader.result || ''))
      reader.onerror = () => setError('That file could not be read.')
      reader.readAsText(file)
    }
    input.click()
  }
  const watch = async index => {
    if (!run) return
    try {
      const replay = await ctx.rest(`/tournament/replay?id=${encodeURIComponent(run.id)}&index=${index}`)
      if (replay && replay.ok !== false) { setWatching({ ...replay, index: 0 }); setAuto(false); setError('') }
      else setError((replay && replay.text) || 'That game could not be replayed.')
    } catch (failure) {
      setError(failure.message || 'That game could not be replayed.')
    }
  }

  const creator = jsxs('div', {
    style: { borderRadius: 14, padding: 16, background: card, display: 'flex', flexDirection: 'column', gap: 12 },
    children: [
      jsx('div', { style: { fontFamily: DISPLAY_FONT, fontSize: 20, lineHeight: 1.2, letterSpacing: '-.012em', fontWeight: 600 }, children: form.id ? `Edit ${form.name || 'champion'}` : 'Create a champion' }),
      jsx('div', { style: { fontSize: 12, color: text.tertiary }, children: 'A name, a motto and a short personality and strategy brief. The brief is what plays: the rules are still the game\'s own.' }),
      jsxs('div', { style: { display: 'flex', gap: 10, flexWrap: 'wrap', alignItems: 'center' }, children: [
        jsx(PetSprite, { ctx, pet, state: 'idle', size: 46 }),
        jsxs('div', { style: { minWidth: 0, flex: 1 }, children: [
          jsx('div', { style: { fontSize: 12, color: text.secondary }, children: 'Its body is your Hermes pet.' }),
          jsx('div', { style: { fontSize: 12, color: text.tertiary, lineHeight: 1.45 }, children: pet && pet.enabled
            ? `${pet.displayName || pet.slug} takes this seat: it idles, waves, runs, jumps, fails, reviews and waits while it plays.`
            : 'No pet is installed yet, so a small placeholder figure stands in. Choose or hatch one in Hermes Settings → Appearance → Pet.' })
        ] })
      ] }),
      jsxs('div', { style: { display: 'flex', gap: 8, flexWrap: 'wrap' }, children: [
        field(form.name, value => setForm(current => ({ ...current, name: value })), `Name (max ${data.limits.name})`),
        field(form.motto, value => setForm(current => ({ ...current, motto: value })), `Motto (max ${data.limits.motto})`)
      ] }),
      jsxs('div', { style: { display: 'flex', gap: 6, flexWrap: 'wrap', alignItems: 'center' }, children: [
        jsx('div', { style: { fontSize: 12, color: text.tertiary, width: 54 }, children: 'Colour' }),
        ...(data.colors || []).map(item => jsx('button', {
          type: 'button',
          key: item.id,
          title: item.id,
          'aria-label': `${item.id} colour`,
          'aria-pressed': form.color === item.id,
          onClick: () => setForm(current => ({ ...current, color: item.id })),
          style: {
            width: 26, height: 26, borderRadius: 6, cursor: 'pointer', padding: 0,
            border: `2px solid ${form.color === item.id ? text.primary : 'transparent'}`,
            background: item.hex
          }
        }))
      ] }),
      jsxs('label', { style: { display: 'flex', flexDirection: 'column', gap: 4 }, children: [
        jsx('span', { style: { fontSize: 12, color: text.tertiary }, children: `Personality and strategy brief (max ${data.limits.brief} characters)` }),
        jsx('textarea', {
          value: form.brief,
          rows: 5,
          maxLength: data.limits.brief,
          placeholder: 'How does this champion think? Patient and positional, or a reckless attacker? What does it do when it is behind?',
          onChange: event => setForm(current => ({ ...current, brief: event.target.value })),
          style: {
            width: '100%', boxSizing: 'border-box', padding: '8px 10px', borderRadius: 8,
            border: `1px solid ${stroke}`, background: 'transparent', color: 'inherit',
            fontSize: 12, fontFamily: 'inherit', resize: 'vertical'
          }
        }),
        jsx('span', { style: { fontSize: 12, color: text.tertiary }, children: `${form.brief.length} / ${data.limits.brief}` })
      ] }),
      jsxs('div', { style: { border: `1px solid ${stroke}`, borderRadius: 8, padding: 8, display: 'flex', flexDirection: 'column', gap: 6 }, children: [
        jsx('div', { style: { fontSize: 12, color: text.secondary }, children: `Model route: ${data.brain && data.brain.model ? `this Hermes's own (${data.brain.model})` : "this Hermes's own"}. Pick a different route for this champion, or leave it on this Hermes. Game Center never stores a key.` }),
        // One shared ModelPicker, the same component every other seat uses: a search box,
        // results grouped by provider, recent picks at the top and the current route marked.
        jsx(ModelPicker, {
          routes,
          current: form.model ? `${form.model}|${form.provider}` : '',
          ctx,
          hint: 'Type to filter by provider or model. Up and down move, Enter picks.',
          onPick: route => setForm(current => ({ ...current, model: (route && route.model) || '', provider: (route && route.provider) || '' }))
        }),
        jsx('div', { style: { fontSize: 12, color: text.tertiary }, children: data.model_ready ? 'A model is ready.' : 'No model is configured: you can still create champions and spar with the computer, but champion tournaments wait for a model.' })
      ] }),
      jsxs('div', { style: { display: 'flex', gap: 6, flexWrap: 'wrap' }, children: [
        button(form.id ? 'Save changes' : 'Create champion', save, { primary: true, disabled: !form.name.trim() || !form.brief.trim() }),
        form.id ? button('Cancel edit', () => setForm(EMPTY_CHAMPION)) : null,
        button('Import a file', pickImport),
        showShare ? button('Hide shared text', () => setShowShare('')) : null
      ] }),
      showShare ? jsx('textarea', {
        value: showShare, readOnly: true, rows: 6,
        onFocus: event => event.target.select(),
        style: { width: '100%', boxSizing: 'border-box', padding: 8, borderRadius: 8, border: `1px solid ${stroke}`, background: fill, color: 'inherit', fontSize: 12, fontFamily: 'var(--font-mono, ui-monospace, monospace)' }
      }) : null,
      jsxs('div', { style: { display: 'flex', gap: 6, flexWrap: 'wrap' }, children: [
        jsx('textarea', {
          value: pasted, rows: 2, placeholder: 'Or paste a shared champion file here',
          onChange: event => setPasted(event.target.value),
          style: { flex: 1, minWidth: 160, padding: 8, borderRadius: 8, border: `1px solid ${stroke}`, background: 'transparent', color: 'inherit', fontSize: 12, fontFamily: 'inherit' }
        }),
        button('Import pasted', () => importChampion(pasted), { disabled: !pasted.trim() })
      ] })
    ]
  })

  // The Bot Passport grid: the pet's body, the playbook it plays, and the record it earned.
  const badgesFor = id => {
    const row = (data.leaderboard || []).find(item => item.id === id)
    return (row && row.badges) || []
  }
  const cards = champions.length
    ? jsxs('div', { style: { display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(260px, 1fr))', gap: 10 }, children: champions.map(champion => {
        const record = (data.ratings || {})[champion.id] || {}
        return jsx(PassportCard, {
          key: champion.id,
          ctx,
          champion: { ...champion, record },
          badges: badgesFor(champion.id),
          avatars: data.avatars,
          colors: data.colors,
          pet,
          onOpenPlaybook: () => { setEditing(champion.id); setNotice(''); setError('') },
          actions: [
            button(picked.includes(champion.id) ? 'In tournament' : 'Add to tournament', () => toggle(picked, setPicked, champion.id), { disabled: champions.length < 2 }),
            button('Export', () => exportChampion(champion)),
            button('Edit', () => {
              setForm({
                ...EMPTY_CHAMPION,
                ...champion,
                model: (champion.model && champion.model.model) || '',
                provider: (champion.model && champion.model.provider) || ''
              })
              setShowShare('')
            }),
            button('Delete', () => remove(champion))
          ]
        })
      }) })
    : jsx('div', { style: { fontSize: 13, color: text.tertiary, borderRadius: 12, padding: 18, background: card }, children: 'No champions yet. Create one above, then write its playbook: the written brain is the whole game.' })

  // Labs: the experimental corner. A house boss is the person's own model in a
  // champion's seat, named after the model it runs. Nothing is stored, and the
  // whole section is absent until that model is ready. It uses the shared Labs
  // badge so this shelf never grows a second badge style.
  const houseBosses = data.house_bosses || []
  const labs = houseBosses.length
    ? jsxs('section', {
        'aria-label': 'Labs',
        style: { borderRadius: 14, padding: 16, background: card, display: 'flex', flexDirection: 'column', gap: 10 },
        children: [
          jsxs('div', { style: { display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }, children: [
            jsx('div', { style: { fontFamily: DISPLAY_FONT, fontSize: 18, letterSpacing: '-.01em', fontWeight: 600 }, children: 'Labs' }),
            labsBadge()
          ] }),
          jsx('div', { style: { fontSize: 12, color: text.secondary }, children: 'Experimental, and not part of the main shelf. A house boss is a built-in champion named after the open model it runs: it takes a seat through your own provider, so it costs the same model calls as any champion.' }),
          jsxs('div', { style: { display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(260px, 1fr))', gap: 10 }, children: houseBosses.map(boss => {
            const row = boards[boss.id] || {}
            return jsxs('div', {
              key: boss.id,
              style: { borderRadius: 12, padding: 14, background: paper, display: 'flex', flexDirection: 'column', gap: 8 },
              children: [
                jsxs('div', { style: { display: 'flex', gap: 12, alignItems: 'center' }, children: [
                  jsx(PetSprite, { ctx, pet, state: 'idle', size: 48 }),
                  jsxs('div', { style: { minWidth: 0 }, children: [
                    jsx('div', { style: { fontFamily: DISPLAY_FONT, fontSize: 17, letterSpacing: '-.01em', fontWeight: 600 }, children: boss.name }),
                    jsx('div', { style: { fontSize: 12, color: text.tertiary }, children: boss.motto || 'No motto' })
                  ] })
                ] }),
                jsx('div', { style: { fontSize: 12, color: text.secondary }, children: boss.runs || '' }),
                jsx('div', { style: { fontSize: 12, color: text.tertiary, maxHeight: 72, overflow: 'hidden' }, children: boss.brief || '' }),
                jsxs('div', { style: { display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'center', fontSize: 12, color: text.tertiary }, children: [
                  row.rating ? jsx('span', { children: `Elo ${Math.round(row.rating)}` }) : null,
                  row.title ? jsx('span', { children: row.title }) : null,
                  jsx('span', { children: boss.note || 'Hidden until a model is ready.' })
                ] }),
                jsx('div', { style: { display: 'flex', gap: 6, flexWrap: 'wrap', marginTop: 'auto' }, children: [
                  button(picked.includes(boss.id) ? 'In tournament' : 'Add to tournament', () => toggle(picked, setPicked, boss.id), { disabled: picked.length >= 8 && !picked.includes(boss.id) })
                ] })
              ]
            })
          }) })
        ]
      })
    : null

  const tournament = jsxs('div', {
    style: { borderRadius: 14, padding: 16, background: card, display: 'flex', flexDirection: 'column', gap: 10 },
    children: [
      jsx('div', { style: { fontFamily: DISPLAY_FONT, fontSize: 18, letterSpacing: '-.01em', fontWeight: 600 }, children: 'Tournament' }),
      jsxs('div', { style: { display: 'flex', gap: 6, flexWrap: 'wrap' }, children: (data.divisions || []).map(item => button(
        item.label, () => { setDivision(item.id); if (item.id === 'prompt') setBots([]) },
        { primary: division === item.id }
      )) }),
      jsx('div', { style: { fontSize: 12, color: text.secondary }, children: divisionInfo.note || '' }),
      jsxs('div', { style: { display: 'flex', gap: 14, flexWrap: 'wrap' }, children: [
        jsxs('div', { style: { flex: 1, minWidth: 220 }, children: [
          jsx('div', { style: { fontSize: 12, color: text.tertiary, marginBottom: 4 }, children: `Champions (${picked.length} picked)` }),
          champions.length
            ? jsxs('div', { style: { display: 'flex', gap: 4, flexWrap: 'wrap' }, children: champions.map(champion => button(
                champion.name, () => toggle(picked, setPicked, champion.id), { primary: picked.includes(champion.id) }
              )) })
            : jsx('div', { style: { fontSize: 12, color: text.tertiary }, children: 'Create two champions to hold a Prompt Division.' })
        ] }),
        jsxs('div', { style: { flex: 1, minWidth: 200 }, children: [
          jsx('div', { style: { fontSize: 12, color: text.tertiary, marginBottom: 4 }, children: 'Sparring partners (built-in computer)' }),
          jsxs('div', { style: { display: 'flex', gap: 4, flexWrap: 'wrap' }, children: (data.bots || []).map(bot => button(
            bot.name, () => toggle(bots, setBots, bot.level),
            { primary: bots.includes(bot.level), disabled: division === 'prompt' }
          )) })
        ] })
      ] }),
      jsxs('div', { children: [
        jsx('div', { style: { fontSize: 12, color: text.tertiary, marginBottom: 4 }, children: 'Games' }),
        jsxs('div', { style: { display: 'flex', gap: 4, flexWrap: 'wrap' }, children: (data.games || []).map(game => button(
          game.title, () => toggle(games, setGames, game.id), { primary: games.includes(game.id) }
        )) })
      ] }),
      jsxs('div', { style: { display: 'flex', gap: 8, flexWrap: 'wrap', alignItems: 'center' }, children: [
        jsxs('label', { style: { display: 'flex', gap: 4, alignItems: 'center', fontSize: 12, color: text.secondary }, children: [
          'Seed', field(seed, setSeed, '1')
        ] }),
        jsxs('label', { style: { display: 'flex', gap: 4, alignItems: 'center', fontSize: 12, color: text.secondary }, children: [
          'Max games', field(capGames, setCapGames, '40')
        ] }),
        jsxs('label', { style: { display: 'flex', gap: 4, alignItems: 'center', fontSize: 12, color: text.secondary }, children: [
          'Max model calls', field(capCalls, setCapCalls, '240')
        ] })
      ] }),
      jsx('div', { role: 'status', 'aria-live': 'polite', style: { fontSize: 12, color: text.secondary }, children: count < 2
        ? 'Pick at least two entrants.'
        : `${count} entrants · ${estimateGames} games (both colours) · about ${estimateCalls} model calls · roughly ${estimateMinutes} min. Limits: ${data.caps.games} games, ${data.caps.calls} calls.` }),
      jsxs('div', { style: { display: 'flex', gap: 6, flexWrap: 'wrap' }, children: [
        button('Start tournament', start, { primary: true, disabled: !canStart }),
        run && run.status === 'running' ? button('Stop', () => act('/tournament/stop', { id: run.id })) : null,
        run ? button('Export result file', async () => {
          const answer = await act('/tournament/export', { id: run.id })
          if (answer && answer.ok) {
            if (!saveFile(answer.filename || `${run.id}.tournament.json`, answer.text)) { setShowShare(answer.text); setNotice('Copy this text to share the result.') }
            else setNotice(`Saved ${answer.filename}.`)
          }
        }) : null
      ] })
    ]
  })

  const progress = run ? jsxs('div', {
    style: { borderRadius: 14, padding: 16, background: card, display: 'flex', flexDirection: 'column', gap: 8 },
    children: [
      jsxs('div', { style: { display: 'flex', justifyContent: 'space-between', gap: 8 }, children: [
        jsx('div', { style: { fontWeight: 700 }, children: run.status === 'running' ? 'Running' : run.status === 'done' ? 'Finished' : run.status === 'stopped' ? 'Stopped' : run.status === 'capped' ? 'Stopped at the model call limit' : 'Could not finish' }),
        jsx('div', { style: { fontSize: 12, color: text.secondary }, children: `${run.played || 0} / ${run.total || 0} games` })
      ] }),
      jsx('div', { style: { height: 6, borderRadius: 3, background: fill, overflow: 'hidden' }, children: jsx('div', {
        style: { height: '100%', width: `${run.total ? Math.round(100 * (run.played || 0) / run.total) : 0}%`, background: accent }
      }) }),
      run.current && run.current.game ? jsx('div', { style: { fontSize: 12, color: text.tertiary }, children: `Now: ${nameOf(run.current.white)} vs ${nameOf(run.current.black)} · ${gameTitle(run.current.game)}` }) : null,
      run.error ? jsx('div', { role: 'alert', style: { fontSize: 12, color: text.primary }, children: run.error }) : null,
      (run.results || []).length ? jsxs('div', { style: { display: 'flex', flexDirection: 'column', gap: 4, maxHeight: 220, overflow: 'auto' }, children: run.results.map((result, index) => jsxs('div', {
        key: index,
        style: { display: 'flex', gap: 8, alignItems: 'center', fontSize: 12, color: text.secondary },
        children: [
        jsx('span', { style: { flex: 1, minWidth: 0 }, children: `${nameOf(result.white)} vs ${nameOf(result.black)} · ${gameTitle(result.game)} · ${result.winner ? `${nameOf(result[result.winner])} won` : 'draw'}` }),
        button('Watch', () => watch(index))
      ] })) }) : null
    ]
  }) : null

  const replay = watching ? jsxs('div', {
    style: { borderRadius: 14, padding: 16, background: card, display: 'flex', flexDirection: 'column', gap: 8 },
    children: [
      jsxs('div', { style: { display: 'flex', justifyContent: 'space-between', gap: 8, alignItems: 'center' }, children: [
        jsx('div', { style: { fontWeight: 700 }, children: `Replay · ${watching.title || watching.game}` }),
        button('Close', () => { setWatching(null); setAuto(false) })
      ] }),
      jsx('div', { style: { fontSize: 12, color: text.tertiary }, children: `${watching.names.white} vs ${watching.names.black} · move ${watching.index} of ${(watching.frames || []).length - 1}` }),
      (() => {
        const frame = (watching.frames || [])[watching.index]
        if (!frame) return jsx('div', { style: { fontSize: 12, color: text.tertiary }, children: 'No frames.' })
        return frame.view === 'arena'
          ? jsx(ArenaStage, { picture: frame, height: 340 })
          : jsx(BoardSvg, { picture: frame, height: 340, interactive: false })
      })(),
      jsxs('div', { style: { display: 'flex', gap: 6, flexWrap: 'wrap', alignItems: 'center' }, children: [
        button('First', () => setWatching(current => current ? { ...current, index: 0 } : current)),
        button('Back', () => setWatching(current => current ? { ...current, index: Math.max(0, current.index - 1) } : current)),
        button('Next', () => setWatching(current => current ? { ...current, index: Math.min((current.frames || []).length - 1, current.index + 1) } : current)),
        button('Last', () => setWatching(current => current ? { ...current, index: (current.frames || []).length - 1 } : current)),
        button(auto ? 'Pause' : 'Play', () => setAuto(value => !value)),
        jsx('input', {
          type: 'range', min: 0, max: Math.max(0, (watching.frames || []).length - 1), value: watching.index,
          'aria-label': 'Replay move',
          onChange: event => setWatching(current => current ? { ...current, index: Number(event.target.value) } : current),
          style: { flex: 1, minWidth: 120 }
        })
      ] }),
      watching.result ? jsx('div', { style: { fontSize: 12, color: text.secondary }, children: watching.result.winner ? `${watching.names[watching.result.winner]} won (${watching.result.status}).` : `The game was ${watching.result.status}.` }) : null
    ]
  }) : null

  const leader = (data.leaderboard || []).length ? jsxs('div', {
    style: { borderRadius: 14, padding: 16, background: card, display: 'flex', flexDirection: 'column', gap: 6 },
    children: [
      jsx('div', { style: { fontFamily: DISPLAY_FONT, fontSize: 18, letterSpacing: '-.01em', fontWeight: 600 }, children: 'Leaderboard' }),
      jsx('div', { style: { fontSize: 12, color: text.tertiary }, children: 'Elo, per game and overall. Only champions and the built-in computer are rated here; people are never rated.' }),
      ...(data.leaderboard || []).map((row, place) => jsxs('div', {
        key: row.id,
        style: { display: 'flex', gap: 8, alignItems: 'center', fontSize: 12, padding: '4px 0', borderTop: place ? `1px solid ${stroke}` : 'none' },
        children: [
        jsx('span', { style: { width: 22, color: text.tertiary }, children: String(place + 1) }),
        jsxs('span', { style: { flex: 1, minWidth: 0, fontWeight: place === 0 ? 700 : 400 }, children: [
          row.name,
          row.title ? jsx('span', { style: { fontSize: 12, color: text.tertiary, fontWeight: 400 }, children: ` · ${row.title}` }) : null
        ] }),
        jsx('span', { style: { ...TABULAR, color: text.secondary }, children: `W${row.wins} L${row.losses} D${row.draws}` }),
        jsx('span', { style: { ...TABULAR, width: 52, textAlign: 'right', color: text.secondary }, children: Math.round(row.rating) })
      ] }))
    ]
  }) : null

  const saved = (data.tournaments || []).length ? jsxs('div', {
    style: { borderRadius: 14, padding: 16, background: card, display: 'flex', flexDirection: 'column', gap: 6 },
    children: [
      jsxs('div', { style: { display: 'flex', justifyContent: 'space-between', gap: 8, alignItems: 'center' }, children: [
        jsx('div', { style: { fontFamily: DISPLAY_FONT, fontSize: 18, letterSpacing: '-.01em', fontWeight: 600 }, children: 'Past tournaments' }),
        button('Import a tournament file', pickTournamentFile)
      ] }),
      ...(data.tournaments || []).map(item => jsxs('div', {
        key: item.id, style: { display: 'flex', gap: 8, alignItems: 'center', fontSize: 12, color: text.secondary },
        children: [
        jsx('span', { style: { flex: 1, minWidth: 0 }, children: `${item.id} · ${item.status} · ${item.played}/${item.total} games` }),
        button('Open', () => openSaved(item.id))
      ] }))
    ]
  }) : null

  const edited = editing ? champions.find(item => item.id === editing) : null
  const openGallery = () => {
    try {
      if (host && typeof host.navigate === 'function') {
        host.navigate('/settings')
        if (alive.current) setNotice('Hermes Settings → Appearance → Pet is where the pet gallery lives. Choose or hatch a pet there.')
        return
      }
    } catch (failure) {
      // A host without navigation still gets the plain instruction below.
    }
    if (alive.current) setNotice('Open Hermes Settings → Appearance → Pet to choose or hatch a pet.')
  }
  const petLine = pet && pet.enabled
    ? jsxs('div', { style: { display: 'flex', gap: 8, alignItems: 'center', fontSize: 12, color: text.tertiary, flexWrap: 'wrap' }, children: [
      jsxs('span', { children: [
        'Champion bodies are your Hermes pet: ',
        jsx('strong', { style: { color: text.secondary }, children: pet.displayName || pet.slug }),
        '. It idles, waves, runs, jumps, fails, reviews and waits while it plays.'
      ] }),
      textLink('Choose or hatch a pet', openGallery)
    ] })
    : jsxs('div', { style: { display: 'flex', gap: 8, alignItems: 'center', fontSize: 12, color: text.tertiary, flexWrap: 'wrap' }, children: [
      jsx('span', { children: 'No Hermes pet yet, so champions wear a small placeholder figure.' }),
      button('Open pet gallery', openGallery)
    ] })

  return jsxs('div', {
    style: { display: 'flex', flexDirection: 'column', gap: 14, padding: 18, minWidth: 0, overflow: 'auto', background: paper },
    children: [
      jsxs('div', { style: { paddingBottom: 10, borderBottom: `1px solid ${stroke}` }, children: [
        jsx('div', { style: { fontFamily: DISPLAY_FONT, fontSize: 28, lineHeight: 1.15, letterSpacing: '-.02em', fontWeight: 600 }, children: 'Champions' }),
        jsx('div', { style: { fontSize: 12, color: text.tertiary, marginTop: 4, maxWidth: 620, lineHeight: 1.5 }, children: 'A champion is a pet\'s body and a written playbook: the questions it asks itself, its tactics, what it notes about a rival, and how it talks. Same model, better brain wins.' }),
        jsx('div', { style: { marginTop: 8 }, children: petLine })
      ] }),
      error ? jsx('div', { role: 'alert', style: { fontSize: 12, color: text.primary, border: `1px solid ${accent}`, borderRadius: 8, padding: '8px 10px' }, children: error }) : null,
      notice ? jsx('div', { role: 'status', style: { fontSize: 12, color: text.secondary }, children: notice }) : null,
      editing && edited ? jsx(PlaybookEditor, {
        key: edited.id,
        ctx,
        champion: edited,
        limits: data.playbook_limits,
        pet,
        onClose: () => setEditing(''),
        onChanged: refresh
      }) : null,
      !editing ? creator : null,
      !editing ? cards : null,
      !editing ? labs : null,
      !editing ? tournament : null,
      !editing ? progress : null,
      !editing ? replay : null,
      !editing ? leader : null,
      !editing ? saved : null
    ]
  })
}

// ---- 50-model-picker.js: one searchable model picker for every seat that takes a model
//
// The page already reads its model list from GET /models: {routes: [{id, label, model,
// provider, where}], current}. Every place that asks a person to put a Hermes model in a
// seat uses this one component, so the search, the grouping and the keyboard behave the
// same in all of them. It never invents a backend: it only reads the routes the page
// already loaded and reports the chosen route back.
const MODEL_RECENT_KEY = 'gameshelf-model-recent'
const MODEL_RECENT_LIMIT = 4
const MODEL_CHAT_ID = ''

function modelPickerRoutes(routes) {
  return (Array.isArray(routes) ? routes : [])
    .filter(item => item && typeof item === 'object' && item.model && item.provider)
}

function modelPickerRecent(ctx) {
  try {
    const raw = ctx && ctx.storage && typeof ctx.storage.get === 'function'
      ? ctx.storage.get(MODEL_RECENT_KEY, [])
      : []
    if (!Array.isArray(raw)) return []
    return raw.filter(item => typeof item === 'string' && item).slice(0, MODEL_RECENT_LIMIT)
  } catch (error) {
    return []
  }
}

function modelPickerRemember(ctx, id) {
  if (!id) return
  try {
    if (!ctx || !ctx.storage || typeof ctx.storage.set !== 'function') return
    const next = [id].concat(modelPickerRecent(ctx).filter(item => item !== id)).slice(0, MODEL_RECENT_LIMIT)
    ctx.storage.set(MODEL_RECENT_KEY, next)
  } catch (error) {
    // An older host without storage: the picker still works, it just forgets.
  }
}

function modelPickerKey(item) {
  if (!item || !item.model) return MODEL_CHAT_ID
  return String(item.id || `${item.model}|${item.provider}`)
}

// A searchable, grouped, keyboard-driven model list. "Use my chat model" is always the
// first entry: it leaves the seat on this Hermes's own model, exactly as an empty model
// does today. Recent picks sit above the provider groups so the model a person used last
// is one press away. The current route is marked, never merely guessed from its label.
function ModelPicker({ routes, current, onPick, ctx, hint = '' }) {
  const list = modelPickerRoutes(routes)
  const [query, setQuery] = useState('')
  const [active, setActive] = useState(0)
  const [recent, setRecent] = useState(() => modelPickerRecent(ctx))
  const needle = String(query || '').trim().toLowerCase()
  const matches = item => {
    if (!needle) return true
    return [item.model, item.provider, item.label, item.where]
      .filter(Boolean).join(' ').toLowerCase().includes(needle)
  }
  const currentId = String(current || '')
  const recentItems = recent
    .map(id => list.find(item => modelPickerKey(item) === id))
    .filter(Boolean)
    .filter(matches)
  const groups = new Map()
  list.filter(matches).forEach(item => {
    const provider = String(item.provider || 'Other')
    if (!groups.has(provider)) groups.set(provider, [])
    groups.get(provider).push(item)
  })
  const chat = { id: MODEL_CHAT_ID, label: 'Use my chat model', model: '', provider: '', kind: 'chat' }
  const entries = [
    chat,
    ...recentItems.map(item => ({ ...item, kind: 'recent' })),
    ...[...groups.keys()].sort().flatMap(provider => groups.get(provider).map(item => ({ ...item, kind: 'model' })))
  ]
  const chosen = entries[Math.min(active, entries.length - 1)] || chat
  const pick = item => {
    const next = item && item.model ? item : chat
    if (next.id) {
      modelPickerRemember(ctx, next.id)
      setRecent(modelPickerRecent(ctx))
    }
    if (typeof onPick === 'function') onPick(next)
  }
  const move = step => {
    const size = entries.length
    setActive(at => (size ? (Math.min(Math.max(at + step, 0), size - 1)) : 0))
  }
  const keyDown = event => {
    if (!event) return
    if (event.key === 'ArrowDown') { event.preventDefault(); move(1) }
    else if (event.key === 'ArrowUp') { event.preventDefault(); move(-1) }
    else if (event.key === 'Enter') { event.preventDefault(); pick(chosen) }
  }
  const isCurrent = item => {
    const key = modelPickerKey(item)
    if (!currentId) return key === MODEL_CHAT_ID
    return key === currentId
  }
  const row = item => {
    const key = modelPickerKey(item)
    const current = isCurrent(item)
    return jsx('button', {
      type: 'button',
      key: `${item.kind || 'model'}:${key || 'chat'}`,
      'data-model-id': key,
      'data-model-current': current ? '1' : undefined,
      'aria-current': current ? 'true' : undefined,
      'aria-label': `${item.label || item.model}${item.provider ? ` · ${item.provider}` : ''}${current ? ' · current' : ''}`,
      title: item.model ? `${item.model} · ${item.provider}${item.where ? ` · ${item.where}` : ''}` : 'This Hermes’s own chat model',
      onClick: () => pick(item),
      style: {
        display: 'flex', alignItems: 'baseline', justifyContent: 'space-between', gap: 8,
        width: '100%', textAlign: 'left', padding: '7px 9px', borderRadius: 7, cursor: 'pointer',
        border: `1px solid ${current ? accent : stroke}`,
        background: current ? fill : 'transparent',
        color: current ? text.primary : text.secondary,
        fontSize: 12, fontWeight: current ? 650 : 500
      },
      children: [
        jsx('span', { children: item.label || item.model }),
        jsx('span', {
          style: { fontSize: 11, color: text.tertiary, whiteSpace: 'nowrap' },
          children: [item.provider, item.where, current ? 'current' : ''].filter(Boolean).join(' · ')
        })
      ]
    }, `${item.kind || 'model'}:${key || 'chat'}`)
  }
  const group = (title, items, key) => items.length
    ? jsxs('div', {
        key,
        style: { display: 'flex', flexDirection: 'column', gap: 3, minWidth: 0 },
        children: [
          jsx('div', { style: { fontSize: 11, letterSpacing: '0.08em', textTransform: 'uppercase', color: text.tertiary }, children: title }),
          ...items.map(row)
        ]
      })
    : null
  return jsxs('div', {
    'data-model-picker': '1',
    style: { display: 'flex', flexDirection: 'column', gap: 6, minWidth: 0 },
    children: [
      jsx('input', {
        type: 'search',
        value: query,
        'aria-label': 'Search models',
        placeholder: 'Search by provider or model',
        onChange: event => { setQuery(event.target.value); setActive(0) },
        onKeyDown: keyDown,
        style: {
          width: '100%', boxSizing: 'border-box', padding: '7px 10px', borderRadius: 8,
          border: `1px solid ${stroke}`, background: 'transparent', color: 'inherit', fontSize: 12
        }
      }),
      hint ? jsx('div', { style: { fontSize: 11, color: text.tertiary }, children: hint }) : null,
      jsxs('div', {
        role: 'listbox',
        'aria-label': 'Models',
        style: { display: 'flex', flexDirection: 'column', gap: 7, maxHeight: 260, overflow: 'auto', minWidth: 0 },
        children: [
          group('Chat model', [chat], 'chat'),
          recentItems.length ? group('Recent', recentItems.map(item => ({ ...item, kind: 'recent' })), 'recent') : null,
          ...[...groups.keys()].sort().map(provider => group(provider, groups.get(provider).map(item => ({ ...item, kind: 'model' })), provider)),
          entries.length ? null : jsx('div', { style: { fontSize: 12, color: text.tertiary }, children: 'No models match that search.' })
        ]
      })
    ]
  })
}

// ---- 60-settings-and-alerts.js: the welcome, Settings and the quiet alert line

// Owner's ask, 2026-11-09: no alerts in any game for now. One switch, so every surface that could
// raise one - the line on the page, the pane's list, the desktop notification - is silent together,
// and bringing them back is this one line. The components stay in the bundle.
const ALERTS_OFF = true
// ---------------------------------------------------------------------------
// First run, Settings and the quiet "someone wants a match" alert.
//
// Nothing here goes anywhere. The rows the alert shows come from /alerts, which
// reads this Hermes's own /games looking list: people in this Hermes and the
// chats it shares. No popup, no sound, no focus steal, and the badge is only a
// small number on the Games item already in the status bar.
const WELCOME_LINE = 'Game Center is where you play the board games that come with Hermes — against the computer, your own agent, or someone here.'
const HERE_LINE = 'People in this Hermes and the chats it shares.'
const MATCH_LINE = 'Tell me when someone wants a match'

// One switch: a title, a plain sentence, and On / Off. The whole row is not a
// button, so a stray click next to it changes nothing.
function toggleRow({ title, note, on, onToggle, name }) {
  const says = name ? `${MATCH_LINE}: ${name}` : title
  return jsxs('div', {
    style: { display: 'flex', gap: 12, alignItems: 'center', justifyContent: 'space-between', padding: '7px 0', borderBottom: `1px solid ${stroke}` },
    children: [
      jsxs('div', {
        style: { minWidth: 0 },
        children: [
          jsx('div', { style: { fontSize: 13, color: text.primary }, children: title }),
          note ? jsx('div', { style: { fontSize: 11, color: text.tertiary, marginTop: 2 }, children: note }) : null
        ]
      }),
      button(on ? 'On' : 'Off', onToggle, { primary: on, label: says, title: says })
    ]
  })
}

// The welcome: what this is, a name that is already filled in, and the games a
// person would play with someone. Continue and Skip both end it for good.
function WelcomePanel({ view, ctx, onDone }) {
  const setup = view.setup || {}
  const [name, setName] = useState(setup.name || setup.suggested_name || '')
  const [games, setGames] = useState(() => Object.keys(setup.watched || {}))
  const [note, setNote] = useState('')
  const [busy, setBusy] = useState(false)
  const list = view.play || []

  const pick = id => setGames(current => (current.includes(id) ? current.filter(item => item !== id) : current.concat([id])))

  const finish = async body => {
    setBusy(true)
    try {
      const answer = await ctx.rest('/setup', { method: 'POST', body: { ...body, done: true } })
      if (answer && answer.ok === false) {
        setNote(answer.text || 'That name did not work. Try another.')
        setBusy(false)
        return
      }
      setBusy(false)
      onDone(answer)
    } catch (failure) {
      setNote((failure && failure.message) || 'Game Center could not save that. Try again.')
      setBusy(false)
    }
  }

  return jsx('div', {
    className: 'games-welcome',
    style: { padding: 18, background: paper, height: '100%', overflow: 'auto' },
    children: jsxs('div', {
      style: { maxWidth: 620, margin: '0 auto', display: 'flex', flexDirection: 'column', gap: 14, border: `1px solid ${stroke}`, borderRadius: 16, padding: 22, background: card },
      children: [
        jsx('div', { style: { fontWeight: 700, fontSize: 24, letterSpacing: '-0.03em' }, children: 'Welcome to Game Center' }),
        jsx('div', { style: { fontSize: 14, lineHeight: 1.5, color: text.secondary }, children: WELCOME_LINE }),
        jsx('div', { style: { fontSize: 12, color: text.tertiary }, children: 'No account, no email, nothing sent anywhere. About 20 seconds.' }),
        jsxs('div', {
          style: { display: 'flex', flexDirection: 'column', gap: 6 },
          children: [
            jsx('div', { style: { fontSize: 13, fontWeight: 650 }, children: 'Pick a name' }),
            jsx('div', { style: { display: 'flex', gap: 8 }, children: [
              field(name, setName, setup.suggested_name || 'Your name', () => {}, { label: 'Your name' }),
              button('Use this', () => setName(setup.suggested_name || ''), { disabled: !setup.suggested_name, title: 'Use the name Game Center suggests' })
            ] }),
            jsx('div', { style: { fontSize: 11, color: text.tertiary }, children: 'This is the name other players see. You can change it later in Settings.' })
          ]
        }),
        list.length
          ? jsxs('div', {
              style: { display: 'flex', flexDirection: 'column', gap: 6 },
              children: [
                jsx('div', { style: { fontSize: 13, fontWeight: 650 }, children: 'Games you would play with someone' }),
                jsx('div', { style: { fontSize: 11, color: text.tertiary }, children: 'Optional. A game switched on shows a quiet badge when someone here wants a match.' }),
                jsx('div', { style: { display: 'flex', gap: 6, flexWrap: 'wrap' }, children: list.map(game =>
                  button(game.title, () => pick(game.id), { primary: games.includes(game.id), label: `Play with someone: ${game.title}`, title: games.includes(game.id) ? `${game.title}: on` : `${game.title}: off` })
                ) })
              ]
            })
          : null,
        note ? jsx('div', { role: 'status', 'aria-live': 'polite', style: { fontSize: 12, color: text.primary }, children: note }) : null,
        jsxs('div', {
          style: { display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap', paddingTop: 4 },
          children: [
            button('Continue', () => finish({ name: name.trim(), games }), { primary: true, disabled: busy, title: 'Save this name and start playing' }),
            button('Skip for now', () => finish({}), { disabled: busy, title: 'Start playing without a name; you can set one in Settings' })
          ]
        })
      ]
    })
  })
}

// Settings: the name, one switch per Play game, a pause, and whether AI seats
// may play here. Every change is saved as it is made.
//
// The version chip lives at the top of THIS panel (owner, 2026-11-10: "keep everything in the status
// bar except the version chip. The version chip lives in Settings"), so it is on the full-screen
// Settings screen and on the play-while-you-wait pane's own Settings view, both drawn by this one
// component. The three navigation hooks are optional because they only make sense on the full page:
// the pane welds a way back to itself and no links it cannot honour. Everything else — every row,
// every switch, every route — is shared, so the two views cannot drift apart.
function SettingsPanel({ view, ctx, onBack, onSaved, onReopen, skin, onSkin, backLabel, backTitle, onCommunity }) {
  const setup = view.setup || {}
  const [name, setName] = useState(setup.name || setup.suggested_name || '')
  const [note, setNote] = useState('')
  const [busy, setBusy] = useState(false)
  const list = view.play || []
  const watched = setup.watched || {}
  const player = view.player || {}

  const save = async (body, said) => {
    setBusy(true)
    try {
      const answer = await ctx.rest('/settings', { method: 'POST', body })
      if (answer && answer.ok === false) setNote(answer.text || 'That did not save.')
      else setNote(said || answer.text || 'Saved.')
      if (onSaved) await onSaved()
    } catch (failure) {
      setNote((failure && failure.message) || 'Game Center could not save that. Try again.')
    } finally {
      setBusy(false)
    }
  }

  const reopen = async () => {
    try {
      await ctx.rest('/setup', { method: 'POST', body: { reopen: true } })
    } catch { /* the welcome shows again on the next refresh, or not at all */ }
    // Read the shelf again before showing it: the welcome is drawn from the saved
    // answer, so without this the page would open on the games and be replaced by the
    // welcome on the next poll, possibly in the middle of something.
    if (onReopen) await onReopen()
  }

  // Navigation, not settings: each link is drawn only for a surface that can honour it, so the pane's
  // Settings view never offers a door that would land somewhere else than it says.
  const links = [
    onReopen ? textLink('Show the welcome again', reopen) : null,
    onCommunity ? textLink('Community creations', () => onCommunity()) : null
  ].filter(Boolean)

  return jsx('div', {
    className: 'games-settings',
    style: { padding: 18, background: paper, height: '100%', overflow: 'auto' },
    children: jsxs('div', {
      style: { maxWidth: 620, margin: '0 auto', display: 'flex', flexDirection: 'column', gap: 16 },
      children: [
        // The install in view, at the top of Settings and nowhere else: not the status bar, not the
        // Games header, not the foot of the pane.
        jsx('div', {
          'data-games-version-top': '1',
          style: { display: 'flex', justifyContent: 'flex-end', minWidth: 0 },
          children: jsx(GamesVersionChip, { ctx })
        }),
        jsxs('div', {
          style: { display: 'flex', justifyContent: 'space-between', gap: 12, alignItems: 'start', flexWrap: 'wrap' },
          children: [
            jsxs('div', { children: [
              jsx('div', { style: { fontWeight: 700, fontSize: 22, letterSpacing: '-0.03em' }, children: 'Game Center settings' }),
              jsx('div', { style: { fontSize: 12, color: text.tertiary, marginTop: 4 }, children: 'Everything here stays on this machine.' })
            ] }),
            button(backLabel || 'Back to Game Center', () => onBack('games'), { title: backTitle || 'Back to the games' })
          ]
        }),
        jsxs('section', {
          'aria-label': 'Your name',
          style: { display: 'flex', flexDirection: 'column', gap: 6, border: `1px solid ${stroke}`, borderRadius: 12, padding: 14, background: card },
          children: [
            heading('Your name'),
            jsx('div', { style: { display: 'flex', gap: 8 }, children: [
              field(name, setName, 'Your name', () => save({ name: name.trim() }), { label: 'Your name' }),
              button('Save name', () => save({ name: name.trim() }), { primary: true, disabled: busy || !name.trim() })
            ] }),
            jsx('div', { style: { fontSize: 11, color: text.tertiary }, children: player.named ? `You are ${player.name}. This is the name other players see.` : 'Other players see this name. Game Center does not ask for an account or an email.' })
          ]
        }),
        jsxs('section', {
          'aria-label': 'Match alerts',
          style: { display: 'flex', flexDirection: 'column', gap: 4, border: `1px solid ${stroke}`, borderRadius: 12, padding: 14, background: card },
          children: [
            heading('When someone wants a match'),
            jsx('div', { style: { fontSize: 11, color: text.tertiary, marginBottom: 6 }, children: `${HERE_LINE} Nothing is searched on the internet.` }),
            list.length
              ? jsx('div', { children: list.map(game =>
                  toggleRow({
                    title: game.title,
                    note: MATCH_LINE,
                    name: game.title,
                    on: Boolean(watched[game.id]),
                    onToggle: () => save({ watch: { [game.id]: !watched[game.id] } })
                  })
                ) })
              : jsx('div', { style: { fontSize: 13, color: text.tertiary }, children: 'No curated games to watch yet.' }),
            toggleRow({
              title: 'Pause all of these',
              note: 'No badge and no line until you switch this back on.',
              on: Boolean(setup.paused),
              onToggle: () => save({ paused: !setup.paused })
            })
          ]
        }),
        jsxs('section', {
          'aria-label': 'AI seats',
          style: { display: 'flex', flexDirection: 'column', gap: 4, border: `1px solid ${stroke}`, borderRadius: 12, padding: 14, background: card },
          children: [
            heading('AI seats'),
            toggleRow({
              title: 'Let AI seats play here',
              note: 'Off means no game here seats an AI. On still asks you at the table each time.',
              on: Boolean(setup.allow_ai),
              onToggle: () => save({ allow_ai: !setup.allow_ai })
            }),
            jsx('div', { style: { fontSize: 11, color: text.tertiary, marginTop: 6 }, children: setup.ai_choice === null || setup.ai_choice === undefined ? "Starts from the plugin's own setting. What you choose here wins." : 'Your choice here wins over the plugin setting.' })
          ]
        }),
        jsxs('section', {
          'aria-label': 'Sound',
          style: { display: 'flex', flexDirection: 'column', gap: 4, border: `1px solid ${stroke}`, borderRadius: 12, padding: 14, background: card },
          children: [
            heading('Sound'),
            jsx(SoundSetting, {}, 'sound')
          ]
        }),
        // The Jackpot cabinet's own switch, in Settings too (owner's ask, 2026-11-11): the SAME
        // component the cabinet's panel and the status bar draw, reading and writing the same three
        // keys — so the two Settings views (the page's and the play-while-you-wait pane's, which is
        // this very component) can never drift from the machine. Guarded by name so a bundle built
        // without the layer part still draws Settings.
        typeof Jackpot2OverChatControls === 'function' ? jsxs('section', {
          'aria-label': 'Jackpot over the chat',
          style: { display: 'flex', flexDirection: 'column', gap: 4, border: `1px solid ${stroke}`, borderRadius: 12, padding: 14, background: card },
          children: [
            heading('Jackpot over the chat'),
            jsx('div', {
              style: { fontSize: 11, color: text.tertiary, marginBottom: 6 },
              children: 'Float the Jackpot cabinet over the conversation, and set how big and how see-through it is. The same switch as the status bar and the cabinet’s own panel.'
            }),
            jsx(Jackpot2OverChatControls, { ctx, tone: 'settings' })
          ]
        }) : null,
        jsxs('section', {
          'aria-label': 'Look',
          style: { display: 'flex', flexDirection: 'column', gap: 4, border: `1px solid ${stroke}`, borderRadius: 12, padding: 14, background: card },
          children: [
            heading('Look'),
            skinToggle(skin, onSkin)
          ]
        }),
        note ? jsx('div', { role: 'status', 'aria-live': 'polite', style: { fontSize: 12, color: text.secondary }, children: note }) : null,
        links.length
          ? jsx('div', {
              style: { display: 'flex', gap: 12, alignItems: 'center', flexWrap: 'wrap' },
              children: links
            })
          : null
      ]
    })
  })
}

// The quiet line on the home page. No dialog, no sound: it appears above Play,
// says who wants what, and offers Join and Dismiss.
function AlertLine({ alerts, onJoin, onDismiss }) {
  const rows = (alerts && alerts.rows) || []
  const total = Math.max(Number((alerts && alerts.count) || 0), rows.length)
  if (!rows.length) return null
  return jsxs('div', {
    className: 'games-alert',
    role: 'status',
    'aria-live': 'polite',
    style: { display: 'flex', flexDirection: 'column', gap: 6, border: `1px solid ${accent}`, borderRadius: 10, padding: '10px 12px', background: card },
    children: [
      jsx('div', { style: { fontSize: 11, letterSpacing: '0.12em', textTransform: 'uppercase', color: text.tertiary }, children: rows.length === 1 ? 'Someone wants a match' : 'People want a match' }),
      ...rows.map(row => jsxs('div', {
        style: { display: 'flex', gap: 8, alignItems: 'center', justifyContent: 'space-between', flexWrap: 'wrap' },
        children: [
          jsx('div', {
            style: { fontSize: 13, color: text.primary, minWidth: 0 },
            // The address is shown when the person gave one with /games looking, so
            // nothing they typed is dropped. Join still only opens our own table: this
            // build has no way to reach another machine, and the line does not pretend.
            children: `${row.name} is looking for a ${row.title || row.game} match${row.where ? ` at ${row.where}` : ''}.`
          }),
          jsxs('div', {
            style: { display: 'flex', gap: 6 },
            children: [
              button('Join', () => onJoin(row), { primary: true, label: `Join ${row.name} at ${row.title || row.game}`, title: `Open the ${row.title || row.game} table` }),
              button('Dismiss', () => onDismiss(row), { label: `Dismiss ${row.name} at ${row.title || row.game}`, title: 'Hide this until they look again' })
            ]
          })
        ]
      }, row.key || `${row.game}:${row.name}`)),
      total > rows.length
        ? jsx('div', { style: { fontSize: 12, color: text.secondary }, children: `${total - rows.length} more ${total - rows.length === 1 ? 'person' : 'people'} are looking too; the count on Games has everyone.` })
        : null,
      jsx('div', { style: { fontSize: 11, color: text.tertiary }, children: HERE_LINE })
    ]
  })
}

// ---- 62-pane-state.js: Play while you code: what the pane remembers and how it reads a game
// ----- Play while you code: the side pane ------------------------------------
//
// A turn-based game in a pane beside the chat, so a person can play a move while
// Hermes works and be told, quietly, when it finishes. The board is BoardSvg —
// the very component the full table draws — so hover, drag and the piece art are
// the same by construction and only the size changes.
//
// Nothing here writes into the chat or asks the person's chat model for anything
// unless they press "Play my Hermes model": the built-in computer is the default
// opponent in this pane, free and instant. A game in progress lives on the
// server, and the pane remembers which game it was, so leaving and coming back
// resumes it.
const SDK_HOST = typeof host === 'undefined' ? null : host
const PANE_ID = 'hermes-gameshelf:pane'
const PANE_GAME_KEY = 'pane-game'
const PANE_ALERTS_KEY = 'pane-alerts'
const PANE_WIDTH = '360px'
// The four the owner named for a quick game. Order is the order they are offered.
const QUICK_GAMES = ['connect4', 'reversi', 'gomoku', 'breakthrough']
const QUICK_LEVEL = 'intermediate'
const IDLE_CHAT = { get: () => false, subscribe: () => () => {} }
// Which game the pane is on. Module state, so the status-bar badge sees the
// pane's choice without a second store.
const paneWatch = { game: '' }

function quickGameLine(id, who = 'computer', level = QUICK_LEVEL) {
  return `allow-ai ${id} black=${who === 'agent' ? 'agent' : 'local'} level=${level || QUICK_LEVEL}`
}

// Play is the curated list and nothing else, so the pane offers exactly the
// games the full table calls match-ready.
function paneGames(view) {
  return ((view && view.play) || []).filter(item => (item.kind || 'table') === 'table' && item.installed !== false)
}

// A game's own board says who it seats. A slot machine seats nobody opposite the
// person: one player, no computer, no levels, no model, no start-over. Read the
// board's view - the game's own metadata - never a sentence's wording.
function gameSeatsNobody(game, pictured) {
  const view = String((pictured && pictured.view) || (game && game.view) || (game && game.id) || '')
  return view === 'slots'
}

function paneGame(view, saved) {
  const games = paneGames(view)
  const wanted = String(saved || '')
  if (wanted && games.some(item => item.id === wanted)) return wanted
  return games.length ? games[0].id : ''
}

function storedValue(ctx, key, fallback) {
  try {
    if (!ctx || !ctx.storage || typeof ctx.storage.get !== 'function') return fallback
    const value = ctx.storage.get(key, fallback)
    return value === undefined || value === null ? fallback : value
  } catch {
    return fallback
  }
}

function storeValue(ctx, key, value) {
  try {
    if (ctx && ctx.storage && typeof ctx.storage.set === 'function') ctx.storage.set(key, value)
  } catch {
    // An older host without plugin storage: the table still saves on the server.
  }
}

function savedPaneGame(ctx) {
  const stored = storedValue(ctx, PANE_GAME_KEY, '')
  return typeof stored === 'string' ? stored : ''
}

function rememberPaneGame(ctx, id) {
  const wanted = String(id || '')
  if (!wanted || savedPaneGame(ctx) === wanted) return
  storeValue(ctx, PANE_GAME_KEY, wanted)
}

// Alerts are per game and off until the person turns them on; "paused" silences
// every game at once without forgetting the per-game choices.
function paneAlerts(ctx) {
  const stored = storedValue(ctx, PANE_ALERTS_KEY, null)
  if (!stored || typeof stored !== 'object') return { paused: false, games: {} }
  const games = stored.games && typeof stored.games === 'object' ? stored.games : {}
  return { paused: Boolean(stored.paused), games }
}

function alertsOn(ctx, gameId) {
  // The status-bar count is a quiet readout, not an alert drop: it stays. What ALERTS_OFF silences
  // is anything that pops up or notifies (owner's ask, 2026-11-09).
  const settings = paneAlerts(ctx)
  return Boolean(gameId && !settings.paused && settings.games[gameId])
}

function myTurn(picture, view) {
  return Boolean(picture && picture.status === 'active' && tableAccess(picture, view).can_move)
}

function lookingRows(lobby) {
  return (lobby && lobby.looking) || []
}

// Someone else waiting for this game. The lobby names people, and a person's own
// row carries their name, so the name is what tells "them" from "me".
function othersLooking(lobby, game, name) {
  return lookingRows(lobby).filter(row => row.game === game && row.name !== name)
}

function isLooking(lobby, game, name) {
  return lookingRows(lobby).some(row => row.game === game && row.name === name)
}

// Someone else waiting for a game this person is also waiting for. Both rows carry
// their names, which is what tells "them" from "me".
function matchFound(lobby, name) {
  const games = lookingRows(lobby).filter(row => row.name === name).map(row => row.game)
  return games.find(game => othersLooking(lobby, game, name).length) || ''
}

// Whose move it is, in one line. The pane and the full table say it in the same words (owner's
// ask, 2026-11-11):
//   - a Hermes model's seat is "Hermes is thinking…" the moment the board says it is that seat's
//     turn: the model works outside the request the person made, so the wait is real from the start;
//   - the built-in computer is "Computer is thinking…" only while a request that will answer it is
//     really in flight, and "Waiting for the computer…" when the board is simply its turn;
//   - another person is "Waiting for <name>…".
// '' means it is the person's own turn and nobody else is working: the board speaks for itself.
function waitWords(picture, view, opts) {
  const working = Boolean(opts && opts.working)
  if (!picture || String(picture.status || '') !== 'active') return ''
  const seats = picture.seats || []
  const seat = seats.find(item => item.side === picture.turn) || null
  const kind = String((seat && seat.kind) || '')
  if (kind === 'agent') return 'Hermes is thinking…'
  if (kind === 'local') return working ? 'Computer is thinking…' : 'Waiting for the computer…'
  // A request that is out is answered by whichever machine seat is at the table, so the person's
  // own move names the wait before the board says whose turn it is.
  const machine = seats.find(item => item.kind === 'agent') || seats.find(item => item.kind === 'local') || null
  if (working && machine) return machine.kind === 'agent' ? 'Hermes is thinking…' : 'Computer is thinking…'
  // Your own move says nothing here: the board itself says what to do.
  if (myTurn(picture, view)) return ''
  const name = String((seat && seat.name) || '')
  if (kind === 'human' && name) return `Waiting for ${name}…`
  return 'Waiting for the other side…'
}

// Is a Hermes model's seat the one to move? The one wait that starts before any request of the
// person's own is out: the model answers on its own schedule.
function agentOnMove(picture) {
  return Boolean(picture && picture.status === 'active' &&
    (picture.seats || []).some(seat => seat.side === picture.turn && seat.kind === 'agent'))
}

// The seconds on a wait line, counted from the moment the wait began: a line that reads "0s" is
// telling the person the clock is running (owner's ask, 2026-11-11).
function waitSecondsWords(seconds) {
  const whole = Math.floor(Number(seconds))
  return `${Number.isFinite(whole) && whole > 0 ? whole : 0}s`
}

// What the pane says under the board, in plain words: whose move it is, with the seconds running,
// while the other side works - and the plain state of this table otherwise.
function paneStatus(picture, view, opts) {
  if (!picture) return 'Quick game: pick a game, then press New game.'
  const status = String(picture.status || '')
  if (status === 'active') {
    const waiting = waitWords(picture, view, opts)
    if (!waiting) return ''
    const seconds = opts && opts.seconds !== undefined ? ` ${waitSecondsWords(opts.seconds)}` : ''
    return `${waiting}${seconds}`
  }
  if (status === 'win') return `${picture.winner === 'black' ? 'Black' : 'White'} wins`
  if (status === 'draw') return 'It is a draw'
  if (status === 'lesson_done') return 'Step done'
  if (status === 'idle' || status === 'preview') return 'Ready to play'
  return status
}

// The line about the agent, in one small row. An approval needs the person, so it
// wins over "working"; working wins over the finished line.
function agentNotice(busy, finished, approval) {
  if (approval) return { text: 'Hermes needs your approval in the chat.', back: true }
  if (busy) return { text: 'Hermes is working…', back: false }
  if (finished) return { text: 'Hermes finished: back to chat', back: true }
  return null
}

function focusChat(ctx) {
  try {
    if (ctx && typeof ctx.runAction === 'function') {
      const answer = ctx.runAction('composer.focus')
      if (!answer || answer.ok !== false) return true
    }
  } catch {
    // An older desktop without runAction: the route below is the fallback.
  }
  try {
    if (SDK_HOST && typeof SDK_HOST.navigate === 'function') {
      SDK_HOST.navigate('/')
      return true
    }
  } catch {
    // Nothing else to try; the chat is still one click away in the window.
  }
  return false
}

// Leave Game Center and land on the chat. Focusing the chat box alone can leave this
// page on screen, so go to the chat first and focus it after.
function closeGameCenter(ctx) {
  try {
    if (SDK_HOST && typeof SDK_HOST.navigate === 'function') SDK_HOST.navigate('/')
  } catch {
    // Fall through to focusing the chat.
  }
  return focusChat(ctx)
}

// Reveal the pane from an explicit user action. revealPane is the SDK's own door;
// the layout event is only a fallback for a desktop that predates it.
// Hermes gives a plugin no call to close its only pane (its own Close would disable the
// whole plugin, and a hide-only tab cannot hide the last tab of its zone). So the pane is
// registered only while it is wanted: × unregisters it and it leaves the layout completely;
// the status item and the palette register it again. The choice survives a restart.
const WAIT_PANE_SLOT = { ctx: null, make: null, dispose: null }
const PANE_GONE_KEY = 'gameshelf.pane.gone'

function paneGone() {
  try {
    return window.localStorage.getItem(PANE_GONE_KEY) === '1'
  } catch {
    return false
  }
}

function rememberPaneGone(gone) {
  try {
    if (gone) window.localStorage.setItem(PANE_GONE_KEY, '1')
    else window.localStorage.removeItem(PANE_GONE_KEY)
  } catch {
    // No storage: the pane still goes away for this visit.
  }
}

function mountWaitPane() {
  if (WAIT_PANE_SLOT.dispose || !WAIT_PANE_SLOT.ctx || !WAIT_PANE_SLOT.make) return false
  try {
    WAIT_PANE_SLOT.dispose = WAIT_PANE_SLOT.ctx.registerMany([WAIT_PANE_SLOT.make()])
    // The doors (the Games header button and the status-bar item) are told the pane is
    // back the moment it is, not on the next poll.
    announcePaneChrome()
    return true
  } catch {
    return false
  }
}

function unmountWaitPane() {
  const dispose = WAIT_PANE_SLOT.dispose
  WAIT_PANE_SLOT.dispose = null
  if (typeof dispose !== 'function') return false
  try {
    dispose()
  } catch {
    // Already gone with the plugin.
  }
  announcePaneChrome()
  return true
}

function openWaitPane() {
  // The way back from a closed or minimized pane, and the way in when it hides:
  // one door, so the status item and the palette behave the same.
  rememberPaneGone(false)
  if (mountWaitPane()) {
    // A freshly registered pane is adopted into the layout on the next tick; reveal it then.
    setTimeout(() => {
      try { restoreWaitPane() } catch { /* nothing to reveal into */ }
    }, 0)
    return true
  }
  try { restoreWaitPane() } catch { /* the reveal below still applies */ }
  try {
    if (SDK_HOST && typeof SDK_HOST.revealPane === 'function') {
      SDK_HOST.revealPane(PANE_ID)
      return true
    }
  } catch {
    // Fall through to the event.
  }
  try {
    if (typeof window !== 'undefined' && typeof window.dispatchEvent === 'function') {
      window.dispatchEvent(new CustomEvent('hermes:pane-toggle-reveal', { detail: { id: PANE_ID, mode: 'open' } }))
      return true
    }
  } catch {
    // A plain browser QA page has no layout to reveal.
  }
  return false
}

// One surface at a time: Game Center full screen and the Play while you code pane
// are the same game in two places, so opening one closes the other. The handoff
// carries the game across so the person lands on the same board, not the list.
const PAGE_HANDOFF = { game: '' }

function paneFromPage(ctx, gameId) {
  if (typeof gameId === 'string' && gameId) {
    paneWatch.game = gameId
    storeValue(ctx, PANE_GAME_KEY, gameId)
  }
  closeGameCenter(ctx)
  openWaitPane()
  return true
}

function pageFromPane(ctx) {
  const game = paneWatch.game || savedPaneGame(ctx)
  PAGE_HANDOFF.game = game || ''
  rememberPaneGone(true)
  if (!unmountWaitPane()) {
    try {
      if (SDK_HOST && typeof SDK_HOST.dismissPane === 'function') SDK_HOST.dismissPane(PANE_ID)
    } catch {
      // The navigate below still leaves the pane behind.
    }
  }
  try {
    if (SDK_HOST && typeof SDK_HOST.navigate === 'function') SDK_HOST.navigate(ROUTE)
  } catch {
    // Nothing else to try; the page is still one click away.
  }
}

// The full-screen page appeared: the pane must go, or the same game would be on
// screen twice. The saved pane game is deliberately left alone so the pane can
// come back to it.
function leavePaneForPage() {
  if (!WAIT_PANE_SLOT.dispose) return
  rememberPaneGone(true)
  unmountWaitPane()
}

function useChatBusy() {
  // The SDK's documented per-chat busy atom. A host without it (or a QA page
  // with no gateway) simply reports not busy, so the pane still works.
  if (typeof useValue !== 'function') return false
  const atom = (SDK_HOST && SDK_HOST.state && SDK_HOST.state.busy) || IDLE_CHAT
  return Boolean(useValue(atom))
}

function useHermesFinished(busy) {
  const [finished, setFinished] = useState(false)
  const wasBusy = useRef(false)
  useEffect(() => {
    if (busy) {
      wasBusy.current = true
      setFinished(false)
      return
    }
    if (wasBusy.current) {
      wasBusy.current = false
      setFinished(true)
    }
  }, [busy])
  // message.complete is the gateway's own end-of-reply event; the busy atom is
  // what the status bar reads. Either one says Hermes is done.
  useEffect(() => {
    if (!SDK_HOST || typeof SDK_HOST.onEvent !== 'function') return undefined
    let stop = () => {}
    try {
      stop = SDK_HOST.onEvent('message.complete', () => setFinished(true)) || stop
    } catch {
      // No event stream on this host: the busy atom alone drives the line.
    }
    return () => {
      try { stop() } catch { /* already gone */ }
    }
  }, [])
  return finished && !busy
}

function useApprovalNotice() {
  const [needs, setNeeds] = useState(false)
  useEffect(() => {
    if (!SDK_HOST || typeof SDK_HOST.onEvent !== 'function') return undefined
    const stops = []
    try {
      stops.push(SDK_HOST.onEvent('approval.request', () => setNeeds(true)))
      stops.push(SDK_HOST.onEvent('approval.settled', () => setNeeds(false)))
      stops.push(SDK_HOST.onEvent('approval.cancelled', () => setNeeds(false)))
      // The gateway publishes approval.settled when a prompt is answered
      // (gateway/session_commands.py); a reply that completes is the other safe end.
      stops.push(SDK_HOST.onEvent('message.complete', () => setNeeds(false)))
    } catch {
      // The event stream is not there: no approval line, and nothing else changes.
    }
    return () => stops.forEach(stop => { try { stop() } catch { /* gone */ } })
  }, [])
  return needs
}

function notifyAlert(ctx, label, gameId, title) {
  if (typeof ALERTS_OFF !== 'undefined' && ALERTS_OFF) return null
  try {
    if (!ctx || !ctx.os || typeof ctx.os.notify !== 'function') return false
    ctx.os.notify({
      title: label,
      body: label === 'Your turn' ? `Your move in ${title || gameId}.` : `Someone is looking for a ${title || gameId} game.`,
      silent: true,
      onActivate: () => openWaitPane()
    })
    return true
  } catch {
    return false
  }
}

// Someone online is waiting for a game the person asked to hear about. Same
// silent notification as a turn, with one click to the pane.
function notifyOnline(ctx, alert) {
  if (typeof ALERTS_OFF !== 'undefined' && ALERTS_OFF) return null
  try {
    if (!ctx || !ctx.os || typeof ctx.os.notify !== 'function') return false
    ctx.os.notify({
      title: 'Someone is waiting online',
      body: String((alert && alert.text) || 'Someone online wants a game.'),
      silent: true,
      onActivate: () => openWaitPane()
    })
    return true
  } catch {
    return false
  }
}

function agentRow(notice, ctx) {
  if (!notice) return null
  return jsxs('div', {
    role: 'status',
    'aria-live': 'polite',
    className: 'games-agent-notice',
    style: {
      display: 'flex', gap: 8, alignItems: 'center', justifyContent: 'space-between',
      padding: '6px 10px', borderRadius: 8, border: `1px solid ${stroke}`, background: fill,
      fontSize: 12, color: text.secondary
    },
    children: [
      jsx('span', { children: notice.text }),
      notice.back ? textLink('Back to chat', () => focusChat(ctx)) : null
    ]
  })
}

// The online source, as the pane reads it: everything the page shows comes from
// /view's "online" answer, and every action goes through one of the /online
// doors. Nothing here talks to the lobby server itself, and nothing at all
// happens until the person's own yes is stored.
function onlineView(view) {
  const online = (view && view.online) || {}
  return {
    on: Boolean(online.on),
    url: online.url || ONLINE_URL,
    linked: Boolean(online.linked),
    name: online.name || '',
    disclosure: online.disclosure || '',
    offline: Boolean(online.offline),
    offlineText: online.offline_text || '',
    game: online.game || '',
    looking: online.looking || {},
    waitingNames: online.waiting_names || [],
    match: online.match || null,
    alerts: online.alerts || {},
    ladder: online.ladder || {},
    league: online.league || {},
    bot: online.bot || {},
    staff: online.staff || { role: '', name: '', key: false, powers: [] }
  }
}

function onlineHost(url) {
  return String(url || '').replace(/^https?:\/\//, '').replace(/\/$/, '')
}

// The one plain sentence about where online play stands.
function onlineLine(online, title) {
  if (!online.on) return 'Off. Games with other people are a separate service; nothing is sent until you turn it on.'
  if (online.offline) return online.offlineText || 'The online lobby cannot be reached right now. Everything here that runs on this computer still works.'
  if (online.match) return `Your table is ready: ${online.match.opponent || 'someone'} for ${online.match.title || online.match.game}.`
  if (!online.linked) return 'On. Choose the name you play as, or enter the key you already have.'
  if (online.game) return `Looking for a ${title || online.game} match. This keeps looking while you use Hermes.`
  return 'On. Nothing is sent until you press Find a match or Enter ladder.'
}

function ladderLine(ladder) {
  const state = String((ladder && ladder.state) || 'idle')
  if (state === 'idle') return ''
  if (state === 'starting') return 'Entering the ladder…'
  if (state === 'waiting') return 'Waiting for another bot to enter the ladder.'
  if (state === 'playing') return `${(ladder && ladder.text) || 'Playing.'} Move ${(ladder && ladder.plies) || 0}.`
  if (state === 'stopped') return 'Ladder game stopped.'
  if (state === 'error') return (ladder && ladder.text) || 'The ladder game stopped.'
  return (ladder && ladder.text) || 'The ladder game is over.'
}

// ----- Out of the way: minimize, close, Esc (owner, 12:35) -------------------
//
// The pane must leave easily and come back at once. Both are one session state,
// remembered in sessionStorage: 'min' collapses the pane to a slim strip, 'closed'
// does the same and asks the layout to hide the pane outright where it can (the
// narrow overlay). The status-bar item and the palette are always the way back.
const PANE_CHROME_KEY = 'gameshelf-pane-chrome'
const PANE_CHROME_EVENT = 'gameshelf:pane-chrome'

function paneChromePref() {
  try {
    const value = window.sessionStorage.getItem(PANE_CHROME_KEY)
    return value === 'min' || value === 'closed' ? value : 'open'
  } catch {
    return 'open'
  }
}

function rememberPaneChrome(value) {
  try {
    if (value === 'min' || value === 'closed') window.sessionStorage.setItem(PANE_CHROME_KEY, value)
    else window.sessionStorage.removeItem(PANE_CHROME_KEY)
  } catch {
    // No session storage (a plain QA page): the pane just stays as it is.
  }
  announcePaneChrome()
}

// Every door that opens, closes or minimizes the pane says so on this one event, and the
// doors that are drawn elsewhere (the Games header button, the status-bar item) listen for
// it: one announcement, so two surfaces can never disagree about where the pane is.
function announcePaneChrome() {
  try {
    window.dispatchEvent(new CustomEvent(PANE_CHROME_EVENT))
  } catch {
    // Nowhere to announce it.
  }
}

// Is the pane on the screen? The one read both doors use. The pane registers itself when it
// is wanted (a fresh load, or the palette/status door) and unregisters on ×, so its
// registration is the truth; a session that chose 'closed' stays closed even where the host
// kept the pane mounted.
function paneOnScreen() {
  if (paneChromePref() === 'closed') return false
  return Boolean(WAIT_PANE_SLOT.dispose)
}

// The same read, as state a component re-renders on (owner's ask, 2026-11-11: the way back
// in must be visible, not only in the command palette).
function usePaneOnScreen() {
  const [onScreen, setOnScreen] = useState(paneOnScreen)
  useEffect(() => {
    const sync = () => setOnScreen(paneOnScreen())
    try {
      window.addEventListener(PANE_CHROME_EVENT, sync)
      sync()
      return () => { try { window.removeEventListener(PANE_CHROME_EVENT, sync) } catch { /* gone */ } }
    } catch {
      return undefined
    }
  }, [])
  return onScreen
}

// Hide/show the pane frame where the layout supports it (narrow overlay); a wide
// dock ignores this and keeps the strip inside the pane.
function revealWaitPane(mode) {
  try {
    window.dispatchEvent(new CustomEvent('hermes:pane-toggle-reveal', { detail: { id: PANE_ID, mode } }))
  } catch {
    // No layout to talk to.
  }
}

function minimizeWaitPane() {
  rememberPaneChrome('min')
}

function closeWaitPane() {
  rememberPaneChrome('closed')
  rememberPaneGone(true)
  // Clear the saved game so reopening the pane starts fresh, not restoring
  // the last game. The pane reopens to the game list, not a stale board.
  try {
    if (typeof window !== 'undefined' && typeof window.sessionStorage !== 'undefined') {
      window.sessionStorage.removeItem(PANE_GAME_KEY)
    }
  } catch {
    // sessionStorage might not be available in some contexts.
  }
  // Off the screen completely: the pane's registration goes away with it.
  if (unmountWaitPane()) return
  // A desktop with dismissPane takes the pane and its column out of the layout
  // without disabling the plugin; revealPane (openWaitPane) brings it back.
  try {
    if (SDK_HOST && typeof SDK_HOST.dismissPane === 'function') {
      SDK_HOST.dismissPane(PANE_ID)
      return
    }
  } catch {
    // Fall back to the layout event below.
  }
  revealWaitPane('close')
}

function restoreWaitPane() {
  rememberPaneChrome('open')
  revealWaitPane('open')
  try {
    if (SDK_HOST && typeof SDK_HOST.revealPane === 'function') SDK_HOST.revealPane(PANE_ID)
  } catch {
    // The event above already covers older layouts.
  }
}

// Esc closes the pane while the person is working in it (focus inside the pane),
// and never while they are typing in the chat composer beside it.
function usePaneEscape(rootRef, onClose) {
  useEffect(() => {
    const onKey = event => {
      if (event.key !== 'Escape') return
      const root = rootRef && rootRef.current
      const focused = typeof document !== 'undefined' && document.activeElement
      if (!root || !focused || !root.contains(focused)) return
      event.stopPropagation()
      onClose()
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [rootRef, onClose])
}

// A floating choice (start-over confirm, ladder ask) also closes on Esc and on a
// click anywhere outside it, the same way every dialog in the app does.
function useOutsideDone(open, ref, onDone) {
  useEffect(() => {
    if (!open) return undefined
    const onKey = event => {
      if (event.key !== 'Escape') return
      event.stopPropagation()
      onDone()
    }
    const onClick = event => {
      const box = ref && ref.current
      if (box && event.target instanceof Node && box.contains(event.target)) return
      onDone()
    }
    window.addEventListener('keydown', onKey)
    window.addEventListener('pointerdown', onClick, true)
    return () => {
      window.removeEventListener('keydown', onKey)
      window.removeEventListener('pointerdown', onClick, true)
    }
  }, [open, ref, onDone])
}

// The four strengths, in the owner's words. /opponents carries the same ids with
// the server's own labels; this fallback keeps the pane honest on an older host.
const LEVEL_CHOICES = [
  { id: 'beginner', label: 'Beginner' },
  { id: 'intermediate', label: 'Intermediate' },
  { id: 'advanced', label: 'Advanced' },
  { id: 'expert', label: 'Expert' }
]
// The same words keyed by id, for whatever strengths a server advertises.
const LEVEL_LABELS = { beginner: 'Beginner', intermediate: 'Intermediate', advanced: 'Advanced', expert: 'Expert', easy: 'Beginner', normal: 'Intermediate', hard: 'Advanced' }

// ---- 64-leagues.js: bots, leagues, card bouts and watching, inside the Lobby tab
//
// Everything here comes from the server's own answer (shelf/online_source.py caches it
// for twenty seconds). No number on this screen is invented: a section with nothing to
// show says so, in a sentence a person can act on.
//
// The plugin's jsx() takes children inside the props object (that is the shape the rest
// of these parts use), so every element here is written as jsx(tag, { …, children }).

// FUTURE(2026-11-11): the Stock league "Read the design" — remove if never built.
// A stock league plays a server-owned character instead of somebody's own bot: it is designed
// (docs/STOCK-LEAGUE.md) and not built, and its "Read the design" button opened a short list of
// what it would need. The row is kept whole; this line keeps it off the screen, so completing the
// design is un-hiding it rather than rebuilding it.
const STOCK_LEAGUE_OFF = true

function leagueOf(online) {
  const league = (online && online.league) || {}
  const rows = value => (Array.isArray(value) ? value.filter(row => row && typeof row === 'object') : [])
  return {
    ranked: rows(league.ranked_games),
    casual: rows(league.casual_games),
    pairLegs: Number(league.pair_legs || 2),
    live: rows(league.live),
    passports: rows(league.passports),
    challenges: rows(league.challenges),
    cards: rows(league.cards),
    open: league.open || {},
    stock: league.stock || {},
    at: Number(league.at || 0)
  }
}

function leagueGameName(row) {
  return String((row && (row.title || row.id)) || '')
}

function bestRating(bot) {
  const games = Array.isArray(bot && bot.games) ? bot.games : []
  if (!games.length) return 'No rated games yet'
  const best = games.slice().sort((one, two) => Number(two.rating || 0) - Number(one.rating || 0))[0]
  return `${leagueGameName(best)} ${best.rating}${best.provisional ? ' (provisional)' : ''}`
}

function smallLine(text, style) {
  return jsx('div', { style: { fontSize: 12, color: text.tertiary, lineHeight: 1.45, ...(style || {}) }, children: text })
}

// One bot's row: name, owner, best rating, and the way in.
function passportRow(bot, onChallenge, ctx, lobbyBase, setNote) {
  return jsx('div', {
    style: { display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8, padding: '6px 0', borderTop: `1px solid ${stroke}` },
    children: [
      jsx('div', {
        style: { display: 'flex', flexDirection: 'column', gap: 2, minWidth: 0 },
        children: [
          jsx('div', { style: { fontSize: 12, fontWeight: 650, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }, children: bot.name }),
          smallLine(`${bot.owner ? `owned by ${bot.owner} · ` : ''}${bestRating(bot)}`)
        ]
      }),
      jsxs('div', { style: { display: 'flex', gap: 6, alignItems: 'center', flexWrap: 'wrap', justifyContent: 'flex-end' }, children: [
        // The passport page is a real page on the lobby server; this only hands
        // its address to the person's browser.
        browserButton(ctx, `${lobbyBase}/b/${encodeURIComponent(String(bot.id || ''))}`, setNote, {
          title: `Opens ${bot.name}'s passport at ${lobbyBase}/b/${bot.id} in your browser — the online lobby, outside Hermes.`
        }),
        button('Challenge', () => onChallenge(bot), {
          primary: true,
          title: `Ask ${bot.name}'s owner to bring it to a table. The invitation waits ten minutes.`
        })
      ] })
    ]
  })
}

function challengeCard(bot, games, busy, onPick, onSend, onCancel) {
  return jsx('div', {
    role: 'group', 'aria-label': `Challenge ${bot.name}`,
    style: { display: 'flex', flexDirection: 'column', gap: 6, border: `1px solid ${accent}`, borderRadius: 8, padding: '8px 10px' },
    children: [
      jsx('div', { style: { fontSize: 12, fontWeight: 650 }, children: `Challenge ${bot.name}` }),
      smallLine('Pick the game. The invitation goes to the bot\'s owner, who brings their bot to the table.'),
      jsx('div', {
        style: { display: 'flex', gap: 6, flexWrap: 'wrap' },
        children: games.slice(0, 8).map(game => button(leagueGameName(game), () => onPick(game.id), {
          primary: Boolean(bot.game === game.id)
        }))
      }),
      jsx('div', {
        style: { display: 'flex', gap: 6 },
        children: [
          button('Send challenge', onSend, { primary: true, disabled: busy || !bot.game }),
          button('Cancel', onCancel, { disabled: busy })
        ]
      })
    ]
  })
}

// The address always comes from the online lobby URL setting (view.online.url),
// never from a host written into this file.
function lobbyBaseOf(online) {
  return String((online && online.url) || ONLINE_URL).replace(/\/+$/, '')
}

async function openTable(room, ctx, lobbyBase) {
  const url = `${lobbyBase}/t/${encodeURIComponent(String(room && room.id ? room.id : ''))}`
  // Only a web address may reach the operating system's handler: a lobby address with
  // another scheme would hand the click to whatever registered it (openInBrowser's rule).
  if (!/^https?:\/\//i.test(url)) return url
  try {
    if (ctx && ctx.os && typeof ctx.os.openExternal === 'function') {
      await ctx.os.openExternal(url)
      return url
    }
  } catch {
    /* the address line beside the button is the fallback */
  }
  return url
}

function liveRow(room, ctx, lobbyBase) {
  const seats = Array.isArray(room.seats) ? room.seats : []
  const white = seats.find(seat => seat.side === 'white') || {}
  const black = seats.find(seat => seat.side === 'black') || {}
  return jsx('div', {
    style: { display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8, padding: '6px 0', borderTop: `1px solid ${stroke}` },
    children: [
      jsx('div', {
        style: { display: 'flex', flexDirection: 'column', gap: 2, minWidth: 0 },
        children: [
          jsx('div', { style: { fontSize: 12, fontWeight: 650 }, children: `${white.name || 'Bot'} v ${black.name || 'Bot'}` }),
          smallLine(`${room.title || room.game} · move ${Number(room.plies || 0) + 1}${room.pair && room.pair.leg ? ` · leg ${room.pair.leg} of ${room.pair.legs}` : ''}`)
        ]
      }),
      button('Watch', () => openTable(room, ctx, lobbyBase), { title: `Opens the live table at ${lobbyBase}/t/${room.id} in your browser — the online lobby, outside Hermes. Watching is read-only.` })
    ]
  })
}

function BotsLeagues({ online, busy, call, ctx, setNote }) {
  const [challenge, setChallenge] = useState(null)
  const [cardPick, setCardPick] = useState(null)
  const [opponents, setOpponents] = useState([])
  const [bout, setBout] = useState(null)
  const [replay, setReplay] = useState('')
  const [showStock, setShowStock] = useState(false)
  const league = leagueOf(online)
  const games = league.ranked
  const lobbyBase = lobbyBaseOf(online)

  const sendChallenge = async () => {
    if (!challenge || !challenge.game) return
    const answer = await call('/online/challenge', { bot: challenge.id, game: challenge.game })
    setNote((answer && answer.text) || '')
    if (answer && answer.ok) setChallenge(null)
  }

  const loadOpponents = async game => {
    const answer = await call('/online/cards/public?game=' + encodeURIComponent(game), undefined, 'GET')
    setOpponents((answer && answer.cards) || [])
    setBout(null)
    setReplay('')
  }

  const playBout = async (mine, theirs) => {
    const answer = await call('/online/bout', { game: cardPick.game, mine, theirs })
    setNote((answer && answer.text) || '')
    if (answer && answer.ok) setBout(answer.bout || null)
  }

  const showReplay = async () => {
    if (!bout) return
    const answer = await call('/online/bout/replay?url=' + encodeURIComponent(bout.replay_url || ''), undefined, 'GET')
    if (!answer || !answer.ok) {
      setReplay('That replay could not be read.')
      return
    }
    const data = (answer.replay && answer.replay.replay) || {}
    const frames = Array.isArray(data.frames) ? data.frames : []
    const last = frames[frames.length - 1] || {}
    const events = Array.isArray(last.events) ? last.events.slice(-4).map(item => String(item)) : []
    setReplay(`Seed ${Number(bout.seed || 0)} · ${frames.length} frames${events.length ? ` · ${events.join(' · ')}` : ''}`)
  }

  const cards = league.cards.filter(card => card && card.game)
  const rankLine = league.casual.length
    ? `Ranked games are played twice on the same deal with the seats swapped, so one rating follows both legs. ${league.casual.map(leagueGameName).join(', ')} stay casual.`
    : 'Ranked games are played twice on the same deal with the seats swapped, so one rating follows both legs.'

  const challenges = league.challenges.length
    ? league.challenges.map(row => jsx('div', {
        style: { display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8, padding: '6px 0', borderTop: `1px solid ${stroke}` },
        children: [
          jsx('div', {
            style: { display: 'flex', flexDirection: 'column', gap: 2 },
            children: [
              jsx('div', { style: { fontSize: 12, fontWeight: 650 }, children: `${row.challenger} invited ${row.bot_name}` }),
              smallLine(`${row.game} · expires in ${Math.max(0, Math.round((Number(row.expires || 0) - Date.now() / 1000) / 60))} min`)
            ]
          }),
          button('Decline', () => call('/online/challenge/decline', { id: row.id }), { disabled: busy })
        ]
      }))
    : [smallLine('No invitations right now.')]

  const live = league.live.length
    ? league.live.slice(0, 5).map(room => liveRow(room, ctx, lobbyBase))
    : [smallLine('No bot games are running.')]

  const passports = league.passports.length
    ? league.passports.slice(0, 6).map(bot => passportRow(bot, setChallenge, ctx, lobbyBase, setNote))
    : [smallLine('No bots have played yet. Your own bot appears here once it has a rated game.')]

  const cardRows = cards.length
    ? cards.map(card => jsx('div', {
        style: { display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8, padding: '5px 0', borderTop: `1px solid ${stroke}` },
        children: [
          jsx('div', {
            style: { display: 'flex', flexDirection: 'column', gap: 2 },
            children: [
              jsx('div', { style: { fontSize: 12, fontWeight: 650 }, children: card.name }),
              smallLine(`${card.game === 'doctrine_arena' ? 'Doctrine Arena' : 'Doctrine'} · ${card.rating && card.rating.games ? `rating ${card.rating.rating}` : 'unrated'}`)
            ]
          }),
          button('Play a bout', () => { setCardPick({ game: card.game, mine: card.id }); loadOpponents(card.game) }, { primary: true, disabled: busy })
        ]
      }))
    : [smallLine('No cards yet. Cards you save in Doctrine appear here.')]

  const boutPanel = cardPick ? jsx('div', {
    style: { display: 'flex', flexDirection: 'column', gap: 6, border: `1px solid ${accent}`, borderRadius: 8, padding: '8px 10px' },
    children: [
      jsx('div', { style: { fontSize: 12, fontWeight: 650 }, children: `Opponent card (${cardPick.game === 'doctrine_arena' ? 'Arena' : 'Doctrine'})` }),
      opponents.length
        ? jsx('div', {
            style: { display: 'flex', gap: 6, flexWrap: 'wrap' },
            children: opponents.slice(0, 8).map(card =>
              button(card.name, () => playBout(cardPick.mine, card.id), { disabled: busy, title: card.owner }))
          })
        : smallLine('No other owner has a card for this game yet.'),
      jsx('div', {
        style: { display: 'flex', gap: 6 },
        children: [button('Close', () => { setCardPick(null); setOpponents([]) }, { disabled: busy })]
      }),
      bout ? jsx('div', {
        style: { display: 'flex', flexDirection: 'column', gap: 4 },
        children: [
          jsx('div', { role: 'status', 'aria-live': 'polite', style: { fontSize: 12 }, children: bout.winner ? `${bout.winner_name} won` : 'A draw' }),
          jsx('div', {
            style: { display: 'flex', gap: 6, flexWrap: 'wrap' },
            children: [
              button('View replay', showReplay),
              // The replay itself is stored on the lobby server. bout.replay_url
              // arrives as a server-relative path (/api/card-arena/…); the button
              // prefixes the lobby URL setting to make it openable, never a guess.
              browserButton(ctx, bout.replay_url
                ? (/^https?:\/\//i.test(String(bout.replay_url)) ? String(bout.replay_url) : `${lobbyBase}${String(bout.replay_url)}`)
                : '', setNote, {
                title: bout.replay_url
                  ? `Opens this bout's replay in your browser — the online lobby, outside Hermes.`
                  : 'No replay address came back from the lobby server.'
              }),
              smallLine(`${bout.plies} frames`, { alignSelf: 'center' })
            ]
          }),
          replay ? smallLine(replay, { fontFamily: 'var(--font-mono, ui-monospace, monospace)' }) : null
        ]
      }) : null
    ]
  }) : null

  const stockNeeds = Array.isArray(league.stock.needs)
    ? league.stock.needs.map((line, index) => jsx('div', { key: `need-${index}`, children: smallLine(`• ${line}`) }))
    : []
  const stockNext = Array.isArray(league.stock.next)
    ? league.stock.next.slice(0, 2).map((line, index) => jsx('div', { key: `next-${index}`, children: smallLine(`• ${line}`) }))
    : []

  return jsx('section', {
    'aria-label': 'Bots and leagues',
    style: { display: 'flex', flexDirection: 'column', gap: 8, border: `1px solid ${stroke}`, borderRadius: 8, padding: '8px 10px' },
    children: [
      jsx('div', {
        style: { display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' },
        children: [
          jsx('div', { style: { fontWeight: 650, fontSize: 13 }, children: 'Bots and leagues' }),
          badge('Labs · experiment')
        ]
      }),
      smallLine(rankLine),
      jsx('div', {
        style: { display: 'flex', flexDirection: 'column', gap: 4 },
        children: [heading('Waiting for your bot'), ...challenges]
      }),
      jsx('div', {
        style: { display: 'flex', flexDirection: 'column', gap: 4 },
        children: [
          heading('Watch a game'),
          ...live,
          smallLine(`Live tables open at ${lobbyBase} in your browser — the online lobby, outside Hermes. Watching is read-only.`)
        ]
      }),
      jsx('div', {
        style: { display: 'flex', flexDirection: 'column', gap: 4 },
        children: [
          heading('Bot passports'),
          ...passports,
          challenge ? challengeCard(challenge, games, busy, game => setChallenge({ ...challenge, game }), sendChallenge, () => setChallenge(null)) : null
        ]
      }),
      jsx('div', {
        style: { display: 'flex', flexDirection: 'column', gap: 4 },
        children: [
          heading('Card arena'),
          smallLine('Two owners\' locked Doctrine cards, played by the server. Rated, with a replay.'),
          ...cardRows,
          boutPanel
        ]
      }),
      jsx('div', {
        style: { display: 'flex', flexDirection: 'column', gap: 4 },
        children: [
          heading('Open league'),
          jsx('div', {
            style: { display: 'flex', alignItems: 'center', gap: 6, flexWrap: 'wrap' },
            children: [
              badge(league.open.badge || 'self-hosted, unverified'),
              smallLine(`${Number(league.open.move_seconds || 30)} seconds a move`)
            ]
          }),
          smallLine(league.open.text || 'Everyone plays from their own computer. The server only referees and keeps the clock, so a seat cannot be checked: self-hosted, unverified.'),
          button('Enter the open league', () => call('/online/ladder', { action: 'start', game: (games[0] || {}).id || '', open_league: true }), {
            disabled: busy || !games.length,
            title: 'Your model plays from this computer, with a thirty-second clock.'
          })
        ]
      }),
      STOCK_LEAGUE_OFF ? null : jsx('div', {
        style: { display: 'flex', flexDirection: 'column', gap: 4, opacity: 0.75 },
        children: [
          jsx('div', {
            style: { display: 'flex', alignItems: 'center', gap: 6, flexWrap: 'wrap' },
            children: [
              heading('Stock league'),
              badge('Labs · experiment'),
              smallLine('needs a server-side model')
            ]
          }),
          smallLine((league.stock && league.stock.text) || 'A stock league plays a server-owned character instead of someone\'s own bot. It is designed, not built.'),
          button(showStock ? 'Hide the design' : 'Read the design', () => setShowStock(!showStock), { disabled: busy }),
          showStock ? jsx('div', {
            style: { display: 'flex', flexDirection: 'column', gap: 4 },
            children: [
              smallLine('What it needs:', { fontWeight: 650, color: text.secondary }),
              ...stockNeeds,
              smallLine('The first step:', { fontWeight: 650, color: text.secondary }),
              ...stockNext
            ]
          }) : null
        ]
      })
    ]
  })
}

// ---- 65-wait-pane.js: the pane itself, and the status-bar badge that opens it

// FUTURE(2026-11-11): the bot ladder on the pane — remove if never built.
// Rated bot-versus-bot works server-side, but it is not proven end to end and a person in the pane
// has no way to follow it (the model calls happen on this computer, the game on the lobby server).
// It belongs with Champions. The section below is kept whole; this one line is what keeps it off
// the pane, so bringing it back is flipping a boolean rather than rebuilding it.
const PANE_LADDER_OFF = true
// FUTURE(2026-11-11): Bots & leagues on the pane — remove if never built.
// Leagues, watching a live table and bot passports all work against the lobby server, but watching
// leaves Hermes for the browser and the pane is not where a league belongs. The block is kept
// whole; this line hides it on the pane (it is the only surface that mounts it).
const PANE_LEAGUES_OFF = true
// FUTURE(2026-11-11): the online-alert checkbox on the pane — remove if never built.
// "Tell me when someone online wants this game" saves its flag, but the system notification it
// promises returns immediately, so the switch would promise an alert nothing raises. Kept whole;
// this line hides it.
const PANE_ONLINE_ALERT_OFF = true

function WaitPane({ ctx }) {
  const saved = useRef(savedPaneGame(ctx))
  const [view, setView] = useState(null)
  const [gameId, setGameId] = useState(saved.current)
  const [board, setBoard] = useState({ text: '', picture: null })
  const [reply, setReply] = useState('')
  const [problem, setProblem] = useState('')
  const [tab, setTab] = useState('game')
  // JACKPOT v2 in the pane. It is not a server game (no /board), so it is its own view rather than a
  // tile in the curated picker; the machine reads the same wallet through the same routes.
  const [jackpot, setJackpot] = useState(false)
  const [working, setWorking] = useState(false)
  const [error, setError] = useState('')
  const [chat, setChat] = useState('')
  const [name, setName] = useState('')
  const [alerts, setAlerts] = useState(() => paneAlerts(ctx))
  const [restarting, setRestarting] = useState(false)
  // Start over / new game: NOTHING is chosen until the person chooses (owner's ask, 2026-11-11).
  // '' means neither radio, which is also what keeps Start disabled: no game is ever dealt against
  // an opponent the person did not name.
  const [dealWho, setDealWho] = useState('')
  // The route the person picked in the shared ModelPicker, and the routes this Hermes has (read
  // when the model choice is first opened, never on a pane that does not touch it).
  const [dealModel, setDealModel] = useState('')
  const [modelRoutes, setModelRoutes] = useState([])
  const [onlineBusy, setOnlineBusy] = useState(false)
  const [onlineNote, setOnlineNote] = useState('')
  const [onlineProblem, setOnlineProblem] = useState('')
  const [keyToCopy, setKeyToCopy] = useState('')
  const [onlineName, setOnlineName] = useState('')
  const [onlineKey, setOnlineKey] = useState('')
  const [ladderAsk, setLadderAsk] = useState(null)
  const [ladderChampion, setLadderChampion] = useState('')
  // "Play here": the room of a match the lobby handed over, played in this pane on the server
  // table rather than in a browser. Empty means the pane is on its own quick games.
  const [onlineRoom, setOnlineRoom] = useState('')
  const [playingHere, setPlayingHere] = useState(false)
  // Out of the way: 'open' | 'min' | 'closed', remembered for the session.
  const [chrome, setChrome] = useState(paneChromePref)
  const [level, setLevel] = useState(QUICK_LEVEL)
  // The move the person has just made, drawn at once (12-board-input.js pendingCells).
  // A model or a search takes its time to answer, and the person's own move must land
  // the moment they make it, never after the answer (owner's report 2026-11-10: "moving
  // a piece versus the computer takes noticeably long before the piece lands").
  const [preview, setPreview] = useState(null)
  const [boardH, setBoardH] = useState(300)
  // Backgammon's dice have a state of their own (waiting behind Roll, tumbling, spent) that the
  // picture cannot carry: the board reports it and the one status line below says it.
  const [bgPhase, setBgPhase] = useState('move')
  // Settings, in the pane: the very same rows the Games app shows, from the same component, so the
  // two can never drift. The skin is the page's own hook, so the Look switch here writes the same
  // storage key and nothing new is invented.
  const [settings, setSettings] = useState(false)
  const [skin, setSkin] = useSkin(ctx)
  const rootBox = useRef(null)
  const confirmBox = useRef(null)
  const ladderBox = useRef(null)
  const boardBox = useRef(null)
  const toldOnline = useRef(0)
  const latest = useRef({ game: saved.current, board: null })
  const alive = useRef(true)
  // Every load takes a number. A slow answer for game A that arrives after the
  // person moved to game B is dropped instead of painting A's board under B.
  const generation = useRef(0)
  const busy = useChatBusy()
  const finished = useHermesFinished(busy)
  const approval = useApprovalNotice()

  useEffect(() => {
    alive.current = true
    return () => { alive.current = false }
  }, [])

  // The status bar and the palette can restore the pane from anywhere; when they
  // do, this instance follows the session pref instead of its stale state.
  useEffect(() => {
    const sync = () => setChrome(paneChromePref())
    window.addEventListener(PANE_CHROME_EVENT, sync)
    return () => window.removeEventListener(PANE_CHROME_EVENT, sync)
  }, [])

  const collapse = useCallback(() => {
    setChrome('closed')
    closeWaitPane()
  }, [])
  usePaneEscape(rootBox, collapse)
  useOutsideDone(Boolean(restarting), confirmBox, () => setRestarting(false))
  useOutsideDone(Boolean(ladderAsk), ladderBox, () => setLadderAsk(null))

  // Boards scale with the pane: the same BoardSvg, sized to the width it gets.
  useEffect(() => {
    if (typeof ResizeObserver === 'undefined' || !boardBox.current) return undefined
    const meter = new ResizeObserver(entries => {
      const width = entries && entries[0] && entries[0].contentRect ? entries[0].contentRect.width : 0
      if (width > 120) setBoardH(Math.max(200, Math.min(460, Math.round(width * 0.92))))
    })
    meter.observe(boardBox.current)
    return () => meter.disconnect()
  }, [])

  const widen = () => {
    setChrome('open')
    restoreWaitPane()
  }

  // A game whose board keeps failing is set aside for a minute so the pane moves on to
  // another game instead of retrying the broken one forever.
  const boardMisses = useRef({ game: '', count: 0 })
  const setAside = useRef(new Map())

  // The last board is never left on screen across a game switch or a new deal, and a
  // move drawn ahead of its answer must not outlive the answer either.
  const clearBoard = () => {
    setPreview(null)
    setBoard({ text: '', picture: null })
  }

  const load = useCallback(async (id, known) => {
    const wanted = id === undefined ? latest.current.game : id
    // Only a game the person picked (or a new deal) makes the reads already on their way stale. A
    // plain poll repeats the same intent, so it must not invalidate the read that is already in
    // flight: bumping the generation on every poll made the pane blind whenever /view took longer
    // than the one-second poll — each response was superseded before it landed, so the picker sat on
    // "No curated games are installed here." for seconds after opening (owner's report, 2026-11-11).
    // The Games page's own refresh already has this shape: its selection generation moves on a pick.
    const mine = id === undefined ? generation.current : generation.current + 1
    generation.current = mine
    try {
      const next = await ctx.rest('/view')
      if (!alive.current || generation.current !== mine) return
      setView(next)
      setError('')
      const now = Date.now()
      setAside.current.forEach((until, game) => { if (until <= now) setAside.current.delete(game) })
      const usable = { ...next, play: ((next && next.play) || []).filter(item => !setAside.current.has(item.id)) }
      const chosen = paneGame(usable, wanted)
      if (!chosen) {
        latest.current = { game: '', board: null }
        if (alive.current && generation.current === mine) setBoard({ text: '', picture: null })
        return
      }
      let shown
      // A caller that already holds the board for this game (a move's own reply carries
      // one) hands it over instead of reading it again: the answer is the authority, and
      // the second round trip only delayed the paint.
      if (known && known.game === chosen) {
        shown = { text: '', picture: known }
      } else {
        try {
          shown = await ctx.rest(`/board?game=${encodeURIComponent(chosen)}`)
        } catch (failure) {
          if (!alive.current || generation.current !== mine) return
          const misses = boardMisses.current.game === chosen ? boardMisses.current.count + 1 : 1
          boardMisses.current = { game: chosen, count: misses }
          if (misses >= 2) {
            setAside.current.set(chosen, Date.now() + 60000)
            boardMisses.current = { game: '', count: 0 }
            latest.current = { game: '', board: null }
            paneWatch.game = ''
            storeValue(ctx, PANE_GAME_KEY, '')
            setBoard({ text: '', picture: null })
            setError(`${chosen} could not load, so the pane moved to another game. It will try ${chosen} again in a minute.`)
          }
          return
        }
      }
      if (!alive.current || generation.current !== mine) return
      boardMisses.current = { game: '', count: 0 }
      latest.current = { game: chosen, board: shown.picture || null }
      paneWatch.game = chosen
      rememberPaneGame(ctx, chosen)
      setGameId(chosen)
      setPreview(null)
      setBoard({ text: shown.text || '', picture: shown.picture || null })
    } catch {
      if (alive.current && generation.current === mine) {
        setError('The pane cannot reach Game Center yet. It tries again every few seconds.')
      }
    }
  }, [ctx])

  useEffect(() => {
    load()
    // The waiting pane is watched, not glanced at: a three-second poll is why the machine in it
    // moved a beat behind the person. It now reads every second, and the board itself only when the
    // game changed or three seconds have passed, so the extra reads stay cheap (owner's report,
    // 2026-11-09: "the slot machine in 'Play while you wait' has latency of a few seconds").
    const timer = setInterval(() => load(), 1000)
    return () => clearInterval(timer)
  }, [load])

  // A message being sent spins the machine: ask straight away instead of waiting for the next tick.
  useEffect(() => {
    if (!SDK_HOST || typeof SDK_HOST.onEvent !== 'function') return undefined
    let stop = () => {}
    try {
      stop = SDK_HOST.onEvent('message.start', () => load()) || stop
    } catch {
      // An older host has no event stream; the one-second poll still catches the spin.
    }
    return () => { try { stop() } catch { /* nothing to unwire */ } }
  }, [load])

  // An online alert, told once, never while a table of the person's own is
  // running or waiting: that gets the match line, not a notification.
  useEffect(() => {
    const fresh = view && view.online && view.online.alert
    if (!fresh || !fresh.at || Number(fresh.at) <= toldOnline.current) return
    const pictured = latest.current.board
    if (pictured && pictured.status === 'active') return
    if (view.online && view.online.match) return
    toldOnline.current = Number(fresh.at)
    notifyOnline(ctx, fresh)
  }, [view, ctx])

  const say = useCallback(async line => {
    try {
      const answer = await ctx.rest('/command', { method: 'POST', body: { line } })
      if (alive.current) {
        setReply(answer && answer.text || '')
        setProblem(answer && answer.ok === false ? (answer.text || 'That did not work.') : '')
      }
      return answer || {}
    } catch {
      if (alive.current) {
        setReply('')
        setProblem('That did not reach Game Center. Try again.')
      }
      return { ok: false }
    }
  }, [ctx])

  // One door for every online action: the answer carries the new online view, so
  // the page paints the server's own answer instead of guessing at it.
  const onlineCall = useCallback(async (path, body, method) => {
    setOnlineBusy(true)
    setOnlineProblem('')
    try {
      const options = body === undefined ? { method: method || 'POST' } : { method: 'POST', body }
      const answer = await ctx.rest(path, options)
      if (!alive.current) return {}
      if (answer && answer.online) {
        setView(current => ({ ...(current || {}), online: answer.online }))
      }
      if (answer && answer.key_to_copy) setKeyToCopy(String(answer.key_to_copy))
      setOnlineNote((answer && answer.text) || '')
      if (answer && answer.ok === false) setOnlineProblem(String(answer.text || 'That did not work.'))
      return answer || {}
    } catch {
      if (alive.current) setOnlineProblem('That did not reach Game Center. Try again.')
      return { ok: false }
    } finally {
      if (alive.current) setOnlineBusy(false)
    }
  }, [ctx])

  // "Play here": open the room on the lobby server, then play it in this pane. It is the same
  // server match the browser would show — the person just does not have to leave Hermes for it.
  const playHere = useCallback(async match => {
    if (playingHere) return
    setPlayingHere(true)
    setOnlineProblem('')
    try {
      const answer = await openOnlineTable(ctx, match && match.room_id, match && match.game)
      if (answer && answer.ok === false) {
        if (alive.current) setOnlineProblem(String(answer.text || 'That table would not open.'))
        return
      }
      if (alive.current) setOnlineRoom(String((match && match.room_id) || ''))
    } finally {
      if (alive.current) setPlayingHere(false)
    }
  }, [ctx, playingHere])

  const showLadderAsk = useCallback(async () => {
    const chosen = latest.current.game
    if (!chosen) return
    setOnlineBusy(true)
    setOnlineProblem('')
    try {
      const answer = await ctx.rest(`/online/ladder?game=${encodeURIComponent(chosen)}`)
      if (alive.current) setLadderAsk(answer || null)
    } catch {
      if (alive.current) setOnlineProblem('The ladder cannot be reached right now.')
    } finally {
      if (alive.current) setOnlineBusy(false)
    }
  }, [ctx])

  const start = async (id, who, atLevel = level) => {
    if (!id || working) return
    setWorking(true)
    setReply('')
    setRestarting(false)
    // The old board must not stay pressable under the new game's name while its own
    // board is on the way.
    clearBoard()
    try {
      const answer = await say(quickGameLine(id, who, atLevel))
      if (answer.ok === false) return
      latest.current = { game: id, board: null }
      paneWatch.game = id
      setGameId(id)
      rememberPaneGame(ctx, id)
      setTab('game')
      await load(id)
    } finally {
      if (alive.current) setWorking(false)
    }
  }

  const move = async (id, token) => {
    // Only the board that is on screen may be played, and only for the game it belongs to.
    if (!id || working || id !== latest.current.game) return
    setWorking(true)
    try {
      const pictured = latest.current.board
      const needsNew = !pictured || pictured.preview || pictured.status === 'idle' || pictured.status === 'abandoned'
      if (needsNew) {
        const started = await say(quickGameLine(id, 'computer', level))
        if (started.ok === false) return
      }
      const answer = await say(`${id} move ${token}`)
      if (answer.ok === false) return
      // The move line's own answer carries the board it left behind - the person's move
      // and the computer's answer - so the paint happens here, the moment it arrives,
      // instead of waiting for the read below (owner's report 2026-11-10).
      if (answer.picture) {
        latest.current = { game: id, board: answer.picture }
        paneWatch.game = id
        setBoard({ text: answer.text || '', picture: answer.picture })
      }
      await load(id, answer.picture || null)
    } finally {
      if (alive.current) { setWorking(false); setPreview(null) }
    }
  }

  // Starting over while a game is active: resign it, then deal a new one against the
  // chosen opponent. Two presses, never a surprise. A house table (Blackjack) never
  // "finishes", so this is also how its opponent is changed.
  const restart = async (id, who = 'computer') => {
    if (!id || working) return
    setRestarting(false)
    setWorking(true)
    setReply('')
    try {
      const resigned = await say(`${id} resign`)
      if (resigned.ok === false) return
      const started = await say(quickGameLine(id, who, level))
      if (started.ok === false) return
      latest.current = { game: id, board: null }
      paneWatch.game = id
      rememberPaneGame(ctx, id)
      clearBoard()
      await load(id)
    } finally {
      if (alive.current) setWorking(false)
    }
  }

  const chooseGame = async id => {
    if (!id) return
    setRestarting(false)
    // Picking a table puts the cabinet away: one surface at a time in a pane this narrow.
    setJackpot(false)
    latest.current = { game: id, board: null }
    paneWatch.game = id
    setGameId(id)
    rememberPaneGame(ctx, id)
    setReply('')
    // The previous game's board is not this game's board: clear it before the new one
    // arrives, so no press on it can be sent to the game the picker just chose.
    clearBoard()
    await load(id)
  }

  const saveAlerts = next => {
    setAlerts(next)
    storeValue(ctx, PANE_ALERTS_KEY, next)
  }

  const toggleAlert = id => saveAlerts({ ...alerts, games: { ...alerts.games, [id]: !alerts.games[id] } })
  const togglePaused = () => saveAlerts({ ...alerts, paused: !alerts.paused })

  const games = paneGames(view)
  const game = games.find(item => item.id === gameId) || games[0] || null
  const soloGame = Boolean(game && game.solo)
  const current = game ? game.id : ''
  const pictured = board.picture || (board.text ? null : game ? startingPicture(game.id) : null)
  const access = pictured ? tableAccess(pictured, view) : { can_move: false }
  const playingNow = Boolean(pictured && pictured.status === 'active')
  // A table whose other seat can be a machine: every board game, and a solo table that
  // seats one (Blackjack's dealer). Slots seats nobody, so it offers no opponent at all.
  const seatsNobody = gameSeatsNobody(game, pictured)
  const aiSeats = Boolean(!seatsNobody && (!soloGame || (game && game.bots !== false)))
  // The wait line under the board, and its clock: the pane names whose move it is, with the
  // seconds running, from the moment the wait begins (owner's ask, 2026-11-11).
  const paneWait = pictured && pictured.status === 'active' ? waitWords(pictured, view, { working }) : ''
  const waited = useWaitSeconds(Boolean(paneWait))
  // "Start over" / "New game": ONE door, and the opponent is chosen inside it - never assumed.
  // The dialog opens with nothing picked and Start disabled (owner's ask, 2026-11-11), so no game
  // is ever dealt against an opponent the person did not name, and the words always match the pick.
  const playedNow = Number((latest.current.board || {}).plies || 0) > 0
  // Whether a deal ends something here: a board game in play, or a solo session with hands behind
  // it. Only then does the confirm resign first; a fresh table is a single press (the server's rule).
  const endsSomething = soloGame ? playedNow : playingNow
  const dealWords = who => (who === 'agent' ? 'your Hermes model' : 'the computer')
  const dealLine = () => {
    const against = dealWho ? ` against ${dealWords(dealWho)}` : ''
    if (soloGame) return endsSomething
      ? `Starting over ends this session and deals a new one${against}.`
      : `A new session${against}. Chips already bet on a settled hand stay settled.`
    return endsSomething
      ? `Starting over resigns this game and deals a new one${against}.`
      : `A new game${against}.`
  }
  const openDeal = () => {
    if (!current || working) return
    setDealWho('')
    setReply('')
    setRestarting(true)
  }
  const deal = () => {
    if (!current || working || !dealWho) return
    const who = dealWho === 'agent' ? 'agent' : 'computer'
    setRestarting(false)
    setDealWho('')
    return endsSomething ? restart(current, who) : start(current, who)
  }
  // The routes this Hermes may hand a seat, for the shared ModelPicker. It is read the first time
  // the model choice is opened: a pane that never touches it sends no request. A host without the
  // route leaves the picker with the one entry every seat has (this Hermes's own chat model).
  useEffect(() => {
    if (!restarting || dealWho !== 'agent' || modelRoutes.length) return undefined
    let live = true
    const load = async () => {
      try {
        const answer = await ctx.rest('/models')
        if (live && answer && answer.ok !== false && Array.isArray(answer.routes)) setModelRoutes(answer.routes)
      } catch (failure) {
        // Nothing to list: the seat's own model is still named in words above the picker.
      }
    }
    load()
    return () => { live = false }
  }, [restarting, dealWho, modelRoutes.length, ctx])
  const lobby = (view && view.lobby) || { lines: [], looking: [] }
  const myName = (view && view.player && view.player.name) || ''
  const found = current ? othersLooking(lobby, current, myName) : []

  // Out of the way beats everything else: a slim strip with one way back. The
  // polls above keep running quietly, so the dot still means your turn.
  if (chrome !== 'open') {
    const stripTurn = myTurn(latest.current.board, view)
    return jsx('div', {
      className: 'games-wait-pane-strip',
      style: { height: 34, display: 'flex', alignItems: 'center', background: paper, boxSizing: 'border-box' },
      children: jsx('button', {
        type: 'button',
        'aria-label': 'Games. Restore the play pane',
        title: 'Play while you code — restore the pane',
        onClick: widen,
        style: {
          display: 'flex', width: '100%', height: '100%', alignItems: 'center', gap: 8,
          padding: '0 12px', border: 'none', background: 'transparent',
          color: text.secondary, fontSize: 12, fontWeight: 650, cursor: 'pointer'
        },
        children: [
          jsx('span', { children: 'Games' }),
          stripTurn ? jsx('span', {
            'aria-hidden': true,
            'data-dot': 'turn',
            style: { width: 6, height: 6, borderRadius: '50%', background: accent, display: 'inline-block' }
          }) : null,
          jsx('span', { style: { fontWeight: 400, color: text.tertiary }, children: '— tap to reopen' })
        ]
      })
    })
  }

  if (error) {
    return jsx('div', { role: 'alert', style: { padding: 12, fontSize: 12, color: text.secondary }, children: error })
  }

  const iconTitles = {
    'Full screen': 'Open this game in Game Center full screen. The pane closes.',
    Minimize: 'Shrink to a strip. The badge keeps watching.',
    Close: 'Close the pane. The status item and the palette bring it back.',
    Settings: 'Game Center settings — the same ones as in the Games app. Press again to come back to the pane.'
  }
  const iconButton = (glyph, label, onClick) => jsx('button', {
    type: 'button',
    'aria-label': label,
    title: iconTitles[label] || label,
    onClick,
    style: {
      width: 24, height: 24, display: 'inline-flex', alignItems: 'center', justifyContent: 'center',
      border: 'none', background: 'transparent', color: text.tertiary,
      fontSize: 13, lineHeight: 1, cursor: 'pointer', borderRadius: 6, padding: 0
    },
    children: glyph
  })

  const header = jsxs('div', {
    style: { display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8, flexWrap: 'wrap' },
    children: [
      jsx('div', { style: { fontWeight: 700, fontSize: 14 }, children: 'Play while you code' }),
      jsxs('div', { style: { display: 'flex', gap: 6, alignItems: 'center' }, children: [
        button('Game', () => { setSettings(false); setTab('game') }, { primary: tab === 'game' && !settings }),
        button('Lobby', () => { setSettings(false); setTab('lobby') }, { primary: tab === 'lobby' && !settings }),
        // What the person has earned, right here under the two tabs they use most.
        jsx(PointsChip, { ctx, style: { marginLeft: 2 } }),
        // One press in and out of Settings: the full screen's own Settings, in a pane too narrow for
        // the whole page.
        iconButton('⚙', 'Settings', () => setSettings(open => !open)),
        iconButton('⤢', 'Full screen', () => pageFromPane(ctx)),
        iconButton('–', 'Minimize', () => { setChrome('min'); minimizeWaitPane() }),
        iconButton('✕', 'Close', collapse)
      ] })
    ]
  })

  // The pane's Settings view: the Games app's own panel, with a way back welded to the pane. No new
  // storage keys, no second copy of the rows - whatever Settings gains, this gains with it.
  const settingsView = jsx('div', {
    'data-pane-settings': '1',
    style: { flex: '1 1 auto', minHeight: 0, display: 'flex', flexDirection: 'column' },
    // The panel is drawn from the same /view answer the pane already polls; before the first one
    // lands there is nothing to fill its rows from, so the pane says so rather than drawing blanks.
    children: view
      ? jsx(SettingsPanel, {
          view,
          ctx,
          skin,
          onSkin: setSkin,
          backLabel: 'Back to the play pane',
          backTitle: 'Back to the game in this pane',
          onSaved: () => load(),
          onBack: () => setSettings(false)
        })
      : jsx('div', {
          className: 'games-settings',
          style: { padding: 18, fontSize: 12, color: text.tertiary },
          children: 'Reading your settings…'
        })
  })

  // The owner's words for the strengths (product rule), whichever ids the server
  // uses; a level the server really has keeps its own name when it is unmapped.
  // A strength press SETS the strength and nothing else: it never deals a game and never
  // resigns one (owner's ask, 2026-11-11). The strength the next game is dealt at is the one
  // lit here, and the deal itself is the dialog's own Start.
  const serverLevels = ((((view || {}).opponents || []).find(item => item.id === 'computer') || {}).levels || [])
    .filter(item => item && item.id && item.label)
  const levelChoices = serverLevels.length
    ? serverLevels.map(item => ({ id: item.id, label: LEVEL_LABELS[item.id] || item.label }))
    : LEVEL_CHOICES
  const levelRow = jsxs('div', {
    'aria-label': 'Difficulty',
    style: { display: 'flex', gap: 6, flexWrap: 'wrap' },
    children: levelChoices.map(item => jsx('button', {
      type: 'button',
      'data-level': item.id,
      onClick: () => setLevel(item.id),
      disabled: working || !current || !(view && view.allow_ai),
      title: (view && view.allow_ai)
        ? `You vs the computer (${item.label}) in ${(game && game.title) || current}. Free and instant. This only sets the strength; press Start to deal.`
        : 'AI seats are off for this profile.',
      style: {
        padding: '4px 9px', borderRadius: 7, cursor: 'pointer', fontSize: 12, fontWeight: 600,
        border: `1px solid ${item.id === level ? accent : stroke}`,
        background: item.id === level ? fill : 'transparent',
        color: item.id === level ? text.primary : text.secondary
      },
      children: item.label
    }, item.id))
  })

  // How a quick game is dealt, in one plain sentence: the tiles pick the game, the one door
  // under the board picks the opponent, and the strength belongs to the computer choice.
  const quick = jsxs('section', {
    'aria-label': 'Quick game',
    style: { display: 'flex', flexDirection: 'column', gap: 6 },
    children: [
      heading('Quick game'),
      soloGame ? null : jsx('div', {
        style: { fontSize: 12, color: text.tertiary },
        children: `Pick the game, then press New game: the built-in computer plays ${sideWordsOf(pictured).black.toLowerCase()} and never uses your chat model, or your own Hermes model takes the seat.`
      })
    ]
  })

  // The model seat's own picker: the shared, searchable ModelPicker every model seat uses
  // (50-model-picker.js), so the search, the grouping and the keyboard behave the same here as in
  // Champions. It lists every route this Hermes has and marks the one this seat really plays; the
  // line above says which that is, and a pick that cannot take effect yet says so rather than
  // pretending (pinning a route to the seat is the next slice).
  const seatModel = String(((view || {}).opponent || {}).model || '')
  const seatRouteId = (() => {
    if (!seatModel) return MODEL_CHAT_ID
    const found = modelPickerRoutes(modelRoutes).find(item => item.model === seatModel)
    return found ? modelPickerKey(found) : ''
  })()
  const modelChoice = jsxs('div', {
    'data-deal-model': '1',
    style: { display: 'flex', flexDirection: 'column', gap: 6, border: `1px solid ${stroke}`, borderRadius: 8, padding: '8px 10px' },
    children: [
      jsx('div', {
        style: { fontSize: 11, color: text.tertiary, lineHeight: 1.45 },
        children: `This seat plays ${seatModel ? `${seatModel} — the model` : 'the model'} pinned in Hermes Settings → Models → "Game Shelf opponent".`
      }),
      jsx(ModelPicker, {
        routes: modelRoutes,
        current: dealModel || seatRouteId,
        ctx,
        hint: 'Type to filter by provider or model. Up and down move, Enter picks.',
        onPick: route => setDealModel(route && route.id ? String(route.id) : '')
      }),
      dealModel && dealModel !== seatRouteId
        ? jsx('div', {
            role: 'status', 'aria-live': 'polite',
            style: { fontSize: 11, color: text.secondary, lineHeight: 1.45 },
            children: `Picked ${dealModel}. This seat still plays ${seatModel || 'the model pinned in Hermes Settings'} until a pick here can be pinned to it.`
          })
        : null
    ]
  })

  // Tiles, not a drop-down: every game is one press, on screen, no menu.
  const rankOf = id => { const at = QUICK_GAMES.indexOf(id); return at === -1 ? 99 : at }
  const orderedGames = games.slice().sort((a, b) => rankOf(a.id) - rankOf(b.id))
  const picker = games.length
    ? jsx('div', {
        className: 'games-pane-games',
        role: 'group',
        'aria-label': 'Game',
        style: { display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 6 },
        children: orderedGames.map(item => jsx('button', {
          type: 'button',
          'aria-pressed': item.id === 'slots' ? jackpot : item.id === current,
          'data-game-tile': item.id,
          title: `Play ${item.title || item.id} in this pane.`,
          // Slots goes to the dedicated pane-sized Jackpot view (its own frame and floor), never the
          // board slot - the same path the old separate Slots button took.
          onClick: () => (item.id === 'slots' ? openJackpot() : chooseGame(item.id)),
          disabled: working,
          style: {
            padding: '8px 10px', borderRadius: 8, cursor: 'pointer', textAlign: 'center', fontSize: 12, fontWeight: 600,
            border: `1px solid ${item.id === current ? accent : stroke}`,
            background: item.id === current ? fill : card,
            color: item.id === current ? text.primary : text.secondary
          },
          children: item.title || item.id
        }, item.id))
      })
    : jsx('div', { style: { fontSize: 12, color: text.tertiary }, children: 'No curated games are installed here.' })

  const boardView = pictured
    ? jsxs('div', {
        'aria-label': 'Game board',
        ref: boardBox,
        style: { display: 'flex', flexDirection: 'column', gap: 6, minWidth: 0, width: '100%' },
        children: [
          // Who is across the board, said above it (owner's ask 2026-11-10). Blackjack
          // carries its own label on the felt; Slots has no opponent at all.
          pictured.view === 'blackjack' || pictured.view === 'slots' ? null : jsx(OpponentLine, { pictured, view, solo: soloGame }),
          pictured.view === 'slots' ? jsx(Jackpot2Full, { ctx }) : pictured.view === 'blackjack'
            ? jsx(BlackjackTable, {
                picture: pictured,
                against: opponentWords(pictured, view, soloGame),
                interactive: Boolean(current && access.can_move && !working),
                busy: working,
                onMove: token => move(current, token),
                onSetting: (path, body) => ctx.rest(path, { method: 'POST', body })
              })
          : pictured.view === 'seabattle'
            ? jsx(SeaBattleTable, {
                picture: pictured,
                interactive: Boolean(current && access.can_move && !working),
                busy: working,
                onMove: token => move(current, token)
              })
            : jsx(pictured && pictured.view === 'backgammon' ? BackgammonSvg : BoardSvg, {
                picture: pictured,
                height: boardH,
                flat: true,
                onPhase: setBgPhase,
                interactive: Boolean(current && access.can_move && !working),
                // The person's own move is drawn the moment they make it, while the
                // table's answer is still on its way: a search or a model takes its time,
                // and a board that sits still reads as a board that did not hear the click
                // (owner's report 2026-11-10).
                pending: preview,
                onPending: mv => { if (access.can_move && !working) setPreview(mv) },
                onMove: token => move(current, token)
              }),
          pictured.view === 'slots' ? null : jsxs('div', {
            role: 'status', 'aria-live': 'polite', className: 'games-status',
            style: { display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap', fontSize: 13, fontWeight: 650 },
            children: [
              // Whose move it is, with the seconds running while the other seat works, in the same
              // words the full table uses (owner's ask, 2026-11-11). On the person's own Backgammon
              // turn the board owns the words (roll, then spend the dice: 14b-backgammon-svg.js).
              jsx('span', {
                children: (pictured.view === 'backgammon' && myTurn(pictured, view)
                  ? backgammonTurnLine(pictured, true, bgPhase) : '') || paneStatus(pictured, view, { working, seconds: waited })
              }),
              working && !paneWait ? jsx('span', { style: { fontSize: 12, color: text.tertiary, fontWeight: 400 }, children: 'one moment…' }) : null
            ]
          })
        ]
      })
    : null

  // JACKPOT v2 in the pane: the same cabinet as the Games page and the over-chat copy. In the game
  // tab's board slot — the pane's Slots game — it is mounted with no frame of its own, so it measures
  // the element it is really in: the pane's own width and height decide the scale, never the window,
  // and the machine can land nowhere but inside its frame. JP2_PANE_MIN_HEIGHT is the floor for the
  // cabinet's own row below: 440 px tall puts it at 0.6 of its design size, and below that its small
  // text stops being readable, so a shorter pane scrolls (the pane root already does) rather than
  // clipping the machine.
  const JP2_PANE_MIN_HEIGHT = 440
  const openJackpot = () => {
    setJackpot(true)
    setRestarting(false)
    setReply('')
    setProblem('')
  }
  // Its own row, not a tile in the curated picker: that group is the turn-based tables served by
  // /board, and the cabinet is not one of them.
  const jackpotRow = jsx('div', {
    'aria-label': 'Jackpot cabinet',
    style: { display: 'flex', gap: 6, flexWrap: 'wrap' },
    children: jsx('button', {
      type: 'button',
      'data-jp2': 'pane-tile',
      'data-game-tile': 'slots',
      'aria-pressed': jackpot,
      title: 'Play Slots in this pane. Same wallet as the tables, no model spend.',
      onClick: openJackpot,
      disabled: working,
      style: {
        padding: '8px 10px', borderRadius: 8, cursor: working ? 'default' : 'pointer', fontSize: 12, fontWeight: 600,
        border: `1px solid ${jackpot ? accent : stroke}`,
        background: jackpot ? fill : card,
        color: jackpot ? text.primary : text.secondary
      },
      children: 'Slots'
    }, JP2L_ID)
  })

  const jackpotView = jsxs('div', {
    'data-jp2': 'pane',
    style: { display: 'flex', flexDirection: 'column', gap: 6, minWidth: 0, width: '100%', flex: '1 1 auto', minHeight: 0 },
    children: [
      jsxs('div', {
        style: { display: 'flex', alignItems: 'center', justifyContent: 'space-between', gap: 8 },
        children: [
          jsx('div', { style: { fontWeight: 650, fontSize: 13 }, children: 'Jackpot' }),
          button('Back to games', () => setJackpot(false), { title: 'Back to this pane’s game list.' })
        ]
      }),
      jsxs('div', {
        'data-jp2': 'pane-frame',
        style: {
          position: 'relative', display: 'flex', alignItems: 'center', justifyContent: 'center',
          width: '100%', flex: '1 1 auto', minHeight: JP2_PANE_MIN_HEIGHT, minWidth: 0, overflow: 'hidden'
        },
        children: jsx(JackpotMachine, { ctx, mode: 'full' })
      })
    ]
  })

  const gameTab = jsxs('div', {
    // While the cabinet is up it takes the pane to itself: a ~400 px column with the game list above it
    // pushed the machine's bottom below the fold, and "scroll down to see it" is not "nothing clipped".
    // The list comes back with the Back control, exactly as the Games page swaps its column for the
    // full view.
    style: {
      display: 'flex', flexDirection: 'column', gap: 10, minWidth: 0,
      ...(jackpot ? { flex: '1 1 auto', minHeight: 0 } : {})
    },
    children: jackpot ? [jackpotView] : [
      soloGame ? null : quick,
      picker,
      // The separate Slots button only when the grid has no Slots tile (a server list without it), so
      // the Jackpot cabinet is always one press away and never shown twice.
      games.some(item => item.id === 'slots') ? null : jackpotRow,
      // Who takes the other seat, on one row: ONE door, and the choice is made inside it. The
      // dialog opens with NOTHING picked, so a game is never dealt against an opponent the person
      // did not name - and the words match the pick, never "the computer" for a model game
      // (owner's ask, 2026-11-11). A solo table that seats a machine gets the same door
      // (Blackjack's dealer); a table that seats nobody (Slots) gets neither.
      aiSeats ? jsxs('div', {
              'data-pane-opponents': '1',
              style: { display: 'flex', gap: 6, flexWrap: 'wrap' },
              children: [
                restarting
                  ? jsxs('div', {
                      role: 'alertdialog', 'aria-label': endsSomething ? 'Start over' : 'New game',
                      ref: confirmBox,
                      style: { display: 'flex', flexDirection: 'column', gap: 8, border: `1px solid ${accent}`, borderRadius: 8, padding: '8px 10px', fontSize: 12 },
                      children: [
                        jsx('div', { children: dealLine() }),
                        jsxs('div', {
                          role: 'radiogroup', 'aria-label': 'Who plays the other side',
                          style: { display: 'flex', flexDirection: 'column', gap: 6 },
                          children: [
                            dealChoiceElement('computer', 'Computer', 'The built-in player. Free, instant, and it never uses your chat model.', dealWho === 'computer', setDealWho),
                            dealChoiceElement('agent', 'Your Hermes model', 'Your own model plays one move per turn, one call each.', dealWho === 'agent', setDealWho)
                          ]
                        }),
                        dealWho === 'computer' ? levelRow : null,
                        dealWho === 'agent' ? modelChoice : null,
                        jsxs('div', { style: { display: 'flex', gap: 6 }, children: [
                          button('Start', deal, {
                            primary: true,
                            disabled: working || !dealWho,
                            title: dealWho
                              ? `Deal a game against ${dealWords(dealWho)} in ${(game && game.title) || current}.`
                              : 'Pick who plays the other side first.'
                          }),
                          button('Cancel', () => { setRestarting(false); setDealWho('') }, {
                            title: endsSomething ? 'Keep this game exactly as it is.' : 'Leave the table as it is.'
                          })
                        ] })
                      ]
                    })
                  : button(endsSomething ? 'Start over' : 'New game', openDeal, {
                      disabled: working || !current,
                      title: `Choose who plays ${(game && game.title) || current} with you: the built-in computer, or your own Hermes model.`
                    })
              ]
            })
        : null,
      boardView,
      ALERTS_OFF ? null : jsxs('details', {
        className: 'games-pane-alerts',
        style: { border: `1px solid ${stroke}`, borderRadius: 8, padding: '6px 10px' },
        children: [
          jsx('summary', { style: { cursor: 'pointer', fontSize: 12, color: text.secondary, fontWeight: 650 }, children: 'Alerts' }),
          jsxs('div', { style: { display: 'flex', flexDirection: 'column', gap: 6, paddingTop: 8, fontSize: 12, color: text.secondary }, children: [
            jsxs('label', { style: { display: 'flex', gap: 8, alignItems: 'center' }, children: [
              jsx('input', { type: 'checkbox', checked: Boolean(alerts.games[current]), onChange: () => toggleAlert(current), disabled: !current }),
              jsx('span', { children: 'Tell me when it is my turn (system notification, off by default)' })
            ] }),
            jsxs('label', { style: { display: 'flex', gap: 8, alignItems: 'center' }, children: [
              jsx('input', { type: 'checkbox', checked: Boolean(alerts.paused), onChange: togglePaused }),
              jsx('span', { children: 'Pause every alert' })
            ] }),
            jsx('div', { style: { fontSize: 11, color: text.tertiary }, children: 'No sound. The badge on the Games item always shows your turn, and the system notification only appears while Hermes is in the background.' })
          ] })
        ]
      })
    ]
  })

  // The online source, under the local lobby. Both are behind the same two
  // buttons (Find a match, Stop looking); this one only appears once the person
  // has turned it on, and every action is one of the /online doors.
  const online = onlineView(view)
  const title = (game && game.title) || current || ''
  const ladderStatus = online.ladder || {}
  const ladderRunning = ['starting', 'waiting', 'playing'].includes(String(ladderStatus.state || ''))
  const ladderEstimate = ladderAsk && ladderAsk.estimate ? ladderAsk.estimate : null
  const ladderReady = Boolean(ladderAsk && ladderAsk.model_ready)
  const champions = (ladderAsk && ladderAsk.champions) || []
  const onlineOffline = online.offline && online.on
  const onlineAlert = (view && view.online && view.online.alert) || null

  const onlineSection = jsxs('section', {
    'aria-label': 'Online play',
    style: { display: 'flex', flexDirection: 'column', gap: 6, border: `1px solid ${stroke}`, borderRadius: 8, padding: '8px 10px' },
    children: [
      jsx('div', { style: { fontWeight: 650, fontSize: 13 }, children: 'Play with people online' }),
      jsx('div', { style: { fontSize: 12, color: onlineOffline ? text.tertiary : text.secondary }, children: onlineLine(online, title) }),
      !online.on ? jsxs('div', { style: { display: 'flex', flexDirection: 'column', gap: 6 }, children: [
        jsx('div', {
          style: { fontSize: 11, color: text.tertiary, lineHeight: 1.45, border: `1px solid ${stroke}`, borderRadius: 6, padding: '6px 8px' },
          children: online.disclosure || `Online play talks to ${online.url} and nothing else.`
        }),
        jsxs('div', { style: { display: 'flex', gap: 6, flexWrap: 'wrap' }, children: [
          button('Turn on online play', () => onlineCall('/online/on'), { primary: true, disabled: onlineBusy }),
          button('Not now', () => setOnlineNote('Online stays off. Everything here still plays on this computer.'), { disabled: onlineBusy })
        ] })
      ] }) : null,
      online.on && !online.linked ? jsxs('div', { style: { display: 'flex', flexDirection: 'column', gap: 6 }, children: [
        jsx('div', { style: { fontSize: 12, color: text.secondary }, children: `Games with other people happen on ${onlineHost(online.url)}. Pick the name you will be known by there.` }),
        jsxs('div', { style: { display: 'flex', gap: 6 }, children: [
          field(onlineName, setOnlineName, 'Your name online', () => onlineCall('/online/signup', { name: onlineName.trim() })),
          button('Create my player', () => onlineCall('/online/signup', { name: onlineName.trim() }), { primary: true, disabled: onlineBusy || !onlineName.trim() })
        ] }),
        jsxs('div', { style: { display: 'flex', gap: 6 }, children: [
          field(onlineKey, setOnlineKey, 'Recovery key you saved', () => onlineCall('/online/signin', { name: onlineName.trim(), key: onlineKey.trim() })),
          button('I have a key', () => onlineCall('/online/signin', { name: onlineName.trim(), key: onlineKey.trim() }), { disabled: onlineBusy || !onlineName.trim() || !onlineKey.trim() })
        ] }),
      ] }) : null,
      keyToCopy ? jsxs('div', { style: { display: 'flex', flexDirection: 'column', gap: 4 }, children: [
        jsx('div', { style: { fontSize: 11, color: text.tertiary }, children: 'This is your recovery key. It is shown once, and it is what signs you in on another computer. It is kept with your other Hermes credentials.' }),
        jsx('div', { style: { fontFamily: 'var(--font-mono, ui-monospace, monospace)', fontSize: 12, overflowWrap: 'anywhere' }, children: keyToCopy }),
        jsxs('div', { style: { display: 'flex', gap: 8, alignItems: 'center' }, children: [
          button('Copy recovery key', () => copyText(keyToCopy, setOnlineNote), { primary: true }),
          textLink('Hide this key', () => setKeyToCopy(''))
        ] })
      ] }) : null,
      online.on && online.linked ? jsxs('div', { style: { display: 'flex', flexDirection: 'column', gap: 6 }, children: [
        jsxs('div', { style: { display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap', fontSize: 12, color: text.secondary }, children: [
          jsx('span', { children: `You are ${online.name} online.` }),
          textLink('Sign out here', () => onlineCall('/online/forget'))
        ] }),
        onlineAlert ? jsx('div', {
          role: 'status', 'aria-live': 'polite',
          style: { fontSize: 12, border: `1px solid ${accent}`, borderRadius: 8, padding: '6px 10px' },
          children: onlineAlert.text || 'Someone online wants this game.'
        }) : null,
        online.match ? jsxs('div', {
          role: 'status', 'aria-live': 'polite',
          style: { display: 'flex', flexDirection: 'column', gap: 6, border: `1px solid ${accent}`, borderRadius: 8, padding: '6px 10px', fontSize: 12 },
          children: [
            jsx('div', { children: `Your table is ready: ${online.match.opponent || 'someone'} for ${online.match.title || online.match.game}. ${online.match.side ? `You play ${online.match.side}.` : ''}` }),
            jsxs('div', { style: { display: 'flex', gap: 6, flexWrap: 'wrap', alignItems: 'center' }, children: [
              // The table, played right here on the same server match the browser would show.
              button('Play here', () => playHere(online.match), {
                primary: true,
                disabled: onlineBusy || playingHere || !online.match.room_id,
                title: 'Play this match in the pane, with the board and the moves on the lobby server. Hermes does not run it.'
              }),
              button('Not now', () => onlineCall('/online/match/close'), { disabled: onlineBusy })
            ] }),
            jsx('div', { style: { fontSize: 11, color: text.tertiary }, children: 'Live tables are held by the lobby server; press Play here to play this one inside Hermes.' })
          ]
        }) : jsxs('div', { style: { display: 'flex', flexDirection: 'column', gap: 6 }, children: [
          jsxs('div', { style: { display: 'flex', gap: 6, flexWrap: 'wrap' }, children: [
            online.game
              ? button('Stop looking online', () => onlineCall('/online/queue/stop'), { disabled: onlineBusy })
              : button(`Find a match online${title ? `: ${title}` : ''}`, () => onlineCall('/online/queue', { game: current }), { primary: true, disabled: onlineBusy || !current })
          ] }),
          online.waitingNames.length
            ? jsx('div', { style: { fontSize: 11, color: text.tertiary }, children: `Waiting for this game now: ${online.waitingNames.join(', ')}.` })
            : null,
          // FUTURE(2026-11-11): the online-alert checkbox — remove if never built.
          // "Tell me when someone online wants this game" writes its flag, but the system
          // notification behind it returns immediately, so the switch would promise an alert
          // nothing raises. The row is kept below the gate; PANE_ONLINE_ALERT_OFF hides it.
          PANE_ONLINE_ALERT_OFF ? null : jsxs('label', { style: { display: 'flex', gap: 8, alignItems: 'center', fontSize: 12, color: text.secondary }, children: [
            jsx('input', {
              type: 'checkbox',
              checked: Boolean(current && online.alerts[current]),
              disabled: !current || onlineBusy,
              onChange: event => onlineCall('/online/alerts', { game: current, enabled: event.target.checked })
            }),
            jsx('span', { children: 'Tell me when someone online wants this game (at most once every ten minutes, never during a match)' })
          ] })
        ] })
      ] }) : null,
      // Whoever turned it on can turn it off, signed in or not: an unlinked person
      // must not be stuck with online play on.
      online.on ? jsx('div', { style: { display: 'flex', marginTop: 6 }, children: textLink('Turn online play off', () => onlineCall('/online/off')) }) : null
    ]
  })

  const ladderSection = jsxs('section', {
    'aria-label': 'Bot ladder',
    style: { display: 'flex', flexDirection: 'column', gap: 6, border: `1px solid ${stroke}`, borderRadius: 8, padding: '8px 10px' },
    children: [
      jsx('div', { style: { fontWeight: 650, fontSize: 13 }, children: 'Bot ladder' }),
      !online.on || !online.linked
        ? jsx('div', { style: { fontSize: 12, color: text.secondary }, children: 'Turn on online play and choose a name first. Your champion then plays rated games against other people\'s bots.' })
        : jsxs('div', { style: { display: 'flex', flexDirection: 'column', gap: 6 }, children: [
          jsx('div', { style: { fontSize: 12, color: text.secondary }, children: 'Your champion or agent can climb the bot ladder. Its model runs on this computer, and only the move it picks is sent.' }),
          ladderRunning ? jsxs('div', { style: { display: 'flex', flexDirection: 'column', gap: 6 }, children: [
            jsx('div', { role: 'status', 'aria-live': 'polite', style: { fontSize: 12 }, children: ladderLine(ladderStatus) }),
            jsx('div', { style: { display: 'flex' }, children: button('Stop the ladder game', () => onlineCall('/online/ladder', { action: 'stop' }), { disabled: onlineBusy }) })
          ] }) : null,
          !ladderRunning && ladderEstimate ? jsxs('div', {
            role: 'status', 'aria-live': 'polite',
            ref: ladderBox,
            style: { display: 'flex', flexDirection: 'column', gap: 6, border: `1px solid ${accent}`, borderRadius: 8, padding: '6px 10px', fontSize: 12 },
            children: [
              jsx('div', { children: ladderEstimate.text }),
              champions.length
                ? jsxs('div', { style: { display: 'flex', gap: 6, alignItems: 'center', flexWrap: 'wrap' }, children: [
                    jsx('span', { children: 'Playing as' }),
                    button('Your agent', () => setLadderChampion(''), { primary: ladderChampion === '' }),
                    ...champions.map(item => button(item.name, () => setLadderChampion(item.id), { primary: ladderChampion === item.id }))
                  ] })
                : null,
              ladderReady
                ? jsxs('div', { style: { display: 'flex', gap: 6, flexWrap: 'wrap' }, children: [
                    button('Start ladder game', () => { onlineCall('/online/ladder', { action: 'start', game: current, champion: ladderChampion }); setLadderAsk(null) }, { primary: true, disabled: onlineBusy || !current }),
                    button('Cancel', () => setLadderAsk(null))
                  ] })
                : jsx('div', { style: { color: text.secondary }, children: 'Pick a model in Settings, Models, Game Shelf opponent, then press Enter ladder again.' })
            ]
          }) : null,
          !ladderRunning && !ladderEstimate ? jsxs('div', { style: { display: 'flex', flexDirection: 'column', gap: 6 }, children: [
            ladderLine(ladderStatus) ? jsx('div', { role: 'status', 'aria-live': 'polite', style: { fontSize: 12 }, children: ladderLine(ladderStatus) }) : null,
            jsx('div', { style: { display: 'flex', gap: 6, flexWrap: 'wrap' }, children: [
              button('Enter ladder', showLadderAsk, { disabled: onlineBusy || !current }),
              online.bot && online.bot.name ? jsx('span', { style: { fontSize: 11, color: text.tertiary, alignSelf: 'center' }, children: `Bot: ${online.bot.name}` }) : null
            ] })
          ] }) : null
        ] })
    ]
  })

  const lobbyTab = jsxs('div', {
    style: { display: 'flex', flexDirection: 'column', gap: 10, minWidth: 0 },
    children: [
      view && view.player && view.player.named
        ? jsx('div', { style: { fontSize: 12, color: text.tertiary }, children: `You are ${view.player.name}` })
        : jsxs('div', {
            style: { display: 'flex', gap: 6 },
            children: [
              field(name, setName, 'Your name', () => { say(`name ${name.trim()}`); setName('') }),
              button('Set', () => { say(`name ${name.trim()}`); setName('') }, { disabled: !name.trim() })
            ]
          }),
      jsx('div', { style: { fontWeight: 650, fontSize: 13 }, children: `Find a match${current ? `: ${(game && game.title) || current}` : ''}` }),
      jsx('div', {
        style: { fontSize: 12, color: text.secondary },
        children: isLooking(lobby, current, myName)
          ? 'Looking. This keeps searching while you use Hermes; you will be told when someone wants this game.'
          : 'Ask to be listed, then play while Hermes works. Nothing interrupts you.'
      }),
      jsxs('div', { style: { display: 'flex', gap: 6, flexWrap: 'wrap' }, children: [
        isLooking(lobby, current, myName)
          ? button('Stop looking', () => say('looking stop'), { disabled: working || !current })
          : button('Find a match', () => say(`looking ${current}`), { primary: true, disabled: working || !current || !myName })
      ] }),
      found.length
        ? jsx('div', {
            role: 'status', 'aria-live': 'polite',
            style: { fontSize: 12, color: text.primary, border: `1px solid ${accent}`, borderRadius: 8, padding: '6px 10px' },
            children: `Match found: ${found.map(row => row.name).join(', ')} wants ${(game && game.title) || current}. Say hello below.`
          })
        : null,
      jsx('div', {
        style: { display: 'flex', flexDirection: 'column', gap: 4, fontSize: 12, color: text.secondary, maxHeight: 140, overflow: 'auto' },
        children: lobby.lines.length
          ? lobby.lines.slice(-8).map((item, index) => {
              const timestamp = item.at ? new Date(item.at * 1000).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : '';
              return jsxs('div', {
                style: { display: 'flex', gap: 6, fontSize: 11 },
                children: [
                  jsx('span', { style: { color: text.tertiary, whiteSpace: 'nowrap', minWidth: 40 }, children: timestamp }),
                  jsx('span', { style: { fontWeight: 650 }, children: `${item.name}: ` }),
                  jsx('span', { children: item.text, style: { flex: 1, minWidth: 0, wordWrap: 'break-word' } })
                ]
              }, index);
            })
          : jsx('div', { style: { color: text.tertiary }, children: 'No messages yet.' })
      }),
      jsxs('div', { style: { display: 'flex', gap: 6 }, children: [
        field(chat, setChat, view && view.player && view.player.named ? 'Say something' : 'Set a name first', () => { if (chat.trim()) { say(`chat say ${chat.trim()}`); setChat('') } }),
        button('Send', () => { say(`chat say ${chat.trim()}`); setChat('') }, { disabled: !chat.trim() || !(view && view.player && view.player.named) })
      ] }),
      onlineProblem
        ? jsx('div', { role: 'alert', style: { fontSize: 12, color: text.primary, border: `1px solid ${accent}`, borderRadius: 8, padding: '6px 10px' }, children: onlineProblem })
        : null,
      onlineNote
        ? jsx('div', { role: 'status', 'aria-live': 'polite', style: { fontSize: 12, color: text.secondary }, children: onlineNote })
        : null,
      onlineSection,
      // FUTURE(2026-11-11): the bot ladder — remove if never built.
      // The section is kept whole (above); PANE_LADDER_OFF keeps it off the pane, so bringing it
      // back is one boolean rather than a rebuild. Rated bot-versus-bot is not proven end to end,
      // and it belongs with Champions.
      PANE_LADDER_OFF ? null : ladderSection,
      // FUTURE(2026-11-11): Bots & leagues — remove if never built.
      // Leagues, watching a live table and bot passports all work against the lobby server, but
      // watching leaves Hermes for the browser. Kept whole (64-leagues.js); PANE_LEAGUES_OFF hides
      // it on the pane, which is the only surface that mounts it.
      PANE_LEAGUES_OFF || !(online.on && online.linked)
        ? null
        : jsx(BotsLeagues, { online, busy: onlineBusy, call: onlineCall, ctx, setNote: setOnlineNote })
    ]
  })

  // A match being played here on the lobby server takes the pane's body: the server's own picture
  // is the board, and it is not a local game, so the quick-game controls step aside entirely. The
  // pane's own header stays: × and – must not disappear just because a table is open.
  const hereRoom = onlineRoom || serverOnlineRoom(view)
  if (hereRoom) {
    return jsxs('div', {
      className: 'games-wait-pane',
      ref: rootBox,
      style: { display: 'flex', flexDirection: 'column', gap: 10, padding: 10, height: '100%', minHeight: 0, overflow: 'hidden', boxSizing: 'border-box', background: paper },
      children: [
        header,
        settings
          ? settingsView
          : jsx('div', {
              style: { flex: '1 1 auto', minHeight: 0, display: 'flex', flexDirection: 'column' },
              children: jsx(OnlineTable, {
                game, view, ctx, roomId: hereRoom, height: boardH,
                onBack: () => setOnlineRoom(''),
                onClose: () => setOnlineRoom('')
              })
            })
      ]
    })
  }

  return jsxs('div', {
    className: 'games-wait-pane',
    ref: rootBox,
    style: { display: 'flex', flexDirection: 'column', gap: 10, padding: 10, height: '100%', minHeight: 0, overflow: 'auto', background: paper, boxSizing: 'border-box' },
    children: settings ? [header, settingsView] : [
      header,
      agentRow(agentNotice(busy, finished, approval), ctx),
      problem ? jsx('div', { role: 'alert', style: { fontSize: 12, color: text.primary, border: `1px solid ${accent}`, borderRadius: 8, padding: '6px 10px', overflowWrap: 'anywhere' }, children: problem }) : null,
      noteLine(reply) ? jsx('div', { role: 'status', 'aria-live': 'polite', style: { fontSize: 12, color: text.secondary }, children: noteLine(reply) }) : null,
      tab === 'lobby' ? lobbyTab : gameTab
    ]
  })
}

// ---- One radio of the start-over dialog -------------------------------------
// The dialog opens with nothing checked (owner's ask, 2026-11-11): the whole point of the control
// is that no opponent is assumed, so a game is never dealt against a seat the person did not name.
// The radios are real inputs in one named group, so arrow keys and a screen reader work as they do
// anywhere else, and the label carries the promise each choice makes.
function dealChoiceElement(id, label, note, chosen, onPick) {
  return jsxs('label', {
    style: { display: 'flex', gap: 8, alignItems: 'flex-start', cursor: 'pointer' },
    children: [
      jsx('input', {
        type: 'radio',
        name: 'games-pane-deal',
        'data-deal-choice': id,
        checked: Boolean(chosen),
        onChange: () => onPick(id),
        style: { marginTop: 2, flex: '0 0 auto' }
      }),
      jsxs('span', {
        style: { display: 'flex', flexDirection: 'column', gap: 2, minWidth: 0 },
        children: [
          jsx('span', { style: { fontWeight: 650 }, children: label }),
          jsx('span', { style: { fontSize: 11, color: text.tertiary }, children: note })
        ]
      })
    ]
  }, id)
}

// ---- The obvious door (owner's ask, 2026-11-11) -----------------------------
// The pane used to come back only from the command palette. Two doors now carry it: a
// button in the Games header, beside the chips, and a status-bar item on the right. Both
// read the one pane state (usePaneOnScreen) and press the same two functions, so they can
// never disagree about where the pane is. The elements below are built by plain functions
// that take that state as an argument, so the surfaces can draw them without a second hook
// apiece and a test can draw either face on its own.
function paneDoorWords(onScreen) {
  return onScreen ? 'Close side pane' : 'Play while you code'
}

function paneDoorTitle(onScreen) {
  return onScreen
    ? 'Close the side pane. The status-bar item and the command palette bring it back.'
    : 'Open the side pane: play a quick game beside the chat while Hermes works.'
}

// The Games header's own button: light, beside the chips, and it says what the next press
// does — open the pane, or close it while it is open. Plain words, no icon: the header is
// where the door has to be unmistakable (the status-bar item is the one that wears the icon).
function paneDoorButtonElement(onScreen, style, onOpen) {
  return jsx('button', {
    type: 'button',
    'data-games-pane-door': onScreen ? 'close' : 'open',
    'aria-pressed': onScreen,
    'aria-label': paneDoorWords(onScreen),
    title: paneDoorTitle(onScreen),
    onClick: () => (onScreen ? closeWaitPane() : (onOpen ? onOpen() : openWaitPane())),
    style: Object.assign({
      display: 'inline-flex', alignItems: 'center', gap: 6, padding: '5px 11px', borderRadius: 999,
      fontSize: 12, fontWeight: 650, whiteSpace: 'nowrap', cursor: 'pointer',
      border: `1px solid ${onScreen ? stroke : accent}`,
      background: onScreen ? 'transparent' : accent,
      color: onScreen ? text.secondary : 'var(--ui-text-on-accent, white)'
    }, style || {}),
    children: paneDoorWords(onScreen)
  })
}

// The status bar's own item: a small game icon and the words, and nothing at all while the
// pane is open (the ask is explicit: it shows only while the pane is closed).
function paneDoorItemElement(onScreen) {
  if (onScreen) return null
  return jsxs('button', {
    type: 'button',
    'data-games-pane-door': 'status',
    'aria-label': 'Play while you code',
    title: paneDoorTitle(false),
    autoFocus: false,
    onClick: () => openWaitPane(),
    style: {
      display: 'inline-flex', alignItems: 'center', gap: 5, padding: '0 6px',
      border: 'none', background: 'transparent', color: text.primary, fontSize: 11, cursor: 'pointer'
    },
    children: [
      paneDoorIconElement(13),
      jsx('span', { children: 'Play while you code' })
    ]
  })
}

// The ONE status-bar item (owner, 12:25): the pane's door and the news that needs saying —
// your turn, a match, your bot's result, or people waiting for a game you asked to hear
// about. The news is quiet while there is nothing to say; the door (owner's ask, 2026-11-11)
// stands while the pane is off the screen and hides while it is open. Neither ever takes the
// keyboard, and a click opens the pane (or the match) instead of nagging.
function GamesStatusItem({ ctx }) {
  const [label, setLabel] = useState('')
  // One memory per kind of news, so a turn that is waiting cannot hide a match.
  const toldTurn = useRef('')
  const toldMatch = useRef('')
  // Where the pane is, so the door follows × and the palette without a second polling loop.
  const onScreen = usePaneOnScreen()
  useEffect(() => {
    let alive = true
    const check = async () => {
      try {
        const next = await ctx.rest('/view')
        const name = (next.player && next.player.name) || ''
        const titleOf = id => (paneGames(next).find(item => item.id === id) || {}).title || id
        // A match is my own looking row plus somebody else on the same game. It
        // comes from the lobby, so it survives a closed pane and a reload.
        const matchGame = matchFound(next.lobby, name)
        // ... and the wider count, for games the person asked to hear about.
        let crowdGame = ''
        let crowdCount = 0
        paneGames(next).forEach(item => {
          if (!alertsOn(ctx, item.id)) return
          const count = othersLooking(next.lobby, item.id, name).length
          if (count > crowdCount) { crowdCount = count; crowdGame = item.id }
        })
        const watching = paneWatch.game || savedPaneGame(ctx)
        let turnNow = false
        let botWord = ''
        if (watching) {
          const shown = await ctx.rest(`/board?game=${encodeURIComponent(watching)}`)
          turnNow = myTurn(shown && shown.picture, next)
          const picture = (shown && shown.picture) || null
          const over = picture && (picture.status === 'win' || picture.status === 'draw')
          const mine = over ? (picture.seats || []).find(seat => seat.kind === 'agent') : null
          if (over && mine) {
            botWord = picture.status === 'draw'
              ? 'Your bot drew'
              : `Your bot ${picture.winner === mine.side ? 'won' : 'lost'}`
          }
          // Only a notification actually sent is remembered: a turn that arrives while
          // alerts are paused still tells them once they unpause this game. The stamp is
          // the move on the board, so a new turn is a new line even between polls.
          const stamp = `${(picture && picture.plies) || ''}:${(picture && picture.last) || ''}:${(picture && picture.turn) || ''}`
          if (turnNow) {
            const key = `${watching}:${stamp}`
            if (key !== toldTurn.current && alertsOn(ctx, watching)) {
              notifyAlert(ctx, 'Your turn', watching, titleOf(watching))
              toldTurn.current = key
            }
          } else {
            toldTurn.current = ''
          }
        }
        if (matchGame) {
          if (matchGame !== toldMatch.current && alertsOn(ctx, matchGame)) {
            notifyAlert(ctx, 'Match found', matchGame, titleOf(matchGame))
            toldMatch.current = matchGame
          }
        } else {
          toldMatch.current = ''
        }
        if (!alive) return
        // The item says the most immediate thing only: the rest is still there
        // on the next quiet poll, never stacked.
        const label = turnNow
          ? `Your turn (${titleOf(watching)})`
          : matchGame
            ? 'Match found'
            : botWord || (crowdGame ? `${crowdCount} looking for ${titleOf(crowdGame)}` : '')
        setLabel(label)
      } catch {
        if (alive) setLabel('')
      }
    }
    check()
    const timer = setInterval(check, 8000)
    return () => { alive = false; clearInterval(timer) }
  }, [ctx])

  const door = paneDoorItemElement(onScreen)
  const news = !label ? null : jsxs('button', {
    type: 'button',
    'data-games-status': 'action',
    'aria-label': `Games: ${label}`,
    title: `${label} — open the side pane`,
    onClick: () => openWaitPane(),
    autoFocus: false,
    style: {
      display: 'flex', gap: 5, alignItems: 'center',
      padding: '0 6px', border: 'none', background: 'transparent',
      color: text.primary, fontSize: 11, cursor: 'pointer'
    },
    children: [
      jsx('span', {
        'aria-hidden': true,
        style: { width: 6, height: 6, borderRadius: '50%', background: accent, display: 'inline-block' }
      }),
      jsx('span', { children: label })
    ]
  })
  if (!door && !news) return null
  return jsxs('span', {
    'data-games-status-bar': '1',
    style: { display: 'inline-flex', alignItems: 'center', gap: 8 },
    children: [door, news]
  })
}

// ---- 66-admin.js: the Admin tab — roles, reports, lookups and the audit log
// The tab exists only when the lobby says this account is staff (view.online.staff.role).
// Every button is one POST to /online/admin/action; the lobby re-checks both the
// account key and the staff key on every call, so this page can only offer what
// the person may already do.

const ADMIN_ROLE_LABEL = { owner: 'Owner', admin: 'Admin', moderator: 'Moderator' }
const ADMIN_REASONS = ['Spam', 'Abuse or threats', 'Impersonation', 'Something else']

function adminRoleBadge(role) {
  if (!role) return null
  return jsx('span', {
    style: {
      fontSize: 11, color: role === 'owner' ? '#d6a23a' : role === 'admin' ? accent : '#5cc28a',
      border: `1px solid ${role === 'owner' ? '#d6a23a' : role === 'admin' ? accent : '#5cc28a'}`,
      borderRadius: 999, padding: '2px 8px', whiteSpace: 'nowrap'
    },
    children: ADMIN_ROLE_LABEL[role] || role
  })
}

function adminWhen(seconds) {
  if (!seconds) return ''
  const date = new Date(seconds * 1000)
  const now = new Date()
  return date.toDateString() === now.toDateString()
    ? date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    : date.toLocaleDateString()
}

function adminUntil(until) {
  if (!until) return 'permanently'
  return 'until ' + new Date(until * 1000).toLocaleString([], { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' })
}

function adminCan(role, what) {
  const rank = { owner: 3, admin: 2, moderator: 1 }[role] || 0
  if (what === 'permanent' || what === 'rename' || what === 'bots' || what === 'table' || what === 'team') return rank >= 2
  if (what === 'appoint-admin') return rank >= 3
  return rank >= 1
}

function adminRow(children, key) {
  return jsx('div', { key, style: { display: 'flex', gap: 6, flexWrap: 'wrap', alignItems: 'center' }, children })
}

function adminCard(children, key) {
  return jsx('div', {
    key,
    style: {
      display: 'flex', flexDirection: 'column', gap: 8, padding: 12, borderRadius: 10,
      border: `1px solid ${stroke}`, background: card, minWidth: 0
    },
    children
  })
}

function adminMuted(label) {
  return jsx('div', { style: { fontSize: 12, color: text.tertiary, lineHeight: 1.45 }, children: label })
}

function AdminPage({ ctx, view, onBack }) {
  const online = view.online || {}
  const staff = online.staff || { role: '', name: '', powers: [] }
  const [where, setWhere] = useState('reports')
  const [reason, setReason] = useState('')
  const [key, setKey] = useState('')
  const [flash, setFlash] = useState('')
  const [issued, setIssued] = useState(null)
  const [busy, setBusy] = useState(false)
  const [version, setVersion] = useState(0)
  const [overview, setOverview] = useState(null)
  const [reports, setReports] = useState(null)
  const [audit, setAudit] = useState(null)
  const [found, setFound] = useState(null)
  const [query, setQuery] = useState('')
  const [newName, setNewName] = useState('')
  const [problem, setProblem] = useState('')
  const role = staff.role

  const load = useCallback(async () => {
    if (!role) return
    setProblem('')
    try {
      const [counts, queue, history] = await Promise.all([
        ctx.rest('/online/admin/overview'),
        ctx.rest('/online/admin/reports?state=open'),
        ctx.rest('/online/admin/audit?limit=80')
      ])
      setOverview(counts && counts.ok ? counts : null)
      setReports(queue && queue.ok ? (queue.reports || []) : [])
      setAudit(history && history.ok ? (history.entries || []) : [])
    } catch (failure) {
      setProblem((failure && failure.message) || 'The lobby could not be reached.')
    }
  }, [ctx, role])

  useEffect(() => { load() }, [load, version])
  useEffect(() => {
    if (where === 'audit' || where === 'team') load()
  }, [where, load])

  const run = useCallback(async payload => {
    setBusy(true)
    setFlash('')
    try {
      const answer = await ctx.rest('/online/admin/action', {
        method: 'POST',
        body: { ...payload, reason }
      })
      setFlash((answer && (answer.text || (answer.ok ? 'Done.' : 'That was refused.'))) || 'Done.')
      if (answer && answer.ok && answer.staff_key) {
        setIssued({ name: answer.staff_name || payload.target || '', role: answer.staff_role || payload.role || '', key: answer.staff_key })
      }
      if (answer && answer.ok) { setVersion(value => value + 1); setReason('') }
      return answer
    } catch (failure) {
      setFlash((failure && failure.message) || 'That did not go through.')
      return null
    } finally { setBusy(false) }
  }, [ctx, reason])

  const useKey = async () => {
    setBusy(true); setProblem(''); setFlash('')
    try {
      const answer = await ctx.rest('/online/staff', { method: 'POST', body: { key: key.trim() } })
      if (answer && answer.ok) { setFlash(answer.text || 'Staff key saved.'); setKey('') }
      else setProblem((answer && answer.text) || 'That staff key does not work with this account.')
    } catch (failure) {
      setProblem((failure && failure.message) || 'That staff key does not work with this account.')
    } finally { setBusy(false) }
  }

  const lookUp = async () => {
    if (!query.trim()) return
    setProblem(''); setFound(null)
    try {
      const answer = await ctx.rest('/online/admin/user?name=' + encodeURIComponent(query.trim()))
      if (answer && answer.ok && answer.player) setFound(answer.player)
      else setProblem((answer && (answer.text || answer.error)) || 'No such name.')
    } catch (failure) { setProblem((failure && failure.message) || 'That lookup failed.') }
  }

  if (!role) {
    return jsxs('div', {
      style: { display: 'flex', flexDirection: 'column', gap: 12, padding: 18, maxWidth: 560 },
      children: [
        adminRow([jsx('div', { style: { fontSize: 20, fontWeight: 700 }, children: 'Admin' }), labsBadge()]),
        adminMuted('Staff only. Paste the staff key an owner or admin gave you. It is checked against the name you play as, and kept in Hermes\u2019s credentials on this computer.'),
        adminRow([field(key, setKey, 'Staff key', useKey, { label: 'Staff key' }), button('Use it', useKey, { primary: true, disabled: busy || !key.trim() })]),
        problem ? jsx('div', { style: { fontSize: 12, color: '#e2726c' }, children: problem }) : null,
        flash ? jsx('div', { style: { fontSize: 12, color: text.secondary }, children: flash }) : null,
        textLink('Back to the Game Center', onBack)
      ]
    })
  }

  const places = [['reports', 'Reports'], ['lookup', 'Look up'], ['audit', 'Audit log'], ['team', 'Team']]
  const reportCards = (reports || []).map(row => adminCard([
    jsxs('div', {
      style: { display: 'flex', justifyContent: 'space-between', gap: 8, flexWrap: 'wrap' },
      children: [
        jsx('b', { style: { fontSize: 13 }, children: `${row.kind === 'message' ? 'Message' : row.kind === 'bot' ? 'Bot' : 'Name'} \u00b7 ${row.target_name || 'unknown'}` }),
        jsx('span', { style: { fontSize: 11, color: text.tertiary }, children: adminWhen(row.at) })
      ]
    }),
    row.text ? jsx('div', {
      style: { fontSize: 12, color: text.secondary, borderLeft: `3px solid ${stroke}`, padding: '6px 9px', background: fill, borderRadius: 6, overflowWrap: 'anywhere' },
      children: row.text
    }) : null,
    adminMuted(`Reported by ${row.reporter_name}${row.reason ? ' \u00b7 ' + row.reason : ''}${row.room_id ? ' \u00b7 ' + (row.room_id === '__lobby__' ? 'the lobby' : 'table ' + row.room_id) : ''}`),
    adminRow([
      row.kind === 'message' ? button('Delete message', () => run({ action: 'delete-message', message_id: row.message_id, room_id: row.room_id, target_id: row.target_id }), { disabled: busy }) : null,
      button('Silence 1h', () => run({ action: 'silence', target_id: row.target_id, minutes: 60 }), { disabled: busy }),
      button('Suspend 7 days', () => run({ action: 'suspend', target_id: row.target_id, minutes: 10080 }), { disabled: busy }),
      button('Nothing wrong', () => run({ action: 'close-report', report_id: row.id, resolution: 'Nothing wrong.' }), { disabled: busy })
    ])
  ], row.id))

  return jsxs('div', {
    style: { display: 'flex', flexDirection: 'column', gap: 12, padding: 18, overflow: 'auto', minHeight: 0, background: paper },
    children: [
      jsxs('div', {
        style: { display: 'flex', justifyContent: 'space-between', gap: 8, flexWrap: 'wrap', alignItems: 'center' },
        children: [
          adminRow([
            jsx('div', { style: { fontSize: 22, fontWeight: 700, letterSpacing: '-0.02em' }, children: 'Admin' }),
            adminRoleBadge(role), labsBadge()
          ]),
          textLink('Back to the Game Center', onBack)
        ]
      }),
      adminRow([
        jsx('div', { style: { fontSize: 12, color: text.tertiary }, children: 'Reason (kept in the audit log)' }),
        field(reason, setReason, 'e.g. spam in lobby chat', () => {}, { label: 'Reason for this action' })
      ]),
      adminRow([
        ...places.map(([id, label]) => button(label, () => (id === where ? setVersion(value => value + 1) : setWhere(id)), { primary: where === id })),
        // New reports arrive while a moderator is looking at the queue, so this
        // panel stays put until someone asks for the latest: one click, no typing.
        button('Refresh', () => setVersion(value => value + 1), { disabled: busy })
      ]),
      flash ? jsx('div', { style: { fontSize: 12, color: text.secondary, border: `1px solid ${accent}`, borderRadius: 8, padding: '8px 10px' }, children: flash }) : null,
      issued ? jsxs('div', {
        style: { display: 'flex', flexDirection: 'column', gap: 6, border: `1px solid ${accent}`, borderRadius: 8, padding: 10 },
        children: [
          jsx('b', { style: { fontSize: 13 }, children: `${issued.name} is ${ADMIN_ROLE_LABEL[issued.role] || issued.role}. Give them this staff key out of band:` }),
          pre(issued.key),
          adminMuted('They sign in as their own name, then paste it in Admin. It is shown once and cannot be read back.'),
          textLink('I have copied it', () => setIssued(null))
        ]
      }) : null,
      problem ? jsx('div', { style: { fontSize: 12, color: '#e2726c', border: '1px solid #e2726c', borderRadius: 8, padding: '8px 10px' }, children: problem }) : null,

      where === 'reports' ? jsxs('div', {
        style: { display: 'flex', flexDirection: 'column', gap: 10, minWidth: 0 },
        children: [
          reportCards.length ? reportCards : adminMuted('Nothing to look at. Nice.')
        ]
      }) : null,

      where === 'lookup' ? jsxs('div', {
        style: { display: 'flex', flexDirection: 'column', gap: 10, minWidth: 0 },
        children: [
          adminRow([
            field(query, setQuery, 'Name, exactly as they play', lookUp, { label: 'Name to look up' }),
            button('Look up', lookUp, { primary: true, disabled: !query.trim() })
          ]),
          !found ? adminMuted('Search a person or a bot to see their record, reports and past actions.') : adminCard([
            adminRow([
              jsx('div', { style: { fontSize: 17, fontWeight: 700 }, children: found.name }),
              found.bot ? badge('BOT') : null,
              adminRoleBadge(found.staff_role)
            ]),
            adminMuted(`${found.games} games \u00b7 ${found.wins}W ${found.losses}L ${found.draws}D \u00b7 ${found.reports_against} reports (${found.open_reports} open) \u00b7 joined ${adminWhen(found.joined)}${found.owner ? ' \u00b7 owner ' + found.owner : ''}`),
            found.silenced_until !== 0 ? adminMuted('Silenced ' + adminUntil(found.silenced_until)) : null,
            found.suspended_until !== 0 ? adminMuted('Suspended ' + adminUntil(found.suspended_until)) : null,
            heading('Silence (they can still play)'),
            adminRow([
              button('10 min', () => run({ action: 'silence', target_id: found.id, minutes: 10 }), { disabled: busy }),
              button('1 hour', () => run({ action: 'silence', target_id: found.id, minutes: 60 }), { disabled: busy }),
              button('24 hours', () => run({ action: 'silence', target_id: found.id, minutes: 1440 }), { disabled: busy }),
              adminCan(role, 'permanent') ? button('Forever', () => run({ action: 'silence', target_id: found.id, minutes: 0 }), { disabled: busy }) : null,
              button('Lift silence', () => run({ action: 'unsilence', target_id: found.id }), { disabled: busy })
            ]),
            heading('Suspend or ban (blocks sign-in, queue and the ladder)'),
            adminRow([
              button('1 hour', () => run({ action: 'suspend', target_id: found.id, minutes: 60 }), { disabled: busy }),
              button('1 day', () => run({ action: 'suspend', target_id: found.id, minutes: 1440 }), { disabled: busy }),
              button('7 days', () => run({ action: 'suspend', target_id: found.id, minutes: 10080 }), { disabled: busy }),
              adminCan(role, 'permanent') ? button('Permanent ban', () => run({ action: 'suspend', target_id: found.id, minutes: 0 }), { disabled: busy }) : null,
              button('Lift suspension', () => run({ action: 'unsuspend', target_id: found.id }), { disabled: busy })
            ]),
            adminCan(role, 'rename') ? adminRow([
              field(newName, setNewName, 'New name', () => { if (newName.trim()) run({ action: 'force-rename', target_id: found.id, name: newName.trim() }) }, { label: 'New name' }),
              button('Force rename', () => { if (newName.trim()) run({ action: 'force-rename', target_id: found.id, name: newName.trim() }) }, { disabled: busy || !newName.trim() })
            ]) : null,
            adminCan(role, 'bots') && found.bot ? adminRow([
              button('Remove bot from the ladder', () => run({ action: 'bot-remove', target_id: found.id }), { disabled: busy }),
              button('Reset its record', () => run({ action: 'bot-reset', target_id: found.id }), { disabled: busy })
            ]) : null,
            adminCan(role, 'team') ? adminRow([
              button('Make moderator', () => run({ action: 'appoint', target_id: found.id, role: 'moderator' }), { disabled: busy }),
              adminCan(role, 'appoint-admin') ? button('Make admin', () => run({ action: 'appoint', target_id: found.id, role: 'admin' }), { disabled: busy }) : null,
              found.staff_role && found.staff_role !== 'owner' ? button('Remove role', () => run({ action: 'revoke', target_id: found.id }), { disabled: busy }) : null
            ]) : null,
            found.actions && found.actions.length ? jsxs('div', {
              style: { display: 'flex', flexDirection: 'column', gap: 4 },
              children: [
                heading('Past actions'),
                ...found.actions.slice(0, 8).map(row => adminMuted(`${adminWhen(row.at)} \u00b7 ${row.actor_name} (${row.actor_role}) \u00b7 ${row.action}${row.reason ? ' \u00b7 ' + row.reason : ''}${row.undone ? ' \u00b7 undone' : ''}`))
              ]
            }) : null
          ])
        ]
      }) : null,

      where === 'audit' ? jsxs('div', {
        style: { display: 'flex', flexDirection: 'column', gap: 6, minWidth: 0 },
        children: [
          !audit ? adminMuted('Loading the audit log\u2026') : !audit.length ? adminMuted('No staff actions yet.') :
            audit.map(row => jsxs('div', {
              key: row.id,
              style: { display: 'flex', gap: 8, alignItems: 'center', justifyContent: 'space-between', fontSize: 12, color: row.undone ? text.tertiary : text.secondary, borderBottom: `1px solid ${stroke}`, padding: '5px 0', flexWrap: 'wrap' },
              children: [
                jsx('span', { children: `${adminWhen(row.at)} \u00b7 ${row.actor_name} (${row.actor_role}) \u00b7 ${row.action}${row.target_name ? ' \u2192 ' + row.target_name : ''}${row.reason ? ' \u00b7 ' + row.reason : ''}${row.undone ? ' \u00b7 undone' : ''}` }),
                !row.undone && !row.undo_of && adminCan(role, 'permanent')
                  ? textLink('Undo', () => run({ action: 'undo', audit_id: row.id }))
                  : null
              ]
            }))
        ]
      }) : null,

      where === 'team' ? jsxs('div', {
        style: { display: 'flex', flexDirection: 'column', gap: 10, minWidth: 0 },
        children: [
          adminRow([
            badge(`${(overview && overview.players) || 0} people`),
            badge(`${(overview && overview.reports_open) || 0} open reports`),
            badge(`${(overview && overview.suspended) || 0} suspended`),
            badge(`${(overview && overview.silenced) || 0} silenced`)
          ]),
          adminCard([
            heading('Staff'),
            ...(((overview && overview.staff) || []).map(row => adminRow([
              jsx('b', { style: { fontSize: 13 }, children: row.name }), adminRoleBadge(row.role)
            ], row.name))),
            !((overview && overview.staff) || []).length ? adminMuted('No staff yet. The owner is made on the server: python -m online.admin grant-owner <name>.') : null
          ]),
          !adminCan(role, 'team') ? adminMuted('Only an owner or an admin appoints moderators. Only the owner appoints admins.') : adminCard([
            heading('Appoint by name'),
            adminRow([
              field(query, setQuery, 'Name on the lobby', () => {}, { label: 'Name to appoint' }),
              button('Make moderator', () => run({ action: 'appoint', target: query.trim(), role: 'moderator' }), { disabled: busy || !query.trim() }),
              adminCan(role, 'appoint-admin') ? button('Make admin', () => run({ action: 'appoint', target: query.trim(), role: 'admin' }), { disabled: busy || !query.trim() }) : null
            ]),
            adminMuted('The staff key is returned once, in the answer below. Give it to that person out of band: it never goes in chat.')
          ]),
          adminCard([
            heading('This computer'),
            adminMuted('The staff key lives in Hermes\u2019s credentials. Forgetting it here does not change the role on the lobby.'),
            textLink('Forget the staff key here', async () => {
              try {
                const answer = await ctx.rest('/online/staff/clear', { method: 'POST', body: {} })
                setFlash((answer && answer.text) || 'Staff key forgotten.')
              } catch { setFlash('Could not forget the key here.') }
            })
          ])
        ]
      }) : null
    ]
  })
}

// ---- 70-home.js: the Games page: Play, Experimental Games, the lobby and the tabs
function GameCenterPage({ ctx, onArea }) {
  const [skin, setSkin] = useSkin(ctx)
  const [view, setView] = useState(null)
  const [error, setError] = useState('')
  const [selected, setSelected] = useState('')
  const [playing, setPlaying] = useState('')
  // Mafia Town: the Labs skin for the mafia table. The card turns it on; opening the
  // game anywhere else puts the classic table back.
  const [town, setTown] = useState(false)
  const [board, setBoard] = useState({ text: '', picture: null })
  const [reply, setReply] = useState('')
  const [move, setMove] = useState('')
  const [chat, setChat] = useState('')
  const [name, setName] = useState('')
  const [hostAddr, setHostAddr] = useState('')
  const [query, setQuery] = useState('')
  const [area, setArea] = useState('games')
  // The route draws Close Game Center itself off the Games screen; it needs to know which screen.
  useEffect(() => { if (typeof onArea === 'function') onArea(area) }, [area])
  // The lobby's short How to play card, opened from the header like the other
  // surfaces' how-to cards.
  const [lobbyHowto, setLobbyHowto] = useState(false)
  // The welcome is shown until it is answered or skipped in this visit. The saved
  // answer lives in /setup, so it is never asked again after that.
  const [welcomeClosed, setWelcomeClosed] = useState(false)
  const selectionGen = useRef(0)
  // Whether the side pane is on the screen, so the header's one button says what its next
  // press does (owner's ask, 2026-11-11). One read, shared with the status-bar item.
  const paneOn = usePaneOnScreen()

  // Full screen and the pane are one at a time. Arriving here closes the pane and
  // opens the game it was showing, so the handoff lands on the same board.
  useEffect(() => {
    leavePaneForPage()
    if (PAGE_HANDOFF.game) {
      setSelected(PAGE_HANDOFF.game)
      PAGE_HANDOFF.game = ''
    }
  }, [])

  const refresh = useCallback(async () => {
    const genAtStart = selectionGen.current
    try {
      const next = await ctx.rest('/view')
      // A refresh whose /view was already in flight when the person switched
      // games is stale: drop it before it paints anything, so game A's board
      // can never land under game B.
      if (selectionGen.current !== genAtStart) return { ok: true, picture: null }
      setView(next)
      setError('')
      const listed = next.store || (next.games || []).concat(next.more || [])
      const current = selected || (listed[0] && listed[0].id) || ''
      if (current && current !== selected) {
        selectionGen.current++
        setSelected(current)
      }
      const myGen = selectionGen.current
      const card = listed.find(item => item.id === current)
      if (current && card) {
        try {
          const shown = card.installed
            ? await ctx.rest(`/board?game=${encodeURIComponent(current)}`)
            : { text: '', picture: startingPicture(current) }
          // Drop this board if the person selected a different game while it was
          // in flight (selectionGen changes only on pick/open, never per poll),
          // so game A's board never paints under game B and a slow /view+/board
          // cannot starve the next poll out of a render.
          if (selectionGen.current !== myGen) return { ok: true, picture: null }
          const picture = shown.picture || (!shown.text ? startingPicture(current) : null)
          setBoard({ text: shown.text || '', picture, error: '' })
          return { ok: true, picture }
        } catch (failure) {
          if (selectionGen.current !== myGen) return { ok: true, picture: null }
          // While the gateway restarts, keep the last real board of this game on
          // screen; swapping in the blank starting board looks like a lost game.
          // Say so out loud, with a way back, instead of retrying behind a blank board.
          const said = String((failure && failure.message) || 'the game did not answer').slice(0, 140)
          setBoard(prev => (prev.picture && prev.picture.game === current && !prev.picture.preview
            ? { ...prev, error: said }
            : { text: '', picture: startingPicture(current), error: said }))
          return { ok: false, text: failure.message || 'Could not refresh the board.' }
        }
      } else {
        if (selectionGen.current !== myGen) return { ok: true, picture: null }
        setBoard({ text: '', picture: null })
        return { ok: true, picture: null }
      }
    } catch (failure) {
      const detail = failure && (failure.message || failure.status || failure.error)
      setError(
        'Game Center is waiting on the Hermes gateway. hermes-gameshelf is already enabled. Stay on this page — it retries every few seconds. If this lasts more than a minute, command palette → Reload desktop plugins.'
        + (detail ? ` (${String(detail).slice(0, 120)})` : '')
      )
      return { ok: false, text: detail ? String(detail) : 'Could not refresh the table.' }
    }
  }, [ctx, selected])

  useEffect(() => {
    refresh()
    const timer = setInterval(refresh, POLL_MS)
    return () => clearInterval(timer)
  }, [refresh])

  const send = useCallback(
    async line => {
      try {
        const answer = await ctx.rest('/command', { method: 'POST', body: { line } })
        setReply(answer.text || '')
        // Paint the board the command itself returned, so a move shows the moment the server answers
        // instead of after a second round trip (owner's report, 2026-11-09: Sea Battle felt slow).
        if (answer && answer.picture) setBoard({ text: answer.text || '', picture: answer.picture, error: '' })
        const refreshed = await refresh()
        return { ...answer, ...refreshed, ok: answer.ok !== false && refreshed.ok, text: refreshed.ok ? answer.text || '' : refreshed.text }
      } catch (failure) {
        const message = failure.message || 'That did not reach the Game Center.'
        setReply(message)
        return { ok: false, text: message }
      }
    },
    [ctx, refresh]
  )

  const playMove = useCallback(
    async (gameId, token) => {
      const pictured = board && board.picture
      const needsNew = !pictured || pictured.preview || pictured.status === 'idle' || pictured.status === 'abandoned'
      try {
        if (needsNew) {
          const started = await ctx.rest('/command', { method: 'POST', body: { line: `${gameId} new` } })
          setReply(started.text || '')
        }
        const answer = await ctx.rest('/command', { method: 'POST', body: { line: `${gameId} move ${token}` } })
        setReply(answer.text || '')
        if (answer && answer.picture) setBoard({ text: answer.text || '', picture: answer.picture, error: '' })
        const refreshed = await refresh()
        return { ...answer, ...refreshed, ok: answer.ok !== false && refreshed.ok, text: refreshed.ok ? answer.text || '' : refreshed.text }
      } catch (failure) {
        const message = failure.message || 'That did not reach the Game Center.'
        setReply(message)
        return { ok: false, text: message }
      }
    },
    [ctx, board, refresh]
  )

  if (error) {
    return skinShell(skin, jsx('div', { style: { padding: 16, color: text.secondary }, children: error }))
  }
  if (!view) {
    return skinShell(skin, jsx('div', { style: { padding: 16, color: text.tertiary }, children: 'Loading Game Center…' }))
  }

  const catalog = view.store || (view.games || []).concat(view.more || [])
  const needle = query.trim().toLowerCase()
  const matches = item => !needle || `${item.title} ${item.id} ${item.summary || ''} ${item.plugin || ''}`.toLowerCase().includes(needle)
  // Play is the curated list that ships with the plugin. Experimental Games is everything else the
  // person has installed, so nothing there can be mistaken for a match-ready table.
  // An experiment is never drawn among the Play tiles: the Labs shelf is where it belongs.
  const playList = (view.play || []).filter(matches).filter(item => !item.labs)
  const yourList = (view.your_games || []).filter(matches)
  // Suggestions are catalog pages, not games on this computer, so a search for a game never
  // surfaces them and they never pretend to be installed.
  const suggestions = view.your_suggestions || []
  const makers = view.makers || { note: '', notice: '', items: [] }
  const labsPlay = (view.labs_games || []).filter(matches)
  const playProblems = view.play_problems || []
  const community = view.community || { notice: '', games: [], problems: [] }
  const submit = submitTarget(view.submit)
  const game = catalog.find(item => item.id === selected) || (view.play || [])[0] || catalog[0]
  const lobby = view.lobby || { lines: [], looking: [] }
  const setup = view.setup || {}
  const alerts = view.alerts || { rows: [], count: 0 }
  const online = onlineView(view)
  const current = selected || ((view.play || [])[0] || {}).id || ''
  const waitingCount = id => online.on ? (online.looking[id] || 0) : (lobby.looking || []).filter(row => row.game === id).length

  // First run: one short panel before the games, and never again once answered.
  if (setup.welcome_needed && !welcomeClosed) {
    return skinShell(skin, jsx(WelcomePanel, {
      view,
      ctx,
      onDone: async () => {
        setWelcomeClosed(true)
        setArea('games')
        await refresh()
      }
    }))
  }

  // A card opens its own game screen. Only Play cards and our own launch panels reach here,
  // so a game another plugin brings can never end up at Game Center's table.
  const openTable = id => {
    selectionGen.current++
    setSelected(id)
    setReply('')
    setBoard({ text: '', picture: null })
    setTown(false)
    setPlaying(id)
  }

  // The Jackpot cabinets (JACKPOT v2, 19-jackpot2-layer.js) are not a server game: they are their
  // own screen with the same wallet, so they open straight into Game Center's left column.
  const openJackpot = () => {
    setPlaying(JP2L_ID)
    setReply('')
    setBoard({ text: '', picture: null })
  }

  // Join opens that game's table, which is where seats are taken. It never claims to
  // connect to anyone: this build has no network, and the wording says so.
  const joinAlert = row => {
    const inPlay = (view.play || []).some(item => item.id === row.game)
    if (inPlay) openTable(row.game)
    else if (row && row.game) setReply(`${row.title || row.game} is not at a table here. /games looking ${row.game} in the chat.`)
  }

  // Dismiss hides one row for a while, quietly: no dialog, no sound, no focus change.
  const dismissAlert = async row => {
    if (!row || !row.key) return
    try {
      await ctx.rest('/alerts/dismiss', { method: 'POST', body: { key: row.key } })
    } catch { /* the next refresh reads the truth either way */ }
    await refresh()
  }

  // Experimental games open their own screen, or nothing at all. A card that cannot open says so on
  // itself, and the rest of the page keeps working.
  const openYourGame = async card => {
    if (card.error) return String(card.error)
    if (card.opens === 'screen' && card.desktop_route) {
      try {
        if (!host || typeof host.navigate !== 'function') return 'Game Center cannot open another plugin’s screen here.'
        host.navigate(card.desktop_route)
        return ''
      } catch {
        return `Could not open ${card.title}. Its own screen is not available here.`
      }
    }
    if (card.opens === 'panel' && card.builtin) {
      openTable(card.id)
      return ''
    }
    return `This game has no screen of its own. In chat, /games install ${card.id} adds it, then /games ${card.id} plays it.`
  }

  // Submit your game: the configured page, or the guide when that page is not set.
  const openSubmit = async () => {
    if (!submit.href) return
    try {
      const opened = ctx && ctx.os && typeof ctx.os.openExternal === 'function'
        ? await ctx.os.openExternal(submit.href)
        : false
      if (!opened) setReply(`Could not open ${submit.href} in your browser.`)
    } catch {
      setReply(`Could not open ${submit.href} in your browser.`)
    }
  }

  const staffRole = (view.online && view.online.staff && view.online.staff.role) || ''
  const tabs = jsxs('div', {
    style: { display: 'flex', gap: 6, padding: area === 'champions' ? '12px 18px 0' : '0', background: paper },
    children: [
      button('Games', () => setArea('games'), { primary: area === 'games' }),
      button('Champions', () => setArea('champions'), { primary: area === 'champions' }),
      // The Admin tab appears only for a staff key that works with this account.
      staffRole ? button('Admin', () => setArea('admin'), { primary: area === 'admin' }) : null,
      // The way out, top right of the Games screen, level with the tabs (owner's ask, 2026-11-11).
      // Other screens get the same button floated top right by GameCenterRoute (80-plugin.js).
      area === 'games' ? jsx('span', { 'data-gc-close-header': '1', style: { marginLeft: 'auto' }, children: closeGameCenterButton(ctx) }) : null
    ]
  })

  if (area === 'admin') {
    return skinShell(skin, jsxs('div', {
      style: { display: 'flex', flexDirection: 'column', height: '100%', minHeight: 0, background: paper },
      children: [jsx('div', { style: { padding: '12px 18px 0' }, children: tabs }), jsx(AdminPage, { ctx, view, onBack: () => setArea('games') })]
    }))
  }

  if (area === 'champions') {
    // Champions is not ready to run matches, so the tab says so plainly instead of opening a
    // page whose buttons would answer with an error. The page stays in the bundle, unreferenced,
    // so bringing it back is one line.
    return skinShell(skin, jsxs('div', {
      style: { display: 'flex', flexDirection: 'column', height: '100%', minHeight: 0, background: paper },
      children: [tabs, jsxs('div', {
        'data-champions-coming-soon': '1',
        style: { padding: '18px 18px 24px', display: 'flex', flexDirection: 'column', gap: 10, alignItems: 'flex-start' },
        children: [
          comingSoon('Champions', 'Build a champion, run it against the other seats and keep its record. Not switched on yet: the matches it needs do not run in this version.'),
          jsx('div', { style: { fontSize: 12, color: text.tertiary }, children: 'Play and Experimental are unaffected.' })
        ]
      })]
    }))
  }

  // Settings: the name, the per-game switches, the pause and the AI choice. It is a
  // side link, not a section of the home page, so nothing there shifts around.
  if (area === 'settings') {
    return jsxs('div', {
      className: 'games-center-shell',
      'data-skin': skin,
      style: { display: 'flex', flexDirection: 'column', gap: 0, height: '100%', minHeight: 0, background: paper },
      children: [
        jsx('style', { children: SKIN_CSS }),
        jsx('div', { style: { padding: '12px 18px 0' }, children: tabs }),
        jsx(SettingsPanel, {
          view,
          ctx,
          skin,
          onSkin: setSkin,
          onBack: next => setArea(next === 'community' ? 'community' : 'games'),
          onCommunity: () => setArea('community'),
          onSaved: refresh,
          onReopen: async () => {
            setWelcomeClosed(false)
            setArea('games')
            // Bring the saved answer in now, so the welcome is what is on screen next
            // rather than a games page that a poll would replace a moment later.
            await refresh()
          }
        })
      ]
    })
  }

  // Community creations is a side link, never part of the Play page: link-out cards only,
  // the same labels and the same disclosure as before.
  if (area === 'community') {
    return jsxs('div', {
      className: 'games-center-shell',
      'data-skin': skin,
      style: { display: 'flex', flexDirection: 'column', gap: 0, height: '100%', minHeight: 0, background: paper, overflow: 'auto', paddingBottom: 96 },
      children: [
        jsx('style', { children: SKIN_CSS }),
        jsx('div', { style: { padding: '12px 18px 0' }, children: tabs }),
        jsxs('div', {
          style: { display: 'flex', flexDirection: 'column', gap: 14, padding: 18, minWidth: 0 },
          children: [
            jsxs('div', {
              style: { display: 'flex', justifyContent: 'space-between', gap: 12, alignItems: 'end', flexWrap: 'wrap' },
              children: [
                jsxs('div', {
                  children: [
                    jsx('div', { style: { fontFamily: DISPLAY_FONT, fontSize: 26, lineHeight: 1.15, letterSpacing: '-.02em', fontWeight: 600 }, children: 'Community creations' }),
                    jsx('div', {
                      style: { fontSize: 12, color: text.tertiary, marginTop: 4 },
                      children: 'Games other people made. Game Center only opens the link in your browser.'
                    })
                  ]
                }),
                jsxs('div', { style: { display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap' }, children: [
                  button(submit.label, openSubmit, {
                    primary: true,
                    disabled: !submit.href,
                    title: submit.href || 'Submissions are not open yet.'
                  }),
                  button('Back to Game Center', () => setArea('games'))
                ] })
              ]
            }),
            submit.href
              ? null
              : jsx('div', {
                  role: 'status',
                  style: { fontSize: 12, color: text.secondary },
                  children: 'Submissions are not open yet. The guide is docs/SUBMIT-A-GAME.md in the Game Center folder.'
                }),
            jsx(CommunityShelf, { community, ctx }),
            reply
              ? jsx('div', { role: 'status', 'aria-live': 'polite', style: { fontSize: 12, color: text.secondary }, children: reply })
              : null
          ]
        })
      ]
    })
  }

  const tileGrid = children => jsx('div', {
    // 200 px a card, not 260: the lobby panel gives up half its width on the main screen
    // (owner's ask, 2026-11-11) and that width buys one more column of game cards.
    style: { display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(min(100%, 200px), 1fr))', gap: 12 },
    children
  })

  // Labs: the experiment shelf. The Make games workshop is its first block; another lane adds the
  // next one to this list with the same element and no new styles. Each block is a real component,
  // so its own state never depends on which other screens have been on this page before.
  const labsBlocks = [
    labsPlay.length
      ? jsx('div', {
          key: 'playable-experiments',
          style: { display: 'contents' },
          children: labsBlock('From the workshop',
            'Drafts you can see now. They open when they are ready; nothing here is rated or in a lobby, and it may change or be removed.',
            tileGrid(labsPlay.map(item => labsPlayCard(item, openTable))))
        })
      : null,
    (makers.items || []).length
      ? jsx(LabsLinks, {
          title: 'Make games',
          note: makers.note || 'Tools for making games, not playing them. Each card opens that tool’s own page.',
          notice: makers.notice,
          items: makers.items,
          ctx
        }, 'make-games')
      : null,
    // Pet Battles is an experiment, so it lives here and not on the Play shelf - and it is locked
    // with the rest of this shelf (owner's ask 2026-11-10, #7): visible, no way in.
    jsx('div', {
      key: 'pet-battles-labs',
      style: { minWidth: 0 },
      children: labsBlock(
        'Play a battle',
        'A turn-based 3v3 pet battle with original critters. Pick a type and four moves, then take on the computer.',
        labsLocked(jsx(PetBattlesLabsCard, {}), 'pet-battles')
      )
    }, 'pet-battles-labs'),
    // Mafia Town: the same mafia table with the town square drawn on top. Locked like its neighbours.
    jsx('div', {
      key: 'mafia-town-labs',
      style: { minWidth: 0 },
      children: labsBlock(
        'Play a different table',
        'The Mafia talking table drawn as a town square: night, dawn, speech bubbles, and votes by portrait.',
        labsLocked(jsx(MafiaTownCard, {}), 'mafia-town')
      )
    }, 'mafia-town-labs')
  ].filter(Boolean)

  // One shelf for everything that is not curated Play: the games a plugin installed and the
  // prototypes from the workshop, under a single heading and a single sentence. Two sections
  // both saying "experimental" read as a filing system, not as something to try (owner's ask,
  // 2026-11-09). Owner's ask 2026-11-11: this whole shelf - the Coming-soon cards and the Labs
  // blocks - is off the main page and behind ONE small "Experimental" link, where it is kept
  // locked and hidden for later. Nothing of it is drawn on the Play page any more.
  const experiments = jsxs('div', {
    'data-experiments': '1',
    style: { display: 'flex', flexDirection: 'column', gap: 12, minWidth: 0 },
    children: [
      heading('Experimental'),
      // The one short line under the heading (owner's ask 2026-11-10, #7): the shelf is a window.
      jsx('div', { 'data-experimental-help': '1', style: { fontSize: 13, color: text.secondary, marginBottom: 2, maxWidth: 620 }, children: LABS_LOCK_HELP }),
      jsx('div', { 'data-experiments-note': '1', style: { fontSize: 12, color: text.tertiary, marginBottom: 2, maxWidth: 620 }, children: EXPERIMENTS_NOTE }),
      yourList.length
        ? tileGrid(yourList.map(item => jsx(YourGameCard, { item, onOpen: openYourGame }, item.id)))
        : jsx('div', { style: { fontSize: 13, color: text.tertiary }, children: 'Nothing installed yet. A game another plugin ships lands here the moment the plugin is on.' }),
      // The workshop blocks keep their own titles; the shelf heading above covers the section.
      labsShelf(labsBlocks, undefined, { withHeading: false }),
      suggestionRow(suggestions, ctx)
    ]
  })

  // The one small link's destination. It is the shelf above, drawn on its own screen so the Play
  // page stays clean; every card in it is still locked, so the screen is a window, not a door.
  if (area === 'experimental') {
    return jsxs('div', {
      className: 'games-center-shell',
      'data-skin': skin,
      style: { display: 'flex', flexDirection: 'column', gap: 0, height: '100%', minHeight: 0, background: paper, overflow: 'auto', paddingBottom: 96 },
      children: [
        jsx('style', { children: SKIN_CSS }),
        jsx('div', { style: { padding: '12px 18px 0' }, children: tabs }),
        jsxs('div', {
          style: { display: 'flex', flexDirection: 'column', gap: 14, padding: 18, minWidth: 0 },
          children: [
            jsxs('div', {
              style: { display: 'flex', justifyContent: 'space-between', gap: 12, alignItems: 'center', flexWrap: 'wrap' },
              children: [
                jsx('div', {
                  style: { fontSize: 12, color: text.tertiary },
                  children: 'Kept here for a look, off the Play page. Nothing in it opens yet.'
                }),
                button('Back to Game Center', () => setArea('games'))
              ]
            }),
            experiments
          ]
        })
      ]
    })
  }

  const store = jsxs('div', {
    style: { display: 'flex', flexDirection: 'column', gap: 18, padding: 18, paddingBottom: 96, minWidth: 0, overflow: 'auto', background: paper },
    children: [
      tabs,
      jsxs('div', {
        style: { display: 'flex', justifyContent: 'space-between', gap: 12, alignItems: 'end', flexWrap: 'wrap' },
        children: [
          jsxs('div', {
            style: { display: 'flex', alignItems: 'center', gap: 14, minWidth: 0 },
            children: [
              jsx(GameCenterMark, { size: 48 }),
              jsxs('div', {
                children: [
                  // The install in view, at the TOP of the Games screen beside the wordmark: small and
                  // muted, one source (/v1/version), the same component Settings mounts.
                  jsxs('div', { style: { display: 'flex', alignItems: 'baseline', gap: 10, flexWrap: 'wrap', minWidth: 0 }, children: [
                    jsx(GameCenterWordmark, {}),
                    jsx('span', {
                      'data-games-version-header': '1',
                      children: jsx(GamesVersionChip, {
                        ctx,
                        style: { fontSize: 10, padding: '1px 6px', opacity: 0.8, letterSpacing: '0.02em' }
                      })
                    })
                  ] }),
                  jsx('div', {
                    style: { fontSize: 12, color: text.tertiary, marginTop: 4 },
                    children: view.player.named ? `You are ${view.player.name}` : 'Pick a name in Settings to chat'
                  }),
                  jsx('div', {
                    style: { marginTop: 6, display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' },
                    children: [
                      jsx(PointsChip, { ctx }),
                      // The obvious door (owner's ask, 2026-11-11): one press opens the side pane
                      // and keeps a game beside the chat while Hermes works. While the pane is
                      // open the same button reads Close side pane.
                      // From full screen the door LEAVES Game Center: back to the chat with the
                      // pane on the right, on the same game (owner, 2026-11-11).
                      paneDoorButtonElement(paneOn, null, () => paneFromPage(ctx, selected))
                    ]
                  })
                ]
              })
            ]
          }),
          jsxs('div', { style: { display: 'flex', gap: 12, alignItems: 'center', flexWrap: 'wrap' }, children: [
            jsx('div', { style: { width: 220 }, children: field(query, setQuery, 'Search games', () => {}) }),
            // The clear way back: one link, back under the chat, wherever this page was left.
            textLink('Back to chat', () => closeGameCenter(ctx)),
            textLink('How to play', () => setLobbyHowto(true)),
            // One small link, and the only trace of the experiments on this page: the Coming-soon
            // cards and the Labs shelf live behind it (owner's ask, 2026-11-11).
            textLink('Experimental', () => setArea('experimental')),
            textLink('Settings', () => setArea('settings')),
            textLink('Community creations', () => setArea('community'))
          ] })
        ]
      }),
      // The way out to the project itself (owner's ask, 2026-11-11): one row of three links, settled
      // right under the header beside Experimental / Settings / Community creations, each handed to
      // the person's own browser by the same door the Submit button uses.
      jsx(GameCenterLinks, { ctx, onNote: setReply }),
      // Owner's ask 2026-11-09: no alert drops anywhere for now. The rows are still read from
      // /alerts and the component is still in the bundle, so bringing it back is this one line.
      null,
      // Find match lives in the lobby panel now, where it can see the lobby's own answer:
      // the stand-alone bar here used to press with whatever game happened to be selected,
      // which is how it could say it was looking for blackjack (owner's ask, 2026-11-11).
      jsx(LobbyWhoOnline, {
        view, ctx, current,
        // "Play here" on a Hall row: the lobby server took the room, so open that game's table,
        // which draws the server's picture instead of a local game.
        onPlayHere: match => openTable((match && match.game) || current)
      }),
      view.notice ? jsx('div', {
        role: 'status', 'aria-live': 'polite',
        style: { padding: '10px 12px', borderRadius: 8, border: `1px solid ${accent}`, fontSize: 13, color: text.primary, background: card },
        children: view.notice
      }) : null,
      playProblems.length
        ? jsx('div', { role: 'status', style: { fontSize: 12, color: text.secondary }, children: playProblems.join(' ') })
        : null,
      jsxs('div', {
        children: [
          heading('Play'),
          jsx('div', { style: { fontSize: 12, color: text.tertiary, marginBottom: 8 }, children: PLAY_NOTE }),
          playList.length
            ? tileGrid(jp2LPlayTiles(playList, openTable, waitingCount, openJackpot, matches))
            : jsx('div', { style: { fontSize: 13, color: text.tertiary }, children: 'No curated games to show.' })
        ]
      }),
      jsx(LobbyLadder, { view, current }),
      null
    ]
  })
  const right = jsx(LobbyChatColumn, {
    view, ctx, send, chat, setChat, name, setName, current,
    // "Play here" on the match card: the lobby server has taken the room, so open that game's
    // table, which draws the server's own picture instead of a local game.
    onPlayHere: match => openTable((match && match.game) || current)
  })

  return jsx('div', {
    className: 'games-center-shell',
    'data-skin': skin,
    style: { height: '100%', minHeight: 0, minWidth: 0, containerType: 'inline-size' },
    children: jsx('div', {
    className: 'games-center-layout',
    style: {
      display: 'grid',
      gridTemplateColumns: playing ? 'minmax(0, 1fr)' : 'minmax(0, 1fr) minmax(110px, 140px)',
      height: '100%',
      minHeight: 0,
      background: paper,
      isolation: 'isolate',
      position: 'relative',
      zIndex: 1
    },
    children: [
      jsx('style', { children: `
        .games-center-layout { container-type: inline-size; }
        .games-play-table { box-sizing: border-box; }
        .games-play-table button:focus-visible, .games-play-table select:focus-visible { outline: 2px solid var(--ui-accent, #7ec8ff); outline-offset: 3px; }
        .games-board-panel > .games-board-stage, .doctrine-board-panel > .games-board-stage { min-width: 0; flex-shrink: 0; }
        .games-seabattle-boards { min-width: 0; }
        @container (max-width: 880px) {
          .games-seabattle-boards { flex-direction: column !important; align-items: center !important; }
        }
        @container (max-width: 520px) { .games-seats { grid-template-columns: minmax(0, 1fr) !important; } }
        @container (max-width: 820px) {
          .games-center-layout { grid-template-columns: minmax(0, 1fr) !important; grid-auto-rows: max-content; overflow: auto; }
          .games-center-layout > .games-play-table { height: auto !important; overflow: visible !important; padding: 14px !important; }
          .games-center-lobby { min-width: 0 !important; border-left: 0 !important; border-top: 1px solid var(--ui-stroke-secondary); max-height: 260px; }
        }
        @media (max-width: 900px) {
          .games-center-layout { grid-template-columns: minmax(0, 1fr) !important; grid-auto-rows: max-content; overflow: auto; }
          .games-center-layout > .games-play-table { height: auto !important; overflow: visible !important; padding: 14px !important; }
          .games-center-lobby { min-width: 0 !important; border-left: 0 !important; border-top: 1px solid var(--ui-stroke-secondary); max-height: 260px; }
        }
        @media (prefers-reduced-motion: reduce) { .games-play-table * { animation: none !important; transition: none !important; } }
      ` + SKIN_CSS }),
      playing && board.error
        ? jsxs('div', {
            role: 'alert',
            'data-games-board-error': playing,
            style: { display: 'flex', gap: 10, alignItems: 'center', flexWrap: 'wrap', padding: '8px 12px', borderRadius: 10, border: `1px solid ${stroke}`, background: card, color: text.secondary, fontSize: 13 },
            children: [
              jsx('span', { children: `This game could not load (${board.error}). Retrying every few seconds.` }),
              button('Back to games', () => setPlaying(''))
            ]
          })
        : null,
      // JACKPOT v2 first: it is not a server game, so it never asks the shelf for a board — it is
      // the machine itself, at the size this column allows, and nothing of it is clipped.
      playing === JP2L_ID || playing === 'slots'
        ? jsx(Jackpot2Full, { ctx, onBack: () => setPlaying('') })
        : playing && game && game.id === playing
        ? game.id === 'doctrine'
          ? jsx(DoctrinePanel, {
              game,
              view,
              board,
              send,
              playMove,
              importText: async text => {
                const answer = await ctx.rest('/doctrine/import', { method: 'POST', body: { text } })
                return answer
              },
              refresh,
              ctx,
              onBack: () => setPlaying('')
            })
          : game.id === ARENA_ID
            ? jsx(ArenaPanel, { game, view, board, send, ctx, onBack: () => setPlaying('') })
            : game.id === PETB_ID
              ? jsx(PetBattlePanel, {
                  game,
                  view,
                  board,
                  send,
                  ctx,
                  onBack: () => setPlaying('')
                })
              : game.id === 'mafia' && town
              ? jsx(MafiaTown, {
                  game,
                  view,
                  board,
                  send,
                  ctx,
                  onBack: () => setPlaying(''),
                  onClassic: () => setTown(false)
                })
              : TALKING_IDS.includes(game.id)
              ? jsx(TalkingTable, {
                  game,
                  view,
                  board,
                  send,
                  refresh,
                  ctx,
                  onBack: () => setPlaying('')
                })
              : (game.kind || 'table') === 'table'
              ? jsx(PlayTable, {
                  game,
                  view,
                  board,
                  playMove,
                  send,
                  ctx,
                  onBack: () => setPlaying('')
                })
              : jsx(LaunchPanel, { game, view, board, send, ctx, onBack: () => setPlaying('') })
        : store,
      playing ? null : right,
      playing || !lobbyHowto ? null : jsx(LobbyHowTo, { onClose: () => setLobbyHowto(false) })
    ]
    })
  })
}

// ---- 72-lobby.js: the home lobby and its chat column

// Every two-player game the lobby server can seat, with the label its switch wears.
// This mirrors online/requests.py REQUESTABLE, and a test compares the two lists, so
// a game added on the server cannot quietly go missing from the lobby.
const LOBBY_GAMES = [
  ['connect4', 'Connect 4'],
  ['reversi', 'Reversi'],
  ['checkers', 'Checkers'],
  ['gomoku', 'Gomoku'],
  ['chessboard', 'Chess'],
  ['go', 'Go'],
  ['hex', 'Hex'],
  ['breakthrough', 'Breakthrough'],
  ['seabattle', 'Sea Battle']
]
const LOBBY_GAME_IDS = LOBBY_GAMES.map(item => item[0])
const LOBBY_TITLES = Object.fromEntries(LOBBY_GAMES)
const lobbyTitle = id => LOBBY_TITLES[id] || id

// A lobby post is a day old at most: the server deletes the rest, and this screen
// never draws anything older even in the moment before that sweep.
const LOBBY_POST_MS = 24 * 3600 * 1000

// "08-04 21:35" - the date and the time on every post, in this computer's own clock.
function lobbyStamp(at) {
  const ms = Number(at || 0) * 1000
  if (!ms) return ''
  const when = new Date(ms)
  const pad = number => String(number).padStart(2, '0')
  return `${pad(when.getMonth() + 1)}-${pad(when.getDate())} ${pad(when.getHours())}:${pad(when.getMinutes())}`
}

// Only lines this screen can date, and only ones from the last day.
function freshLobbyLines(lines) {
  const now = Date.now()
  return (Array.isArray(lines) ? lines : []).filter(item =>
    item && Number(item.at || 0) > 0 && now - Number(item.at) * 1000 < LOBBY_POST_MS)
}

// The short "How to play" card for the lobby page, in the same shape as the other
// surfaces' how-to cards: a header button, plain words, one way out.
function LobbyHowTo({ onClose }) {
  const paragraph = { fontSize: 13, color: text.secondary, lineHeight: 1.5 }
  return jsx('div', {
    'data-testid': 'lobby-howto',
    style: {
      position: 'fixed', inset: 0, zIndex: 70, display: 'flex', alignItems: 'center', justifyContent: 'center',
      background: 'rgba(8,11,16,0.7)', backdropFilter: 'blur(3px)', padding: 16, overflowY: 'auto'
    },
    children: jsxs('div', {
      style: {
        width: 'min(520px, 100%)', maxHeight: '90%', overflow: 'auto', borderRadius: 18,
        border: `1px solid ${stroke}`, background: 'var(--ui-bg-elevated, #141c26)', padding: 20,
        display: 'flex', flexDirection: 'column', gap: 10, boxShadow: '0 18px 50px rgba(0,0,0,0.4)'
      },
      children: [
        jsx('div', { style: { fontSize: 18, fontWeight: 700 }, children: 'How to play' }),
        jsx('div', { style: paragraph, children: 'This is Game Center: board games you can sit down at right now. Under Play, press a game — then pick a level to face the computer, or Choose how to play for the other ways in. You move by clicking the board.' }),
        jsx('div', { style: paragraph, children: 'To play a person: open the lobby and press Find match on the games you want (one, several, or All games) — the lobby pairs you with anyone else who wants one of them right now, and a dialog asks you to join when a match is found. Chat with everyone in #games on the right (set a name first). When a table is ready, press Play here and the match opens on this page.' }),
        jsx('div', { style: paragraph, children: 'Each game decides its own winner — Connect 4 gets four discs in a row, Reversi turns the board over. The screen always says whose turn it is and how the game ended.' }),
        jsxs('div', { style: { display: 'flex', gap: 8, justifyContent: 'flex-end', marginTop: 2 }, children: [
          button('Got it', onClose, { primary: true })
        ] })
      ]
    })
  })
}

function usePetAvatar() {
  const [pet, setPet] = useState('')
  useEffect(() => {
    let active = true
    async function load() {
      try {
        if (typeof host === 'undefined' || !host || typeof host.request !== 'function') return
        const info = await host.request('pet.info', {})
        if (!info || !info.enabled || !info.slug) return
        const thumb = await host.request('pet.thumb', { slug: info.slug, url: '' })
        if (active && thumb && thumb.ok && typeof thumb.dataUri === 'string') setPet(thumb.dataUri)
      } catch { /* A pet is optional. */ }
    }
    load()
    return () => { active = false }
  }, [])
  return pet
}

function Avatar({ name, pet, kind }) {
  const circle = { width: 18, height: 18, borderRadius: '50%', flexShrink: 0 }
  return jsxs('span', { style: { display: 'inline-flex', alignItems: 'center', gap: 3 }, children: [
    pet && kind !== 'bot'
      ? jsx('img', { src: pet, alt: '', style: { ...circle, objectFit: 'cover' } })
      : jsx('span', { style: { ...circle, display: 'inline-flex', alignItems: 'center', justifyContent: 'center', background: fill, color: text.secondary, fontSize: 10 }, children: String(name || '?')[0].toUpperCase() }),
    kind === 'bot' ? jsx('span', { style: { fontSize: 9, color: text.tertiary }, children: 'BOT' }) : null
  ] })
}

// Find match: chips, one per game the server can seat, plus All games. What is picked
// is what the server is looking for right now - the chips read back the server's own
// answer, so a chip can never claim to be looking for a game the lobby was not told
// about. Nothing is picked by default: pressing Find match yourself turns one on, and
// pressing the last one off (or Stop) turns it off.
function LobbyFindMatch({ looking, post, pending, busyNote }) {
  const mine = LOBBY_GAME_IDS.filter(id => (looking || []).includes(id))
  const all = mine.length === LOBBY_GAME_IDS.length
  const held = say => ({ disabled: Boolean(pending), title: pending ? busyNote : say })
  const chipStyle = on => ({
    fontSize: 11, padding: '3px 8px', borderRadius: 999, cursor: 'pointer',
    border: `1px solid ${on ? accent : stroke}`,
    background: on ? fill : 'transparent', color: text.secondary
  })
  const chip = (id, label, on) => jsx('button', {
    'data-lobby-chip': id,
    'aria-pressed': on ? 'true' : 'false',
    ...held(on ? `Stop looking for ${label}.` : `Look for a game of ${label} right now.`),
    onClick: () => {
      const next = on ? mine.filter(item => item !== id) : mine.concat([id])
      post(`looking:${id}`, '/online/hall/looking',
        next.length ? { games: next } : { on: false })
    },
    style: chipStyle(on),
    children: label
  })
  // "All games" is not one more game in the list: it is the server's own all, so a game
  // added on the server later is looked for too without this screen being changed.
  const allChip = jsx('button', {
    'data-lobby-chip': 'all',
    'aria-pressed': all ? 'true' : 'false',
    ...held(all ? 'Stop looking for a match.' : 'Look for every game the server can seat right now.'),
    onClick: () => post('looking:all', '/online/hall/looking', all ? { on: false } : { all: true }),
    style: chipStyle(all),
    children: 'All games'
  })
  const wanted = all
    ? 'Looking for a game in every game the lobby can seat right now — the first person who wants one of them gets the offer.'
    : mine.length
      ? `Looking for ${mine.map(lobbyTitle).join(', ')} right now — the lobby pairs you with anyone else who wants one of them.`
      : 'Nothing picked yet: press a game to start looking, and the lobby pairs you with anyone else who wants it.'
  return jsxs('div', {
    'data-lobby-find': '1',
    style: { display: 'flex', flexDirection: 'column', gap: 6, borderTop: `1px solid ${stroke}`, paddingTop: 10 }
  , children: [
    jsxs('div', { style: { display: 'flex', alignItems: 'center', gap: 8, flexWrap: 'wrap' }, children: [
      jsx('span', { style: { fontSize: 12, fontWeight: 650 }, children: 'Find match' }),
      mine.length ? jsx('button', {
        'data-lobby-find-stop': '1',
        ...held('Stop looking for a match.'),
        onClick: () => post('looking:stop', '/online/hall/looking', { on: false }),
        style: { fontSize: 11, padding: '2px 8px', borderRadius: 999, border: `1px solid ${stroke}`, background: 'transparent', color: text.tertiary, cursor: 'pointer' },
        children: 'Stop looking'
      }) : null
    ] }),
    jsx('div', { role: 'group', 'aria-label': 'Games to find a match in', style: { display: 'flex', flexWrap: 'wrap', gap: 6 }, children: [
      ...LOBBY_GAMES.map(([id, label]) => chip(id, label, mine.includes(id))),
      allChip
    ] }),
    jsx('div', { style: { fontSize: 11, color: text.tertiary, lineHeight: 1.45 }, children: wanted })
  ] })
}

// A match offer. Find match made it, so neither person sent it: whichever of you
// presses Join sits both down at the same private table. The dialog is the ask; the
// dim line under the roster is the same news kept on the panel.
function LobbyOfferDialog({ card, other, otherName, onJoin, onNotNow, busy, busyNote }) {
  const title = `${otherName} wants to play ${lobbyTitle(card.game)}`
  return jsx('div', {
    'data-lobby-offer': String(card.id),
    role: 'dialog', 'aria-modal': 'true', 'aria-label': title,
    style: {
      position: 'fixed', inset: 0, zIndex: 90, display: 'flex', alignItems: 'center', justifyContent: 'center',
      background: 'rgba(8,11,16,0.62)', backdropFilter: 'blur(2px)', padding: 16
    },
    children: jsxs('div', {
      style: {
        width: 'min(420px, 100%)', borderRadius: 16, border: `1px solid ${stroke}`,
        background: 'var(--ui-bg-elevated, #141c26)', padding: 18, display: 'flex', flexDirection: 'column', gap: 10,
        boxShadow: '0 18px 50px rgba(0,0,0,0.4)'
      },
      children: [
        jsx('div', { style: { fontSize: 16, fontWeight: 700 }, children: title }),
        jsx('div', { style: { fontSize: 12, color: text.secondary, lineHeight: 1.5 }, children: 'You are both looking for this game. Join and you sit down together at a private table inside Hermes — no code to copy.' }),
        jsxs('div', { style: { display: 'flex', gap: 8, justifyContent: 'flex-end', marginTop: 2 }, children: [
          jsx('button', {
            'data-lobby-offer-notnow': '1',
            disabled: Boolean(busy), title: busy ? busyNote : 'Say not this time.',
            onClick: onNotNow,
            style: { fontSize: 13, padding: '6px 12px', borderRadius: 10, border: `1px solid ${stroke}`, background: 'transparent', color: text.secondary, cursor: 'pointer' },
            children: 'Not now'
          }),
          button('Join', onJoin, { primary: true, disabled: Boolean(busy), title: busy ? busyNote : `Sit down with ${otherName}.` })
        ] })
      ]
    })
  })
}

// ---- The Hall: who is here right now, and the game requests between you -----
// While online play is on, Game Center keeps one lobby socket open (even with the
// dock closed); this screen reads that socket's snapshot from GET /online/hall and
// sends every move through the four /online/hall/* doors. It never shows an
// address, a key or an invite code — only names, the game each person accepts, and
// the requests you have open.
const HALL_POLL_MS = 3000

// post() lets one Hall action through at a time. Every other control on the panel is held
// while that one is out — and says so on hover, rather than looking pressable and being ignored.
const HALL_BUSY_NOTE = 'Another Hall action is still going through. Wait for it, then try again.'

// online is ready to play, away is here but idle, playing is already at a table.
const HALL_STATUS_DOT = { online: '#3ee0c5', away: '#ffb020', playing: 'var(--ui-fill-tertiary, rgba(127,127,127,0.45))' }

function LobbyHall({ ctx, current, view, onPlayHere }) {
  const [snap, setSnap] = useState(null)
  // A read that failed. The last snapshot stays on screen — it is still the best picture
  // there is — but never as if it were live.
  const [stale, setStale] = useState(false)
  // The one control whose POST is in flight; that control, and only it, is locked.
  const [pending, setPending] = useState('')
  const [ack, setAck] = useState('')
  // A seat the server offered that would not open, in the server's own words, and how many
  // times the person has asked for it again.
  const [seatProblem, setSeatProblem] = useState(null)
  const [seatAttempt, setSeatAttempt] = useState(0)
  // Rooms already opened, so a seat the server keeps reporting opens the table once.
  const handled = useRef(new Set())
  const alive = useRef(true)

  useEffect(() => { alive.current = true; return () => { alive.current = false } }, [])

  // The Hall snapshot, read every 3 s while this screen is up. The socket is the
  // shelf's; this only paints its latest answer, and clears the poll on unmount. A read
  // that fails is said out loud rather than leaving an old roster looking live.
  useEffect(() => {
    if (!ctx || typeof ctx.rest !== 'function') return undefined
    let timer = null
    const read = async () => {
      try {
        const answer = await ctx.rest('/online/hall')
        if (!alive.current) return
        if (answer && typeof answer === 'object') setSnap(answer)
        setStale(false)
      } catch (error) {
        // Keep the last snapshot; the next tick retries. It is simply not live any more.
        if (alive.current) setStale(true)
      }
    }
    read()
    timer = setInterval(read, HALL_POLL_MS)
    return () => { if (timer) clearInterval(timer) }
  }, [ctx])

  const state = snap ? String(snap.state || '') : 'connecting'
  const you = (snap && snap.you) || {}
  const prefs = (snap && snap.prefs) || { open: false, games: {} }
  const roster = (snap && snap.roster) || []
  const requests = (snap && snap.requests) || []
  const seated = (snap && snap.seated) || null
  // Appearing offline and find match come with "you": they are about this account, not
  // about the row it shows in the list.
  const invisible = Boolean(you.invisible)
  const looking = Array.isArray(you.looking) ? LOBBY_GAME_IDS.filter(id => you.looking.includes(id)) : []

  // A seat the server has made opens the online table here, then hands the room to
  // the page — once. The same room never opens twice on the next poll. A room that
  // will not open is not marked handled: nothing moves the person to a table that
  // never opened, the server's own words are shown, and the same seat can be asked
  // for again.
  useEffect(() => {
    const room = seated && seated.room_id ? String(seated.room_id) : ''
    if (!room || handled.current.has(room)) return
    handled.current.add(room)
    ;(async () => {
      let answer = null
      try { answer = await openOnlineTable(ctx, room, seated.game) } catch (error) { answer = { ok: false } }
      if (!answer || answer.ok === false) {
        handled.current.delete(room)
        if (alive.current) setSeatProblem({ room, text: String((answer && answer.text) || '') || 'That table would not open. Try again.' })
        return
      }
      if (alive.current) setSeatProblem(null)
      if (onPlayHere) onPlayHere({ room_id: room, game: seated.game })
    })()
  }, [seated && seated.room_id, seatAttempt])

  // The retry the refusal offers: the same room, asked for again.
  const retrySeat = () => setSeatAttempt(count => count + 1)

  // One door for every control: it is locked while its own POST is out, and a
  // refusal is shown in the server's own words rather than swallowed.
  const post = async (key, path, body) => {
    if (pending) return { ok: false }
    setPending(key)
    setAck('')
    try {
      const answer = ctx && typeof ctx.rest === 'function'
        ? await ctx.rest(path, { method: 'POST', body })
        : { ok: false, text: 'Game Center cannot be reached.' }
      if (alive.current && answer && answer.ok === false) setAck(String(answer.text || ''))
      return answer || { ok: true }
    } catch (error) {
      if (alive.current) setAck('That did not reach Game Center. Try again.')
      return { ok: false }
    } finally {
      if (alive.current) setPending('')
    }
  }

  const muted = { fontSize: 12, color: text.tertiary }
  // Every control on this panel posts through the one pending slot, so every control wears the
  // same lock and the same reason while anything is out.
  const held = say => ({ disabled: Boolean(pending), title: pending ? HALL_BUSY_NOTE : say })
  const shell = children => jsxs('div', {
    'data-hall': '1', 'data-hall-state': state,
    style: { borderTop: `1px solid ${stroke}`, paddingTop: 10, marginTop: 10, display: 'flex', flexDirection: 'column', gap: 8 },
    children: [heading('The Hall'), ...children]
  })
  const note = say => shell([jsx('div', { style: muted, children: say })])

  if (state === 'off') return note('Turn online play on to see who is here.')
  if (state === 'old-server') return note('This lobby server has no Hall yet. Find a match still works.')
  if (state !== 'live') return note(stale ? 'Reconnecting…' : 'Joining the Hall…')

  // The switches, in the order the person meets them: appear offline first (the one
  // control that takes you out of the lobby), then the master "Take game requests", then
  // one switch per game the server can seat. Every one of them is held while any Hall
  // POST is out, like every other control on this panel.
  const toggle = (label, checked, key, body, title, only) => jsxs('label', {
    title: pending ? HALL_BUSY_NOTE : title, 'data-hall-toggle': key,
    ...(only ? { 'data-hall-game': only } : {}),
    style: { display: 'flex', alignItems: 'center', gap: 6, fontSize: 12, color: text.secondary, cursor: 'pointer' },
    children: [
      jsx('input', { type: 'checkbox', checked: Boolean(checked), disabled: Boolean(pending),
        onChange: event => post(key === 'game' ? `game:${only}` : key, '/online/hall/prefs', body(event.target.checked)) }),
      jsx('span', { children: label })
    ]
  })
  const offered = LOBBY_GAME_IDS.filter(id => prefs.games && prefs.games[id])
  const header = jsxs('div', { style: { display: 'flex', flexDirection: 'column', gap: 6 }, children: [
    toggle('Appear offline', invisible, 'invisible', on => ({ invisible: on }),
      'When this is on, nobody sees you in the lobby list and nobody can ask you to a game. Turn it off to be listed again.'),
    jsx('div', { style: muted, children: invisible
      ? 'You are appearing offline: you are not in anyone else\u2019s lobby list, and requests to you are refused.'
      : `You are ${you.name || 'in the lobby'} and everyone else in the lobby can see you.` }),
    toggle('Take game requests', prefs.open, 'open', on => ({ open: on }),
      'When this is on, other players can ask you to a game. Turn it off and new requests stop; your per-game choices are kept.'),
    jsx('div', { style: { fontSize: 11, color: text.tertiary }, children: offered.length
      ? `Taking requests for: ${offered.map(lobbyTitle).join(', ')}.`
      : 'No game is switched on yet, so nobody can ask you for one.' }),
    jsx('div', { role: 'group', 'aria-label': 'Games you take requests for', style: { display: 'flex', flexWrap: 'wrap', gap: 10 }, children:
      LOBBY_GAMES.map(([id, label]) => toggle(label, prefs.games && prefs.games[id], 'game',
        on => ({ games: { [id]: on } }),
        `Accept requests for ${label}. The master switch above still has to be on.`, id))
    })
  ] })

  // A match offer from find match. Which of the two sent it does not matter: the dialog
  // is the same for both, and either side may join.
  const offerCards = requests.filter(req => req && req.state === 'pending' && req.offer)
  const offer = offerCards[0] || null
  const offerOther = offer
    ? (String(offer.from && offer.from.id) === String(you.id) ? (offer.to || {}) : (offer.from || {}))
    : null

  // The roster, you left out. A dot says whether each person can play now, and Ask is
  // offered only to someone online who accepts a game you are also taking.
  const others = roster.filter(row => String(row.id) !== String(you.id))
  const anyMine = LOBBY_GAME_IDS.some(id => prefs.games && prefs.games[id])
  const myAccepted = (prefs.open || anyMine) ? LOBBY_GAME_IDS.filter(id => prefs.games && prefs.games[id]) : LOBBY_GAME_IDS
  const rosterRows = others.length ? others.map(row => {
    const status = String(row.status || '')
    const shared = (Array.isArray(row.games) ? row.games : []).filter(id => myAccepted.includes(id))
    const askGame = shared[0] || ''
    const canAsk = status === 'online' && Boolean(askGame)
    const askKey = `ask:${row.id}`
    return jsxs('div', {
      'data-hall-row': String(row.id),
      style: { display: 'flex', alignItems: 'center', gap: 8, fontSize: 12, color: text.secondary },
      children: [
        jsx('span', { 'aria-hidden': true, style: { width: 8, height: 8, borderRadius: '50%', flexShrink: 0, background: HALL_STATUS_DOT[status] || text.tertiary } }),
        jsx('span', { style: { flex: 1, minWidth: 0 }, children: row.name }),
        shared.length ? jsx('span', { style: { ...muted, flexShrink: 0 }, children: shared.map(lobbyTitle).join(', ') }) : null,
        jsx('span', { 'data-hall-status': status, style: muted, children: status }),
        canAsk ? button('Ask', () => post(askKey, '/online/hall/request', { to: row.id, game: askGame }),
          held(`Ask ${row.name} to a game of ${lobbyTitle(askGame)}.`)) : null
      ]
    }, String(row.id))
  }) : jsx('div', { style: muted, children: 'Nobody else is here right now.' })

  // The requests between you: the ones to answer, then the ones you are waiting on.
  // A match offer is neither - it has its own dialog and its own line.
  const cardStyle = { display: 'flex', alignItems: 'center', flexWrap: 'wrap', gap: 8, fontSize: 12, color: text.secondary, border: `1px solid ${stroke}`, borderRadius: 10, padding: '8px 10px', background: card }
  const inbound = requests.filter(req => req.state === 'pending' && !req.offer && req.to && String(req.to.id) === String(you.id))
  const outbound = requests.filter(req => req.state === 'pending' && !req.offer && req.from && String(req.from.id) === String(you.id))
  const requestCards = [
    ...inbound.map(req => jsxs('div', { 'data-hall-request': String(req.id), style: cardStyle, children: [
      jsx('span', { style: { flex: 1, minWidth: 120 }, children: `${req.from.name} wants to play ${req.game}` }),
      button('Accept', () => post(`respond:${req.id}`, '/online/hall/respond', { id: req.id, accept: true }),
        { primary: true, ...held(`Accept and sit down with ${req.from.name}.`) }),
      button('Decline', () => post(`respond:${req.id}`, '/online/hall/respond', { id: req.id, accept: false }),
        held('Say no to this request.'))
    ] }, String(req.id))),
    ...outbound.map(req => jsxs('div', { 'data-hall-request': String(req.id), style: cardStyle, children: [
      jsx('span', { style: { flex: 1, minWidth: 120 }, children: `Asked ${req.to.name}… ` }),
      button('Cancel', () => post(`cancel:${req.id}`, '/online/hall/cancel', { id: req.id }),
        held(`Take back your request to ${req.to.name}.`))
    ] }, String(req.id)))
  ]

  return shell([
    header,
    stale ? jsx('div', {
      role: 'status', 'aria-live': 'polite', 'data-hall-reconnecting': '1',
      style: { ...muted, color: text.secondary },
      children: 'Reconnecting… the list below is the last one this computer saw.'
    }) : null,
    jsx(LobbyFindMatch, { looking, post, pending, busyNote: HALL_BUSY_NOTE }),
    offer ? jsxs('div', {
      'data-lobby-offer-line': '1', role: 'status', 'aria-live': 'polite',
      style: { fontSize: 11, color: text.tertiary, lineHeight: 1.45 },
      children: [
        jsx('span', { children: `${offerOther.name || 'Someone'} wants to play ${lobbyTitle(offer.game)} — Join or Not now on the dialog.` }),
        jsx('span', { children: ' (Not sent to the model: Game Center shows this itself.)' })
      ]
    }) : null,
    seatProblem ? jsxs('div', {
      role: 'alert', 'data-hall-seat-problem': '1',
      style: { ...muted, color: text.primary, border: `1px solid ${accent}`, borderRadius: 10, padding: '8px 10px', display: 'flex', alignItems: 'center', flexWrap: 'wrap', gap: 8 },
      children: [
        jsx('span', { style: { flex: 1, minWidth: 120 }, children: `Your table could not be opened: ${seatProblem.text}` }),
        button('Try again', retrySeat, { title: 'Ask the lobby server to open that same table again.' })
      ]
    }) : null,
    jsx('div', { style: { display: 'flex', flexDirection: 'column', gap: 6 }, children: rosterRows }),
    requestCards.length ? jsx('div', { style: { display: 'flex', flexDirection: 'column', gap: 6 }, children: requestCards }) : null,
    ack ? jsx('div', { role: 'status', 'aria-live': 'polite', style: { ...muted, color: text.secondary }, children: ack }) : null,
    offer ? jsx(LobbyOfferDialog, {
      card: offer, other: offerOther, otherName: String(offerOther.name || 'Someone'),
      busy: Boolean(pending), busyNote: HALL_BUSY_NOTE,
      onJoin: () => post(`offer:${offer.id}`, '/online/hall/respond', { id: offer.id, accept: true }),
      onNotNow: () => post(`offer:${offer.id}`, '/online/hall/respond', { id: offer.id, accept: false })
    }) : null
  ])
}

function LobbyWhoOnline({ view, ctx, current, onPlayHere }) {
  const pet = usePetAvatar()
  const online = onlineView(view)
  const presence = (view.online && view.online.presence) || {}
  const muted = { fontSize: 12, color: text.tertiary }
  if (!online.on || online.offline) {
    const rows = (view.lobby && view.lobby.looking) || []
    return jsxs('div', { children: [
      jsxs('div', { style: { borderTop: `1px solid ${stroke}`, paddingTop: 10 }, children: [
        heading('Seen in the lobby'),
        jsx('div', { style: muted, children: 'This computer and the chats it shares.' }),
        rows.length ? rows.map((row, index) => jsx('div', { style: { fontSize: 12, color: text.secondary }, children: row.name }, index))
          : jsx('div', { style: muted, children: 'Nobody is online yet.' })
      ] }),
      jsx(LobbyHall, { view, ctx, current, onPlayHere })
    ] })
  }
  const group = (label, rows, kind, empty) => jsxs('div', { style: { minWidth: 150 }, children: [
    jsx('div', { style: { fontSize: 12, fontWeight: 650 }, children: label }),
    rows.length ? rows.map((row, index) => jsxs('div', { style: { display: 'flex', alignItems: 'center', gap: 6, fontSize: 12, color: text.secondary, marginTop: 4 }, children: [
      jsx(Avatar, { name: row.name, kind, pet: row.name === (view.player && view.player.name) ? pet : '' }),
      jsx('span', { children: row.name }),
      row.game ? jsx('span', { children: row.game }) : null,
      row.rating != null ? jsx('span', { children: `${row.provisional ? '~' : ''}${row.rating}` }) : null
    ] }, row.id || index)) : jsx('div', { style: muted, children: empty })
  ] })
  return jsxs('div', { children: [
    jsxs('div', { style: { borderTop: `1px solid ${stroke}`, paddingTop: 10 }, children: [heading('Seen in the lobby'), jsxs('div', { style: { display: 'flex', flexWrap: 'wrap', gap: 20 }, children: [
      group('People', presence.humans || [], 'human', 'No people right now.'),
      group('Bots', presence.bots || [], 'bot', 'No bots right now.')
    ] })] }),
    jsx(LobbyHall, { view, ctx, current, onPlayHere })
  ] })
}

function LobbyLadder({ view, current }) {
  const pet = usePetAvatar()
  const online = onlineView(view)
  const rows = ((view.online && view.online.ladder_board) || {})[current] || []
  const status = ladderLine(online.ladder)
  const muted = { fontSize: 12, color: text.tertiary }
  let content
  if (!online.on) content = 'Turn on online play to see the ladder.'
  else if (online.offline) content = onlineLine(online)
  else if (!rows.length) content = 'No rated bot games yet.'
  return jsxs('div', { children: [
    heading('Ladder'),
    content ? jsx('div', { style: muted, children: content }) : rows.map((row, index) => jsxs('div', {
      style: { display: 'flex', alignItems: 'center', gap: 8, fontSize: 12, color: text.secondary, marginTop: 4 },
      children: [
        jsx('span', { children: `#${index + 1}` }),
        jsx(Avatar, { name: row.name, pet: online.bot.id && row.id === online.bot.id ? pet : '', kind: online.bot.id && row.id === online.bot.id ? 'human' : 'bot' }),
        jsx('span', { children: row.name }),
        jsx('span', { children: `${row.provisional ? '~' : ''}${row.rating}` }),
        jsx('span', { children: `${row.wins || 0}/${row.losses || 0}/${row.draws || 0}` })
      ]
    }, row.id || index)),
    status ? jsx('div', { style: { ...muted, marginTop: 6 }, children: status }) : null
  ] })
}

function LobbyChatColumn({ view, ctx, send, chat, setChat, name, setName, current, onPlayHere }) {
  // "Play here": the match the lobby just made, opened on the lobby server and played on this
  // page's own table (OnlineTable draws the server's own picture).
  const [playingHere, setPlayingHere] = useState(false)
  const [playProblem, setPlayProblem] = useState('')
  // What the lobby said about the last name or message. A refusal is shown, never swallowed.
  const [sayProblem, setSayProblem] = useState('')
  const playHere = async match => {
    if (playingHere) return
    setPlayingHere(true)
    setPlayProblem('')
    try {
      const answer = await openOnlineTable(ctx, match && match.room_id, match && match.game)
      if (answer && answer.ok === false) { setPlayProblem(String(answer.text || 'That table would not open.')); return }
      if (onPlayHere) onPlayHere(match)
    } finally {
      setPlayingHere(false)
    }
  }
  const lobby = view.lobby || { lines: [], looking: [] }
  const match = onlineView(view).match
  const looking = lobby.looking || []
  // Posts from the last day only, each with its own date and time beside it.
  const posts = freshLobbyLines(lobby.lines)
  const lookingLine = looking.length
    ? `Looking: ${looking.map(item => (item.address ? `${item.name} (${item.game}) @ ${item.address}` : `${item.name} (${item.game})`)).join(', ')}`
    : 'Nobody is looking yet.'
  // One door for the two drafts. A line the lobby refuses — a taken name, a message it will
  // not take — leaves the words where they are and says why; only a line the lobby has taken
  // clears the box, so nothing typed here is thrown away on a failure.
  const say = async line => {
    if (typeof send !== 'function') return { ok: false, text: 'Game Center cannot be reached.' }
    try { return (await send(line)) || { ok: true } }
    catch (error) { return { ok: false, text: 'That did not reach Game Center. Try again.' } }
  }
  const setPlayerName = async () => {
    const wanted = name.trim()
    if (!wanted) return
    setSayProblem('')
    const answer = await say(`name ${wanted}`)
    if (answer && answer.ok === false) { setSayProblem(String(answer.text || 'That name was not taken. Try again.')); return }
    setName('')
  }
  const sendChat = async () => {
    const said = chat.trim()
    if (!said) return
    setSayProblem('')
    const answer = await say(`chat say ${said}`)
    if (answer && answer.ok === false) { setSayProblem(String(answer.text || 'The lobby did not take that message. Try again.')); return }
    setChat('')
  }
  const muted = { fontSize: 11, color: text.tertiary }
  return jsxs('div', {
    className: 'games-center-lobby',
    // Compact on purpose (owner's ask, 2026-11-11): the column is a side panel, not a page. It is
    // capped at 140 px by the layout grid - half what it was, with the freed width going to one
    // more column of game cards - so everything here is one step smaller and tighter.
    style: { display: 'flex', flexDirection: 'column', gap: 6, padding: 10, borderLeft: `1px solid ${stroke}`, minWidth: 110, fontSize: 12, overflow: 'auto', background: paper },
    children: [
      // Only the lobby here (owner's ask, 2026-11-11): on the Game Center page the person is not at a
      // table, so there is no Game tab. A match the lobby has made shows as one card on top.
      match ? jsxs('div', { style: { display: 'flex', flexDirection: 'column', alignItems: 'flex-start', gap: 6 }, children: [
        jsx('div', { style: { fontSize: 11, color: text.secondary }, children: `Your table is ready: ${match.opponent || 'someone'} for ${match.title || match.game || current}.` }),
        // The same server table, whoever started it: Hermes plays it here on the board the
        // server sends. Closing it does not end the match.
        button('Play here', () => playHere(match), {
          primary: true,
          disabled: playingHere || !match.room_id,
          title: 'Plays this match here, on the lobby server, without leaving Hermes.'
        }),
        playProblem ? jsx('div', { role: 'alert', style: { fontSize: 11, border: `1px solid ${accent}`, borderRadius: 8, padding: '6px 10px' }, children: playProblem }) : null
      ] }) : null,
      jsxs('div', {
        style: { display: 'flex', flexDirection: 'column', gap: 6, flex: 1 }, children: [
          jsx('div', { style: { fontWeight: 650, fontSize: 12 }, children: '#games' }),
          view.player.named ? null : jsxs('div', { 'data-lobby-say-row': '1', style: { display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: 4 }, children: [
            jsx('div', { style: { display: 'flex', alignSelf: 'stretch' }, children: field(name, setName, 'Your name', setPlayerName, { label: 'Your name' }) }), button('Set', setPlayerName, { disabled: !name.trim() })
          ] }),
          jsx('div', { style: muted, children: lookingLine }),
          jsx('div', { style: { display: 'flex', flexDirection: 'column', gap: 4, flex: 1, fontSize: 11 }, children: posts.length
            ? posts.map((item, index) => jsxs('div', { 'data-lobby-post': String(index), children: [
              jsx('span', { style: { fontWeight: 650 }, children: `${item.name}: ` }),
              jsx('span', { style: { color: text.secondary }, children: item.text }),
              jsx('span', { style: { color: text.tertiary, marginLeft: 4, whiteSpace: 'nowrap' }, children: lobbyStamp(item.at) })
            ] }, index)) : jsx('div', { style: { color: text.tertiary }, children: 'No messages yet.' }) }),
          jsxs('div', { 'data-lobby-say-row': '1', style: { display: 'flex', flexDirection: 'column', alignItems: 'flex-end', gap: 4 }, children: [
            jsx('div', { style: { display: 'flex', alignSelf: 'stretch' }, children: field(chat, setChat, view.player.named ? 'Say something' : 'Set a name first', sendChat, { label: 'Say something in the lobby chat' }) }),
            button('Send', sendChat, { disabled: !chat.trim() || !view.player.named })
          ] }),
          sayProblem ? jsx('div', {
            role: 'alert', 'data-lobby-say-note': '1',
            style: { fontSize: 11, color: text.primary, border: `1px solid ${accent}`, borderRadius: 8, padding: '6px 10px' },
            children: sayProblem
          }) : null
        ]
      })
    ]
  })
}

// ---- 73-online-table.js: the lobby's table, played inside Hermes
//
// CONTRACT C, the dashboard routes this screen speaks:
//   GET  /online/table          -> {"table": null} or {"table": {...}}
//   POST /online/table/open     {room_id}
//   POST /online/table/cmd      {action, args}
//   POST /online/table/chat     {text}          -> {ok, text}
//   POST /online/table/close
// The table payload is {room_id, state, picture, room, side, opponent:{name}, error, finished,
// chat:[{id, player_id, name, role, text, at, bot, staff, removed}]} — the last 50 messages the
// server has for this seat, the same list the website's table chat draws — and chat_error
// {text, sent, at} when the server turned a message down: its own words, and the text it refused
// (the last this seat sent, since a chat frame carries no id to match a refusal against).
//
// "picture" is this seat's own picture — the same schema BoardSvg already draws, including
// permissions.can_move, legal, plies, turn and status — so this screen draws the very board the
// local table draws; only where a move is sent changes.
//
// One rule above the rest: this is a table between people on the lobby server. Nothing here may
// send a local game command, and nothing here may claim a Hermes model is thinking. The turn line
// says whose move it is, and nothing else.
//
// The chat panel beside the board follows the same rule as the board: a message appears when the
// table has taken it, never when the finger leaves the key. Sending is one route, and the message
// comes back on the polled feed like anybody else's.
const ONLINE_TABLE_POLL_MS = 400

// "Play here" remembers the room in this window so the full-screen table opens on it. The same
// shape as PAGE_HANDOFF (62-pane-state.js): one module value, set by the press, read by the table.
// The game is remembered with it, so a table opened for one game can never appear over another.
// A table that closes or finishes forgets it again, so the game's own local table comes back.
const ONLINE_ROOM = { roomId: '', gameId: '' }

function rememberOnlineRoom(roomId, gameId) {
  ONLINE_ROOM.roomId = String(roomId == null ? '' : roomId)
  ONLINE_ROOM.gameId = ONLINE_ROOM.roomId ? String(gameId == null ? '' : gameId) : ''
}

// The room the server itself says it is holding for this person (when the view carries it).
function serverOnlineRoom(view) {
  const table = (view && view.online && view.online.table) || null
  return String((table && table.room_id) || '')
}

// The game the server's table is for, when its answer says.
function serverOnlineGame(view) {
  const table = (view && view.online && view.online.table) || null
  if (!table) return ''
  return String(table.game || (table.picture && table.picture.game) || '')
}

// Which room to play at *this* game's table: the server's own answer first, then the one "Play
// here" opened. Never a room for another game — a Connect Four room over Reversi would be a
// different game's board, played under the wrong title.
function onlineRoomFor(view, gameId) {
  const wanted = String(gameId || '')
  const fromServer = serverOnlineRoom(view)
  if (fromServer) {
    const theirs = serverOnlineGame(view)
    return theirs && wanted && theirs !== wanted ? '' : fromServer
  }
  if (!ONLINE_ROOM.roomId) return ''
  return ONLINE_ROOM.gameId && wanted && ONLINE_ROOM.gameId !== wanted ? '' : ONLINE_ROOM.roomId
}

// "Play here": one press opens the room on the lobby server and hands the room to the surface
// that asked, which then paints this table. The person is moved only once the server has taken it.
async function openOnlineTable(ctx, roomId, gameId) {
  const room = String(roomId == null ? '' : roomId).trim()
  if (!room) return { ok: false, text: 'That table has no room to open.' }
  if (!ctx || typeof ctx.rest !== 'function') return { ok: false, text: 'This window cannot reach Game Center.' }
  try {
    const answer = await ctx.rest('/online/table/open', { method: 'POST', body: { room_id: room } })
    if (answer && answer.ok === false) return answer
    rememberOnlineRoom(room, gameId)
    return answer || { ok: true }
  } catch (error) {
    return { ok: false, text: 'That did not reach Game Center. Try again.' }
  }
}

// Who is across the table, in plain words — never a blank name.
function onlineOpponent(table) {
  return String((table && table.opponent && table.opponent.name) || '') || 'your opponent'
}

// May this seat move? The server's per-seat permissions are authoritative; the older
// identity-based reading is the fallback for a picture that carries none.
function onlineCanMove(picture, view) {
  if (!picture || picture.status !== 'active') return false
  if (picture.permissions && typeof picture.permissions.can_move === 'boolean') return picture.permissions.can_move
  return tableAccess(picture, view || {}).can_move
}

function OnlineTable({ game, view, ctx, roomId, height, onBack, onClose }) {
  const [table, setTable] = useState(null)
  const [read, setRead] = useState(false)
  const [problem, setProblem] = useState('')
  const [busy, setBusy] = useState(false)
  const [notice, setNotice] = useState('')
  const [failure, setFailure] = useState('')
  const [confirming, setConfirming] = useState(false)
  const [resultShown, setResultShown] = useState(true)
  const alive = useRef(true)
  const inFlight = useRef(false)
  // Which read is the newest. A 400 ms poll can overlap — a slow answer, or this screen
  // reading again when the room changes — and the answers can then arrive out of order.
  // Only the newest read may paint, so a late answer never puts an older board back on screen.
  const readSeq = useRef(0)
  // Whether this person has ever seen the table. One that is gone after being seen is closed for
  // good; one that has never arrived is still being opened, so the room is not forgotten yet.
  const seen = useRef(false)
  const latest = useRef({ roomId: '' })
  latest.current = { roomId: roomId || '' }

  useEffect(() => {
    alive.current = true
    return () => { alive.current = false }
  }, [])

  // The same mount-time guard the local table needed for a straggler setBusy: a command in flight
  // when this screen was replaced must never leave the fresh one locked.
  useEffect(() => { setBusy(false); inFlight.current = false }, [])

  // The table, read every 400 ms while this screen is up. The server owns the state; this only
  // paints its answer, so a move played in the browser shows up here too.
  useEffect(() => {
    const mine = roomId || ''
    let timer = null
    const readTable = async () => {
      if (!ctx || typeof ctx.rest !== 'function') return
      const seq = readSeq.current + 1
      readSeq.current = seq
      try {
        const answer = await ctx.rest('/online/table')
        if (!alive.current || latest.current.roomId !== mine) return
        // A newer read has started while this one was out: its answer is the one that counts.
        if (seq !== readSeq.current) return
        const next = (answer && answer.table) || null
        if (next) seen.current = true
        else if (seen.current) rememberOnlineRoom('')
        setTable(next)
        setProblem('')
        setRead(true)
      } catch (error) {
        if (!alive.current || latest.current.roomId !== mine) return
        if (seq !== readSeq.current) return
        setRead(true)
        setProblem('The table cannot be reached right now. It keeps trying.')
      }
    }
    readTable()
    timer = setInterval(readTable, ONLINE_TABLE_POLL_MS)
    return () => { if (timer) clearInterval(timer) }
  }, [ctx, roomId])

  // The table's chat: the server's own list, like the board, comes down the same poll — so a
  // message from anybody at this table, including this person's own, appears when the table has it.
  const chatLines = Array.isArray(table && table.chat) ? table.chat : []
  const [draft, setDraft] = useState('')
  const [sending, setSending] = useState(false)
  const [chatProblem, setChatProblem] = useState('')
  const chatLog = useRef(null)

  // The newest line is the one in view. The element is only there in a real window, so a
  // missing one is simply nothing to scroll.
  useEffect(() => {
    const list = chatLog.current
    if (list && typeof list.scrollHeight === 'number') list.scrollTop = list.scrollHeight
  }, [chatLines.length])

  // A message the table turns down — muted by the host, silenced, or too fast — comes back on the
  // table's own feed, not as an answer to the press. It is shown in the server's words, and the
  // words that were refused go back in the box, so nothing typed here is lost.
  const chatRefusal = (table && table.chat_error) || null
  const seenRefusal = useRef(0)
  useEffect(() => {
    const at = chatRefusal && chatRefusal.at
    if (!at || at === seenRefusal.current) return
    seenRefusal.current = at
    setChatProblem(String(chatRefusal.text || 'The table did not take that message.'))
    setDraft(current => current || String(chatRefusal.sent || ''))
  }, [chatRefusal && chatRefusal.at])

  // One door for a message, the way the board has one door for a move. The line is not drawn
  // here: it is drawn by the next poll, once the table has taken it.
  const sendChat = async () => {
    const text = draft.trim()
    if (!text || sending || !alive.current) return
    if (!ctx || typeof ctx.rest !== 'function') return
    setSending(true)
    setChatProblem('')
    try {
      const answer = await ctx.rest('/online/table/chat', { method: 'POST', body: { text } })
      if (!alive.current) return
      if (answer && answer.ok === false) setChatProblem(String(answer.text || 'The table did not take that message.'))
      else setDraft('')
    } catch (error) {
      if (alive.current) setChatProblem('That did not reach the table. Try again.')
    } finally {
      if (alive.current) setSending(false)
    }
  }

  const picture = (table && table.picture) || null
  const state = String((table && table.state) || '')
  const status = String((picture && picture.status) || '')
  const over = ['win', 'draw', 'abandoned', 'done'].includes(status)
  const done = Boolean(over || (table && table.finished && picture))
  const canMove = Boolean(!busy && !confirming && !done && state !== 'reconnecting' && onlineCanMove(picture, view))
  const myTurn = onlineCanMove(picture, view)
  // The chat is open while the table is: the same condition the server's own room uses.
  const atTable = state === 'live'
  const opponent = onlineOpponent(table)
  const mySide = String((table && table.side) || '')
  const winner = String((picture && picture.winner) || '')
  const iWon = Boolean(winner && mySide && winner === mySide)
  const resultLine = status === 'draw' ? 'It is a draw.'
    : iWon ? 'You win!'
    : winner ? `${opponent} wins.`
    : 'Game over.'
  const headline = resultHeadline({
    pictured: picture, status, iWon, machineWon: false,
    sideName: winner === 'black' ? 'Black' : 'White'
  })
  // The turn line, in the owner's words: your move the moment the server says it is yours;
  // otherwise it waits, by name. A table that is reconnecting says that instead of pretending.
  const reconnecting = state === 'reconnecting'
  const turnKind = reconnecting ? 'reconnecting' : done ? 'over' : myTurn ? 'mine' : 'theirs'
  const caption = reconnecting ? 'Reconnecting…'
    : done ? resultLine
    : myTurn ? 'Your turn'
    : `Waiting for ${opponent}`
  const dotColor = !picture || done ? '#7d8796' : picture.turn === 'black' ? '#20262e' : '#f0d0b0'
  const shown = picture || { view: (game && game.id) || '', game: (game && game.id) || '', status: 'idle', legal: [] }

  // A new table, or a game that ends, brings the result card back even after it was put away by
  // hand — the same rule the local table uses.
  useEffect(() => { setResultShown(true) }, [table && table.room_id, status, done])
  // A table that finishes forgets the room so the game's own local table comes back.
  useEffect(() => { if (done) rememberOnlineRoom('') }, [done])
  // A new position leaves no stale question behind: a resign dialog belongs to the position it
  // was opened on. A refusal is deliberately not cleared here — the table's own words stay until
  // the next move, so a refused move can never look like it did nothing.
  useEffect(() => { setConfirming(false) }, [picture && picture.plies, status, state])

  // One door for every command: the board and the resign button both go through it, both are
  // locked while it is out, and the answer's picture is painted at once. No prediction — the
  // person's move appears when the table has taken it, never before.
  const command = async (action, args) => {
    if (inFlight.current || !alive.current) return { ok: false }
    inFlight.current = true
    setBusy(true)
    setFailure('')
    try {
      const answer = await ctx.rest('/online/table/cmd', { method: 'POST', body: { action, args: args || [] } })
      if (!alive.current) return answer || { ok: false }
      if (answer && answer.picture) setTable(current => ({ ...(current || {}), picture: answer.picture }))
      if (answer && answer.ok === false) setFailure(String(answer.text || 'The table refused that move.'))
      else setNotice((answer && answer.text) || '')
      return answer || { ok: true }
    } catch (error) {
      if (alive.current) setFailure('That did not reach the table. Try again.')
      return { ok: false }
    } finally {
      inFlight.current = false
      if (alive.current) setBusy(false)
    }
  }

  // Putting the table away is not resigning and not closing the match: the room stays on the
  // lobby server. So it is one press, with no question asked.
  const putAway = async () => {
    if (busy) return
    setBusy(true)
    try {
      if (ctx && typeof ctx.rest === 'function') await ctx.rest('/online/table/close', { method: 'POST' })
    } catch (error) {
      // The table goes away here either way; the room is the server's to settle.
    }
    rememberOnlineRoom('')
    if (alive.current) setBusy(false)
    if (onClose) onClose()
    else if (onBack) onBack()
  }

  const header = jsxs('div', {
    style: { display: 'flex', justifyContent: 'space-between', gap: 12, alignItems: 'center', flexWrap: 'wrap', paddingBottom: 10, borderBottom: `1px solid ${stroke}` },
    children: [
      jsxs('div', { style: { display: 'flex', gap: 12, alignItems: 'center', minWidth: 0 }, children: [
        button('Back', () => onBack && onBack()),
        jsxs('div', { style: { minWidth: 0 }, children: [
          jsx('div', { style: { fontSize: 20, fontWeight: 700 }, children: (game && game.title) || (picture && picture.game) || 'Online table' }),
          jsx('div', { style: { fontSize: 12, color: text.tertiary }, children: `Against ${opponent}${mySide ? ` · you play ${mySide}` : ''}` })
        ] })
      ] }),
      jsxs('div', { style: { display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap' }, children: [
        status === 'active' && !done ? button('Resign', () => setConfirming(true), { disabled: busy }) : null,
        button('Close table', putAway, { disabled: busy, title: 'Puts this table away here. The match stays on the lobby server.' })
      ] })
    ]
  })

  const strip = jsxs('div', {
    role: 'status', 'aria-live': 'polite', className: 'games-status',
    style: { display: 'flex', gap: 10, alignItems: 'center', flexWrap: 'wrap', fontSize: 14, fontWeight: 650 },
    children: [
      jsx('span', {
        'aria-hidden': true, className: 'games-turn-dot',
        style: { display: 'inline-block', width: 12, height: 12, borderRadius: '50%', background: dotColor, border: dotColor === '#20262e' ? '1px solid #7d8796' : '1px solid #8a704f' }
      }),
      jsx('span', {
        'data-turn-line': turnKind,
        style: myTurn ? { color: accent, fontWeight: 800 } : { color: text.secondary },
        children: caption
      }),
      // Never "Hermes is thinking" here: nobody's model is playing this seat. A command that is
      // out is the table's own round trip, and it says so.
      busy ? jsx('span', { className: 'games-waiting', style: { fontSize: 12, color: text.tertiary, fontWeight: 400 }, children: 'sending…' }) : null,
      notice ? jsx('span', { style: { fontSize: 12, color: text.tertiary, fontWeight: 400 }, children: notice }) : null
    ]
  })

  const resultCard = done && resultShown ? jsx('div', {
    className: 'games-result',
    onClick: () => setResultShown(false),
    style: {
      position: 'absolute', inset: 0, zIndex: 4, display: 'flex', alignItems: 'center', justifyContent: 'center',
      padding: 12, background: 'rgba(8, 12, 18, .58)', borderRadius: 12, cursor: 'pointer'
    },
    children: jsxs('section', {
      role: 'alert', 'aria-label': 'Game over', 'aria-live': 'assertive',
      onClick: event => event.stopPropagation(),
      style: { display: 'flex', flexDirection: 'column', gap: 10, alignItems: 'center', textAlign: 'center', maxWidth: 470, padding: '18px 20px', borderRadius: 16, border: `2px solid ${iWon ? accent : stroke}`, background: card, boxShadow: '0 20px 44px rgba(0, 0, 0, .55)' },
      children: [
        jsx('div', { className: 'games-result-title', style: { fontSize: 30, fontWeight: 800, lineHeight: 1.1 }, children: headline }),
        jsx('div', { className: 'games-result-why', style: { fontSize: 13, color: text.secondary }, children: `You vs ${opponent}, on the lobby server` }),
        jsxs('div', { style: { display: 'flex', gap: 8, flexWrap: 'wrap', justifyContent: 'center', marginTop: 2 }, children: [
          // One name per control on this screen: the header already carries Close table.
          button('Back to games', () => { rememberOnlineRoom(''); if (onBack) onBack() }, { primary: true })
        ] }),
        textLink('Look at the board', () => setResultShown(false))
      ]
    })
  }) : null

  const board = jsxs('div', {
    className: 'games-board-hero',
    style: { display: 'flex', flex: '0 0 auto', alignItems: 'center', justifyContent: 'center', padding: 4, position: 'relative' },
    children: [
      jsx(shown && shown.view === 'backgammon' ? BackgammonSvg : BoardSvg, {
        picture: shown,
        height: height || PLAY_HEIGHT,
        flat: true,
        interactive: canMove,
        onMove: token => { if (canMove) command('move', [token]) }
      }),
      resultCard
    ]
  })

  // The panel itself is drawn by 74-online-chat.js, which owns how it looks; this screen owns the
  // state: what is typed, whether a message is out, and the table's own refusal.
  const chatPanel = onlineChatPanel({
    lines: chatLines, draft, problem: chatProblem, canType: atTable, sending,
    log: chatLog, onDraft: setDraft, onSend: sendChat
  })

  const body = !table
    ? jsx('div', {
        role: 'status', 'aria-live': 'polite',
        style: { fontSize: 13, color: text.secondary, border: `1px solid ${stroke}`, borderRadius: 12, padding: 14, background: card },
        children: read
          ? 'No table is open here. A match the lobby hands you opens with Play here.'
          : 'Looking for your table…'
      })
    : jsxs('div', { style: { display: 'flex', flexDirection: 'column', gap: 10, minWidth: 0 }, children: [
        jsxs('div', {
          className: 'games-online-table-row',
          style: { display: 'flex', flexWrap: 'wrap', gap: 12, alignItems: 'flex-start', minWidth: 0 },
          children: [board, chatPanel]
        }),
        table.error || state === 'error'
          ? jsx('div', { role: 'alert', style: { fontSize: 13, border: '1px solid #d76b65', borderRadius: 8, padding: '8px 10px' }, children: String(table.error || 'The table stopped.') })
          : null,
        state === 'closed' ? jsx('div', { role: 'status', style: { fontSize: 13, color: text.secondary }, children: 'This table is closed. The lobby is where a new one is found.' }) : null
      ] })

  return jsxs('div', {
    className: 'games-online-table',
    style: { display: 'flex', flexDirection: 'column', gap: 10, padding: 14, paddingBottom: 96, minWidth: 0, minHeight: 0, overflow: 'auto', background: paper, height: '100%' },
    children: [
      header,
      strip,
      body,
      problem ? jsx('div', { role: 'status', 'aria-live': 'polite', style: { fontSize: 12, color: text.secondary }, children: problem }) : null,
      failure ? jsx('div', { role: 'alert', style: { padding: 12, border: '1px solid #d76b65', borderRadius: 8, fontSize: 13 }, children: failure }) : null,
      // Resigning hands the game to the other person, so it is asked for once, in those words.
      confirming ? jsxs('section', {
        role: 'alertdialog', 'aria-label': 'Confirm resign', 'aria-describedby': 'games-online-resign',
        onKeyDown: event => { if (event.key === 'Escape') setConfirming(false) },
        style: { padding: 16, border: `1px solid ${accent}`, borderRadius: 12, background: card },
        children: [
          jsx('p', { id: 'games-online-resign', style: { margin: '0 0 12px', fontSize: 13 }, children: `Resigning ends this match and awards the win to ${opponent}.` }),
          jsxs('div', { style: { display: 'flex', gap: 8 }, children: [
            button('Cancel', () => setConfirming(false), { autoFocus: true }),
            button('Confirm resign', () => { setConfirming(false); command('resign', []) }, { primary: true, disabled: busy })
          ] })
        ]
      }) : null,
      jsx('div', { style: { fontSize: 11, color: text.tertiary, lineHeight: 1.45 }, children: 'This table is a match on the lobby server. Closing it here puts the table away; it does not resign the game.' })
    ]
  })
}

// ---- 74-online-chat.js: the table's chat, as the one panel the online table draws
//
// Split out of 73-online-table.js so neither part grows past what a reader can hold. The table owns
// the state (the box's words, the send in flight, the refusal) and this part draws it.
//
// It is a plain function rather than a component, and that is deliberate: the panel is drawn inside
// OnlineTable's own tree, so the list, the box and the refusal are one set of elements — the same
// elements the UI harness walks to read the screen's words.
const ONLINE_CHAT_KEEP = 50

// Who said it, in the website's words: players and the host plainest, a watcher named as one.
function onlineChatRole(role) {
  return role === 'host' ? ' (host)' : role === 'player' ? '' : ' (watching)'
}

// One line of the server's own chat: who said it, and what they said.
function onlineChatLine(message, index) {
  const line = message && typeof message === 'object' ? message : {}
  const who = String(line.name || 'Someone')
  const tag = onlineChatRole(String(line.role || ''))
  return jsxs('div', {
    key: String(line.id != null ? line.id : index),
    'data-chat-line': '1',
    style: { fontSize: 12, lineHeight: 1.4, minWidth: 0, overflowWrap: 'anywhere', color: text.secondary },
    children: [
      jsx('b', { style: { color: text.primary }, children: tag ? `${who}${tag}` : who }),
      jsx('span', { children: `: ${String(line.text || '')}` })
    ]
  })
}

// The panel: the server's list, a box capped where the server caps, and Send. It sits beside the
// board on a wide page and under it on a narrow one, and it scrolls to the newest line.
function onlineChatPanel({ lines, draft, problem, canType, sending, log, onDraft, onSend }) {
  return jsxs('section', {
    className: 'games-online-chat',
    'aria-label': 'Table chat',
    'data-online-chat': '1',
    style: { display: 'flex', flexDirection: 'column', gap: 8, flex: '1 1 260px', minWidth: 220, maxWidth: 380, minHeight: 220, padding: 10, border: `1px solid ${stroke}`, borderRadius: 12, background: card },
    children: [
      jsx('div', {
        title: `Everyone at this table — players, the host and watchers — shares this chat. The server keeps the last ${ONLINE_CHAT_KEEP} messages.`,
        style: { fontSize: 13, fontWeight: 700 },
        children: 'Table chat'
      }),
      jsx('div', {
        className: 'games-online-chat-log', 'data-chat-list': '1', role: 'log', 'aria-live': 'polite',
        ref: log,
        style: { display: 'flex', flexDirection: 'column', gap: 6, flex: 1, minHeight: 120, maxHeight: '40vh', overflowY: 'auto', paddingRight: 4 },
        children: lines.length
          ? lines.map(onlineChatLine)
          : jsx('span', { style: { fontSize: 12, color: text.tertiary, fontStyle: 'italic' }, children: 'Say hi. Players and watchers share this chat.' })
      }),
      jsxs('div', { style: { display: 'flex', gap: 8, alignItems: 'center', minWidth: 0 }, children: [
        jsx('input', {
          className: 'games-online-chat-input', 'data-chat-input': '1',
          value: draft, maxLength: 300, placeholder: 'Message',
          'aria-label': 'Chat message',
          title: 'Up to 300 characters, like the website. Enter sends; Send does the same.',
          disabled: !canType,
          onChange: event => onDraft(event.target.value),
          onKeyDown: event => { if (event.key === 'Enter') { event.preventDefault(); onSend() } },
          style: { flex: 1, minWidth: 0, padding: '7px 10px', borderRadius: 8, border: `1px solid ${stroke}`, background: 'transparent', color: 'inherit', fontSize: 12 }
        }),
        button('Send', onSend, {
          primary: true, disabled: !canType || sending || !draft.trim(),
          title: 'Sends your message to everyone at this table. It appears once the table has taken it.'
        })
      ] }),
      problem ? jsx('div', { role: 'alert', style: { fontSize: 12, border: '1px solid #d76b65', borderRadius: 8, padding: '6px 8px' }, children: problem }) : null
    ]
  })
}

// ---- 78-overchat-slot.js: the see-through machines, in the composer's own slot
//
// Both slot machines have a "show it over the conversation" switch: the original cabinet
// (18-slot-machine.js / 19-jackpot-overlay.js) and Jackpot v2 (19-jackpot2-layer.js). This part is the
// one place they are put on screen, and it is the review's fix (2026-11-12).
//
// WHAT IT REPLACED. Each machine used to put itself over the app: a position:fixed div appended to
// document.body, a stylesheet appended to <head>, and a measurement of the app's own markup — scan every
// <textarea>, walk their ancestors until one was wider than half the window, call that "the chat column",
// and read the route's hash to guess which screen was showing. A plugin that does that can be broken by
// an app update and can break the app, which is exactly what the review asked us to stop.
//
// WHAT THIS IS. One contribution to `COMPOSER_AREAS.underside`, the composer's chrome-free strip below
// the input — a real Desktop SDK surface, registered like any other contribution:
//
//   - the slot decides WHERE. It is part of the conversation's composer, so it exists exactly while the
//     conversation is on screen: no route sniffing, no DOM test, nothing to keep the machine off the
//     Games page, Settings or another plugin's page.
//   - the slot decides HOW WIDE. This component measures ITS OWN box (the one element it is allowed to
//     measure) and hands each machine its share: the whole width for one, the two halves for both.
//   - the machines decide their own look. Each copy fits itself into that share, keeps its own opacity,
//     and is watch-only (it must never take a click the conversation wanted).
//
// The strip is drawn only while at least one switch is on, so its height is zero — and the composer's
// underside is empty — whenever nobody asked for a machine.
const OVERCHAT_GAP = 10

// What one machine's slot looks like. `minWidth: 0` matters: without it a flex item refuses to shrink
// below its content, and a wide cabinet would push the strip past the composer instead of being fitted.
const OVERCHAT_SLOT = { minWidth: 0, display: 'flex', alignItems: 'flex-end', justifyContent: 'center' }

// The strip's own width, read from the element it owns. Read on every render rather than kept in state:
// one property, one element of ours, and a ResizeObserver only has to ask for a new render.
function overchatStripWidth(ref) {
  const node = ref && ref.current
  if (!node) return 0
  if (typeof node.getBoundingClientRect === 'function') {
    const rect = node.getBoundingClientRect()
    const width = rect ? Number(rect.width) || 0 : 0
    if (width > 0) return width
  }
  return Number(node.clientWidth) || 0
}

function OverChatStrip({ ctx }) {
  const [slotsOn] = useSmOverchat()
  const [jackpotOn] = useJp2LOverchat(ctx)
  const box = useRef(null)
  const [, setResized] = useState(0)

  // Our own box, and nothing else. A ResizeObserver rather than a window listener: the composer changes
  // width when a pane opens, when the window moves between screens and when the person drags a sash —
  // all of those are the same event to this element.
  useJpLayoutEffect(() => {
    // One render after mount: the ref is only filled in once the tree is committed, so the first render
    // cannot see the box at all. (A strip that is already its final width fires no resize event.)
    setResized(count => count + 1)
    const node = box.current
    if (typeof ResizeObserver === 'undefined' || !node) return undefined
    let watcher = null
    try {
      watcher = new ResizeObserver(() => setResized(count => count + 1))
      watcher.observe(node)
    } catch {
      return undefined
    }
    return () => { if (watcher && typeof watcher.disconnect === 'function') watcher.disconnect() }
  }, [])

  const width = overchatStripWidth(box)
  const on = Boolean(slotsOn || jackpotOn)
  if (!on) return null
  const both = Boolean(slotsOn && jackpotOn)
  const share = both ? Math.max(0, width - OVERCHAT_GAP) / 2 : width
  return jsx('div', {
    'data-overchat': 'strip',
    ref: box,
    style: {
      width: '100%',
      minWidth: 0,
      display: 'flex',
      gap: OVERCHAT_GAP,
      alignItems: 'flex-end',
      justifyContent: 'center',
      // The strip is a picture: nothing in it may take a click from the conversation. Each machine's own
      // dismissal controls opt back in (19-jackpot2-layer.js, jp2LStyleRules).
      pointerEvents: 'none'
    },
    children: [
      slotsOn ? jsx('div', {
        'data-overchat': 'slots',
        style: { ...OVERCHAT_SLOT, width: share ? share : '100%' },
        children: jsx(SlotsOverChatCopy, { ctx, width: share })
      }, 'slots') : null,
      jackpotOn ? jsx('div', {
        'data-overchat': 'jackpot',
        style: { ...OVERCHAT_SLOT, width: share ? share : '100%' },
        children: jsx(jp2LOverChatCopy, { ctx, width: share })
      }, 'jackpot') : null
    ]
  })
}

// ---- 79-version.js: the version chip, so the install on screen can be identified at a glance
/**
 * One source: the plugin's own backend (/v1/version -> version_stamp), never a number typed into
 * this bundle. A hard-coded badge drifts the moment the manifest moves, and drifts silently.
 *
 * It is a chip, and it is drawn twice from the one component (owner, 2026-11-11): small and muted at
 * the top of the Games header, beside the wordmark, and at the top of Settings — which is what the
 * full-screen Games app shows and what the play-while-you-wait pane's own gear opens (owner,
 * 2026-11-10: "keep everything in the status bar except the version chip. The version chip lives in
 * Settings"). One component, so the two copies can never drift apart; the header copy only passes a
 * smaller, dimmer `style` so it stays a whisper beside the title.
 *
 * It is also click-to-copy (owner's ask, 2026-11-11): one press — or Enter/Space from the keyboard —
 * puts the full chip text on the clipboard and says "Copied" for a breath, so a bug report can quote
 * the exact build without anyone retyping it.
 */

// How long the chip wears "Copied". Long enough to see, short enough not to look stuck.
const CHIP_COPIED_MS = 1500

// Copies one line and resolves true once it is on the clipboard, through the app's own door first.
//
// `ctx.os.writeClipboard` is the SDK's curated clipboard and the only one a plugin should use: it is
// attributed to the plugin, it resolves false (never throws) where the capability is missing, and it
// needs nothing of the document. What it replaced was a hidden <textarea> appended to the app's <body>
// and an execCommand — the same reach into the app's markup the review asked us to stop doing
// (2026-11-12), for a copy that the browser's own clipboard API already does.
function copyChipText(text, ctx) {
  try {
    const door = ctx && ctx.os && typeof ctx.os.writeClipboard === 'function' ? ctx.os : null
    if (door) {
      return Promise.resolve(door.writeClipboard(text)).then(done => {
        if (done !== false) return true
        return copyWithNavigator(text)
      }, () => copyWithNavigator(text))
    }
  } catch (error) { /* fall through to the browser's own clipboard */ }
  return copyWithNavigator(text)
}

function copyWithNavigator(text) {
  try {
    if (typeof navigator !== 'undefined' && navigator.clipboard && typeof navigator.clipboard.writeText === 'function') {
      return Promise.resolve(navigator.clipboard.writeText(text)).then(() => true, () => false)
    }
  } catch (error) { /* no clipboard on this host */ }
  return Promise.resolve(false)
}

function GamesVersionChip({ ctx, style }) {
  const [build, setBuild] = useState(null)
  const [copied, setCopied] = useState(false)
  const timer = useRef(null)
  useEffect(() => {
    let live = true
    Promise.resolve(ctx.rest('/v1/version'))
      .then(answer => { if (live && answer && answer.version) setBuild(answer) })
      .catch(() => {})
    return () => { live = false }
  }, [ctx])
  // A chip that leaves the screen mid-breath must not leave a timer behind.
  useEffect(() => () => { if (timer.current) clearTimeout(timer.current) }, [])
  if (!build) return null
  // version · build date · short commit — the same line `--version` prints.
  const parts = ['v' + build.version]
  if (build.commit_date) parts.push(String(build.commit_date).slice(0, 10))
  if (build.commit_short || build.commit) parts.push(String(build.commit_short || build.commit).slice(0, 8))
  const line = parts.join(' · ') + (build.dirty ? ' · modified' : '')
  const explain = [
    'Game Center ' + build.version,
    build.commit ? 'commit ' + build.commit : 'no commit (installed copy)',
    build.commit_date ? 'committed ' + build.commit_date : '',
    build.built_at ? 'installed ' + build.built_at : '',
    build.channel ? 'channel ' + build.channel : '',
    build.source ? 'read from ' + build.source : '',
    'Click to copy the version'
  ].filter(Boolean).join('\n')
  // The chip copies its own text — the same line it shows, so what is pasted is what was read. It only
  // says "Copied" when the copy actually happened: a host with no clipboard at all must not claim one.
  const copy = () => {
    Promise.resolve(copyChipText(line, ctx)).then(done => {
      if (!done) return
      setCopied(true)
      if (timer.current) clearTimeout(timer.current)
      timer.current = setTimeout(() => setCopied(false), CHIP_COPIED_MS)
    })
  }
  return jsx('span', {
    'data-games-version': 'chip',
    role: 'button',
    tabIndex: 0,
    title: explain,
    onClick: copy,
    onKeyDown: event => {
      if (event.key === 'Enter' || event.key === ' ' || event.key === 'Spacebar') {
        if (event.preventDefault) event.preventDefault()
        copy()
      }
    },
    style: Object.assign({
      display: 'inline-flex',
      alignItems: 'center',
      padding: '2px 8px',
      borderRadius: 999,
      border: `1px solid ${stroke}`,
      fontSize: 11,
      letterSpacing: '0.04em',
      fontFamily: 'ui-monospace, SFMono-Regular, Menlo, monospace',
      color: build.dirty ? '#b45309' : text.tertiary,
      whiteSpace: 'nowrap',
      cursor: 'pointer',
      ...TABULAR
    }, style || {}),
    children: copied ? 'Copied' : line
  })
}

// ---- 80-plugin.js: what Hermes loads: the page, the pane, the palette and the badges
export default {
  id: 'hermes-gameshelf',
  name: 'Game Center',
  register(ctx) {
    // The wait pane is registered on its own so × can take it off the screen (see 62-pane-state.js).
    WAIT_PANE_SLOT.ctx = ctx
    // A fresh load starts clean: the host already disposed the previous load's pane.
    WAIT_PANE_SLOT.dispose = null
    WAIT_PANE_SLOT.make = () => ({
      id: 'pane',
      area: PANES_AREA,
      title: 'Play while you code',
      // Beside the chat, as its own column. It lands minimized so installing the
      // plugin never reshapes a layout, and it is hide-only so Hermes never offers
      // its own Close (that would disable the whole plugin); our × unregisters it.
      data: {
        placement: 'right',
        dock: { pane: 'workspace', pos: 'right' },
        width: PANE_WIDTH,
        minWidth: '300px',
        maxWidth: '560px',
        defaultCollapsed: true,
        hideOnly: true
      },
      render: () => jsx(GamesBoundary, {
        where: 'pane',
        // Back to the pane's game list: forget the game that crashed so it is not reopened.
        onReset: () => {
          paneWatch.game = ''
          storeValue(ctx, PANE_GAME_KEY, '')
        },
        children: jsx(WaitPane, { ctx })
      })
    })
    if (!paneGone()) mountWaitPane()
    ctx.registerMany([
      {
        id: 'page',
        area: ROUTES_AREA,
        data: { path: ROUTE },
        render: () => jsx(GameCenterRoute, { ctx })
      },
      {
        id: 'nav',
        area: SIDEBAR_NAV_AREA,
        data: { path: ROUTE, label: 'Games', codicon: 'game' }
      },
      {
        id: 'open',
        area: PALETTE_AREA,
        data: {
          id: 'hermes-gameshelf.open',
          label: 'Open Game Center',
          keywords: ['games', 'shelf', 'lobby', 'store', 'install'],
          run: () => host.navigate(ROUTE)
        }
      },
      {
        id: 'wait',
        area: PALETTE_AREA,
        data: {
          id: 'hermes-gameshelf.wait',
          label: 'Play while you code',
          keywords: ['game', 'pane', 'play', 'wait', 'code', 'agent', 'quick', 'side'],
          run: () => openWaitPane()
        }
      },
      {
        id: 'status',
        area: STATUSBAR_AREAS.right,
        order: 140,
        // ONE item (owner, 12:25): hidden while there is nothing to say, one
        // actionable line when there is. It renders null, not a permanent label.
        render: () => jsx(GamesStatusItem, { ctx })
      },
      {
        // The two see-through machines, in the composer's own slot (78-overchat-slot.js). A slot, not an
        // overlay: the app owns where it goes and how wide it is, so an app update cannot break it and it
        // cannot break the app (review, 2026-11-12). The strip draws only while a switch is on, and the
        // switches themselves live where they always did — the Slots table, the cabinet's own panel and
        // Settings.
        id: 'overchat',
        area: COMPOSER_AREAS.underside,
        render: () => jsx(OverChatStrip, { ctx })
      }
    ])
  }
}

// Shared with Game Center Online (online/web/app.js), which draws the same boards in a browser.
export { BoardSvg, coverArt, startingPicture, tableAccess }

// The Game Center page and its one way out. On the Games screen Close Game Center sits in the
// header, top right, beside search (owner's ask, 2026-11-11); on every other screen (Settings,
// Champions, Community, ...) it floats top right instead of the old bottom-right corner.
function GameCenterRoute({ ctx }) {
  const [area, setArea] = useState('games')
  return jsxs('div', {
    style: { position: 'relative', height: '100%' },
    children: [
      jsx(GamesBoundary, { where: 'page', onClose: () => closeGameCenter(ctx), children: jsx(GameCenterPage, { ctx, onArea: setArea }) }),
      area === 'games' ? null : jsx('div', {
        'data-gc-close-float': '1',
        style: { position: 'absolute', right: 16, top: 12, zIndex: 40 },
        children: closeGameCenterButton(ctx)
      })
    ]
  })
}

function closeGameCenterButton(ctx) {
  return button('Close Game Center', () => closeGameCenter(ctx), { title: 'Back to the chat. Your game stays where you left it.' })
}
